const { notionApi, handleApiError, apiCallWithRetry } = require('./api-utils');
const { notionDatabaseId, requiredEnvVars } = require('./config');
const { cache } = require('./cache');

// Mount modular route handlers
router.use(pageRoutes);
router.use(pageOperations);
router.use(memoryRoutes);

/**
 * @route   GET /query-database
 * @desc    Queries the configured Notion database and returns entries
 * @query   {number} limit - Maximum number of entries to return
 * @returns {Object} JSON response with database entries
 */
router.get("/query-database", async (req, res) => {
  try {
    const { CONFIG } = require('./config');
    const { limit = CONFIG.DEFAULT_PAGE_SIZE } = req.query;

    if (!notionDatabaseId) {
      return res.status(400).json({ error: "Missing NOTION_DATABASE_ID in environment variables." });
    }
    
    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit < 1) {
      return res.status(400).json({ error: "Invalid limit parameter. Must be a positive number." });
    }

    console.log(`Querying database ${notionDatabaseId} with limit=${parsedLimit}`);
    const response = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionDatabaseId}/query`, {
        page_size: parsedLimit
      })
    );

    const { extractPageTitle } = require('./page-utils');
    const rows = await Promise.all(response.data.results.map(async (item) => {
      try {
        const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;

        return {
          title,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null
        };
      } catch (err) {
        console.error(`Error processing database item ${item.id}:`, err.message);
        return {
          title: `Error (${item.id.substring(0, 8)})`,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null,
          error: true
        };
      }
    }));

    res.json({ success: true, count: rows.length, entries: rows });
  } catch (error) {
    handleApiError(res, error, "query-database");
  }
});

/**
 * @route   GET /health
 * @desc    Health check endpoint for Notion integration
 * @returns {Object} JSON response with health status
 */
router.get("/health", async (req, res) => {
  try {
    const { notionParentPageId } = require('./config');

    // Check if Notion API is accessible
    const response = await apiCallWithRetry(() => notionApi.get('/users/me'));
    
    // Verify required environment variables
    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);
    
    if (missingVars.length > 0) {
      return res.status(503).json({
        status: 'degraded',
        message: 'Missing required environment variables',
        details: { missingVars }
      });
    }
    
    // Check if parent page exists
    try {
      await apiCallWithRetry(() => notionApi.get(`/pages/${notionParentPageId}`));
    } catch (error) {
      return res.status(503).json({
        status: 'degraded',
        message: 'Parent page ID is invalid or inaccessible',
        details: { error: error.message }
      });
    }
    
    // Include cache stats
    const cacheStats = cache.getStats();
    
    res.json({ 
      status: 'healthy', 
      message: 'Notion integration is working properly',
      version: '1.0.0',
      timestamp: new Date().toISOString(),
      cache: cacheStats
    });
  } catch (error) {
    res.status(503).json({ 
      status: 'unhealthy', 
      message: 'Unable to connect to Notion API',
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

// Add a catch-all route to handle invalid endpoints
router.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint ${req.originalUrl} does not exist`,
    availableEndpoints: [
      'GET /list-pages',
      'PUT /write-page-by-title',
      'PATCH /append-to-page-by-title',
      'PATCH /update-page',
      'GET /query-database',
      'PUT /post-standalone-page',
      'DELETE /page/:id',
      'GET /read-memory',
      'PATCH /create-memory',
      'PATCH /update-memory',
      'DELETE /delete-memory',
      'GET /health'
    ]
  });
});

module.exports = router;

/**
 * Notion Memory Routes
 * 
 * This module provides Express route handlers for Notion memory operations including:
 * - Reading memory entries (with optional key filtering)
 * - Creating new memory entries
 * - Updating existing memory entries
 * - Deleting memory entries
 */

const express = require('express');
const router = express.Router();

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  normalizeKey
} = require('./api-utils');

const { 
  notionMemoryDBId 
} = require('./config');

/**
 * @route   GET /read-memory
 * @desc    Reads memory entries from Notion, with optional key filtering
 * @query   {string} key - Optional key to filter by
 * @returns {Object} JSON response with memory data
 */
router.get("/read-memory", async (req, res) => {
  try {
    if (!notionMemoryDBId) {
      return res.status(400).json({ error: "Missing GPT_MEMORY in environment variables." });
    }
    
    const rawKey = req.query.key;
    let body = {};
    
    if (rawKey) {
      try {
        const normalizedKey = normalizeKey(rawKey);
        body = {
          filter: {
            property: "Key",
            title: { equals: normalizedKey }
          }
        };
      } catch (e) {
        return res.status(400).json({ 
          error: "Invalid key format.", 
          details: e.message 
        });
      }
    }

    const response = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionMemoryDBId}/query`, body)
    );

    const memory = response.data.results.map(page => {
      const key = page.properties.Key?.title?.[0]?.plain_text || "(no key)";
      const value = page.properties.Value?.rich_text?.[0]?.plain_text || "";
      const lastUpdated = page.properties.LastUpdated?.date?.start || null;
      return { key, value, lastUpdated, id: page.id };
    });

    if (rawKey && memory.length === 0) {
      return res.status(404).json({ 
        error: `Memory key '${rawKey}' not found.`,
        message: "No matching memory entry found"
      });
    }

    res.json({ 
      success: true, 
      memory: rawKey ? memory[0] : memory,
      count: memory.length
    });
  } catch (err) {
    handleApiError(res, err, "read-memory");
  }
});

/**
 * @route   PATCH /create-memory
 * @desc    Creates a new memory entry or updates an existing one
 * @body    {string} line - Memory entry in format "key: value"
 * @returns {Object} JSON response with creation/update status
 */
router.patch("/create-memory", async (req, res) => {
  try {
    const { line } = req.body;
    
    if (!notionMemoryDBId) {
      return res.status(400).json({ error: "Missing GPT_MEMORY in environment variables." });
    }
    
    if (!line || typeof line !== 'string' || !line.includes(":")) {
      return res.status(400).json({ 
        error: "Missing or malformed memory line. Format must be 'key: value'" 
      });
    }

    const [keyPart, ...rest] = line.split(":");
    
    // Validate key is not empty after normalization
    const key = normalizeKey(keyPart);
    if (!key) {
      return res.status(400).json({ error: "Key cannot be empty." });
    }
    
    const value = rest.join(":").trim();
    if (!value) {
      return res.status(400).json({ error: "Value cannot be empty." });
    }

    // Check if key already exists to avoid duplicates
    const existingQuery = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionMemoryDBId}/query`, {
        filter: { property: "Key", title: { equals: key } }
      })
    );

    if (existingQuery.data.results.length > 0) {
      const existingId = existingQuery.data.results[0].id;
      
      // Update existing memory instead of creating a duplicate
      await apiCallWithRetry(() => 
        notionApi.patch(`/pages/${existingId}`, {
          properties: {
            Value: { rich_text: [{ text: { content: value } }] },
            LastUpdated: { date: { start: new Date().toISOString() } }
          }
        })
      );
      
      return res.json({ 
        success: true, 
        updated: true,
        pageId: existingId,
        message: `Updated existing memory with key '${keyPart.trim()}'`
      });
    }

    // Create new memory entry
    const response = await apiCallWithRetry(() => 
      notionApi.post('/pages', {
        parent: { database_id: notionMemoryDBId },
        properties: {
          Key: { title: [{ text: { content: key } }] },
          Value: { rich_text: [{ text: { content: value } }] },
          LastUpdated: { date: { start: new Date().toISOString() } }
        }
      })
    );

    res.json({ 
      success: true, 
      created: true,
      pageId: response.data.id,
      message: `Created new memory with key '${keyPart.trim()}'`
    });
  } catch (err) {
    handleApiError(res, err, "create-memory");
  }
});

/**
 * @route   PATCH /update-memory
 * @desc    Updates an existing memory entry by key
 * @body    {string} key - The key of the memory to update
 * @body    {string} value - The new value to set
 * @returns {Object} JSON response with update status
 */
router.patch("/update-memory", async (req, res) => {
  try {
    const { key, value } = req.body;
    
    if (!notionMemoryDBId) {
      return res.status(400).json({ error: "Missing GPT_MEMORY in environment variables." });
    }
    
    if (!key || typeof key !== 'string') {
      return res.status(400).json({ error: "Missing or invalid key." });
    }
    
    if (!value || typeof value !== 'string') {
      return res.status(400).json({ error: "Missing or invalid value." });
    }

    let decodedKey;
    try {
      decodedKey = normalizeKey(key);
      if (!decodedKey) {
        return res.status(400).json({ error: "Key cannot be empty after normalization." });
      }
    } catch (e) {
      return res.status(400).json({ 
        error: "Invalid key format.", 
        details: e.message 
      });
    }

    const query = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionMemoryDBId}/query`, {
        filter: { property: "Key", title: { equals: decodedKey } }
      })
    );

    const pageId = query.data.results[0]?.id;
    if (!pageId) {
      return res.status(404).json({ 
        error: `No entry found for key '${key}'`,
        message: "Memory key not found"
      });
    }

    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, {
        properties: {
          Value: { rich_text: [{ text: { content: value } }] },
          LastUpdated: { date: { start: new Date().toISOString() } }
        }
      })
    );

    res.json({ 
      success: true, 
      message: `Memory updated for key '${key}'`,
      pageId
    });
  } catch (err) {
    handleApiError(res, err, "update-memory");
  }
});

