    if (!notionMemoryDBId) {
      return res.status(400).json({ error: "Missing GPT_MEMORY in environment variables." });
    }
    
    if (!key || typeof key !== 'string') {
      return res.status(400).json({ error: "Missing or invalid key." });
    }

    let decodedKey;
    try {
      decodedKey = normalizeKey(key);
      if (!decodedKey) {
        return res.status(400).json({ error: "Key cannot be empty after normalization." });
      }
    } catch (e) {
      return res.status(400).json({ 
        error: "Invalid key format.", 
        details: e.message 
      });
    }

    const query = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionMemoryDBId}/query`, {
        filter: { property: "Key", title: { equals: decodedKey } }
      })
    );

