/**
 * Converts Notion blocks to markdown format
 * @param {Array} blocks - Array of Notion blocks
 * @returns {string} - Markdown representation of the blocks
 */
function blocksToMarkdown(blocks) {
  if (!blocks || !Array.isArray(blocks)) return '';

  return blocks.map(block => {
    switch (block.type) {
      case 'paragraph':
        const paragraphText = extractTextFromRichText(block.paragraph.rich_text);
        return paragraphText ? `${paragraphText}\n\n` : '\n';

      case 'heading_1':
        return `# ${extractTextFromRichText(block.heading_1.rich_text)}\n\n`;

      case 'heading_2':
        return `## ${extractTextFromRichText(block.heading_2.rich_text)}\n\n`;

      case 'heading_3':
        return `### ${extractTextFromRichText(block.heading_3.rich_text)}\n\n`;

      case 'bulleted_list_item':
        return `* ${extractTextFromRichText(block.bulleted_list_item.rich_text)}\n`;

      case 'numbered_list_item':
        return `1. ${extractTextFromRichText(block.numbered_list_item.rich_text)}\n`;

      case 'code':
        return `\`\`\`${block.code.language || 'plain_text'}\n${extractTextFromRichText(block.code.rich_text)}\n\`\`\`\n\n`;

      case 'quote':
        return `> ${extractTextFromRichText(block.quote.rich_text)}\n\n`;

      case 'callout':
        const emoji = block.callout.icon?.emoji || '💡';
        return `> ${emoji} ${extractTextFromRichText(block.callout.rich_text)}\n\n`;

      case 'to_do':
        const checkbox = block.to_do.checked ? '[x]' : '[ ]';
        return `${checkbox} ${extractTextFromRichText(block.to_do.rich_text)}\n`;

      case 'toggle':
        return `>>> ${extractTextFromRichText(block.toggle.rich_text)}\n\n`;

      case 'divider':
        return `---\n\n`;

      // Add other block types as needed

      default:
        return '';
    }
  }).join('');
}

/**
 * Helper function to extract plain text from rich_text array
 * @param {Array} richText - Notion rich_text array
 * @returns {string} - Plain text representation
 */
function extractTextFromRichText(richText) {
  if (!richText || !Array.isArray(richText)) return '';
  return richText.map(rt => rt.plain_text || rt.text?.content || '').join('');
}
