/**
 * Parses markdown text into Notion block objects
 * @param {string} markdown - Markdown text to parse
 * @returns {Array} Array of Notion block objects
 */
const parseMarkdownToBlocks = (markdown) => {
  if (!markdown || typeof markdown !== 'string') {
    return [];
  }

  const lines = markdown.split('\n');
  const blocks = [];
  let codeBlock = null;
  let codeBlockLanguage = '';
  let i = 0;

  while (i < lines.length) {
    const line = lines[i].trim();
    const nextLine = i + 1 < lines.length ? lines[i + 1].trim() : '';

    // Skip empty lines
    if (line === '') {
      i++;
      continue;
    }

    // Handle code blocks
    if (line.startsWith('```')) {
      if (codeBlock === null) {
        // Start of code block
        codeBlockLanguage = line.substring(3).trim() || 'plain text';
        codeBlock = '';
        i++;
        continue;
      } else {
        // End of code block
        blocks.push(createCodeBlock(codeBlock, codeBlockLanguage));
        codeBlock = null;
        i++;
        continue;
      }
    }

    // Continue collecting code block content
    if (codeBlock !== null) {
      codeBlock += (codeBlock ? '\n' : '') + line;
      i++;
      continue;
    }

    // Handle headings
    if (line.startsWith('# ')) {
      blocks.push(createHeadingBlock(line.substring(2), 1));
      i++;
      continue;
    }

    if (line.startsWith('## ')) {
      blocks.push(createHeadingBlock(line.substring(3), 2));
      i++;
      continue;
    }

    if (line.startsWith('### ')) {
      blocks.push(createHeadingBlock(line.substring(4), 3));
      i++;
      continue;
    }

    // Handle horizontal rule
