router.delete('/memory/:memoryId', asyncHandler(async (req, res) => {
  const { memoryId } = req.params;
  
  const errorMsg = validateParams({ memoryId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  // Archive the page (Notion's way of "deleting")
  await notionClient.updatePage(memoryId, { archived: true });
  
  res.json({
    success: true,
    message: 'Memory entry archived successfully',
    id: memoryId
  });
}));

