/**
 * page-routes.js
 * Express router for Notion page-related operations
 */

const express = require('express');
const router = express.Router();
const { createNotionClient } = require('./api');
const pageUtils = require('./page-utils');
const blockUtils = require('./block-utils');
const markdownUtils = require('./markdown-utils');

// Initialize Notion client
const notionClient = createNotionClient(process.env.NOTION_API_KEY);

/**
 * Error handler wrapper for async route handlers
 * @param {Function} fn - Async route handler function
 * @returns {Function} - Error-handled route handler
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Validates required parameters and returns an error message if missing
 * @param {Object} params - Parameters to validate
 * @returns {string|null} - Error message or null if valid
 */
const validateParams = (params) => {
  for (const [key, value] of Object.entries(params)) {
    if (!value) {
      return `Missing required parameter: ${key}`;
    }
  }
  return null;
};

// ROUTES

/**
 * Get a page by ID
 * GET /api/notion/pages/:pageId
 */
router.get('/:pageId', asyncHandler(async (req, res) => {
  const { pageId } = req.params;
  
  const errorMsg = validateParams({ pageId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  const page = await notionClient.getPage(pageId);
  
  // Extract page properties for a cleaner response
  const properties = pageUtils.extractPageProperties(page);
  
  res.json({
    id: page.id,
    url: page.url,
    created_time: page.created_time,
    last_edited_time: page.last_edited_time,
    properties
  });
}));

/**
