/**
 * Checks if content is already in Notion block format
 * @param {*} content - Content to check
 * @returns {boolean} True if content is in block format
 */
const isBlockFormat = (content) => {
    return Array.isArray(content) && 
           content.length > 0 && 
           content.every(item => typeof item === 'object' && item.type);
  };
  
  /**
   * Processes content into Notion blocks if not already in block format
   * @param {string|Array} content - Content to process
   * @returns {Array} Content in block format
   */
  const processIntoBlocks = (content) => {
    if (isBlockFormat(content)) {
      return content;
    }
    
    if (Array.isArray(content)) {
      return content.map(item => {
        if (typeof item === 'string') {
          return createParagraphBlock(item);
        }
        return item;
      });
    }
    
    if (typeof content === 'string') {
      // Split by double newlines to get paragraphs
      const paragraphs = content.split(/\n\n+/);
      return paragraphs
        .filter(p => p.trim().length > 0)
        .map(p => createParagraphBlock(p.trim()));
    }
    
    return [];
  };
  
  /**
   * Creates a rich text object
   * @param {string} content - Text content
   * @param {Object} annotations - Optional annotations for formatting
   * @returns {Object} Rich text object
   */
  const createRichText = (content, annotations = {}) => {
    return {
      type: 'text',
      text: { content },
      annotations: {
        bold: annotations.bold || false,
        italic: annotations.italic || false,
        strikethrough: annotations.strikethrough || false,
        underline: annotations.underline || false,
        code: annotations.code || false,
        color: annotations.color || 'default'
      }
    };
  };
  
  /**
   * Converts a string or array of strings to rich text array
   * @param {string|Array} text - Text content or array of rich text objects
   * @returns {Array} Array of rich text objects
   */
  const toRichTextArray = (text) => {
    if (!text) return [];
    
    if (Array.isArray(text)) {
      if (text.length === 0) return [];
      // If already rich text array format, return as is
      if (text[0].type && text[0].text) return text;
      // Convert array of strings to rich text objects
      return text.map(t => createRichText(String(t)));
    }
    
    return [createRichText(String(text))];
  };
  
  /**
   * Creates a paragraph block
   * @param {string|Array} text - Text content or rich text array
   * @returns {Object} Paragraph block
   */
  const createParagraphBlock = (text) => {
    return {
      type: 'paragraph',
      paragraph: {
        rich_text: toRichTextArray(text)
      }
    };
  };
  
  /**
