   * Creates a column list block with columns
   * @param {Array} columnContents - Array of arrays, each sub-array contains blocks for one column
   * @returns {Object} Column list block with column children
   */
  const createColumnListBlock = (columnContents) => {
    if (!Array.isArray(columnContents) || columnContents.length === 0) {
      return null;
    }
    
    const columnList = {
      type: 'column_list',
      column_list: {
        children: []
      }
    };
    
    // Create column blocks
    columnContents.forEach(columnBlocks => {
      const column = {
        type: 'column',
        column: {
          children: processIntoBlocks(columnBlocks)
        }
      };
      columnList.column_list.children.push(column);
    });
    
    return columnList;
  };
  
  /**
   * Creates a template block
   * @param {string|Array} text - Template text or rich text array
   * @param {Array} children - Child blocks for the template
   * @returns {Object} Template block
   */
  const createTemplateBlock = (text, children = []) => {
    const block = {
      type: 'template',
      template: {
        rich_text: toRichTextArray(text)
      }
    };
    
    if (children.length > 0) {
      block.template.children = processIntoBlocks(children);
    }
    
    return block;
  };
  
  /**
   * Creates a synced block
   * @param {string} syncedFrom - Block ID to sync from (null for original synced block)
   * @param {Array} children - Child blocks (only used for original synced blocks)
   * @returns {Object} Synced block
   */
  const createSyncedBlock = (syncedFrom = null, children = []) => {
    const block = {
      type: 'synced_block',
      synced_block: {}
    };
    
    if (syncedFrom) {
      // This is a synced copy that references an original
      block.synced_block.synced_from = {
        type: 'block_id',
        block_id: syncedFrom
      };
    } else {
      // This is an original synced block
      block.synced_block.children = processIntoBlocks(children);
    }
    
    return block;
  };
  
  /**
   * Creates a link_to_page block that links to a page
   * @param {string} pageId - ID of the page to link to
   * @returns {Object} Link to page block
   */
  const createLinkToPageBlock = (pageId) => {
