    }
    
    return block;
  };
  
  /**
   * Creates a PDF block from a URL
   * @param {string} url - PDF URL
   * @param {string|Array} caption - Optional caption
   * @returns {Object} PDF block
   */
  const createPdfBlock = (url, caption = '') => {
    const block = {
      type: 'pdf',
      pdf: {
