    }
    
    return block;
  };
  
  /**
   * Creates a file block from a URL
   * @param {string} url - File URL
   * @param {string} name - File name
   * @returns {Object} File block
   */
  const createFileBlock = (url, name) => {
    return {
      type: 'file',
      file: {
        type: 'external',
        external: {
          url
        },
        caption: name ? toRichTextArray(name) : []
      }
    };
  };
  
  module.exports = {
    // Block detection and processing
    isBlockFormat,
    processIntoBlocks,
    
    // Rich text helpers
    createRichText,
    toRichTextArray,
    
    // Basic blocks
    createParagraphBlock,
    createHeadingBlock,
    createBulletedListItemBlock,
    createNumberedListItemBlock,
    createToDoBlock,
    createCodeBlock,
    createQuoteBlock,
    createDividerBlock,
    createToggleBlock,
    createCalloutBlock,
    
    // Media blocks
    createImageBlock,
    createVideoBlock,
    createFileBlock,
    createPdfBlock,
    createEmbedBlock,
    
    // Complex blocks
    createBookmarkBlock,
    createEquationBlock,
    createTableBlock,
    createTableOfContentsBlock,
    createBreadcrumbBlock,
    createColumnListBlock,
    createTemplateBlock,
    createSyncedBlock,
    createLinkToPageBlock,
    createLinkPreviewBlock,
    
    // Block manipulation
    addChildrenToBlock
