    expect(response.status).toBe(200);
    expect(response.data.markdown).toContain('E2E Test Page');
  });

  test('Should archive the test page when done', async () => {
    const response = await axios.delete(`${API_URL}/pages/${createdPageId}`);

    expect(response.status).toBe(200);
    expect(response.data.success).toBe(true);
