## End-to-End Testing

For end-to-end testing, you'll need a real Notion workspace with test databases. Create a separate `.env.e2e` file:

```
NOTION_API_KEY=your_real_notion_api_key
PORT=3002
TEST_DATABASE_ID=your_test_database_id
```

Then create E2E test scripts:

```javascript
// tests/e2e/notion-api.test.js
require('dotenv').config({ path: '.env.e2e' });
const axios = require('axios');

// Start your server before running these tests
const API_URL = `http://localhost:${process.env.PORT || 3002}/api/notion`;
const TEST_DB_ID = process.env.TEST_DATABASE_ID;

describe('Notion API E2E Tests', () => {
  let createdPageId;

  test('Should create a new page in test database', async () => {
    const response = await axios.post(`${API_URL}/pages/database/${TEST_DB_ID}`, {
      title: `Test Page ${Date.now()}`,
      properties: {
        tags: {
          multi_select: [{ name: 'e2e-test' }]
        }
      },
      content: '# E2E Test Page\n\nThis page was created by an E2E test.',
      contentFormat: 'markdown'
    });

    expect(response.status).toBe(201);
    expect(response.data.id).toBeTruthy();
    createdPageId = response.data.id;
  });

  test('Should retrieve created page', async () => {
    const response = await axios.get(`${API_URL}/pages/${createdPageId}`);

    expect(response.status).toBe(200);
    expect(response.data.id).toBe(createdPageId);
  });

  test('Should get page content as markdown', async () => {
    const response = await axios.get(`${API_URL}/pages/${createdPageId}/markdown`);

    expect(response.status).toBe(200);
    expect(response.data.markdown).toContain('E2E Test Page');
  });

  test('Should archive the test page when done', async () => {
    const response = await axios.delete(`${API_URL}/pages/${createdPageId}`);

    expect(response.status).toBe(200);
    expect(response.data.success).toBe(true);
    expect(response.data.archived).toBe(true);
  });
});
```

