/**
 * Create a new database
 * POST /api/notion/memory-db/database
 * Body:
 *  - parent_page_id: ID of parent page
 *  - title: Database title
 *  - description: Database description (optional)
 *  - properties: Database property schema
 */
router.post('/database', asyncHandler(async (req, res) => {
  const { parent_page_id, title, description = '', properties } = req.body;
  
  const errorMsg = validateParams({ parent_page_id, title, properties });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  // Create database
  const newDatabase = await notionClient.client.databases.create({
    parent: {
      type: 'page_id',
      page_id: parent_page_id
    },
    title: [
      {
        type: 'text',
        text: {
          content: title
        }
      }
    ],
    description: [
      {
        type: 'text',
        text: {
          content: description
        }
      }
    ],
    properties
  });
  
  res.status(201).json({
