/**
 * api-utils.js
 * Minimalist utility functions for the Notion API integration
 */

/**
 * Sanitizes input strings to prevent injection attacks
 * @param {string} input - The input string to sanitize
 * @returns {string} - The sanitized string
 */
function sanitizeInput(input) {
  // Return empty string for null or undefined inputs
  if (input === null || input === undefined) {
    return '';
  }

  // Convert to string if not already
  const str = String(input);

  // Remove potentially harmful characters and trim whitespace
  return str
    .replace(/[<>'"\\]/g, '') // Remove potentially harmful characters like < > ' " \
    .replace(/\s+/g, ' ')     // Replace multiple spaces with a single space
    .trim();                  // Remove leading and trailing whitespace
}

/**
 * Creates a standardized error response object
 * @param {string} message - Error message
 * @param {number} status - HTTP status code
 * @returns {Object} - Standardized error object
 */
function createErrorResponse(message, status = 400) {
  return {
    error: {
      message: message || 'An error occurred',
      status: status
    }
  };
}

/**
 * Wraps an async function with standardized error handling
 * @param {Function} fn - Async function to wrap
 * @param {Response} res - Express response object
 * @returns {Promise} - Promise with error handling
 */
async function handleAsyncError(fn, res) {
  try {
    return await fn();
  } catch (error) {
    const status = error.status || 500;
    res.status(status).json(createErrorResponse(error.message, status));
  }
}

module.exports = {
  sanitizeInput,
  createErrorResponse,
  handleAsyncError
};

