for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim();

  // Check if line starts a JSON object
  if (line === '{') {
    currentJson = '{';
  } 
  // Check if line closes a JSON object
  else if (line === '}') {
    currentJson += '}';
    try {
      const jsonObj = JSON.parse(currentJson);
      logEntries.push(jsonObj);
      currentJson = '';
    } catch (e) {
      // Not a complete JSON object yet
      currentJson += '\n';
    }
  }
  // Add line to current JSON being built
  else if (currentJson) {
    currentJson += '\n' + line;
  }
  // Collect non-JSON lines
  else if (line.startsWith('✅')) {
    nonJsonLines.push(line);
  }
}

