    if (!requestIds[entry.requestId]) {
      requestIds[entry.requestId] = 1;
    } else {
      requestIds[entry.requestId]++;
    }
  }

  if (entry.data && entry.data.path) {
    const path = entry.data.path;
    if (!paths[path]) {
      paths[path] = 1;
    } else {
      paths[path]++;
    }
