 Based on the analysis, here are specific solutions to address the `ServerDisconnectedError` issue:

## 1. Handle Duplicate Requests

```javascript
// Implement request deduplication with a simple in-memory cache
const requestCache = new Map();

app.use((req, res, next) => {
  const requestKey = `${req.method}:${req.path}:${JSON.stringify(req.query)}`;

  if (requestCache.has(requestKey)) {
    const cachedTimestamp = requestCache.get(requestKey);
    // Only consider it a duplicate if it's within 2 seconds
    if (Date.now() - cachedTimestamp < 2000) {
      console.log(`Duplicate request detected: ${requestKey}`);
      return res.status(429).json({ error: "Too many duplicate requests" });
    }
  }

  requestCache.set(requestKey, Date.now());
  // Clean up old cache entries
  setTimeout(() => requestCache.delete(requestKey), 5000);

  next();
});
```

## 2. Implement Proper Timeout Handling

```javascript
// For Node.js with Express and Axios for API calls
app.get('/notion/list-pages', async (req, res) => {
  // Set a timeout for the response
  res.setTimeout(30000, () => {
    console.log('Response timeout, client may have disconnected');
    if (!res.headersSent) {
      res.status(503).json({ error: 'Service taking too long to respond' });
    }
  });

  try {
    // Set a timeout for the Notion API request
    const notionResponse = await axios.get('https://api.notion.com/v1/search', {
      timeout: 25000,  // 25-second timeout
      headers: {
        'Authorization': `Bearer ${process.env.NOTION_API_KEY}`,
        'Notion-Version': '2022-06-28'
      },
      params: {
        filter: { property: 'object', value: 'page' },
        page_size: 100
      }
    });

    // Return successful response
    res.json(notionResponse.data);
  } catch (error) {
    console.error('Notion API error:', error.message);

    // Send appropriate error message
    if (error.code === 'ECONNABORTED') {
      res.status(504).json({ error: 'Notion API timeout' });
    } else if (error.response) {
      res.status(error.response.status).json({ 
        error: `Notion API error: ${error.response.statusText}` 
      });
    } else {
      res.status(500).json({ error: 'Internal server error' });
    }
  }
});
```

## 3. Optimize Recursive Operations

```javascript
// Instead of a single recursive call, implement pagination with smaller batches
async function listNotionPages(req, res) {
  try {
    // Send headers early to keep connection alive
    res.writeHead(200, {
      'Content-Type': 'application/json',
      'Transfer-Encoding': 'chunked',
      'X-Accel-Buffering': 'no' // Disable Nginx buffering if applicable
    });

    // Start the response as a JSON array
    res.write('{"pages":[');

    let hasMore = true;
    let startCursor = undefined;
    let pageCount = 0;
    let isFirstResult = true;

    // Process in smaller batches instead of all at once
    while (hasMore) {
      const response = await notionClient.search({
        filter: { property: 'object', value: 'page' },
        page_size: 20, // Smaller batch size
        start_cursor: startCursor
      });

      // Process each page
      for (const page of response.results) {
        if (!isFirstResult) {
          res.write(',');
        }
        isFirstResult = false;

        // Send this page data immediately
        res.write(JSON.stringify(getPageData(page)));
        pageCount++;

        // Add a heartbeat to keep connection alive
        res.write(''); // Empty write keeps the connection open
      }

      // Update for next iteration
      hasMore = response.has_more;
      startCursor = response.next_cursor;

      // Limit total pages for safety
      if (pageCount >= 100) {
        hasMore = false;
      }
    }

    // Close the JSON response
    res.write(']}');
    res.end();

  } catch (error) {
    // If headers haven't been sent yet, send an error response
    if (!res.headersSent) {
      res.status(500).json({ error: error.message });
    } else {
      // If we've already started sending data, try to end cleanly
      try {
        res.write(']}');
        res.end();
      } catch (e) {
        console.error('Error ending response:', e);
      }
    }
  }
}
```

## 4. Implement Server-Side Caching

```javascript
const NodeCache = require('node-cache');
const pageCache = new NodeCache({ stdTTL: 300 }); // 5-minute cache

app.get('/notion/list-pages', async (req, res) => {
  const cacheKey = 'notion-pages';

  // Check if we have a cached response
  if (pageCache.has(cacheKey)) {
    console.log('Returning cached Notion pages');
    return res.json(pageCache.get(cacheKey));
  }

  try {
    // Fetch from Notion
    const pages = await fetchNotionPages();

    // Cache the response
    pageCache.set(cacheKey, pages);

    // Return to client
    res.json(pages);
  } catch (error) {
    console.error('Error fetching Notion pages:', error);
    res.status(500).json({ error: 'Failed to fetch pages' });
  }
});

// Add a background refresh that doesn't affect users
setInterval(async () => {
  try {
    const cacheKey = 'notion-pages';
    const pages = await fetchNotionPages();
    pageCache.set(cacheKey, pages);
    console.log('Background cache refresh completed');
  } catch (error) {
    console.error('Background cache refresh failed:', error);
  }
}, 240000); // Every 4 minutes
```

## 5. Improve Path Handling

```javascript
// Normalize paths for consistent handling
app.use((req, res, next) => {
  // Normalize paths to ensure consistency
  if (req.path.startsWith('/notion/') || req.path.startsWith('/notion')) {
    req.normalizedPath = req.path;
  } else if (req.url.includes('/notion/')) {
    // Extract the path from the URL if needed
    req.normalizedPath = '/notion' + req.path;
  } else {
