  // Set a timeout for the response
  res.setTimeout(30000, () => {
    console.log('Response timeout, client may have disconnected');
    if (!res.headersSent) {
      res.status(503).json({ error: 'Service taking too long to respond' });
    }
  });

  try {
    // Set a timeout for the Notion API request
    const notionResponse = await axios.get('https://api.notion.com/v1/search', {
      timeout: 25000,  // 25-second timeout
      headers: {
        'Authorization': `Bearer ${process.env.NOTION_API_KEY}`,
        'Notion-Version': '2022-06-28'
      },
      params: {
        filter: { property: 'object', value: 'page' },
        page_size: 100
      }
    });

    // Return successful response
    res.json(notionResponse.data);
  } catch (error) {
    console.error('Notion API error:', error.message);

    // Send appropriate error message
