## 3. Optimize Recursive Operations

```javascript
// Instead of a single recursive call, implement pagination with smaller batches
async function listNotionPages(req, res) {
  try {
    // Send headers early to keep connection alive
    res.writeHead(200, {
      'Content-Type': 'application/json',
      'Transfer-Encoding': 'chunked',
      'X-Accel-Buffering': 'no' // Disable Nginx buffering if applicable
    });

    // Start the response as a JSON array
    res.write('{"pages":[');

    let hasMore = true;
    let startCursor = undefined;
    let pageCount = 0;
    let isFirstResult = true;

    // Process in smaller batches instead of all at once
    while (hasMore) {
      const response = await notionClient.search({
        filter: { property: 'object', value: 'page' },
        page_size: 20, // Smaller batch size
        start_cursor: startCursor
      });

      // Process each page
      for (const page of response.results) {
        if (!isFirstResult) {
          res.write(',');
        }
        isFirstResult = false;

        // Send this page data immediately
        res.write(JSON.stringify(getPageData(page)));
        pageCount++;

        // Add a heartbeat to keep connection alive
        res.write(''); // Empty write keeps the connection open
      }

      // Update for next iteration
      hasMore = response.has_more;
      startCursor = response.next_cursor;

      // Limit total pages for safety
      if (pageCount >= 100) {
        hasMore = false;
      }
    }

    // Close the JSON response
    res.write(']}');
    res.end();

  } catch (error) {
    // If headers haven't been sent yet, send an error response
    if (!res.headersSent) {
      res.status(500).json({ error: error.message });
    } else {
      // If we've already started sending data, try to end cleanly
      try {
        res.write(']}');
        res.end();
      } catch (e) {
        console.error('Error ending response:', e);
      }
    }
  }
}
```

