    const memoryUsage = process.memoryUsage();
    
    // Get system info
    const systemInfo = {
      platform: process.platform,
      arch: process.arch,
      nodeVersion: process.version,
      uptime: process.uptime()
    };
    
    // Get feature flags
    const features = { ...FEATURES };
    
    // Get cache stats
    const cacheStats = getCacheStats();
    
    // Get rate limiter stats
    const rateLimitStats = getRateLimitStats();
    
    // Get logging config
    const loggingConfig = logger.getConfig();
    
    // Environment variables (excluding sensitive data)
    const environment = {
      NODE_ENV: process.env.NODE_ENV,
      PORT: process.env.PORT || 3000,
      // Don't include tokens or secrets
      NOTION_CONFIGURED: !!process.env.NOTION_TOKEN,
      GITHUB_CONFIGURED: !!process.env.GITHUB_TOKEN,
      GPT_MEMORY_CONFIGURED: !!process.env.GPT_MEMORY
    };
    
    const debugInfo = {
      timestamp: new Date().toISOString(),
      systemInfo,
      memoryUsage: {
        rss: `${Math.round(memoryUsage.rss / 1024 / 1024)} MB`,
        heapTotal: `${Math.round(memoryUsage.heapTotal / 1024 / 1024)} MB`,
        heapUsed: `${Math.round(memoryUsage.heapUsed / 1024 / 1024)} MB`,
        external: `${Math.round(memoryUsage.external / 1024 / 1024)} MB`
      },
      features,
      cache: cacheStats,
      rateLimiter: rateLimitStats,
      logging: loggingConfig,
      environment
    };
    
    res.json({
      success: true,
      debug: debugInfo
    });
  } catch (error) {
    logger.error("Error generating debug information", error, req.requestId);
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

// Error handling middleware
app.use(logger.errorLogger());

// Serve the OpenAPI spec file
app.get("/openapi.json", (req, res) => {
  logger.info("OpenAPI spec requested", null, req.requestId);
  res.sendFile(path.join(__dirname, "openapi.json"));
});

// Start the server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, "0.0.0.0", () => {
  console.log(`🚀 Server is running on port ${PORT}`);
  logger.info("Server started", { 
    port: PORT,
    features: FEATURES,
    cacheEnabled: FEATURES.CACHE_ENABLED,
    rateLimitingEnabled: FEATURES.RATE_LIMITING_ENABLED,
    loggingEnabled: FEATURES.LOGGING_ENABLED
  });
});

// Export for testing
module.exports = { app, server };

