      ttl: this.ttl,
      maxItems: this.maxItems,
      ...this.stats,
      hitRatio: this.stats.hits + this.stats.misses > 0 
        ? (this.stats.hits / (this.stats.hits + this.stats.misses)).toFixed(2)
        : 0
    };
  }
  
  /**
   * Enables or disables caching
   * @param {boolean} isEnabled - Whether caching should be enabled
   * @returns {Object} The current caching state
   */
  setEnabled(isEnabled) {
    this.enabled = isEnabled;
    
    if (isEnabled) {
      // Start cleanup timer if it's not running
      if (!this.cleanupTimer) {
        this.startPeriodicCleanup();
      }
      console.log(`🧠 Cache enabled (ttl=${this.ttl}ms, maxItems=${this.maxItems})`);
    } else {
      // Stop cleanup timer if it's running
      if (this.cleanupTimer) {
        clearInterval(this.cleanupTimer);
        this.cleanupTimer = null;
      }
      console.log('🧠 Cache disabled');
    }
    
    return { enabled: this.enabled };
  }
  
  /**
   * Updates the cache configuration
   * @param {Object} options - New configuration options
   * @param {number} [options.ttl] - New TTL in milliseconds
   * @param {number} [options.maxItems] - New maximum items per store
   * @param {number} [options.cleanupInterval] - New cleanup interval
   * @returns {Object} The updated configuration
   */
  updateConfig(options = {}) {
    const oldConfig = {
      ttl: this.ttl,
      maxItems: this.maxItems,
      cleanupInterval: this.cleanupInterval
    };
    
    if (options.ttl) this.ttl = options.ttl;
    if (options.maxItems) this.maxItems = options.maxItems;
    
    if (options.cleanupInterval && options.cleanupInterval !== this.cleanupInterval) {
      this.cleanupInterval = options.cleanupInterval;
      // Restart cleanup timer with new interval
      if (this.enabled && this.cleanupTimer) {
        this.startPeriodicCleanup();
      }
    }
    
    logger.info('Cache configuration updated', { 
      previous: oldConfig,
      current: {
        ttl: this.ttl,
        maxItems: this.maxItems,
        cleanupInterval: this.cleanupInterval
      }
    });
    
    return {
      ttl: this.ttl,
      maxItems: this.maxItems,
      cleanupInterval: this.cleanupInterval,
      enabled: this.enabled
    };
  }
}

