module.exports = router;

/**
 * Notion Page Operations Routes
 * 
 * This module provides Express route handlers for additional Notion page operations including:
 * - Appending content to existing pages
 * - Updating page content by ID
 * - Creating standalone pages
 * - Archiving pages
 */

const express = require('express');
const router = express.Router();

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  sanitizeInput 
} = require('./api-utils');

const { 
  notionParentPageId 
} = require('./config');

const { 
  cache 
} = require('./cache');

const { 
  createHeadingBlock, 
  createParagraphBlock,
  parseMarkdownToBlocks,
  isBlockFormat,
  processContentToBlocks,
  blocksToMarkdown
} = require('./block-utils');

const { 
  findPageByTitle 
} = require('./page-utils');

const logger = require('./logger');

/**
 * @route   PATCH /append-to-page-by-title
 * @desc    Appends content to an existing page by title, or creates a new page if it doesn't exist
 * @body    {string} title - The page title to append to
 * @body    {string|Array} content - The content to append (markdown string or block array)
 * @returns {Object} JSON response with operation status
 */
router.patch("/append-to-page-by-title", async (req, res) => {
  try {
    const { title, content } = req.body;

    // Input validation
    if (!title || !content) {
      logger.warn("Missing title or content for append operation", 
        { hasTitle: !!title, hasContent: !!content }, req.requestId);
      return res.status(400).json({ error: "Missing title or content." });
    }
    
    if (typeof title !== 'string') {
      logger.warn("Invalid title type for append operation", { titleType: typeof title }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid input. Title must be a string." 
      });
    }
    
    if (typeof content !== 'string' && !Array.isArray(content)) {
      logger.warn("Invalid content type for append operation", 
        { contentType: typeof content, isArray: Array.isArray(content) }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid content. Content must be a string or an array of blocks." 
      });
    }
    
    const sanitizedTitle = sanitizeInput(title);

    if (!sanitizedTitle) {
      logger.warn("Empty title after sanitization", { title }, req.requestId);
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    logger.info(`Attempting to append to page titled "${sanitizedTitle}"`, null, req.requestId);
    const match = await findPageByTitle(sanitizedTitle);
    let pageId;

    if (!match) {
      logger.info(`Page "${sanitizedTitle}" not found, creating new page`, null, req.requestId);
      const createRes = await apiCallWithRetry(() => 
        notionApi.post('/pages', {
          parent: { type: "page_id", page_id: notionParentPageId },
          properties: {
            title: [
              {
                type: "text",
                text: { content: sanitizedTitle }
              }
            ]
          }
        })
      , { requestId: req.requestId });

      pageId = createRes.data.id;
      logger.info(`Created new page with title "${sanitizedTitle}"`, { pageId }, req.requestId);
      
      // Clear cache after creating a new page
      cache.clear();
    } else {
      pageId = match.page.id;
      logger.info(`Found existing page with title "${sanitizedTitle}"`, { pageId }, req.requestId);
    }

    // Process content into blocks, handling both markdown and block formats
    const contentBlocks = processContentToBlocks(content);
    
    // Log whether we processed markdown or block format
    const contentFormat = isBlockFormat(content) ? 'block' : 'markdown';
    logger.info(`Processed content as ${contentFormat} format`, { contentFormat }, req.requestId);
    logger.debug(`Generated ${contentBlocks.length} blocks to append`, 
      { blockCount: contentBlocks.length }, req.requestId);
    
    // Handle API limits with chunks
    for (let i = 0; i < contentBlocks.length; i += 10) {
      const chunk = contentBlocks.slice(i, i + 10);
      logger.debug(`Appending chunk ${Math.floor(i/10) + 1}/${Math.ceil(contentBlocks.length/10)}`, 
        { chunkSize: chunk.length, offset: i }, req.requestId);
        
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: chunk
        })
      , { requestId: req.requestId });
    }

    // Invalidate cache
    cache.invalidate(pageId);
    logger.info(`Content successfully appended to page "${sanitizedTitle}"`, { pageId }, req.requestId);

    res.json({ 
      success: true, 
      pageId,
      message: match ? "Content appended to existing page" : "Created new page and appended content"
    });
  } catch (error) {
    logger.error("Error appending to page by title", error, req.requestId);
    handleApiError(res, error, "append-to-page-by-title");
  }
});

/**
 * @route   PATCH /update-page
 * @desc    Updates page content by ID
 * @body    {string} pageId - The Notion page ID to update
 * @body    {string|Array} content - The content to update (markdown string or block array)
 * @body    {boolean} [replaceAll=false] - Whether to replace all content (true) or append (false)
 * @returns {Object} JSON response with operation status
 */
router.patch("/update-page", async (req, res) => {
  try {
    const { pageId, content, replaceAll = false } = req.body;

    // Input validation
    if (!pageId || !content) {
      logger.warn("Missing pageId or content for update operation", 
        { hasPageId: !!pageId, hasContent: !!content }, req.requestId);
      return res.status(400).json({ error: "Missing pageId or content." });
    }
    
    // Validate pageId format
    if (typeof pageId !== 'string' || !pageId.match(/^[a-f0-9-]+$/i)) {
      logger.warn("Invalid pageId format", { pageId }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }
    
    // Validate content
    if (typeof content !== 'string' && !Array.isArray(content)) {
      logger.warn("Invalid content type for update operation", 
        { contentType: typeof content, isArray: Array.isArray(content) }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid content. Must be a string or an array of blocks." 
      });
    }
    
    logger.info(`Updating page with ID ${pageId}`, { pageId, replaceAll }, req.requestId);
    
    // Process content into blocks, handling both markdown and block formats
    const contentBlocks = processContentToBlocks(content);
    
    // Log whether we processed markdown or block format
    const contentFormat = isBlockFormat(content) ? 'block' : 'markdown';
    logger.info(`Processed content as ${contentFormat} format`, { contentFormat }, req.requestId);
    logger.debug(`Generated ${contentBlocks.length} blocks for update`, 
      { blockCount: contentBlocks.length }, req.requestId);
    
    // If replaceAll is true, we need to delete existing blocks first
    if (replaceAll) {
      try {
        logger.info(`Replacing all content: fetching existing blocks to archive`, { pageId }, req.requestId);
        
        // Get existing blocks
        const existingBlocksRes = await apiCallWithRetry(() => 
          notionApi.get(`/blocks/${pageId}/children?page_size=100`)
        , { requestId: req.requestId });
        
        // Archive existing blocks (Notion API doesn't allow bulk deletion, so we do it one by one)
        const blockIds = existingBlocksRes.data.results.map(block => block.id);
        
        logger.info(`Archiving ${blockIds.length} existing blocks`, 
          { blockCount: blockIds.length }, req.requestId);
        
        for (const blockId of blockIds) {
          logger.debug(`Archiving block ${blockId}`, { blockId }, req.requestId);
          await apiCallWithRetry(() => 
            notionApi.patch(`/blocks/${blockId}`, {
              archived: true
            })
          , { requestId: req.requestId });
        }
        
        logger.info(`Successfully archived ${blockIds.length} existing blocks`, 
          { blockCount: blockIds.length }, req.requestId);
      } catch (err) {
        logger.error("Error archiving existing blocks", err, req.requestId);
        // Continue with the update even if archiving fails
      }
    }
    
    // Handle API limits with chunks
    for (let i = 0; i < contentBlocks.length; i += 10) {
      const chunk = contentBlocks.slice(i, i + 10);
      logger.debug(`Updating with chunk ${Math.floor(i/10) + 1}/${Math.ceil(contentBlocks.length/10)}`, 
        { chunkSize: chunk.length, offset: i }, req.requestId);
        
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: chunk
        })
      , { requestId: req.requestId });
    }

    // Invalidate cache
    cache.invalidate(pageId);
    logger.info(`Content successfully updated for page ID ${pageId}`, 
      { pageId, replaceAll, blockCount: contentBlocks.length }, req.requestId);

    res.json({ 
      success: true, 
      updated: true, 
      replaced: replaceAll,
      pageId 
    });
  } catch (error) {
    logger.error("Error updating page", error, req.requestId);
    handleApiError(res, error, "update-page");
  }
});

