        cache.invalidate(key, 'titles');
        logger.debug(`Invalidated title cache for page ID ${pageId}`, null, req.requestId);
        break;
      }
    }

    res.json({ 
      success: true, 
      archived: true,
      message: `Page ${pageId} archived successfully`
    });
  } catch (error) {
