const express = require("express");
const app = express();
const path = require("path");

// Load environment variables
const NOTION_TOKEN = process.env.NOTION_TOKEN;
const NOTION_PARENT_PAGE_ID = process.env.NOTION_PARENT_PAGE_ID;
const NOTION_DATABASE_ID = process.env.NOTION_DATABASE_ID;
const NOTION_MEMORY_DB_ID = process.env.GPT_MEMORY;

// Apply JSON middleware
app.use(express.json());

// Import route modules
const pageRoutes = require("./notion/page-routes");
const memoryRoutes = require("./notion/memory-routes");

// Health Check
app.get("/", (req, res) => {
  res.send("✅ Notion API is live.");
});

// Status endpoint
app.get('/status', (req, res) => {
  const status = {
    ok: true,
    timestamp: new Date().toISOString(),
    notionReady: !!NOTION_TOKEN,
    parentPageReady: !!NOTION_PARENT_PAGE_ID,
    databaseReady: !!NOTION_DATABASE_ID,
    memoryReady: !!NOTION_MEMORY_DB_ID
  };

  status.message = `Notion API is online. Notion is ${status.notionReady ? 'connected' : 'not connected'}. ` +
                   `Parent page is ${status.parentPageReady ? 'configured' : 'not configured'}. ` +
                   `Database is ${status.databaseReady ? 'configured' : 'not configured'}. ` +
                   `Memory is ${status.memoryReady ? 'configured' : 'not configured'}.`;

  res.json(status);
});

// Mount route modules
app.use("/notion", pageRoutes);
app.use("/notion", memoryRoutes);

// Serve the OpenAPI spec file
app.get("/openapi.json", (req, res) => {
  res.sendFile(path.join(__dirname, "openapi.json"));
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, "0.0.0.0", () => {
  console.log(`🚀 Server is running on port ${PORT}`);
});

// Export for testing
module.exports = { app };

const axios = require('axios');

// Environment variables
const NOTION_TOKEN = process.env.NOTION_TOKEN;
const NOTION_PARENT_PAGE_ID = process.env.NOTION_PARENT_PAGE_ID;
const NOTION_DATABASE_ID = process.env.NOTION_DATABASE_ID;
const NOTION_MEMORY_DB_ID = process.env.GPT_MEMORY;

// Configured Axios instance for Notion API
const notionApi = axios.create({
  baseURL: 'https://api.notion.com/v1',
  headers: {
    Authorization: `Bearer ${NOTION_TOKEN}`,
    "Notion-Version": "2022-06-28",
    "Content-Type": "application/json"
  },
  timeout: 10000 // 10 seconds
});

/**
 * Handle API errors and respond with appropriate status codes
 * @param {Object} res - Express response object
 * @param {Error} error - Error that occurred
 * @param {string} context - Context for the error
 */
function handleApiError(res, error, context) {
  // Determine appropriate status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';

  if (error.response) {
    statusCode = error.response.status;
    errorMessage = error.response.data?.message || error.message;

    // Special handling for rate limit errors
    if (statusCode === 429) {
      errorMessage = `Rate limit exceeded. Please retry later.`;
    }
  } else if (error.request) {
    statusCode = 503; // Service Unavailable
    errorMessage = 'No response received from Notion API';
  } else {
    errorMessage = error.message;
  }

  console.error(`API Error in ${context}: ${errorMessage}`);

  res.status(statusCode).json({ 
    error: errorMessage,
    context
  });
}

/**
 * Safely sanitize input strings
 * @param {string} input - Input to sanitize
 * @param {string} defaultValue - Default value if input is invalid
 * @returns {string} - Sanitized string
 */
function sanitizeInput(input, defaultValue = "") {
  if (input === null || input === undefined) return defaultValue;
  if (typeof input !== 'string') {
    try {
      input = String(input);
    } catch (e) {
      return defaultValue;
    }
  }
  return input.trim();
}

/**
 * Extracts title from a Notion page object
 * @param {Object} page - Notion page object
 * @returns {string} - Page title or default
 */
async function extractPageTitle(page) {
  if (!page) return "Untitled Page";

  // For pages with properties
  if (page.properties) {
    // Check common title properties
    const titleProps = ['title', 'Name', 'Title'];
    for (const prop of titleProps) {
      const titleArray = page.properties[prop]?.title;
      if (titleArray && titleArray.length > 0) {
        const textContent = titleArray[0]?.plain_text || titleArray[0]?.text?.content;
        if (textContent) return textContent;
      }
    }
  }

  // For direct title property
  if (page.title) {
    if (Array.isArray(page.title) && page.title.length > 0) {
      return page.title[0]?.plain_text || page.title[0]?.text?.content || "Untitled Page";
    } else if (typeof page.title === 'string') {
      return page.title;
    }
  }

  // For child page blocks
  if (page.child_page?.title) {
    return page.child_page.title;
  }

  return `Untitled Page (${page.id ? page.id.substring(0, 8) : 'unknown'})`;
}

/**
 * Finds a page by title
 * @param {string} title - Title to search for
 * @param {boolean} exactMatch - Whether to require exact match
 * @returns {Promise<Object|null>} - Found page or null
 */
async function findPageByTitle(title, exactMatch = false) {
  title = sanitizeInput(title);
  if (!title) return null;

  const normalizedInput = title.toLowerCase();

  try {
    console.log(`Searching for page titled "${title}"`);

    const searchResponse = await notionApi.post('/search', {
      query: title,
      filter: { property: "object", value: "page" },
      page_size: 10
    });

    // No results
    if (!searchResponse.data.results.length) {
      return null;
    }

    // Get titles for all results
    const pages = await Promise.all(searchResponse.data.results.map(async (page) => {
      const extractedTitle = await extractPageTitle(page);
      return {
        page,
        title: extractedTitle
      };
    }));

    // Find exact match or closest match
    const exactMatchItem = pages.find(item => 
      item.title && item.title.toLowerCase() === normalizedInput
    );

    // If exact match is required and none found, return null
    if (exactMatch && !exactMatchItem) {
      return null;
    }

    return exactMatchItem || pages[0] || null;
  } catch (error) {
    console.error(`Error finding page for "${title}": ${error.message}`);
    return null;
  }
}

module.exports = {
  notionApi,
  handleApiError,
  sanitizeInput,
  extractPageTitle,
  findPageByTitle,
  NOTION_TOKEN,
  NOTION_PARENT_PAGE_ID,
  NOTION_DATABASE_ID,
  NOTION_MEMORY_DB_ID
};

const { sanitizeInput } = require('./api-utils');

// Constants
const MAX_CONTENT_LENGTH = 2000; // Maximum content length per block in Notion

/**
 * Creates a paragraph block or array of paragraph blocks if content exceeds max length
 * @param {string} content - Text content for the paragraph
 * @returns {Object|Array} - Paragraph block(s)
 */
function createParagraphBlock(content) {
  content = sanitizeInput(content, "");
  if (!content) return createSingleParagraphBlock("");

  // Split content if too long
  if (content.length > MAX_CONTENT_LENGTH) {
    const chunks = [];
    let currentChunk = "";

    // Split by sentences for more natural breaks
    const sentences = content.split(/(?<=[.!?])\s+/);

    for (const sentence of sentences) {
      if ((currentChunk + (currentChunk ? " " : "") + sentence).length > MAX_CONTENT_LENGTH) {
        if (currentChunk) {
          chunks.push(createSingleParagraphBlock(currentChunk));
          currentChunk = "";
        }

        // Handle very long sentences by splitting them by words
        if (sentence.length > MAX_CONTENT_LENGTH) {
          const words = sentence.split(/\s+/);
          let wordChunk = "";

          for (const word of words) {
            if ((wordChunk + (wordChunk ? " " : "") + word).length > MAX_CONTENT_LENGTH) {
              if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));

              // Split very long words
              if (word.length > MAX_CONTENT_LENGTH) {
                for (let i = 0; i < word.length; i += MAX_CONTENT_LENGTH) {
                  chunks.push(createSingleParagraphBlock(word.substring(i, i + MAX_CONTENT_LENGTH)));
                }
                wordChunk = "";
              } else {
                wordChunk = word;
              }
            } else {
              wordChunk += (wordChunk ? " " : "") + word;
            }
          }

          if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
        } else {
          currentChunk = sentence;
        }
      } else {
        currentChunk += (currentChunk ? " " : "") + sentence;
      }
    }

    if (currentChunk) chunks.push(createSingleParagraphBlock(currentChunk));
    return chunks;
  }

  return createSingleParagraphBlock(content);
}

/**
 * Creates a single paragraph block
 * @param {string} content - Text content
 * @returns {Object} - Notion paragraph block
 */
function createSingleParagraphBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "paragraph",
    paragraph: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a heading block
 * @param {string} content - Text content
 * @param {number} level - Heading level (1, 2, or 3)
 * @returns {Object} - Notion heading block
 */
function createHeadingBlock(content, level = 1) {
  content = sanitizeInput(content, "Untitled");

  // Validate level
  if (![1, 2, 3].includes(level)) {
    console.warn(`Invalid heading level: ${level}, defaulting to 1`);
    level = 1;
  }

  const headingType = `heading_${level}`;
  return {
    object: "block",
    type: headingType,
    [headingType]: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a bulleted list item block
 * @param {string} content - Text content
 * @returns {Object} - Notion bulleted list item block
 */
function createBulletedListItemBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "bulleted_list_item",
    bulleted_list_item: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a numbered list item block
 * @param {string} content - Text content
 * @returns {Object} - Notion numbered list item block
 */
function createNumberedListItemBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "numbered_list_item",
    numbered_list_item: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a divider block
 * @returns {Object} - Notion divider block
 */
function createDividerBlock() {
  return {
    object: "block",
    type: "divider",
    divider: {}
  };
}

/**
 * Creates a code block
 * @param {string} content - Code content
 * @param {string} language - Programming language
 * @returns {Object} - Notion code block
 */
function createCodeBlock(content, language = "plain_text") {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "code",
    code: {
      rich_text: [{ type: "text", text: { content } }],
      language: language
    }
  };
}

/**
 * Creates a callout block
 * @param {string} content - Text content
 * @param {string} emoji - Emoji for icon
 * @returns {Object} - Notion callout block
 */
function createCalloutBlock(content, emoji = "💡") {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "callout",
    callout: {
      rich_text: [{ type: "text", text: { content } }],
      icon: { type: "emoji", emoji }
    }
  };
}

/**
 * Creates a todo block
 * @param {string} content - Text content
 * @param {boolean} checked - Whether todo is checked
 * @returns {Object} - Notion todo block
 */
function createToDoBlock(content, checked = false) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "to_do",
    to_do: {
      rich_text: [{ type: "text", text: { content } }],
      checked: checked
    }
  };
}

/**
 * Creates a toggle block
 * @param {string} content - Text content
 * @returns {Object} - Notion toggle block
 */
function createToggleBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "toggle",
    toggle: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a quote block
 * @param {string} content - Text content
 * @returns {Object} - Notion quote block
 */
function createQuoteBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "quote",
    quote: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Determines if content is already in Notion block format
 * @param {string|Array} content - Content to check
 * @returns {boolean} - True if in block format
 */
function isBlockFormat(content) {
  // Check if it's an array of blocks
  if (Array.isArray(content)) {
    return content.length > 0 && 
           content.every(block => 
             typeof block === 'object' &&
             block !== null &&
             (block.object === 'block' || block.object === undefined) && 
             typeof block.type === 'string'
           );
  }

  // Check if it's a JSON string of blocks
  if (typeof content === 'string') {
    try {
      const parsed = JSON.parse(content);
      if (Array.isArray(parsed)) {
        return parsed.length > 0 && 
               parsed.every(block => 
                 typeof block === 'object' &&
                 block !== null &&
                 (block.object === 'block' || block.object === undefined) && 
                 typeof block.type === 'string'
               );
      }
      return false;
    } catch (e) {
      return false;
    }
  }

  return false;
}

module.exports = {
  createParagraphBlock,
  createSingleParagraphBlock,
  createHeadingBlock,
  createBulletedListItemBlock,
  createNumberedListItemBlock,
  createDividerBlock,
  createCodeBlock,
  createCalloutBlock,
  createToDoBlock,
  createToggleBlock,
  createQuoteBlock,
  isBlockFormat,
  MAX_CONTENT_LENGTH
};

const { sanitizeInput } = require('./api-utils');
const blockUtils = require('./block-utils');

/**
 * Processes content into Notion blocks, handling both markdown and block formats
 * @param {string|Array} content - Content in markdown or block format
 * @returns {Array} - Array of Notion blocks
 */
function processContentToBlocks(content) {
  if (!content) return [];

  // Check if content is already in block format
  if (blockUtils.isBlockFormat(content)) {
    return typeof content === 'string' ? JSON.parse(content) : content;
  }

  // Otherwise, parse as markdown
  const sanitizedContent = sanitizeInput(content);
  return parseMarkdownToBlocks(sanitizedContent);
}

/**
 * Parses markdown text and converts it to Notion blocks
 * @param {string} markdownText - Markdown text to convert
 * @returns {Array} - Array of Notion blocks
 */
function parseMarkdownToBlocks(markdownText) {
  if (!markdownText) return [];

  const blocks = [];
  const lines = markdownText.split('\n');

  let i = 0;
  while (i < lines.length) {
    const line = lines[i].trim();

    // Skip empty lines but add an empty paragraph for spacing
    if (!line) {
      blocks.push(blockUtils.createSingleParagraphBlock(""));
      i++;
      continue;
    }

    // Heading 1: # Heading
    if (line.startsWith('# ')) {
      blocks.push(blockUtils.createHeadingBlock(line.substring(2), 1));
    }
    // Heading 2: ## Heading
    else if (line.startsWith('## ')) {
      blocks.push(blockUtils.createHeadingBlock(line.substring(3), 2));
    }
    // Heading 3: ### Heading
    else if (line.startsWith('### ')) {
      blocks.push(blockUtils.createHeadingBlock(line.substring(4), 3));
    }
    // Divider: ---
    else if (line === '---') {
      blocks.push(blockUtils.createDividerBlock());
    }
    // Bullet list items: * Item or - Item
    else if (line.startsWith('* ') || line.startsWith('- ')) {
      blocks.push(blockUtils.createBulletedListItemBlock(line.substring(2)));
    }
    // Numbered list items: 1. Item
    else if (/^\d+\.\s/.test(line)) {
      const content = line.substring(line.indexOf('.') + 1).trim();
      blocks.push(blockUtils.createNumberedListItemBlock(content));
    }
    // Code blocks: ```language
    else if (line.startsWith('```')) {
      const language = line.substring(3).trim() || 'plain_text';

      // Find the closing tag
      let codeContent = [];
      let j = i + 1;
      while (j < lines.length && !lines[j].trim().startsWith('```')) {
        codeContent.push(lines[j]);
        j++;
      }

      blocks.push(blockUtils.createCodeBlock(codeContent.join('\n'), language));
      i = j; // Skip to after the closing tag
    }
    // For callout blocks: > [emoji] text
    else if (line.startsWith('> ')) {
      const calloutText = line.substring(2);

      // Check if it starts with an emoji
      const emojiMatch = calloutText.match(/^(\p{Emoji})\s+(.*)/u);
      if (emojiMatch) {
        const emoji = emojiMatch[1];
        const text = emojiMatch[2];
        blocks.push(blockUtils.createCalloutBlock(text, emoji));
      } else {
        blocks.push(blockUtils.createQuoteBlock(calloutText));
      }
    }
    // For todo blocks: [ ] text or [x] text
    else if (line.startsWith('[ ] ') || line.startsWith('[x] ')) {
      const checked = line.startsWith('[x] ');
      const content = line.substring(4);
      blocks.push(blockUtils.createToDoBlock(content, checked));
    }
    // For toggle blocks: >>> text
    else if (line.startsWith('>>> ')) {
      blocks.push(blockUtils.createToggleBlock(line.substring(4)));
    }
    // Default to paragraph
    else {
      blocks.push(blockUtils.createParagraphBlock(line));
    }

    i++;
  }

  return blocks;
}

/**
 * Helper function to extract text from Notion's rich_text arrays
 * @param {Array} richText - Notion rich text array
 * @returns {string} - Plain text content
 */
function extractTextFromRichText(richText) {
  if (!richText || !Array.isArray(richText)) return '';

  return richText.map(rt => {
    if (!rt) return '';
    if (rt.text && rt.text.content) return rt.text.content;
    if (rt.plain_text) return rt.plain_text;
    return '';
  }).join('');
}

/**
 * Converts Notion blocks to markdown text
 * @param {Array} blocks - Array of Notion blocks
 * @returns {string} - Converted markdown text
 */
function blocksToMarkdown(blocks) {
  if (!blocks || !Array.isArray(blocks)) return '';

  return blocks.map(block => {
    if (!block || typeof block !== 'object' || !block.type) {
      console.warn('Invalid block:', block);
      return '';
    }

    switch (block.type) {
      case 'paragraph': {
        const text = extractTextFromRichText(block.paragraph?.rich_text);
        return text ? `${text}\n\n` : '\n';
      }

      case 'heading_1': {
        const text = extractTextFromRichText(block.heading_1?.rich_text);
        return `# ${text}\n\n`;
      }

      case 'heading_2': {
        const text = extractTextFromRichText(block.heading_2?.rich_text);
        return `## ${text}\n\n`;
      }

