        const text = extractTextFromRichText(block.heading_3?.rich_text);
        return `### ${text}\n\n`;
      }

      case 'bulleted_list_item': {
        const text = extractTextFromRichText(block.bulleted_list_item?.rich_text);
        return `* ${text}\n`;
      }

      case 'numbered_list_item': {
