const express = require('express');
const router = express.Router();

const { 
  notionApi, 
  handleApiError, 
  sanitizeInput,
  NOTION_MEMORY_DB_ID
} = require('./api-utils');

/**
 * Normalizes a key for memory operations
 * @param {string} key - The key to normalize
 * @returns {string} - Normalized key
 */
function normalizeKey(key) {
  if (!key) return "";

  const sanitizedKey = sanitizeInput(key, "");

  try {
    return decodeURIComponent(sanitizedKey.toLowerCase());
  } catch (e) {
    console.warn(`Error decoding URI component: ${key}`, e);
    return sanitizedKey.toLowerCase();
  }
}

/**
 * @route   GET /read-memory
 * @desc    Reads memory entries from Notion, with optional key filtering
 */
router.get("/read-memory", async (req, res) => {
  try {
    if (!NOTION_MEMORY_DB_ID) {
      return res.status(400).json({ error: "Memory database not configured" });
    }

    const rawKey = req.query.key;
    let body = {};

    console.log(`Reading memory${rawKey ? ` for key: ${rawKey}` : ' (all entries)'}`);

    if (rawKey) {
      try {
        const normalizedKey = normalizeKey(rawKey);
        body = {
          filter: {
            property: "Key",
            title: { equals: normalizedKey }
          }
        };
      } catch (e) {
        return res.status(400).json({ 
          error: "Invalid key format.", 
          details: e.message 
        });
      }
    }

    const response = await notionApi.post(`/databases/${NOTION_MEMORY_DB_ID}/query`, body);

    const memory = response.data.results.map(page => {
      const key = page.properties.Key?.title?.[0]?.plain_text || "(no key)";
      const value = page.properties.Value?.rich_text?.[0]?.plain_text || "";
      const lastUpdated = page.properties.LastUpdated?.date?.start || null;
      return { key, value, lastUpdated, id: page.id };
    });

    if (rawKey && memory.length === 0) {
      return res.status(404).json({ 
        error: `Memory key '${rawKey}' not found.`,
        message: "No matching memory entry found"
      });
    }

    console.log(`Retrieved ${memory.length} memory entries`);
    res.json({ 
      success: true, 
      memory: rawKey ? memory[0] : memory,
      count: memory.length
    });
  } catch (err) {
    console.error("Error reading memory:", err);
    handleApiError(res, err, "read-memory");
  }
});

