/**
 * @route   GET /query-database
 * @desc    Queries the main Notion database
 */
router.get("/query-database", async (req, res) => {
  try {
    const { NOTION_DATABASE_ID } = require('./api-utils');
    const { limit = 100 } = req.query;

    if (!NOTION_DATABASE_ID) {
      return res.status(400).json({ error: "Database ID not configured" });
    }

    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit < 1) {
      return res.status(400).json({ error: "Invalid limit parameter. Must be a positive number." });
    }

    console.log(`Querying database with limit=${parsedLimit}`);
    const response = await notionApi.post(`/databases/${NOTION_DATABASE_ID}/query`, {
      page_size: parsedLimit
    });

    const { extractPageTitle } = require('./api-utils');
    const rows = await Promise.all(response.data.results.map(async (item) => {
      try {
        const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;

        return {
          title,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null
        };
      } catch (err) {
        console.error(`Error processing database item ${item.id}`, err);
        return {
          title: `Error (${item.id.substring(0, 8)})`,
          id: item.id,
          error: true
        };
      }
    }));

    console.log(`Database query returned ${rows.length} results`);
    res.json({ success: true, count: rows.length, entries: rows });
  } catch (error) {
    console.error("Database query failed:", error);
    handleApiError(res, error, "query-database");
  }
});

