    "start": "node index.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "axios": "^1.3.4"
  }
}

const express = require("express");
const router = express.Router();
const axios = require("axios");

const githubToken = process.env.GITHUB_TOKEN;
const repoOwner = process.env.GITHUB_REPO_OWNER;
const repoName = process.env.GITHUB_REPO_NAME;

const headers = {
  Authorization: `Bearer ${githubToken}`,
  'X-GitHub-Api-Version': '2022-11-28',
  "User-Agent": "replit-gpt-api",
};

// Verify GitHub token is available
if (!githubToken) {
  console.error("WARNING: GITHUB_TOKEN environment variable not set");
}

// Helper function to handle rate limits
function handleRateLimit(error, res) {
  if (error.response?.status === 403 && error.response?.data?.message?.includes('API rate limit exceeded')) {
    return res.status(429).json({ 
      error: "GitHub API rate limit exceeded, please try again later",
      reset_at: error.response.headers['x-ratelimit-reset']
    });
  }
  // Handle other errors
  const status = error.response?.status || 500;
  res.status(status).json({
    error: error.response?.data?.message || error.message,
    status: status,
    documentation_url: error.response?.data?.documentation_url
  });
}

// Default axios options
const axiosOptions = {
  headers,
  timeout: 10000 // 10 seconds
};

// === Create GitHub issue ===
router.put("/issue", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { title, body } = req.body;

  console.log("Received body:", body);

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  try {
    const response = await axios.post(
      `https://api.github.com/repos/${repoOwner}/${repoName}/issues`,
      { title, body },
      axiosOptions
    );
    res.json({ success: true, issueUrl: response.data.html_url });
  } catch (error) {
    console.error("GitHub create issue error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === Update GitHub issue ===
router.patch("/issue", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { issue_number, title, body, state } = req.body;

  if (!issue_number) {
    return res.status(400).json({ error: "Issue number is required" });
  }

  try {
    const response = await axios.patch(
      `https://api.github.com/repos/${repoOwner}/${repoName}/issues/${issue_number}`,
      { title, body, state },
      axiosOptions
    );
    res.json({ success: true, updated: response.data });
  } catch (error) {
    console.error("GitHub update issue error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === Add or update file ===
router.put("/file", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { path, content, message, branch } = req.body;

  if (!path || content === undefined) {
    return res.status(400).json({ error: "Path and content are required" });
  }

  if (!message) {
    return res.status(400).json({ error: "Commit message is required" });
  }

  try {
    let sha = null;
    try {
      const params = branch ? { ref: branch } : {};
      const getRes = await axios.get(
        `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
        { ...axiosOptions, params }
      );
      sha = getRes.data.sha;
    } catch (_) {
      // File doesn't exist yet, which is fine
    }

    const payload = {
      message,
      content: Buffer.from(content).toString("base64"),
      ...(sha && { sha }),
      ...(branch && { branch })
    };

    const response = await axios.put(
      `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
      payload,
      axiosOptions
    );
    res.json({ 
      success: true, 
      fileUrl: response.data.content.html_url,
      sha: response.data.content.sha
    });
  } catch (error) {
    console.error("GitHub file upload error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === Delete file ===
router.put("/delete-file", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { path, message, branch } = req.body;

  if (!path) {
    return res.status(400).json({ error: "Path is required" });
  }

  if (!message) {
    return res.status(400).json({ error: "Commit message is required" });
  }

  try {
    const params = branch ? { ref: branch } : {};
    const getRes = await axios.get(
      `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
      { ...axiosOptions, params }
    );
    const sha = getRes.data.sha;

    const payload = { 
      message, 
      sha,
      ...(branch && { branch })
    };

    const response = await axios.delete(
      `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
      {
        ...axiosOptions,
        data: payload
      }
    );
    res.json({ 
      success: true, 
      deleted: path,
      commit: response.data.commit
    });
  } catch (error) {
    console.error("GitHub file delete error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === List issues ===
router.get("/issues", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { page = 1, per_page = 30, state = 'all' } = req.query;

  try {
    const response = await axios.get(
      `https://api.github.com/repos/${repoOwner}/${repoName}/issues`,
      { 
        ...axiosOptions,
        params: { page, per_page, state, sort: 'created', direction: 'desc' }
      }
    );

    res.json({
      issues: response.data,
      pagination: {
        current_page: parseInt(page),
        per_page: parseInt(per_page),
        has_next: response.data.length === parseInt(per_page)
      }
    });
  } catch (error) {
    console.error("GitHub list issues error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

module.exports = router;

/**
 * Notion API Utilities
 * 
 * This module provides API communication utilities, error handling,
 * and helper functions for interacting with the Notion API.
 */

const axios = require('axios');
const { notionToken, CONFIG } = require('./config');

/**
 * Configured Axios instance for Notion API with default headers and timeout
 */
const notionApi = axios.create({
  baseURL: 'https://api.notion.com/v1',
  headers: {
    Authorization: `Bearer ${notionToken}`,
    "Notion-Version": "2022-06-28",
    "Content-Type": "application/json"
  },
  timeout: CONFIG.API_TIMEOUT
});

/**
 * Improved error handling for API requests
 * @param {Object} res - Express response object
 * @param {Error} error - The error that occurred
 * @param {string} context - Context description for the error
 */
const handleApiError = (res, error, context) => {
  // Determine appropriate status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';
  let errorDetails = {};
  
  if (error.response) {
    // The request was made and the server responded with a status code
    // that falls out of the range of 2xx
    statusCode = error.response.status;
    errorMessage = error.response.data?.message || error.message;
    errorDetails = error.response.data || {};
  } else if (error.request) {
    // The request was made but no response was received
    statusCode = 503; // Service Unavailable
    errorMessage = 'No response received from Notion API';
    errorDetails = { errorCode: 'NO_RESPONSE', message: error.message };
  } else {
    // Something happened in setting up the request that triggered an Error
    errorMessage = error.message;
    errorDetails = { errorCode: 'REQUEST_SETUP_ERROR' };
  }
  
  // Add request context to the error
  errorDetails.context = context;
  
  console.error(`❌ ${context} error:`, errorMessage, errorDetails);
  
  res.status(statusCode).json({ 
    error: errorMessage,
    details: errorDetails,
    context
  });
};

/**
 * Enhanced API call with retry logic, exponential backoff and jitter
 * @param {Function} fn - Function that returns a promise for the API call
 * @param {Object} options - Configuration options for retry behavior
 * @param {number} [options.maxRetries=3] - Maximum number of retry attempts
 * @param {number} [options.baseDelay=1000] - Base delay in milliseconds
 * @param {number} [options.maxDelay=10000] - Maximum delay in milliseconds
 * @param {number} [options.timeout] - Timeout in milliseconds
 * @returns {Promise<*>} - The API response
 */
async function apiCallWithRetry(fn, options = {}) {
  const maxRetries = options.maxRetries || 3;
  const baseDelay = options.baseDelay || 1000; // 1 second
  const maxDelay = options.maxDelay || 10000; // 10 seconds
  const timeoutMs = options.timeout || CONFIG.API_TIMEOUT;
  
  let retries = 0;
  
  while (true) {
    try {
      // Add timeout handling
      const timeoutPromise = new Promise((_, reject) => {
