/**
 * Notion Rate Limiter
 * 
 * This module provides rate limiting functionality for the Notion API to respect
 * the API's limits of 3 requests per second overall and varying limits for different
 * operation types.
 */

/**
 * Token bucket rate limiter for the Notion API
 * Handles:
 * - 3 requests per second per token overall
 * - Request queueing with promise resolution
 * - Dynamic adjustment based on rate limit headers
 */
class NotionRateLimiter {
  /**
   * Creates a new NotionRateLimiter instance
   * @param {Object} options - Rate limiter configuration
   * @param {number} [options.maxTokens=3] - Maximum number of tokens (requests per second)
   * @param {number} [options.refillRate=3] - Tokens to add per second
   */
  constructor(options = {}) {
    this.maxTokens = options.maxTokens || 3;
    this.refillRate = options.refillRate || 3;
    this.tokens = this.maxTokens;
    this.lastRefill = Date.now();
    this.queued = [];
    this.processing = false;

    // Track different operation types for more specific rate limiting
    this.operationLimits = {
      read: { tokens: 3, lastRefill: Date.now() },     // 3 req/sec for reads
      write: { tokens: 2, lastRefill: Date.now() }     // 2 req/sec for writes
    };

    // Track per-minute limits
    this.minuteLimits = {
      write: { 
        count: 0, 
        resetTime: Date.now() + 60000,
        max: 30   // 30 req/min for writes
      }
    };

    // Set up automatic queue processing
    setInterval(() => {
      if (this.queued.length > 0 && !this.processing) {
        this.processQueue();
      }
    }, 100);
  }

  /**
   * Refills tokens based on time elapsed since last refill
   * @private
   */
  refillTokens() {
    const now = Date.now();
    const timePassed = now - this.lastRefill;

    if (timePassed >= 1000) {
      const secondsPassed = timePassed / 1000;
      const tokensToAdd = Math.floor(secondsPassed * this.refillRate);

      if (tokensToAdd > 0) {
        this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
        this.lastRefill = now;

        // Also refill operation-specific tokens
        for (const op of Object.keys(this.operationLimits)) {
          const opLimit = this.operationLimits[op];
          const opTimePassed = now - opLimit.lastRefill;
          const opSecondsPassed = opTimePassed / 1000;
          const opTokensToAdd = Math.floor(opSecondsPassed * opLimit.tokens);

          if (opTokensToAdd > 0) {
            opLimit.tokens = Math.min(opLimit.tokens, opLimit.tokens + opTokensToAdd);
            opLimit.lastRefill = now;
          }
        }
      }
    }

    // Check minute-based limits
    for (const op of Object.keys(this.minuteLimits)) {
      const minuteLimit = this.minuteLimits[op];
      if (now >= minuteLimit.resetTime) {
        minuteLimit.count = 0;
        minuteLimit.resetTime = now + 60000;
      }
    }
  }

  /**
   * Queues a request with promise resolution
   * @param {Function} requestFn - Function that returns a promise for the API call
   * @param {Object} options - Queue options
   * @param {string} [options.operationType='read'] - Type of operation ('read' or 'write')
   * @param {string} [options.resourceType=null] - Type of resource (e.g., 'database', 'page')
   * @param {boolean} [options.priority=false] - Whether this request has priority in the queue
   * @returns {Promise<*>} - Promise that resolves with the API response
   */
  queueRequest(requestFn, options = {}) {
    const operationType = options.operationType || 'read';
    const resourceType = options.resourceType || null;
    const priority = options.priority || false;

    return new Promise((resolve, reject) => {
      const request = { 
        requestFn, 
        resolve, 
        reject, 
        operationType,
        resourceType,
        attempts: 0,
        maxAttempts: 5
      };

      if (priority) {
        this.queued.unshift(request);
      } else {
        this.queued.push(request);
      }

      if (!this.processing) {
        this.processQueue();
      }
    });
  }

  /**
   * Processes queued requests if tokens are available
   * @private
   */
  async processQueue() {
    if (this.processing || this.queued.length === 0) {
      return;
    }

    this.processing = true;
    this.refillTokens();

    // Find the next request that can be processed based on token availability
    let requestIndex = -1;

    for (let i = 0; i < this.queued.length; i++) {
      const request = this.queued[i];

      // Check if we have overall tokens available
      if (this.tokens <= 0) {
        break;
      }

      // Check operation-specific tokens
      const opLimit = this.operationLimits[request.operationType];
      if (opLimit && opLimit.tokens <= 0) {
        continue;
      }

      // Check minute-based limits
      const minuteLimit = this.minuteLimits[request.operationType];
      if (minuteLimit && minuteLimit.count >= minuteLimit.max) {
        continue;
      }

      requestIndex = i;
      break;
    }

    if (requestIndex === -1) {
      // No eligible requests, wait for token refill
      this.processing = false;
      return;
    }

    // Process the request
    const request = this.queued.splice(requestIndex, 1)[0];
    this.tokens--;

    // Update operation-specific tokens
    const opLimit = this.operationLimits[request.operationType];
    if (opLimit) {
      opLimit.tokens--;
    }

    // Update minute-based limits
    const minuteLimit = this.minuteLimits[request.operationType];
    if (minuteLimit) {
      minuteLimit.count++;
    }

    try {
      const result = await request.requestFn();

      // Update token info from headers if available
      if (result.headers) {
        if (result.headers['x-notion-rate-limit-limit']) {
          this.maxTokens = parseInt(result.headers['x-notion-rate-limit-limit']);
        }

        if (result.headers['x-notion-rate-limit-remaining']) {
          this.tokens = Math.min(
            this.maxTokens, 
            parseInt(result.headers['x-notion-rate-limit-remaining'])
          );
        }
      }

      request.resolve(result);
    } catch (err) {
      request.attempts++;

      // Handle rate limit errors
      if (err.response && err.response.status === 429) {
        console.warn(`🚦 Rate limit hit for ${request.operationType} operation. Retrying...`);

        // Get reset time from headers or use default
        const resetTime = err.response.headers && err.response.headers['x-notion-rate-limit-reset'] 
          ? parseInt(err.response.headers['x-notion-rate-limit-reset']) * 1000
          : 1000;

        if (request.attempts < request.maxAttempts) {
          // Re-queue the request with priority after waiting
          setTimeout(() => {
            this.queued.unshift(request);
          }, resetTime);
        } else {
          console.error(`❌ Max retries (${request.maxAttempts}) exceeded for rate-limited request`);
          request.reject(err);
        }
      } else {
        // Other errors, just reject
        request.reject(err);
      }
    } finally {
      this.processing = false;

      // Process more from queue after a small delay
      if (this.queued.length > 0) {
        setTimeout(() => this.processQueue(), 50);
      }
    }
  }

  /**
   * Gets statistics about the rate limiter state
   * @returns {Object} Object containing rate limit statistics
   */
  getStats() {
    return {
      queueLength: this.queued.length,
      availableTokens: this.tokens,
      maxTokens: this.maxTokens,
      operationLimits: { ...this.operationLimits },
      minuteLimits: { ...this.minuteLimits }
    };
  }
}

// Create and export a rate limiter instance
const notionRateLimiter = new NotionRateLimiter();

module.exports = {
  NotionRateLimiter,
  notionRateLimiter
};

/**
 * Notion API Utilities
 * 
 * This module provides API communication utilities, error handling,
 * and helper functions for interacting with the Notion API.
 */

const axios = require('axios');
const { notionToken, CONFIG } = require('./config');
const { notionRateLimiter } = require('./rate-limiter');

/**
 * Configured Axios instance for Notion API with default headers and timeout
 */
const notionApi = axios.create({
  baseURL: 'https://api.notion.com/v1',
  headers: {
    Authorization: `Bearer ${notionToken}`,
    "Notion-Version": "2022-06-28",
    "Content-Type": "application/json"
  },
  timeout: CONFIG.API_TIMEOUT
});

/**
 * Improved error handling for API requests
 * @param {Object} res - Express response object
 * @param {Error} error - The error that occurred
 * @param {string} context - Context description for the error
 */
const handleApiError = (res, error, context) => {
  // Determine appropriate status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';
  let errorDetails = {};

  if (error.response) {
    // The request was made and the server responded with a status code
    // that falls out of the range of 2xx
    statusCode = error.response.status;
    errorMessage = error.response.data?.message || error.message;
    errorDetails = error.response.data || {};

    // Special handling for rate limit errors
    if (statusCode === 429) {
      const retryAfter = error.response.headers?.['retry-after'] || 
                       error.response.headers?.['x-notion-rate-limit-reset'] || 
                       '10';

      errorMessage = `Rate limit exceeded. Please retry after ${retryAfter} seconds.`;
      errorDetails.retryAfter = retryAfter;
    }
  } else if (error.request) {
    // The request was made but no response was received
    statusCode = 503; // Service Unavailable
    errorMessage = 'No response received from Notion API';
    errorDetails = { errorCode: 'NO_RESPONSE', message: error.message };
  } else {
    // Something happened in setting up the request that triggered an Error
    errorMessage = error.message;
    errorDetails = { errorCode: 'REQUEST_SETUP_ERROR' };
  }

  // Add request context to the error
  errorDetails.context = context;

  console.error(`❌ ${context} error:`, errorMessage, errorDetails);

  res.status(statusCode).json({ 
    error: errorMessage,
    details: errorDetails,
    context
  });
};

/**
 * Determines if an operation is a write operation based on HTTP method or endpoint
 * @param {Function} requestFn - The API request function
 * @returns {boolean} - True if this is a write operation
 */
function isWriteOperation(requestFn) {
  const fnStr = requestFn.toString().toLowerCase();

  // Check for write HTTP methods
  if (fnStr.includes('post(') || 
      fnStr.includes('put(') || 
      fnStr.includes('patch(') || 
      fnStr.includes('delete(')) {
    return true;
  }

  // Check for write endpoints
  if (fnStr.includes('/pages') && !fnStr.includes('get(')) {
    return true;
  }

  if (fnStr.includes('/blocks') && !fnStr.includes('get(')) {
    return true;
  }

  return false;
}

/**
 * Enhanced API call with rate limiting, retry logic, and exponential backoff
 * @param {Function} fn - Function that returns a promise for the API call
 * @param {Object} options - Configuration options
 * @param {number} [options.maxRetries=3] - Maximum number of retry attempts
 * @param {number} [options.baseDelay=1000] - Base delay in milliseconds
 * @param {number} [options.maxDelay=10000] - Maximum delay in milliseconds
 * @param {number} [options.timeout] - Timeout in milliseconds
 * @param {string} [options.operationType] - Type of operation ('read' or 'write')
 * @param {string} [options.resourceType] - Type of resource being accessed
 * @returns {Promise<*>} - The API response
 */
async function apiCallWithRetry(fn, options = {}) {
  const maxRetries = options.maxRetries || 3;
  const baseDelay = options.baseDelay || 1000; // 1 second
  const maxDelay = options.maxDelay || 10000; // 10 seconds
  const timeoutMs = options.timeout || CONFIG.API_TIMEOUT;

  // Determine operation type if not specified
  const operationType = options.operationType || (isWriteOperation(fn) ? 'write' : 'read');
  const resourceType = options.resourceType || null;

  // Create the actual request function with timeout handling
  const requestWithTimeout = async () => {
    const timeoutPromise = new Promise((_, reject) => {
      setTimeout(() => reject(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs);
    });

    const resultPromise = fn();

    // Race between the API call and the timeout
    return Promise.race([resultPromise, timeoutPromise]);
  };

  // Use the rate limiter for Notion API calls
  if (fn.toString().includes('notionApi')) {
    return notionRateLimiter.queueRequest(requestWithTimeout, {
      operationType,
      resourceType
    });
  }

  // For non-Notion API calls (e.g., GitHub), use the original retry logic
  let retries = 0;

  while (true) {
    try {
      return await requestWithTimeout();
    } catch (error) {
      const isRetryable = 
        error.response?.status === 429 || // Rate limited
        error.response?.status === 503 || // Service unavailable
        error.response?.status >= 500 ||  // Server errors
        error.code === 'ECONNRESET' ||    // Connection reset
        error.code === 'ETIMEDOUT' ||     // Connection timeout
        error.message.includes('timeout'); // Generic timeout error

      if (isRetryable && retries < maxRetries) {
        // Calculate delay with exponential backoff and jitter
        const exponentialDelay = Math.min(
          maxDelay,
          baseDelay * Math.pow(2, retries)
        );
        // Add jitter: random value between 0 and 1 * 0.5 * calculated delay
        const jitter = Math.random() * 0.5 * exponentialDelay;
        const delay = exponentialDelay + jitter;

        console.log(`API call failed with ${error.response?.status || error.code || 'unknown error'}, retrying in ${Math.round(delay)}ms... (${retries + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, delay));
        retries++;
      } else {
        // Either not retryable or max retries exceeded
        if (retries >= maxRetries) {
          console.error(`❌ Max retries (${maxRetries}) exceeded for API call. Last error:`, error.message);
        }
        throw error;
      }
    }
  }
}

/**
 * Safely sanitizes input strings to prevent injection and handle edge cases
 * @param {*} input - The input to sanitize
 * @param {string} [defaultValue=""] - Default value if input is invalid
 * @returns {string} - Sanitized input string
 */
function sanitizeInput(input, defaultValue = "") {
  if (input === null || input === undefined) return defaultValue;
  if (typeof input !== 'string') {
    try {
      input = String(input);
    } catch (e) {
      return defaultValue;
    }
  }
  return input.trim();
}

/**
 * Normalizes keys for memory functions with better error handling
 * @param {string} key - The key to normalize
 * @returns {string} - Normalized key
 */
function normalizeKey(key) {
  if (!key) return "";

  const sanitizedKey = sanitizeInput(key, "");

  try {
    return decodeURIComponent(sanitizedKey.toLowerCase());
  } catch (e) {
    console.error(`❌ Error decoding URI component: ${key}`, e);
    return sanitizedKey.toLowerCase();
  }
}

/**
 * Creates a paginated request to Notion API with appropriate handling
 * @param {string} endpoint - The API endpoint to call
 * @param {Object} params - Request parameters
 * @param {Object} options - Pagination options
 * @param {number} [options.pageSize] - Items per page
 * @param {number} [options.maxItems] - Maximum total items to fetch
 * @param {number} [options.concurrentRequests] - Number of concurrent requests for pagination
 * @returns {Promise<Array>} - Array of results from all pages
 */
async function paginatedRequest(endpoint, params = {}, options = {}) {
  const pageSize = options.pageSize || CONFIG.DEFAULT_PAGE_SIZE;
  const maxItems = options.maxItems || CONFIG.MAX_ITEMS_PER_PAGE;
  const concurrentRequests = options.concurrentRequests || 1;

  let results = [];
  let hasMore = true;
  let startCursor = undefined;
  let pageCount = 0;

  const makeRequest = async (cursor) => {
    const queryParams = { ...params, page_size: pageSize };
    if (cursor) {
      queryParams.start_cursor = cursor;
    }

    const response = await apiCallWithRetry(() => {
      if (endpoint === 'search') {
        return notionApi.post('/search', queryParams);
      } else {
        const url = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
        return notionApi.get(url, { params: queryParams });
      }
    }, { operationType: 'read' });

    return response.data;
  };

  // First request to get initial batch and pagination info
  try {
    const firstBatch = await makeRequest(undefined);
    results = [...firstBatch.results];
    hasMore = firstBatch.has_more;
    startCursor = firstBatch.next_cursor;
    pageCount++;

    console.log(`📊 Fetched page ${pageCount} with ${results.length} items from ${endpoint}`);

    // If we need more pages and haven't hit limits
    const cursors = [];
    while (hasMore && results.length < maxItems && pageCount < 50) {
      cursors.push(startCursor);

      // Process in batches of concurrent requests
      if (cursors.length >= concurrentRequests || !hasMore) {
        const batchResults = await Promise.all(
          cursors.map(cursor => makeRequest(cursor))
        );

        for (const data of batchResults) {
          results = results.concat(data.results || []);
          hasMore = data.has_more;
          startCursor = data.next_cursor;
          pageCount++;

          console.log(`📊 Fetched page ${pageCount} with ${data.results.length} items from ${endpoint}`);

          if (results.length >= maxItems) {
            console.warn(`⚠️ Pagination limit reached (${maxItems} items)`);
            hasMore = false;
            break;
          }

          if (pageCount >= 50) {
            console.error(`❌ Too many pages fetched (${pageCount}). Possible API issue.`);
            hasMore = false;
            break;
          }

          if (!data.has_more) {
            hasMore = false;
            break;
          }
        }

        cursors.length = 0;
      }
    }

    return results;
  } catch (error) {
    console.error(`❌ Pagination error for ${endpoint}:`, error.message);
    throw error;
  }
}

/**
 * Gets rate limit statistics from the Notion rate limiter
 * @returns {Object} - Object containing rate limit statistics
 */
function getRateLimitStats() {
  return notionRateLimiter.getStats();
}

module.exports = {
  notionApi,
  handleApiError,
  apiCallWithRetry,
  sanitizeInput,
  normalizeKey,
  paginatedRequest,
  getRateLimitStats
};

/**
 * Notion Integration Router
 * 
 * This is the main router for the Notion integration, assembling all modular components
 * and route handlers. It serves as the entry point for all Notion-related functionality.
 * 
 * The router combines the following modules:
 * - Page routes (list, create, version)
 * - Page operations (append, update, archive)
 * - Memory routes (CRUD operations for Notion memory database)
 * - Database operations
 * - Health checks
 */

const express = require('express');
const router = express.Router();

// Import route modules
const pageRoutes = require('./page-routes');
const pageOperations = require('./page-operations');
const memoryRoutes = require('./memory-routes');

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  getRateLimitStats 
} = require('./api-utils');
const { notionDatabaseId, requiredEnvVars } = require('./config');
const { cache } = require('./cache');

// Mount modular route handlers
router.use(pageRoutes);
router.use(pageOperations);
router.use(memoryRoutes);

/**
 * @route   GET /query-database
 * @desc    Queries the configured Notion database and returns entries
 * @query   {number} limit - Maximum number of entries to return
 * @returns {Object} JSON response with database entries
 */
router.get("/query-database", async (req, res) => {
  try {
    const { CONFIG } = require('./config');
    const { limit = CONFIG.DEFAULT_PAGE_SIZE } = req.query;

    if (!notionDatabaseId) {
      return res.status(400).json({ error: "Missing NOTION_DATABASE_ID in environment variables." });
    }

    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit < 1) {
      return res.status(400).json({ error: "Invalid limit parameter. Must be a positive number." });
    }

    console.log(`Querying database ${notionDatabaseId} with limit=${parsedLimit}`);
    const response = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionDatabaseId}/query`, {
        page_size: parsedLimit
      })
    );

    const { extractPageTitle } = require('./page-utils');
    const rows = await Promise.all(response.data.results.map(async (item) => {
      try {
        const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;

        return {
          title,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null
        };
      } catch (err) {
        console.error(`Error processing database item ${item.id}:`, err.message);
        return {
          title: `Error (${item.id.substring(0, 8)})`,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null,
          error: true
        };
      }
    }));

    res.json({ success: true, count: rows.length, entries: rows });
  } catch (error) {
    handleApiError(res, error, "query-database");
  }
});

/**
 * @route   GET /health
 * @desc    Health check endpoint for Notion integration
 * @returns {Object} JSON response with health status
 */
router.get("/health", async (req, res) => {
  try {
    const { notionParentPageId } = require('./config');

    // Check if Notion API is accessible
    const response = await apiCallWithRetry(() => notionApi.get('/users/me'));

    // Verify required environment variables
    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
      return res.status(503).json({
        status: 'degraded',
        message: 'Missing required environment variables',
        details: { missingVars }
      });
    }

    // Check if parent page exists
    try {
      await apiCallWithRetry(() => notionApi.get(`/pages/${notionParentPageId}`));
    } catch (error) {
      return res.status(503).json({
        status: 'degraded',
        message: 'Parent page ID is invalid or inaccessible',
        details: { error: error.message }
      });
    }

    // Include cache stats
    const cacheStats = cache.getStats();

    // Include rate limiter stats
    const rateLimitStats = getRateLimitStats();

    res.json({ 
      status: 'healthy', 
      message: 'Notion integration is working properly',
      version: '1.0.0',
      timestamp: new Date().toISOString(),
      cache: cacheStats,
      rateLimits: rateLimitStats
    });
  } catch (error) {
    res.status(503).json({ 
      status: 'unhealthy', 
      message: 'Unable to connect to Notion API',
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @route   GET /rate-limits
 * @desc    Get rate limit statistics
 * @returns {Object} JSON response with rate limit information
 */
router.get("/rate-limits", (req, res) => {
  try {
    const stats = getRateLimitStats();
    res.json({
      success: true,
      rateLimit: stats
    });
  } catch (error) {
    handleApiError(res, error, "rate-limits");
  }
});

// Add a catch-all route to handle invalid endpoints
router.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint ${req.originalUrl} does not exist`,
    availableEndpoints: [
      'GET /list-pages',
      'PUT /write-page-by-title',
      'PATCH /append-to-page-by-title',
      'PATCH /update-page',
      'GET /query-database',
      'PUT /post-standalone-page',
      'DELETE /page/:id',
      'GET /read-memory',
      'PATCH /create-memory',
      'PATCH /update-memory',
      'DELETE /delete-memory',
      'GET /rate-limits',
      'GET /health'
    ]
  });
});

module.exports = router;

