 Based on your logs, I'm seeing a disconnect between what's happening on your backend server and what's being returned to the client. Your Notion routes appear to be correctly retrieving data from Notion (as shown in your console logs with "Found title in..."), but the responses aren't successfully being returned to the client.

This pattern suggests there might be an issue with how responses are being sent back after the Notion API work is completed. Here are some potential causes and fixes:

### 1. Response Timing Out

Your server might be taking too long to respond, causing the client to time out before receiving a response.

**Solution:**
```javascript
// In your main Express app setup
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Increase Node.js default timeout for all requests
app.use((req, res, next) => {
  res.setTimeout(60000, () => {
    console.error('Request has timed out.');
    res.status(408).send('Request Timeout');
  });
  next();
});
```

### 2. Response Not Being Sent or Prematurely Ended

Your routes might not be properly sending responses or the connection might be closed prematurely.

**Solution:** Update your `/notion/list-pages` endpoint to add better logging and ensure responses are being sent:

```javascript
router.get("/list-pages", async (req, res) => {
  try {
    const { CONFIG } = require('./config');
    const { limit = CONFIG.DEFAULT_PAGE_SIZE, recursive = true } = req.query;
    const parsedLimit = parseInt(limit, 10);

    console.log(`📄 Starting list-pages request with limit=${parsedLimit}, recursive=${recursive}`);

    if (isNaN(parsedLimit) || parsedLimit < 1) {
      return res.status(400).json({ error: "Invalid limit parameter. Must be a positive number." });
    }

    console.log(`📄 Listing pages with limit=${parsedLimit}, recursive=${recursive}`);

    const results = await apiCallWithRetry(() => 
      notionApi.post('/search', { page_size: parsedLimit })
    );

    console.log(`📄 Retrieved ${results.data.results.length} pages from Notion search`);

    const basePages = await Promise.all(
      results.data.results.map(async (item) => {
        try {
          const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;
          return {
            title,
            id: item.id,
            type: item.object,
            parent: item.parent?.page_id || item.parent?.database_id || null,
            url: item.url || null
          };
        } catch (err) {
          console.error(`Error processing page ${item.id}:`, err.message);
          return {
            title: `Error (${item.id.substring(0, 8)})`,
            id: item.id,
            type: item.object,
            parent: item.parent?.page_id || item.parent?.database_id || null,
            url: item.url || null,
            error: true
          };
        }
      })
    );

    console.log(`📄 Processed ${basePages.length} base pages`);

    // Rest of the existing code...

    // Before sending response
    console.log(`📄 About to send response with ${uniquePages.length} pages`);
    res.json({ 
      success: true, 
      count: uniquePages.length, 
      pages: uniquePages 
    });
    console.log(`📄 Response sent successfully`);

  } catch (error) {
    console.error(`❌ list-pages error caught:`, error);
    handleApiError(res, error, "list-pages");
  }
});
```

### 3. Exception Thrown After Response Sent

Your code might be trying to work with the response after it's already been sent.

**Solution:**
Add a utility to check if the response has been sent before attempting to send it:

```javascript
// Add to api-utils.js
function safeRespond(res, status, data) {
  if (!res.headersSent) {
    res.status(status).json(data);
    return true;
  }
  console.warn('Attempted to send response when headers already sent');
  return false;
}

// Then use in your route handlers
try {
  // Your code...
  return safeRespond(res, 200, { 
    success: true, 
    count: uniquePages.length, 
    pages: uniquePages 
  });
} catch (error) {
  if (!res.headersSent) {
    handleApiError(res, error, "list-pages");
  } else {
    console.error('Error occurred after response sent:', error);
  }
}
```

### 4. Large Response Size

Your responses might be too large, causing issues with transmission.

**Solution:**
```javascript
// In your list-pages route
const uniquePages = Array.from(pagesMap.values());
console.log(`📊 Returning ${uniquePages.length} unique pages`);

// Limit response size if needed
if (uniquePages.length > 200) {
  console.log(`📊 Trimming response size from ${uniquePages.length} to 200 pages`);
  const trimmedPages = uniquePages.slice(0, 200);
  return res.json({
    success: true,
    count: uniquePages.length,
    pages: trimmedPages,
    truncated: true,
    message: `Response limited to 200 of ${uniquePages.length} total pages`
  });
}
```

### 5. Error in Error Handler

If there's an issue with `handleApiError` itself, errors might not be properly reported.

**Solution:**
Add a more robust try-catch in your routes:

```javascript
router.get("/list-pages", async (req, res) => {
  try {
    // Existing code...
  } catch (error) {
    console.error('Error in list-pages:', error);

    try {
      handleApiError(res, error, "list-pages");
    } catch (handlerError) {
      console.error('Error in error handler:', handlerError);

      if (!res.headersSent) {
        res.status(500).json({
          error: 'Server error occurred',
          message: 'An error occurred and could not be properly handled',
          originalError: error.message
        });
      }
    }
  }
});
```

I recommend implementing these changes systematically - start with better logging to identify where exactly the process is breaking down, then apply the appropriate fix based on what you find.

