/**
 * Notion Block Utilities
 * 
 * This module provides helper functions for creating and managing Notion blocks,
 * including handling of text content with proper splitting for Notion API limitations.
 * Supports bidirectional conversion between Notion blocks and markdown.
 */

const { CONFIG } = require('./config');
const { sanitizeInput } = require('./api-utils');

/**
 * Creates a paragraph block or array of paragraph blocks for content
 * Handles automatic splitting of content that exceeds Notion's maximum length
 * 
 * @param {string} content - The text content for the paragraph
 * @returns {Object|Array} - A single paragraph block or array of blocks if content exceeds max length
 */
function createParagraphBlock(content) {
  // Validate and sanitize content
  content = sanitizeInput(content, "");
  if (!content) return createSingleParagraphBlock("");

  // Split content into manageable chunks if too long
  if (content.length > CONFIG.MAX_CONTENT_LENGTH) {
    const chunks = [];
    const maxLength = CONFIG.MAX_CONTENT_LENGTH;

    // First try to split by sentences for more natural breaks
    const sentences = content.split(/(?<=[.!?])\s+/);
    let currentChunk = "";

    for (const sentence of sentences) {
      // If adding this sentence exceeds max length, create a new chunk
      if ((currentChunk + (currentChunk ? " " : "") + sentence).length > maxLength) {
        if (currentChunk) {
          chunks.push(createSingleParagraphBlock(currentChunk));
          currentChunk = "";
        }

        // Handle case where a single sentence is too long
        if (sentence.length > maxLength) {
          // Split by words for very long sentences
          const words = sentence.split(/\s+/);
          let wordChunk = "";

          for (const word of words) {
            if ((wordChunk + (wordChunk ? " " : "") + word).length > maxLength) {
              if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
              // If a single word is too long (rare), split it
              if (word.length > maxLength) {
                for (let i = 0; i < word.length; i += maxLength) {
                  chunks.push(createSingleParagraphBlock(word.substring(i, i + maxLength)));
                }
                wordChunk = "";
              } else {
                wordChunk = word;
              }
            } else {
              wordChunk += (wordChunk ? " " : "") + word;
            }
          }

          if (wordChunk) chunks.push(createSingleParagraphBlock(wordChunk));
        } else {
          currentChunk = sentence;
        }
      } else {
        currentChunk += (currentChunk ? " " : "") + sentence;
      }
    }

    if (currentChunk) chunks.push(createSingleParagraphBlock(currentChunk));
    return chunks;
  }

  return createSingleParagraphBlock(content);
}

/**
 * Creates a single paragraph block with the given content
 * 
 * @param {string} content - The text content for the paragraph
 * @returns {Object} - A Notion paragraph block object
 */
function createSingleParagraphBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "paragraph",
    paragraph: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a heading block with the specified content and level
 * 
 * @param {string} content - The text content for the heading
 * @param {number} [level=1] - The heading level (1, 2, or 3)
 * @returns {Object} - A Notion heading block object
 */
function createHeadingBlock(content, level = 1) {
  content = sanitizeInput(content, "Untitled");

  // Validate level is 1, 2, or 3
  if (![1, 2, 3].includes(level)) {
    console.warn(`Invalid heading level: ${level}, defaulting to 1`);
    level = 1;
  }

  const headingType = `heading_${level}`;
  return {
    object: "block",
    type: headingType,
    [headingType]: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a bulleted list item block
 * 
 * @param {string} content - The text content for the list item
 * @returns {Object} - A Notion bulleted list item block
 */
function createBulletedListItemBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "bulleted_list_item",
    bulleted_list_item: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a numbered list item block
 * 
 * @param {string} content - The text content for the list item
 * @returns {Object} - A Notion numbered list item block
 */
function createNumberedListItemBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "numbered_list_item",
    numbered_list_item: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a divider block
 * 
 * @returns {Object} - A Notion divider block
 */
function createDividerBlock() {
  return {
    object: "block",
    type: "divider",
    divider: {}
  };
}

/**
 * Creates a code block with specified content and language
 * 
 * @param {string} content - The code content
 * @param {string} [language="plain_text"] - The programming language
 * @returns {Object} - A Notion code block
 */
function createCodeBlock(content, language = "plain_text") {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "code",
    code: {
      rich_text: [{ type: "text", text: { content } }],
      language: language
    }
  };
}

/**
 * Creates a callout block with specified content and icon
 * 
 * @param {string} content - The text content for the callout
 * @param {string} [emoji="💡"] - The emoji to use as icon
 * @returns {Object} - A Notion callout block
 */
function createCalloutBlock(content, emoji = "💡") {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "callout",
    callout: {
      rich_text: [{ type: "text", text: { content } }],
      icon: { type: "emoji", emoji }
    }
  };
}

/**
 * Creates a todo block with specified content and checked state
 * 
 * @param {string} content - The text content for the todo
 * @param {boolean} [checked=false] - Whether the todo is checked
 * @returns {Object} - A Notion todo block
 */
function createToDoBlock(content, checked = false) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "to_do",
    to_do: {
      rich_text: [{ type: "text", text: { content } }],
      checked: checked
    }
  };
}

/**
 * Creates a toggle block with specified content
 * 
 * @param {string} content - The text content for the toggle header
 * @returns {Object} - A Notion toggle block
 */
function createToggleBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "toggle",
    toggle: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Creates a quote block with specified content
 * 
 * @param {string} content - The text content for the quote
 * @returns {Object} - A Notion quote block
 */
function createQuoteBlock(content) {
  content = sanitizeInput(content, "");
  return {
    object: "block",
    type: "quote",
    quote: {
      rich_text: [{ type: "text", text: { content } }]
    }
  };
}

/**
 * Determines if the content is already in Notion block format
 * @param {string|Array} content - The content to check
 * @returns {boolean} - True if content appears to be in block format
 */
function isBlockFormat(content) {
  // If it's already an array, check if it looks like block format
  if (Array.isArray(content)) {
    return content.length > 0 && 
           content.every(block => 
             typeof block === 'object' &&
             block !== null &&
             (block.object === 'block' || block.object === undefined) && 
             typeof block.type === 'string'
           );
  }

  // If it's a string, try to parse it as JSON
  if (typeof content === 'string') {
    try {
      const parsed = JSON.parse(content);
      // Check if it's an array of blocks with expected properties
      if (Array.isArray(parsed)) {
        return parsed.length > 0 && 
               parsed.every(block => 
                 typeof block === 'object' &&
                 block !== null &&
                 (block.object === 'block' || block.object === undefined) && 
                 typeof block.type === 'string'
               );
      }
      return false;
    } catch (e) {
      // If it's not valid JSON, it's not block format
      return false;
    }
  }

  return false;
}

/**
 * Processes content into Notion blocks regardless of input format
 * @param {string|Array} content - Content in markdown or block format
 * @returns {Array} - Array of Notion blocks
 */
function processContentToBlocks(content) {
  if (!content) return [];

  // Check if content is already in block format
  if (isBlockFormat(content)) {
    return typeof content === 'string' ? JSON.parse(content) : content;
  }

  // Otherwise, parse as markdown
  const sanitizedContent = sanitizeInput(content);
  return parseMarkdownToBlocks(sanitizedContent);
}

/**
 * Parses markdown-style text and converts it to Notion blocks
 * @param {string} markdownText - The markdown text to convert
 * @returns {Array} - Array of Notion blocks
 */
function parseMarkdownToBlocks(markdownText) {
  if (!markdownText) return [];

  const blocks = [];
  const lines = markdownText.split('\n');

  let i = 0;
  while (i < lines.length) {
    const line = lines[i].trim();

    // Skip empty lines but add a paragraph with empty string to preserve spacing
    if (!line) {
      blocks.push(createSingleParagraphBlock(""));
      i++;
      continue;
    }

    // Heading 1: # Heading
    if (line.startsWith('# ')) {
      blocks.push(createHeadingBlock(line.substring(2), 1));
    }
    // Heading 2: ## Heading
    else if (line.startsWith('## ')) {
      blocks.push(createHeadingBlock(line.substring(3), 2));
    }
    // Heading 3: ### Heading
    else if (line.startsWith('### ')) {
      blocks.push(createHeadingBlock(line.substring(4), 3));
    }
    // Divider: ---
    else if (line === '---') {
      blocks.push(createDividerBlock());
    }
    // Bullet list items: * Item or - Item
    else if (line.startsWith('* ') || line.startsWith('- ')) {
      blocks.push(createBulletedListItemBlock(line.substring(2)));
    }
    // Numbered list items: 1. Item
    else if (/^\d+\.\s/.test(line)) {
      const content = line.substring(line.indexOf('.') + 1).trim();
      blocks.push(createNumberedListItemBlock(content));
    }
    // Code blocks: ```language
    else if (line.startsWith('```')) {
      const language = line.substring(3).trim() || 'plain_text';

      // Find the closing tag
      let codeContent = [];
      let j = i + 1;
      while (j < lines.length && !lines[j].trim().startsWith('```')) {
        codeContent.push(lines[j]);
        j++;
      }

      blocks.push(createCodeBlock(codeContent.join('\n'), language));
      i = j; // Skip to after the closing tag
    }
    // For callout blocks: > [emoji] text
    else if (line.startsWith('> ')) {
      const calloutText = line.substring(2);

      // Check if it starts with an emoji
      const emojiMatch = calloutText.match(/^(\p{Emoji})\s+(.*)/u);
      if (emojiMatch) {
        const emoji = emojiMatch[1];
        const text = emojiMatch[2];
        blocks.push(createCalloutBlock(text, emoji));
      } else {
        blocks.push(createQuoteBlock(calloutText));
      }
    }
    // For todo blocks: [ ] text or [x] text
    else if (line.startsWith('[ ] ') || line.startsWith('[x] ')) {
      const checked = line.startsWith('[x] ');
      const content = line.substring(4);
      blocks.push(createToDoBlock(content, checked));
    }
    // For toggle blocks: >>> text
    else if (line.startsWith('>>> ')) {
      blocks.push(createToggleBlock(line.substring(4)));
    }
    // Default to paragraph
    else {
      blocks.push(createParagraphBlock(line));
    }

    i++;
  }

  return blocks;
}

/**
 * Converts Notion blocks to markdown text
 * @param {Array} blocks - Array of Notion blocks
 * @returns {string} - Converted markdown text
 */
function blocksToMarkdown(blocks) {
  if (!blocks || !Array.isArray(blocks)) return '';

  return blocks.map(block => {
    if (!block || typeof block !== 'object' || !block.type) {
      console.warn('Invalid block:', block);
      return '';
    }

    switch (block.type) {
      case 'paragraph': {
        const text = extractTextFromRichText(block.paragraph?.rich_text);
        return text ? `${text}\n\n` : '\n';
      }

      case 'heading_1': {
        const text = extractTextFromRichText(block.heading_1?.rich_text);
        return `# ${text}\n\n`;
      }

      case 'heading_2': {
        const text = extractTextFromRichText(block.heading_2?.rich_text);
        return `## ${text}\n\n`;
      }

      case 'heading_3': {
        const text = extractTextFromRichText(block.heading_3?.rich_text);
        return `### ${text}\n\n`;
      }

      case 'bulleted_list_item': {
        const text = extractTextFromRichText(block.bulleted_list_item?.rich_text);
        return `* ${text}\n`;
      }

      case 'numbered_list_item': {
        const text = extractTextFromRichText(block.numbered_list_item?.rich_text);
        return `1. ${text}\n`;
      }

      case 'to_do': {
        const text = extractTextFromRichText(block.to_do?.rich_text);
        const checked = block.to_do?.checked;
        return `[${checked ? 'x' : ' '}] ${text}\n`;
      }

      case 'toggle': {
        const text = extractTextFromRichText(block.toggle?.rich_text);
        return `>>> ${text}\n\n`;
      }

      case 'callout': {
        const text = extractTextFromRichText(block.callout?.rich_text);
        const emoji = block.callout?.icon?.emoji || '💡';
        return `> ${emoji} ${text}\n\n`;
      }

      case 'quote': {
        const text = extractTextFromRichText(block.quote?.rich_text);
        return `> ${text}\n\n`;
      }

      case 'code': {
        const text = extractTextFromRichText(block.code?.rich_text);
        const language = block.code?.language || 'plain_text';
        return `\`\`\`${language}\n${text}\n\`\`\`\n\n`;
      }

      case 'divider': {
        return `---\n\n`;
      }

      default: {
        console.warn(`Unsupported block type: ${block.type}`);
        return '';
      }
    }
  }).join('');
}

/**
 * Helper function to extract text from Notion's rich_text arrays
 * @param {Array} richText - Notion rich text array
 * @returns {string} - Plain text content
 */
function extractTextFromRichText(richText) {
  if (!richText || !Array.isArray(richText)) return '';

  return richText.map(rt => {
    if (!rt) return '';
    if (rt.text && rt.text.content) return rt.text.content;
    if (rt.plain_text) return rt.plain_text;
    return '';
  }).join('');
}

module.exports = {
  createParagraphBlock,
  createSingleParagraphBlock,
  createHeadingBlock,
  createBulletedListItemBlock,
  createNumberedListItemBlock,
  createDividerBlock,
  createCodeBlock,
  createCalloutBlock,
  createToDoBlock,
  createToggleBlock,
  createQuoteBlock,
  parseMarkdownToBlocks,
  blocksToMarkdown,
  isBlockFormat,
  processContentToBlocks
};

/**
 * Notion Page Operations Routes
 * 
 * This module provides Express route handlers for additional Notion page operations including:
 * - Appending content to existing pages
 * - Updating page content by ID
 * - Creating standalone pages
 * - Archiving pages
 */

const express = require('express');
const router = express.Router();

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  sanitizeInput 
} = require('./api-utils');

const { 
  notionParentPageId 
} = require('./config');

const { 
  cache 
} = require('./cache');

const { 
  createHeadingBlock, 
  createParagraphBlock,
  parseMarkdownToBlocks,
  isBlockFormat,
  processContentToBlocks,
  blocksToMarkdown
} = require('./block-utils');

const { 
  findPageByTitle 
} = require('./page-utils');

/**
 * @route   PATCH /append-to-page-by-title
 * @desc    Appends content to an existing page by title, or creates a new page if it doesn't exist
 * @body    {string} title - The page title to append to
 * @body    {string|Array} content - The content to append (markdown string or block array)
 * @returns {Object} JSON response with operation status
 */
router.patch("/append-to-page-by-title", async (req, res) => {
  try {
    const { title, content } = req.body;

    // Input validation
    if (!title || !content) {
      return res.status(400).json({ error: "Missing title or content." });
    }

    if (typeof title !== 'string') {
      return res.status(400).json({ 
        error: "Invalid input. Title must be a string." 
      });
    }

    if (typeof content !== 'string' && !Array.isArray(content)) {
      return res.status(400).json({ 
        error: "Invalid content. Content must be a string or an array of blocks." 
      });
    }

    const sanitizedTitle = sanitizeInput(title);

    if (!sanitizedTitle) {
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    console.log(`Attempting to append to page titled "${sanitizedTitle}"...`);
    const match = await findPageByTitle(sanitizedTitle);
    let pageId;

    if (!match) {
      console.warn(`Creating new page titled "${sanitizedTitle}"...`);
      const createRes = await apiCallWithRetry(() => 
        notionApi.post('/pages', {
          parent: { type: "page_id", page_id: notionParentPageId },
          properties: {
            title: [
              {
                type: "text",
                text: { content: sanitizedTitle }
              }
            ]
          }
        })
      );

      pageId = createRes.data.id;

      // Clear cache after creating a new page
      cache.clear();
    } else {
      pageId = match.page.id;
    }

    // Process content into blocks, handling both markdown and block formats
    const contentBlocks = processContentToBlocks(content);

    // Log whether we processed markdown or block format
    console.log(`Processed content as ${isBlockFormat(content) ? 'block format' : 'markdown format'}`);

    // Handle API limits with chunks
    for (let i = 0; i < contentBlocks.length; i += 10) {
      const chunk = contentBlocks.slice(i, i + 10);
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: chunk
        })
      );
    }

    // Invalidate cache
    cache.invalidate(pageId);

    res.json({ 
      success: true, 
      pageId,
      message: match ? "Content appended to existing page" : "Created new page and appended content"
    });
  } catch (error) {
    handleApiError(res, error, "append-to-page-by-title");
  }
});

/**
 * @route   PATCH /update-page
 * @desc    Updates page content by ID
 * @body    {string} pageId - The Notion page ID to update
 * @body    {string|Array} content - The content to update (markdown string or block array)
 * @body    {boolean} [replaceAll=false] - Whether to replace all content (true) or append (false)
 * @returns {Object} JSON response with operation status
 */
router.patch("/update-page", async (req, res) => {
  try {
    const { pageId, content, replaceAll = false } = req.body;

    // Input validation
    if (!pageId || !content) {
      return res.status(400).json({ error: "Missing pageId or content." });
    }

    // Validate pageId format
    if (typeof pageId !== 'string' || !pageId.match(/^[a-f0-9-]+$/i)) {
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    // Validate content
    if (typeof content !== 'string' && !Array.isArray(content)) {
      return res.status(400).json({ 
        error: "Invalid content. Must be a string or an array of blocks." 
      });
    }

    // Process content into blocks, handling both markdown and block formats
    const contentBlocks = processContentToBlocks(content);

    // Log whether we processed markdown or block format
    console.log(`Processed content as ${isBlockFormat(content) ? 'block format' : 'markdown format'}`);

    // If replaceAll is true, we need to delete existing blocks first
    if (replaceAll) {
      try {
        // Get existing blocks
        const existingBlocksRes = await apiCallWithRetry(() => 
          notionApi.get(`/blocks/${pageId}/children?page_size=100`)
        );

        // Archive existing blocks (Notion API doesn't allow bulk deletion, so we do it one by one)
        const blockIds = existingBlocksRes.data.results.map(block => block.id);

        for (const blockId of blockIds) {
          await apiCallWithRetry(() => 
            notionApi.patch(`/blocks/${blockId}`, {
              archived: true
            })
          );
        }

        console.log(`Archived ${blockIds.length} existing blocks`);
      } catch (err) {
        console.error("Error while trying to archive existing blocks:", err.message);
        // Continue with the update even if archiving fails
      }
    }

    // Handle API limits with chunks
    for (let i = 0; i < contentBlocks.length; i += 10) {
      const chunk = contentBlocks.slice(i, i + 10);
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: chunk
        })
      );
    }

    // Invalidate cache
    cache.invalidate(pageId);

    res.json({ 
      success: true, 
      updated: true, 
      replaced: replaceAll,
      pageId 
    });
  } catch (error) {
    handleApiError(res, error, "update-page");
  }
});

/**
 * @route   PUT /post-standalone-page
 * @desc    Creates a standalone page with optional content
 * @body    {string} title - The title for the new page
 * @body    {string|Array} content - Optional content for the new page (markdown string or block array)
 * @returns {Object} JSON response with creation status and page ID
 */
router.put("/post-standalone-page", async (req, res) => {
  try {
    const { title, content } = req.body;
    console.log("Received request to create standalone page with title:", title);

    // Input validation
    if (!title) {
      return res.status(400).json({ error: "Missing title." });
    }

    if (typeof title !== 'string') {
      return res.status(400).json({ 
        error: "Invalid title. Must be a string." 
      });
    }

    if (content && typeof content !== 'string' && !Array.isArray(content)) {
      return res.status(400).json({ 
        error: "Invalid content. Must be a string or an array of blocks if provided." 
      });
    }

    const sanitizedTitle = sanitizeInput(title);

    if (!sanitizedTitle) {
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    // Start with a heading for the title
    const childrenBlocks = [createHeadingBlock(sanitizedTitle)];

    // Add content if provided - process into blocks
    if (content) {
      const contentBlocks = processContentToBlocks(content);
      childrenBlocks.push(...contentBlocks);

      // Log whether we processed markdown or block format
      console.log(`Processed content as ${isBlockFormat(content) ? 'block format' : 'markdown format'}`);
    }

    const response = await apiCallWithRetry(() => 
      notionApi.post('/pages', {
        parent: { type: "page_id", page_id: notionParentPageId },
        properties: {
          title: [
            {
              type: "text",
              text: { content: sanitizedTitle }
            }
          ]
        },
        children: childrenBlocks
      })
    );

    // Invalidate cache
    cache.clear();

    res.json({ 
      success: true, 
      pageId: response.data.id,
      message: "Standalone page created successfully"
    });
  } catch (error) {
    handleApiError(res, error, "create-standalone-page");
  }
});

/**
 * @route   GET /page/:id/content
 * @desc    Gets page content by ID with optional format conversion
 * @param   {string} id - The Notion page ID to get content from
 * @query   {string} format - Output format: 'blocks' (default) or 'markdown'
 * @returns {Object} JSON response with page content
 */
router.get("/page/:id/content", async (req, res) => {
  try {
    const pageId = req.params.id;
    const { format = 'blocks' } = req.query;

    if (!pageId) {
      return res.status(400).json({ error: "Missing page ID." });
    }

    // Validate pageId format
    if (!pageId.match(/^[a-f0-9-]+$/i)) {
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    // Validate format
    if (format !== 'blocks' && format !== 'markdown') {
      return res.status(400).json({
        error: "Invalid format. Must be 'blocks' or 'markdown'."
      });
    }

    // Get page blocks
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=100`)
    );

    const blocks = response.data.results;

    // Convert to requested format
    let formattedContent;
    if (format === 'markdown') {
      formattedContent = blocksToMarkdown(blocks);
    } else {
      formattedContent = blocks;
    }

    res.json({ 
      success: true, 
      pageId, 
      format,
      content: formattedContent 
    });
  } catch (error) {
    handleApiError(res, error, "get-page-content");
  }
});

