      });
    }

    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, {
        archived: true
      })
    );

    // Invalidate cache
    cache.invalidate(pageId);

    // Also remove any entries in the titles cache that might reference this page
    for (const [key] of Object.entries(cache.stores.titles)) {
