const express = require('express')
const notionApi = require('./notion-api')
const pageUtils = require('./page-utils')

const router = express.Router()
const DB_ID = process.env.NOTION_DATABASE_ID

router.put('/createentry', async (req, res, next) => {
  try {
    let title, properties = {}

    if (req.body.line) {
      const [key, value] = req.body.line.split(/:(.+)/).map(s => s.trim())
      if (!key || !value) return res.status(400).json({ error: 'Invalid line format. Use "key: value"' })
      title = pageUtils.normalizeKey(key)
      properties = {
        Name: { title: [{ text: { content: title } }] },
        Value: { rich_text: [{ text: { content: value } }] }
      }
    } else {
      title = req.body.title
      properties = req.body.properties || {}
      if (!title) return res.status(400).json({ error: 'Title is required' })
      properties = {
        Name: { title: [{ text: { content: title } }] },
        ...properties
      }
    }

    const page = await notionApi.createPage({
      parent: { database_id: DB_ID },
      properties
    })
    res.json({ created: true, id: page.id })
  } catch (err) {
    next(err)
  }
})

// Examine page structure before updating
router.patch('/updateentry', async (req, res, next) => {
  try {
    let page;

    if (req.body.key && req.body.value) {
      // If we get both idOrTitle AND key/value, use the ID directly
      if (req.body.idOrTitle) {
        try {
          // Format the ID correctly - remove any dashes if they exist
          let pageId = req.body.idOrTitle.replace(/-/g, '');

          // First retrieve the page to check its structure
          const pageDetails = await notionApi.retrievePage(pageId);
          console.log('Page properties:', Object.keys(pageDetails.properties));

          // Check if the property exists, otherwise we might need to create it
          const propertyExists = Object.keys(pageDetails.properties).includes(req.body.key);

          // Create property update object with proper formatting
          const propertyUpdates = {};

          if (propertyExists) {
            // If property exists, update it with the appropriate type
            const propType = pageDetails.properties[req.body.key]?.type || 'rich_text';

            if (propType === 'title') {
              propertyUpdates[req.body.key] = { 
                title: [{ text: { content: req.body.value } }] 
              };
            } else {
              propertyUpdates[req.body.key] = { 
                rich_text: [{ text: { content: req.body.value } }] 
              };
            }
          } else {
            // If property doesn't exist, default to rich_text
            propertyUpdates[req.body.key] = { 
              rich_text: [{ text: { content: req.body.value } }] 
            };
          }

          console.log('Attempting direct update with:', { pageId, properties: propertyUpdates });

          // Try to update directly with the ID
          const updated = await notionApi.updatePage(pageId, propertyUpdates);
          return res.json({ updated: true, id: updated.id });
        } catch (err) {
          console.error('Direct update failed:', err.message);
          // Fall through to try alternate methods
        }
      }

      // Standard key-based search flow
      try {
        // First try with Name property
        const { results } = await notionApi.queryDatabase(DB_ID)

        // Find the property that seems to be the title property
        const titleProperty = results.length > 0 ? 
          Object.keys(results[0]?.properties || {}).find(key => 
            results[0].properties[key].type === 'title') : 'Name'

        if (!titleProperty) {
          return res.status(400).json({ error: 'Could not determine title property in database' })
        }

        // Now query with the correct title property
        const { results: matchingPages } = await notionApi.queryDatabase(DB_ID, {
          filter: {
            property: titleProperty,
            title: { equals: pageUtils.normalizeKey(req.body.key) }
          }
        })

        page = matchingPages[0]
        if (!page) return res.status(404).json({ error: 'Key not found' })

        const updated = await notionApi.updatePage(page.id, {
          [req.body.key]: { rich_text: [{ text: { content: req.body.value } }] }
        })
        return res.json({ updated: true, id: updated.id })
      } catch (err) {
        console.error('Error during key-based update:', err.message)
        throw err
      }
    }

    const { idOrTitle, properties } = req.body
    if (!idOrTitle || !properties) return res.status(400).json({ error: 'Missing idOrTitle or properties' })

    page = await pageUtils.findPage(DB_ID, idOrTitle)
    if (!page) return res.status(404).json({ error: 'Database entry not found' })

    // Format properties for Notion API
    const formattedProperties = {}

    // Handle each property based on its type
    for (const [key, value] of Object.entries(properties)) {
      // Skip the Name property as it shouldn't be changed after creation
      if (key === 'Name') continue

      // Determine property type and format accordingly
      if (typeof value === 'string') {
        // Treat string values as rich_text by default
        formattedProperties[key] = { 
          rich_text: [{ text: { content: value } }] 
        }
      } else if (typeof value === 'number') {
        // Handle numbers
        formattedProperties[key] = { number: value }
      } else if (typeof value === 'boolean') {
        // Handle booleans
        formattedProperties[key] = { checkbox: value }
      } else if (value instanceof Date) {
        // Handle dates
        formattedProperties[key] = { 
          date: { start: value.toISOString().split('T')[0] } 
        }
      } else if (value && typeof value === 'object') {
        // If it's already formatted for Notion API, use as is
        formattedProperties[key] = value
      }
    }

    const updated = await notionApi.updatePage(page.id, formattedProperties)
    res.json({ updated: true, id: updated.id })
  } catch (err) {
    next(err)
  }
})

router.delete('/deleteentry', async (req, res, next) => {
  try {
    let page

    if (req.query.key) {
      const normKey = pageUtils.normalizeKey(req.query.key)
      const { results } = await notionApi.queryDatabase(DB_ID, {
        filter: {
          property: 'Name',
          title: { equals: normKey }
        }
      })
      page = results[0]
    } else if (req.query.idOrTitle) {
      page = await pageUtils.findPage(DB_ID, req.query.idOrTitle)
    } else {
      return res.status(400).json({ error: 'Missing key or idOrTitle' })
    }

    if (!page) return res.status(404).json({ error: 'Database entry not found' })
    const deleted = await notionApi.deleteBlock(page.id)
    res.json({ deleted: true, id: deleted.id })
  } catch (err) {
    next(err)
  }
})

