```javascript
router.get('/memories', asyncHandler(async (req, res) => {
  const databaseId = req.notionMemoryDBId;
  const { limit = 10, tag, search } = req.query;

  const errorMsg = validateParams({ databaseId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  // Build filter object
  let filter = {};

  if (tag) {
    filter = {
      property: 'tags',
      multi_select: {
        contains: tag
      }
    };
  }

  if (search) {
    filter = {
      property: 'title',
      title: {
        contains: search
      }
    };
  }

  // If both tag and search are provided, use an AND filter
  if (tag && search) {
    filter = {
      and: [
        {
          property: 'tags',
          multi_select: {
            contains: tag
          }
        },
        {
          property: 'title',
          title: {
            contains: search
          }
        }
      ]
    };
  }

  // Query the database with filter
  const response = await notionClient.queryDatabase(databaseId, filter);

  // Extract limited number of entries
  const entries = response.results
    .slice(0, parseInt(limit, 10))
    .map(page => {
      // Extract title
      const title = page.properties.title?.title
        ?.map(t => t.plain_text)
        .join('') || 'Untitled';

      // Extract tags
      const tags = page.properties.tags?.multi_select
        ?.map(item => item.name) || [];

      return {
        id: page.id,
        title,
        tags,
        created_time: page.created_time,
        last_edited_time: page.last_edited_time,
        url: page.url
      };
    });

  res.json({
    entries,
    has_more: response.has_more
  });
}));
```

