  const lines = markdownText.split('\n');

  let i = 0;
  while (i < lines.length) {
    const line = lines[i].trim();

    // Skip empty lines but add a paragraph with empty string to preserve spacing
    if (!line) {
      blocks.push(createParagraphBlock(""));
      i++;
      continue;
    }

    // Heading 1: # Heading
    if (line.startsWith('# ')) {
      blocks.push(createHeadingBlock(line.substring(2), 1));
    }
    // Heading 2: ## Heading
    else if (line.startsWith('## ')) {
      blocks.push(createHeadingBlock(line.substring(3), 2));
    }
    // Heading 3: ### Heading
    else if (line.startsWith('### ')) {
      blocks.push(createHeadingBlock(line.substring(4), 3));
    }
    // Divider: ---
    else if (line === '---') {
      blocks.push(createDividerBlock());
    }
    // Bullet list items: * Item or - Item
    else if (line.startsWith('* ') || line.startsWith('- ')) {
      blocks.push(createBulletedListItemBlock(line.substring(2)));
    }
    // Numbered list items: 1. Item
    else if (/^\d+\.\s/.test(line)) {
      const content = line.substring(line.indexOf('.') + 1).trim();
      blocks.push(createNumberedListItemBlock(content));
    }
    // Code blocks: ```language
    else if (line.startsWith('```')) {
      const language = line.substring(3).trim() || 'plain_text';

      // Find the closing tag
      let codeContent = [];
      let j = i + 1;
      while (j < lines.length && !lines[j].trim().startsWith('```')) {
        codeContent.push(lines[j]);
        j++;
      }

      blocks.push(createCodeBlock(codeContent.join('\n'), language));
      i = j; // Skip to after the closing tag
    }
    // Default to paragraph
    else {
      blocks.push(createParagraphBlock(line));
    }

    i++;
  }

  return blocks;
}
```

