/**
 * Converts Notion blocks to markdown text
 * @param {Array} blocks - Array of Notion block objects
 * @returns {string} - Markdown representation of the blocks
 */
function blocksToMarkdown(blocks) {
  if (!Array.isArray(blocks) || blocks.length === 0) {
    return '';
  }

  const markdownParts = [];

  for (const block of blocks) {
    if (!block || !block.type) {
      continue; // Skip invalid blocks
    }

    // Helper function to extract text from rich_text array
    const extractText = (richTextArray) => {
      if (!Array.isArray(richTextArray)) return '';
      return richTextArray.map(rt => rt.plain_text || rt.text?.content || '').join('');
    };

    switch (block.type) {
      case 'paragraph': {
        const text = extractText(block.paragraph?.rich_text);
        markdownParts.push(text);
        markdownParts.push(''); // Add empty line after paragraph
        break;
      }

      case 'heading_1': {
        const text = extractText(block.heading_1?.rich_text);
        markdownParts.push(`# ${text}`);
        markdownParts.push(''); // Add empty line after heading
        break;
      }

      case 'heading_2': {
        const text = extractText(block.heading_2?.rich_text);
        markdownParts.push(`## ${text}`);
        markdownParts.push(''); // Add empty line after heading
        break;
      }

      case 'heading_3': {
        const text = extractText(block.heading_3?.rich_text);
        markdownParts.push(`### ${text}`);
        markdownParts.push(''); // Add empty line after heading
        break;
      }

      case 'bulleted_list_item': {
        const text = extractText(block.bulleted_list_item?.rich_text);
        markdownParts.push(`- ${text}`);
        break;
      }

      case 'numbered_list_item': {
        const text = extractText(block.numbered_list_item?.rich_text);
        markdownParts.push(`1. ${text}`); // Using 1. for all items as markdown renderers handle numbering
        break;
      }

      case 'to_do': {
        const text = extractText(block.to_do?.rich_text);
        const checked = block.to_do?.checked;
        markdownParts.push(`${checked ? '[x]' : '[ ]'} ${text}`);
        break;
      }

      case 'toggle': {
        const text = extractText(block.toggle?.rich_text);
        markdownParts.push(`>>> ${text}`);
        break;
      }

      case 'code': {
        const text = extractText(block.code?.rich_text);
        const language = block.code?.language || 'plain_text';
        markdownParts.push(`\`\`\`${language}`);
        markdownParts.push(text);
        markdownParts.push('```');
        markdownParts.push(''); // Add empty line after code block
        break;
      }

      case 'quote': {
        const text = extractText(block.quote?.rich_text);
        markdownParts.push(`> ${text}`);
        markdownParts.push(''); // Add empty line after quote
        break;
      }

      case 'callout': {
        const text = extractText(block.callout?.rich_text);
        const emoji = block.callout?.icon?.emoji || '💡';
        markdownParts.push(`> ${emoji} ${text}`);
        markdownParts.push(''); // Add empty line after callout
        break;
      }

      case 'divider': {
        markdownParts.push('---');
        markdownParts.push(''); // Add empty line after divider
        break;
      }

      // Handle additional block types as needed
      default: {
        // For unhandled block types, try to extract any text content
        if (block[block.type]?.rich_text) {
          const text = extractText(block[block.type].rich_text);
          if (text) {
            markdownParts.push(text);
            markdownParts.push(''); // Add empty line
          }
        }
        break;
      }
    }
  }

  // Clean up empty lines (no more than one consecutive empty line)
  let result = markdownParts.join('\n');
  result = result.replace(/\n{3,}/g, '\n\n'); // Replace 3+ newlines with 2
  return result.trim();
}

/**
 * Format detection and conversion utilities
 * 
 * These functions handle automatic detection and conversion between:
 * - Markdown text format
 * - Notion block structure format
 */

/**
 * Determines if the content is already in Notion block format
 * @param {string|Array} content - The content to check
 * @returns {boolean} - True if content appears to be in block format
 */
function isBlockFormat(content) {
  // If it's already an array, assume it's block format
  if (Array.isArray(content)) {
    return content.length > 0 && 
           content.every(block => 
             block && typeof block === 'object' && 
             typeof block.type === 'string'
           );
  }

  // If it's a string, try to parse it as JSON
  if (typeof content === 'string') {
    try {
      const parsed = JSON.parse(content);
      // Check if it's an array of blocks with expected properties
      return Array.isArray(parsed) && 
             parsed.length > 0 && 
             parsed.every(block => 
               block && typeof block === 'object' && 
               typeof block.type === 'string'
             );
    } catch (e) {
      // If it's not valid JSON, it's not block format
      return false;
    }
  }

  return false;
}

/**
 * Handles content that could be in either markdown or block format
 * @param {string|Array} content - The content to process
 * @param {string} [preferredFormat='blocks'] - The desired output format ('blocks' or 'markdown')
 * @returns {Object} - Object containing detected format and converted content
 */
function handleContentFormat(content, preferredFormat = 'blocks') {
  const { sanitizeInput } = require('./api-utils');

  // Default return structure
  const result = {
    originalFormat: null,
    outputFormat: preferredFormat,
    content: null
  };

  // Guard against empty content
  if (!content) {
    console.warn("Empty content provided to handleContentFormat");
    return {
      originalFormat: 'empty',
      outputFormat: preferredFormat,
      content: preferredFormat === 'blocks' ? [] : ''
    };
  }

  // Detect format
  const isBlocks = isBlockFormat(content);
  result.originalFormat = isBlocks ? 'blocks' : 'markdown';

  // Process based on detected format and preferred output
  if (isBlocks) {
    // Input is blocks format
    const blockArray = typeof content === 'string' ? JSON.parse(content) : content;

    if (preferredFormat === 'blocks') {
      // No conversion needed
      result.content = blockArray;
    } else {
      // Convert blocks to markdown
      const { blocksToMarkdown } = require('./block-utils');
      result.content = blocksToMarkdown(blockArray);
    }
  } else {
    // Input is markdown format
    const markdownText = typeof content === 'object' ? 
          JSON.stringify(content) : sanitizeInput(content, "");

    if (preferredFormat === 'markdown') {
      // No conversion needed
      result.content = markdownText;
    } else {
      // Convert markdown to blocks
      const { parseMarkdownToBlocks } = require('./block-utils');
      result.content = parseMarkdownToBlocks(markdownText);
    }
  }

  console.log(`Content format: ${result.originalFormat} → ${result.outputFormat}`);
  return result;
}

module.exports = {
  isBlockFormat,
  handleContentFormat
};

/**
 * Example of using the universal format handler in the update-page route
 */
router.patch("/update-page", async (req, res) => {
  try {
    const { pageId, content, outputFormat = 'blocks' } = req.body;

    // Input validation
    if (!pageId || !content) {
      return res.status(400).json({ error: "Missing pageId or content." });
    }

    // Validate pageId format
    if (typeof pageId !== 'string' || !pageId.match(/^[a-f0-9-]+$/i)) {
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    // Handle content in either format (markdown or blocks)
    const { handleContentFormat } = require('./format-utils');
    const processedContent = handleContentFormat(content, 'blocks');

    // Log the conversion for debugging
    console.log(`Content converted from ${processedContent.originalFormat} to blocks format`);

    // Handle API limits with chunks
    const contentBlocks = processedContent.content;
    for (let i = 0; i < contentBlocks.length; i += 10) {
      const chunk = contentBlocks.slice(i, i + 10);
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: chunk
        })
      );
    }

    // Invalidate cache
    cache.invalidate(pageId);

    // For API responses, return content in the requested format
    // This is useful if the client wants the content back in a specific format
    let responseContent = contentBlocks;
    if (outputFormat === 'markdown') {
      const { blocksToMarkdown } = require('./block-utils');
      responseContent = blocksToMarkdown(contentBlocks);
    }

    res.json({ 
      success: true, 
      updated: true, 
      pageId,
      originalFormat: processedContent.originalFormat,
      outputFormat: outputFormat === 'markdown' ? 'markdown' : 'blocks',
      contentPreview: outputFormat === 'markdown' ? 
        responseContent.substring(0, 100) : 
        `${contentBlocks.length} blocks processed`
    });
  } catch (error) {
    handleApiError(res, error, "update-page");
  }
});

/**
 * Example of adding a new route to get page content in either format
 */
router.get("/get-page-content/:id", async (req, res) => {
  try {
    const pageId = req.params.id;
    const { format = 'markdown' } = req.query;

    if (!pageId) {
      return res.status(400).json({ error: "Missing page ID." });
    }

    // Validate pageId format
    if (!pageId.match(/^[a-f0-9-]+$/i)) {
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    // Get page blocks from Notion
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children`)
    );

    const blocks = response.data.results;

    // Choose output format based on request
    if (format.toLowerCase() === 'blocks') {
      // Send blocks directly
      res.json({ 
        success: true, 
        pageId,
        format: 'blocks',
        content: blocks
      });
    } else {
      // Convert to markdown
      const { blocksToMarkdown } = require('./block-utils');
      const markdown = blocksToMarkdown(blocks);

      res.json({ 
        success: true, 
        pageId,
        format: 'markdown',
        content: markdown
      });
    }
  } catch (error) {
    handleApiError(res, error, "get-page-content");
  }
});

