/**
 * Improved error handling for API requests with logging integration
 * @param {Object} res - Express response object
 * @param {Error} error - The error that occurred
 * @param {string} context - Context description for the error
 */
const handleApiError = (res, error, context) => {
  // Get requestId from response object if available
  const requestId = res.req?.requestId;
  
  // Determine appropriate status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';
  let errorDetails = {};
  
  if (error.response) {
    // The request was made and the server responded with a status code
    // that falls out of the range of 2xx
    statusCode = error.response.status;
    errorMessage = error.response.data?.message || error.message;
    errorDetails = error.response.data || {};
    
    // Special handling for rate limit errors
    if (statusCode === 429) {
      const retryAfter = error.response.headers?.['retry-after'] || 
                       error.response.headers?.['x-notion-rate-limit-reset'] || 
                       '10';
      
      errorMessage = `Rate limit exceeded. Please retry after ${retryAfter} seconds.`;
      errorDetails.retryAfter = retryAfter;
    }
  } else if (error.request) {
    // The request was made but no response was received
    statusCode = 503; // Service Unavailable
    errorMessage = 'No response received from Notion API';
    errorDetails = { errorCode: 'NO_RESPONSE', message: error.message };
  } else {
    // Something happened in setting up the request that triggered an Error
    errorMessage = error.message;
    errorDetails = { errorCode: 'REQUEST_SETUP_ERROR' };
  }
  
  // Add request context to the error
  errorDetails.context = context;
  
  // Log the error with detailed information
  logger.error(`API Error in ${context}: ${errorMessage}`, {
    statusCode,
    errorMessage,
    errorDetails,
    originalError: {
      message: error.message,
      stack: error.stack
    }
  }, requestId);
  
  res.status(statusCode).json({ 
    error: errorMessage,
    details: errorDetails,
    context
  });
};

/**
 * Determines if an operation is a write operation based on HTTP method or endpoint
 * @param {Function} requestFn - The API request function
 * @returns {boolean} - True if this is a write operation
 */
function isWriteOperation(requestFn) {
  const fnStr = requestFn.toString().toLowerCase();
  
  // Check for write HTTP methods
  if (fnStr.includes('post(') || 
      fnStr.includes('put(') || 
      fnStr.includes('patch(') || 
      fnStr.includes('delete(')) {
    return true;
  }
  
  // Check for write endpoints
  if (fnStr.includes('/pages') && !fnStr.includes('get(')) {
    return true;
  }
  
  if (fnStr.includes('/blocks') && !fnStr.includes('get(')) {
    return true;
  }
  
  return false;
}

/**
 * Enhanced API call with rate limiting, retry logic, exponential backoff, and logging
 * @param {Function} fn - Function that returns a promise for the API call
 * @param {Object} options - Configuration options
 * @param {number} [options.maxRetries=3] - Maximum number of retry attempts
 * @param {number} [options.baseDelay=1000] - Base delay in milliseconds
 * @param {number} [options.maxDelay=10000] - Maximum delay in milliseconds
 * @param {number} [options.timeout] - Timeout in milliseconds
 * @param {string} [options.operationType] - Type of operation ('read' or 'write')
 * @param {string} [options.resourceType] - Type of resource being accessed
 * @param {string} [options.requestId] - Request ID for logging correlation
 * @returns {Promise<*>} - The API response
 */
async function apiCallWithRetry(fn, options = {}) {
  const maxRetries = options.maxRetries || 3;
  const baseDelay = options.baseDelay || 1000; // 1 second
  const maxDelay = options.maxDelay || 10000; // 10 seconds
  const timeoutMs = options.timeout || CONFIG.API_TIMEOUT;
  const requestId = options.requestId;
  
  // Determine operation type if not specified
  const operationType = options.operationType || (isWriteOperation(fn) ? 'write' : 'read');
  const resourceType = options.resourceType || null;
  
  // Extract endpoint for logging (best effort)
  let endpoint = 'unknown';
  try {
    const fnStr = fn.toString();
    const endpointMatch = fnStr.match(/\/([a-z0-9_-]+)/i);
    if (endpointMatch) {
      endpoint = endpointMatch[0];
    }
  } catch (e) {
    // Ignore extraction errors
  }
  
  // Create the actual request function with timeout handling
  const requestWithTimeout = async () => {
    const timeoutPromise = new Promise((_, reject) => {
      setTimeout(() => reject(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs);
    });
    
    const resultPromise = fn();
    
    // Race between the API call and the timeout
    return Promise.race([resultPromise, timeoutPromise]);
  };
  
  // Log the API call
  logger.debug(`API call: ${operationType} ${endpoint}`, {
    operationType,
    resourceType,
    endpoint,
    timeoutMs
  }, requestId);
  
  // Use the rate limiter for Notion API calls
  if (fn.toString().includes('notionApi')) {
    return notionRateLimiter.queueRequest(requestWithTimeout, {
      operationType,
      resourceType,
      requestId
    });
  }
  
  // For non-Notion API calls (e.g., GitHub), use the original retry logic
  let retries = 0;
  
  while (true) {
    try {
      const response = await requestWithTimeout();
      logger.debug(`API call successful: ${operationType} ${endpoint}`, {
        statusCode: response.status,
        responseSize: JSON.stringify(response.data).length
      }, requestId);
      return response;
    } catch (error) {
      const isRetryable = 
        error.response?.status === 429 || // Rate limited
        error.response?.status === 503 || // Service unavailable
        error.response?.status >= 500 ||  // Server errors
        error.code === 'ECONNRESET' ||    // Connection reset
        error.code === 'ETIMEDOUT' ||     // Connection timeout
        error.message.includes('timeout'); // Generic timeout error
        
      if (isRetryable && retries < maxRetries) {
        // Calculate delay with exponential backoff and jitter
        const exponentialDelay = Math.min(
          maxDelay,
          baseDelay * Math.pow(2, retries)
        );
        // Add jitter: random value between 0 and 1 * 0.5 * calculated delay
        const jitter = Math.random() * 0.5 * exponentialDelay;
        const delay = exponentialDelay + jitter;
        
        const retryMessage = `API call failed with ${error.response?.status || error.code || 'unknown error'}, retrying in ${Math.round(delay)}ms... (${retries + 1}/${maxRetries})`;
        logger.warn(retryMessage, {
          error: error.message,
          statusCode: error.response?.status,
          errorCode: error.code,
          retry: {
            current: retries + 1,
            max: maxRetries,
            delay: Math.round(delay)
          }
        }, requestId);
        
        await new Promise(resolve => setTimeout(resolve, delay));
        retries++;
      } else {
        // Either not retryable or max retries exceeded
        if (retries >= maxRetries) {
          const errorMessage = `Max retries (${maxRetries}) exceeded for API call.`;
          logger.error(errorMessage, {
            error: error.message,
            statusCode: error.response?.status,
            errorCode: error.code,
            maxRetries
          }, requestId);
        } else {
          logger.error(`API call failed: ${operationType} ${endpoint}`, {
            error: error.message,
            statusCode: error.response?.status,
            errorCode: error.code,
            retryable: isRetryable
          }, requestId);
        }
        throw error;
      }
    }
  }
}

/**
 * Safely sanitizes input strings to prevent injection and handle edge cases
 * @param {*} input - The input to sanitize
 * @param {string} [defaultValue=""] - Default value if input is invalid
 * @returns {string} - Sanitized input string
 */
function sanitizeInput(input, defaultValue = "") {
  if (input === null || input === undefined) return defaultValue;
  if (typeof input !== 'string') {
    try {
      input = String(input);
    } catch (e) {
      return defaultValue;
    }
  }
  return input.trim();
}

/**
 * Normalizes keys for memory functions with better error handling
 * @param {string} key - The key to normalize
 * @returns {string} - Normalized key
 */
function normalizeKey(key) {
  if (!key) return "";
  
  const sanitizedKey = sanitizeInput(key, "");
  
  try {
    return decodeURIComponent(sanitizedKey.toLowerCase());
  } catch (e) {
    logger.warn(`Error decoding URI component: ${key}`, e);
    return sanitizedKey.toLowerCase();
  }
}

/**
 * Creates a paginated request to Notion API with appropriate handling
 * @param {string} endpoint - The API endpoint to call
 * @param {Object} params - Request parameters
 * @param {Object} options - Pagination options
 * @param {number} [options.pageSize] - Items per page
 * @param {number} [options.maxItems] - Maximum total items to fetch
 * @param {number} [options.concurrentRequests] - Number of concurrent requests for pagination
 * @param {string} [options.requestId] - Request ID for logging correlation
 * @returns {Promise<Array>} - Array of results from all pages
 */
async function paginatedRequest(endpoint, params = {}, options = {}) {
  const pageSize = options.pageSize || CONFIG.DEFAULT_PAGE_SIZE;
  const maxItems = options.maxItems || CONFIG.MAX_ITEMS_PER_PAGE;
  const concurrentRequests = options.concurrentRequests || 1;
  const requestId = options.requestId;
  
  let results = [];
  let hasMore = true;
  let startCursor = undefined;
  let pageCount = 0;
  
  logger.debug(`Starting paginated request to ${endpoint}`, {
    params,
    pageSize,
    maxItems,
    concurrentRequests
  }, requestId);
  
  const makeRequest = async (cursor) => {
    const queryParams = { ...params, page_size: pageSize };
    if (cursor) {
      queryParams.start_cursor = cursor;
    }
    
    const response = await apiCallWithRetry(() => {
      if (endpoint === 'search') {
        return notionApi.post('/search', queryParams);
      } else {
        const url = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
        return notionApi.get(url, { params: queryParams });
      }
    }, { operationType: 'read', requestId });
    
    return response.data;
  };
  
  // First request to get initial batch and pagination info
  try {
    const firstBatch = await makeRequest(undefined);
    results = [...firstBatch.results];
    hasMore = firstBatch.has_more;
    startCursor = firstBatch.next_cursor;
    pageCount++;
    
    logger.info(`Fetched page ${pageCount} with ${results.length} items from ${endpoint}`, {
      endpoint,
      pageCount,
      itemCount: results.length,
      hasMore
    }, requestId);
    
    // If we need more pages and haven't hit limits
    const cursors = [];
    while (hasMore && results.length < maxItems && pageCount < 50) {
      cursors.push(startCursor);
      
      // Process in batches of concurrent requests
      if (cursors.length >= concurrentRequests || !hasMore) {
        const batchResults = await Promise.all(
          cursors.map(cursor => makeRequest(cursor))
        );
        
        for (const data of batchResults) {
          results = results.concat(data.results || []);
          hasMore = data.has_more;
          startCursor = data.next_cursor;
          pageCount++;
          
          logger.info(`Fetched page ${pageCount} with ${data.results.length} items from ${endpoint}`, {
            endpoint,
            pageCount,
            itemCount: data.results.length,
            totalItems: results.length,
            hasMore
          }, requestId);
          
          if (results.length >= maxItems) {
            const warningMsg = `Pagination limit reached (${maxItems} items)`;
            logger.warn(warningMsg, { maxItems, endpoint }, requestId);
            hasMore = false;
            break;
          }
          
          if (pageCount >= 50) {
            const errorMsg = `Too many pages fetched (${pageCount}). Possible API issue.`;
            logger.error(errorMsg, { pageCount, endpoint }, requestId);
            hasMore = false;
            break;
          }
          
          if (!data.has_more) {
            hasMore = false;
            break;
          }
        }
        
        cursors.length = 0;
      }
    }
    
    logger.info(`Completed paginated request to ${endpoint}`, {
      endpoint,
      totalItems: results.length,
      pageCount
    }, requestId);
    
    return results;
  } catch (error) {
    logger.error(`Pagination error for ${endpoint}`, {
      error: error.message,
      stack: error.stack,
      endpoint,
      pageCount
    }, requestId);
    throw error;
  }
}

