  }
  
  // If it's a string, try to parse it as JSON
  if (typeof content === 'string') {
    try {
      const parsed = JSON.parse(content);
      // Check if it's an array of blocks with expected properties
      if (Array.isArray(parsed)) {
        return parsed.length > 0 && 
