/**
 * Notion Page Operations Routes
 * 
 * This module provides Express route handlers for additional Notion page operations including:
 * - Appending content to existing pages
 * - Updating page content by ID
 * - Creating standalone pages
 * - Archiving pages
 */

const express = require('express');
const router = express.Router();

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  sanitizeInput 
} = require('./api-utils');

const { 
  notionParentPageId 
} = require('./config');

const { 
  cache 
} = require('./cache');

const { 
  createHeadingBlock, 
  createParagraphBlock,
  parseMarkdownToBlocks,
  isBlockFormat,
  processContentToBlocks,
  blocksToMarkdown
} = require('./block-utils');

const { 
  findPageByTitle 
} = require('./page-utils');

const logger = require('./logger');

/**
 * @route   PATCH /append-to-page-by-title
 * @desc    Appends content to an existing page by title, or creates a new page if it doesn't exist
 * @body    {string} title - The page title to append to
 * @body    {string|Array} content - The content to append (markdown string or block array)
 * @returns {Object} JSON response with operation status
 */
router.patch("/append-to-page-by-title", async (req, res) => {
  try {
    const { title, content } = req.body;

    // Input validation
    if (!title || !content) {
      logger.warn("Missing title or content for append operation", 
        { hasTitle: !!title, hasContent: !!content }, req.requestId);
      return res.status(400).json({ error: "Missing title or content." });
    }
    
    if (typeof title !== 'string') {
      logger.warn("Invalid title type for append operation", { titleType: typeof title }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid input. Title must be a string." 
      });
    }
    
    if (typeof content !== 'string' && !Array.isArray(content)) {
      logger.warn("Invalid content type for append operation", 
        { contentType: typeof content, isArray: Array.isArray(content) }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid content. Content must be a string or an array of blocks." 
      });
    }
    
    const sanitizedTitle = sanitizeInput(title);

    if (!sanitizedTitle) {
      logger.warn("Empty title after sanitization", { title }, req.requestId);
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    logger.info(`Attempting to append to page titled "${sanitizedTitle}"`, null, req.requestId);
    const match = await findPageByTitle(sanitizedTitle);
    let pageId;

    if (!match) {
      logger.info(`Page "${sanitizedTitle}" not found, creating new page`, null, req.requestId);
      const createRes = await apiCallWithRetry(() => 
        notionApi.post('/pages', {
          parent: { type: "page_id", page_id: notionParentPageId },
          properties: {
            title: [
              {
                type: "text",
                text: { content: sanitizedTitle }
              }
            ]
          }
        })
      , { requestId: req.requestId });

      pageId = createRes.data.id;
      logger.info(`Created new page with title "${sanitizedTitle}"`, { pageId }, req.requestId);
      
      // Clear cache after creating a new page
      cache.clear();
    } else {
      pageId = match.page.id;
      logger.info(`Found existing page with title "${sanitizedTitle}"`, { pageId }, req.requestId);
    }

    // Process content into blocks, handling both markdown and block formats
    const contentBlocks = processContentToBlocks(content);
    
    // Log whether we processed markdown or block format
    const contentFormat = isBlockFormat(content) ? 'block' : 'markdown';
    logger.info(`Processed content as ${contentFormat} format`, { contentFormat }, req.requestId);
    logger.debug(`Generated ${contentBlocks.length} blocks to append`, 
      { blockCount: contentBlocks.length }, req.requestId);
    
    // Handle API limits with chunks
    for (let i = 0; i < contentBlocks.length; i += 10) {
      const chunk = contentBlocks.slice(i, i + 10);
      logger.debug(`Appending chunk ${Math.floor(i/10) + 1}/${Math.ceil(contentBlocks.length/10)}`, 
        { chunkSize: chunk.length, offset: i }, req.requestId);
        
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: chunk
        })
      , { requestId: req.requestId });
    }

    // Invalidate cache
    cache.invalidate(pageId);
    logger.info(`Content successfully appended to page "${sanitizedTitle}"`, { pageId }, req.requestId);

    res.json({ 
      success: true, 
      pageId,
      message: match ? "Content appended to existing page" : "Created new page and appended content"
    });
  } catch (error) {
    logger.error("Error appending to page by title", error, req.requestId);
    handleApiError(res, error, "append-to-page-by-title");
  }
});

/**
 * @route   PATCH /update-page
 * @desc    Updates page content by ID
 * @body    {string} pageId - The Notion page ID to update
 * @body    {string|Array} content - The content to update (markdown string or block array)
 * @body    {boolean} [replaceAll=false] - Whether to replace all content (true) or append (false)
 * @returns {Object} JSON response with operation status
 */
router.patch("/update-page", async (req, res) => {
  try {
    const { pageId, content, replaceAll = false } = req.body;

    // Input validation
    if (!pageId || !content) {
      logger.warn("Missing pageId or content for update operation", 
        { hasPageId: !!pageId, hasContent: !!content }, req.requestId);
      return res.status(400).json({ error: "Missing pageId or content." });
    }
    
    // Validate pageId format
    if (typeof pageId !== 'string' || !pageId.match(/^[a-f0-9-]+$/i)) {
      logger.warn("Invalid pageId format", { pageId }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }
    
    // Validate content
    if (typeof content !== 'string' && !Array.isArray(content)) {
      logger.warn("Invalid content type for update operation", 
        { contentType: typeof content, isArray: Array.isArray(content) }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid content. Must be a string or an array of blocks." 
      });
    }
    
    logger.info(`Updating page with ID ${pageId}`, { pageId, replaceAll }, req.requestId);
    
    // Process content into blocks, handling both markdown and block formats
    const contentBlocks = processContentToBlocks(content);
    
    // Log whether we processed markdown or block format
    const contentFormat = isBlockFormat(content) ? 'block' : 'markdown';
    logger.info(`Processed content as ${contentFormat} format`, { contentFormat }, req.requestId);
    logger.debug(`Generated ${contentBlocks.length} blocks for update`, 
      { blockCount: contentBlocks.length }, req.requestId);
    
    // If replaceAll is true, we need to delete existing blocks first
    if (replaceAll) {
      try {
        logger.info(`Replacing all content: fetching existing blocks to archive`, { pageId }, req.requestId);
        
        // Get existing blocks
        const existingBlocksRes = await apiCallWithRetry(() => 
          notionApi.get(`/blocks/${pageId}/children?page_size=100`)
        , { requestId: req.requestId });
        
        // Archive existing blocks (Notion API doesn't allow bulk deletion, so we do it one by one)
        const blockIds = existingBlocksRes.data.results.map(block => block.id);
        
        logger.info(`Archiving ${blockIds.length} existing blocks`, 
          { blockCount: blockIds.length }, req.requestId);
        
        for (const blockId of blockIds) {
          logger.debug(`Archiving block ${blockId}`, { blockId }, req.requestId);
          await apiCallWithRetry(() => 
            notionApi.patch(`/blocks/${blockId}`, {
              archived: true
            })
          , { requestId: req.requestId });
        }
        
        logger.info(`Successfully archived ${blockIds.length} existing blocks`, 
          { blockCount: blockIds.length }, req.requestId);
      } catch (err) {
        logger.error("Error archiving existing blocks", err, req.requestId);
        // Continue with the update even if archiving fails
      }
    }
    
    // Handle API limits with chunks
    for (let i = 0; i < contentBlocks.length; i += 10) {
      const chunk = contentBlocks.slice(i, i + 10);
      logger.debug(`Updating with chunk ${Math.floor(i/10) + 1}/${Math.ceil(contentBlocks.length/10)}`, 
        { chunkSize: chunk.length, offset: i }, req.requestId);
        
      await apiCallWithRetry(() => 
        notionApi.patch(`/blocks/${pageId}/children`, {
          children: chunk
        })
      , { requestId: req.requestId });
    }

    // Invalidate cache
    cache.invalidate(pageId);
    logger.info(`Content successfully updated for page ID ${pageId}`, 
      { pageId, replaceAll, blockCount: contentBlocks.length }, req.requestId);

    res.json({ 
      success: true, 
      updated: true, 
      replaced: replaceAll,
      pageId 
    });
  } catch (error) {
    logger.error("Error updating page", error, req.requestId);
    handleApiError(res, error, "update-page");
  }
});

/**
 * @route   PUT /post-standalone-page
 * @desc    Creates a standalone page with optional content
 * @body    {string} title - The title for the new page
 * @body    {string|Array} content - Optional content for the new page (markdown string or block array)
 * @returns {Object} JSON response with creation status and page ID
 */
router.put("/post-standalone-page", async (req, res) => {
  try {
    const { title, content } = req.body;
    logger.info(`Received request to create standalone page with title: ${title}`, 
      { title, hasContent: !!content }, req.requestId);

    // Input validation
    if (!title) {
      logger.warn("Missing title for standalone page", null, req.requestId);
      return res.status(400).json({ error: "Missing title." });
    }
    
    if (typeof title !== 'string') {
      logger.warn("Invalid title type for standalone page", { titleType: typeof title }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid title. Must be a string." 
      });
    }
    
    if (content && typeof content !== 'string' && !Array.isArray(content)) {
      logger.warn("Invalid content type for standalone page", 
        { contentType: typeof content, isArray: Array.isArray(content) }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid content. Must be a string or an array of blocks if provided." 
      });
    }
    
    const sanitizedTitle = sanitizeInput(title);

    if (!sanitizedTitle) {
      logger.warn("Empty title after sanitization", { title }, req.requestId);
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    // Start with a heading for the title
    const childrenBlocks = [createHeadingBlock(sanitizedTitle)];
    
    // Add content if provided - process into blocks
    if (content) {
      const contentBlocks = processContentToBlocks(content);
      childrenBlocks.push(...contentBlocks);
      
      // Log whether we processed markdown or block format
      const contentFormat = isBlockFormat(content) ? 'block' : 'markdown';
      logger.info(`Processed content as ${contentFormat} format`, 
        { contentFormat, blockCount: contentBlocks.length }, req.requestId);
    }
    
    logger.info(`Creating standalone page titled "${sanitizedTitle}"`, 
      { blockCount: childrenBlocks.length }, req.requestId);
      
    const response = await apiCallWithRetry(() => 
      notionApi.post('/pages', {
        parent: { type: "page_id", page_id: notionParentPageId },
        properties: {
          title: [
            {
              type: "text",
              text: { content: sanitizedTitle }
            }
          ]
        },
        children: childrenBlocks
      })
    , { requestId: req.requestId });

    const pageId = response.data.id;
    logger.info(`Successfully created standalone page with title "${sanitizedTitle}"`, 
      { pageId }, req.requestId);

    // Invalidate cache
    cache.clear();

    res.json({ 
      success: true, 
      pageId,
      message: "Standalone page created successfully"
    });
  } catch (error) {
    logger.error("Error creating standalone page", error, req.requestId);
    handleApiError(res, error, "create-standalone-page");
  }
});

/**
 * @route   GET /page/:id/content
 * @desc    Gets page content by ID with optional format conversion
 * @param   {string} id - The Notion page ID to get content from
 * @query   {string} format - Output format: 'blocks' (default) or 'markdown'
 * @returns {Object} JSON response with page content
 */
router.get("/page/:id/content", async (req, res) => {
  try {
    const pageId = req.params.id;
    const { format = 'blocks' } = req.query;
    
    if (!pageId) {
      logger.warn("Missing page ID for content retrieval", null, req.requestId);
      return res.status(400).json({ error: "Missing page ID." });
    }
    
    // Validate pageId format
    if (!pageId.match(/^[a-f0-9-]+$/i)) {
      logger.warn("Invalid pageId format", { pageId }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }
    
    // Validate format
    if (format !== 'blocks' && format !== 'markdown') {
      logger.warn("Invalid format for content retrieval", { format }, req.requestId);
      return res.status(400).json({
        error: "Invalid format. Must be 'blocks' or 'markdown'."
      });
    }

    logger.info(`Getting content for page ID ${pageId} in ${format} format`, 
      { pageId, format }, req.requestId);

    // Get page blocks
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=100`)
    , { requestId: req.requestId });

    const blocks = response.data.results;
    logger.debug(`Retrieved ${blocks.length} blocks for page ID ${pageId}`, 
      { blockCount: blocks.length }, req.requestId);
    
    // Convert to requested format
    let formattedContent;
    if (format === 'markdown') {
      formattedContent = blocksToMarkdown(blocks);
      logger.debug(`Converted blocks to markdown (${formattedContent.length} chars)`, 
        { contentLength: formattedContent.length }, req.requestId);
    } else {
      formattedContent = blocks;
    }

    logger.info(`Successfully retrieved page content`, 
      { pageId, format, blockCount: blocks.length }, req.requestId);

    res.json({ 
      success: true, 
      pageId, 
      format,
      content: formattedContent 
    });
  } catch (error) {
    logger.error("Error getting page content", error, req.requestId);
    handleApiError(res, error, "get-page-content");
  }
});

/**
 * @route   DELETE /page/:id
 * @desc    Archives a Notion page by ID
 * @param   {string} id - The Notion page ID to archive
 * @returns {Object} JSON response with archive status
 */
router.delete("/page/:id", async (req, res) => {
  try {
    const pageId = req.params.id;
    
    if (!pageId) {
      logger.warn("Missing page ID for archive operation", null, req.requestId);
      return res.status(400).json({ error: "Missing page ID." });
    }
    
    // Validate pageId format
    if (!pageId.match(/^[a-f0-9-]+$/i)) {
      logger.warn("Invalid pageId format", { pageId }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    logger.info(`Archiving page with ID ${pageId}`, { pageId }, req.requestId);
    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, {
        archived: true
      })
    , { requestId: req.requestId });

    // Invalidate cache
    cache.invalidate(pageId);
    logger.info(`Successfully archived page with ID ${pageId}`, { pageId }, req.requestId);
    
    // Also remove any entries in the titles cache that might reference this page
    for (const [key] of Object.entries(cache.stores.titles)) {
      if (key === pageId) {
        cache.invalidate(key, 'titles');
        logger.debug(`Invalidated title cache for page ID ${pageId}`, null, req.requestId);
        break;
      }
    }

    res.json({ 
      success: true, 
      archived: true,
      message: `Page ${pageId} archived successfully`
    });
  } catch (error) {
    logger.error("Error archiving page", error, req.requestId);
    handleApiError(res, error, "archive-page");
  }
});

module.exports = router;

/**
 * Notion Page Routes
 * 
 * This module provides Express route handlers for Notion page operations including:
 * - Listing pages (with optional recursive discovery)
 * - Writing/replacing page content with versioning
 * - And other page-related operations
 */

const express = require('express');
const router = express.Router();

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  sanitizeInput, 
  paginatedRequest 
} = require('./api-utils');

const { 
  notionParentPageId 
} = require('./config');

const { 
  cache 
} = require('./cache');

const { 
  createHeadingBlock, 
  createParagraphBlock,
  parseMarkdownToBlocks,
  isBlockFormat,
  processContentToBlocks,
  blocksToMarkdown
} = require('./block-utils');

const { 
  extractPageTitle, 
  findPageByTitle, 
  extractChildPages 
} = require('./page-utils');

const logger = require('./logger');

/**
 * @route   GET /list-pages
 * @desc    Lists Notion pages with optional recursive child page discovery
 * @query   {number} limit - Maximum number of pages to return
 * @query   {boolean} recursive - Whether to include child pages recursively
 * @returns {Object} JSON response with page data
 */
router.get("/list-pages", async (req, res) => {
  try {
    const { CONFIG } = require('./config');
    const { limit = CONFIG.DEFAULT_PAGE_SIZE, recursive = true } = req.query;
    const parsedLimit = parseInt(limit, 10);
    
    if (isNaN(parsedLimit) || parsedLimit < 1) {
      logger.warn("Invalid limit parameter", { limit }, req.requestId);
      return res.status(400).json({ error: "Invalid limit parameter. Must be a positive number." });
    }
    
    logger.info(`Listing pages with limit=${parsedLimit}, recursive=${recursive}`, null, req.requestId);
    
    const results = await apiCallWithRetry(() => 
      notionApi.post('/search', { page_size: parsedLimit })
    , { requestId: req.requestId });

    const basePages = await Promise.all(
      results.data.results.map(async (item) => {
        try {
          const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;

          return {
            title,
            id: item.id,
            type: item.object,
            parent: item.parent?.page_id || item.parent?.database_id || null,
            url: item.url || null
          };
        } catch (err) {
          logger.error(`Error processing page ${item.id}`, err, req.requestId);
          return {
            title: `Error (${item.id.substring(0, 8)})`,
            id: item.id,
            type: item.object,
            parent: item.parent?.page_id || item.parent?.database_id || null,
            url: item.url || null,
            error: true
          };
        }
      })
    );

    logger.info(`Found ${basePages.length} base pages`, { count: basePages.length }, req.requestId);

    const childPages = [];
    if (recursive === 'true' || recursive === true) {
      logger.info(`Starting recursive page discovery for ${basePages.length} base pages`, null, req.requestId);
      const visited = new Set(); // Track visited pages to prevent duplicates
      
      // Process in batches of 5 to limit concurrent requests
      const batchSize = 5;
      for (let i = 0; i < basePages.length; i += batchSize) {
        const batch = basePages.slice(i, i + batchSize);
        await Promise.all(
          batch.map(base => {
            if (!visited.has(base.id)) {
              return extractChildPages(base.id, childPages, visited);
            }
            return Promise.resolve();
          })
        );
      }
      
      logger.info(`Completed recursive discovery, found ${childPages.length} child pages`, 
        { childPagesCount: childPages.length }, req.requestId);
    }

    // Use a Map to deduplicate pages by ID while keeping the most informative entry
    const pagesMap = new Map();

    // First add all base pages
    for (const page of basePages) {
      pagesMap.set(page.id, page);
    }

    // Then add child pages, but don't overwrite if the existing entry has a title
    // and the new one doesn't
    for (const page of childPages) {
      const existingPage = pagesMap.get(page.id);

      if (!existingPage || 
          (page.title && page.title !== "(no title)" && 
           (!existingPage.title || existingPage.title === "(no title)" || existingPage.title.includes("Untitled")))) {
        pagesMap.set(page.id, page);
      }
    }

    const uniquePages = Array.from(pagesMap.values());
    logger.info(`Returning ${uniquePages.length} unique pages`, { uniquePagesCount: uniquePages.length }, req.requestId);
    
    res.json({ 
      success: true, 
      count: uniquePages.length, 
      pages: uniquePages 
    });
  } catch (error) {
    logger.error("Error listing pages", error, req.requestId);
    handleApiError(res, error, "list-pages");
  }
});

/**
 * @route   PUT /write-page-by-title
 * @desc    Write/Replace content in Notion page by title with automatic versioning
 * @body    {string} title - The page title to write/update
 * @body    {string|Array} content - The content to write (markdown string or block array)
 * @body    {boolean} replace - Whether to replace existing content (default: false)
 * @body    {number} maxVersionAttempts - Max attempts for version creation (default: 3)
 * @returns {Object} JSON response with page creation/update status
 */
router.put("/write-page-by-title", async (req, res) => {
  try {
    const { title, content, replace = false, maxVersionAttempts = 3 } = req.body;

    // Input validation
    if (!title || !content) {
      logger.warn("Missing title or content", { hasTitle: !!title, hasContent: !!content }, req.requestId);
      return res.status(400).json({ error: "Missing title or content." });
    }

    if (typeof title !== 'string') {
      logger.warn("Invalid title type", { titleType: typeof title }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid input. Title must be a string." 
      });
    }
    
    if (typeof content !== 'string' && !Array.isArray(content)) {
      logger.warn("Invalid content type", { contentType: typeof content, isArray: Array.isArray(content) }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid content. Content must be a string or an array of blocks." 
      });
    }
    
    const sanitizedTitle = sanitizeInput(title);

    if (!sanitizedTitle) {
      logger.warn("Empty title after sanitization", { title }, req.requestId);
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    // Process content into blocks, handling both markdown and block formats
    const isBlockFormatContent = isBlockFormat(content);
    logger.info(`Content format: ${isBlockFormatContent ? 'block' : 'markdown'}`, 
      { contentFormat: isBlockFormatContent ? 'block' : 'markdown' }, req.requestId);

    // Create a helper function for version creation to support retry logic
    const createVersionedPage = async (baseTitle, contentToUse, attempt = 1) => {
      // Escape regex special characters in baseTitle for safe matching
      const safeTitle = baseTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const titleRegex = new RegExp(`^${safeTitle}\\s+(\\d+)$`);

      logger.debug(`Searching for existing versions of "${baseTitle}"`, { attempt }, req.requestId);
      
      // Search for all pages with similar titles
      const searchResults = await apiCallWithRetry(() => 
        notionApi.post('/search', {
          query: baseTitle,
          filter: { property: "object", value: "page" },
          page_size: 100
        })
      , { requestId: req.requestId });

      // Track versions and build version map for possible debugging
      let highestVersion = 0;
      const versionMap = new Map();

      // Process all search results to find existing versions
      for (const page of searchResults.data.results) {
        try {
          const extractedTitle = await extractPageTitle(page);
          if (extractedTitle) {
            const match = extractedTitle.match(titleRegex);
            if (match) {
              const version = parseInt(match[1], 10);
              if (!isNaN(version)) {
                versionMap.set(version, extractedTitle);
                if (version > highestVersion) {
                  highestVersion = version;
                }
              }
            }
          }
        } catch (err) {
          logger.error(`Error processing version for page ${page.id}`, err, req.requestId);
          // Continue with other pages
        }
      }

      // Calculate next version number
      const newVersion = highestVersion + 1;
      const versionSuffix = newVersion < 10 ? `0${newVersion}` : `${newVersion}`;
      const newTitle = `${baseTitle} ${versionSuffix}`;

      logger.info(`Creating new version: "${newTitle}" (version ${newVersion})`, 
        { baseTitle, newVersion, highestVersion }, req.requestId);

      // Defensive check for existing page with the same versioned title
      const duplicateCheck = await findPageByTitle(newTitle);
      if (duplicateCheck) {
        logger.warn(`Version collision detected for "${newTitle}"`, 
          { newTitle, attempt, maxVersionAttempts }, req.requestId);

        // Retry with exponential backoff if we haven't exceeded max attempts
        if (attempt < maxVersionAttempts) {
          logger.info(`Retrying version creation (attempt ${attempt + 1}/${maxVersionAttempts})`, 
            { attempt: attempt + 1, maxAttempts: maxVersionAttempts }, req.requestId);
          
          // Wait with exponential backoff
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 500));
          return createVersionedPage(baseTitle, contentToUse, attempt + 1);
        }

        throw new Error(`Version collision persists after ${maxVersionAttempts} attempts`);
      }
      
      // Create the new versioned page
      const childrenBlocks = [
        createHeadingBlock(newTitle),
        createParagraphBlock(`Version ${newVersion} of "${baseTitle}" - Created ${new Date().toLocaleString()}`),
        // Optional: Add metadata or version history information
        createHeadingBlock("Version History", 3)
      ];
      
      // Add version history paragraph
      const versionHistory = Array.from(versionMap.keys()).sort((a, b) => a - b);
      childrenBlocks.push(
        createParagraphBlock(`This is version ${newVersion}. Previous versions: ${versionHistory.join(', ') || 'None'}`)
      );
      
      // Add content section
      childrenBlocks.push(createHeadingBlock("Content", 2));
      
      // Process content into blocks, handling both markdown and block formats
      const contentBlocks = processContentToBlocks(contentToUse);
      childrenBlocks.push(...contentBlocks);

      const createRes = await apiCallWithRetry(() => 
        notionApi.post('/pages', {
          parent: { type: "page_id", page_id: notionParentPageId },
          properties: {
            title: [
              {
                type: "text",
                text: { content: newTitle }
              }
            ]
          },
          children: childrenBlocks
        })
      , { requestId: req.requestId });

      logger.info(`Created new version page: "${newTitle}"`, 
        { pageId: createRes.data.id, version: newVersion }, req.requestId);

      return {
        pageId: createRes.data.id,
        newTitle,
        version: newVersion,
        versionHistory
      };
    };

    // Main execution logic
    logger.info(`Attempting to write/replace page titled "${sanitizedTitle}"`, 
      { title: sanitizedTitle, replace }, req.requestId);
      
    const match = await findPageByTitle(sanitizedTitle);

    if (!match) {
      // Create first version of the page (no versioning needed yet)
      logger.info(`Creating new page titled "${sanitizedTitle}"`, null, req.requestId);
      
      const childrenBlocks = [
        createHeadingBlock(sanitizedTitle),
        createParagraphBlock(`Original version - Created ${new Date().toLocaleString()}`),
        createHeadingBlock("Content", 2)
      ];
      
      // Process content into blocks, handling both markdown and block formats
      const contentBlocks = processContentToBlocks(content);
      childrenBlocks.push(...contentBlocks);
      
      const createRes = await apiCallWithRetry(() => 
        notionApi.post('/pages', {
          parent: { type: "page_id", page_id: notionParentPageId },
          properties: {
            title: [
              {
                type: "text",
                text: { content: sanitizedTitle }
              }
            ]
          },
          children: childrenBlocks
        })
      , { requestId: req.requestId });

      const pageId = createRes.data.id;

      logger.info(`Created new page: "${sanitizedTitle}"`, { pageId }, req.requestId);

      // Invalidate cache after creating a new page
      cache.clear();

      return res.json({ 
        success: true, 
        created: true, 
        pageId,
        message: "Created new page (first version)",
        contentFormat: isBlockFormatContent ? 'block' : 'markdown'
      });
    } else {
      // Page exists, create a versioned page
      try {
        logger.info(`Page "${sanitizedTitle}" exists, creating versioned page`, 
          { existingPageId: match.page.id }, req.requestId);
          
        const result = await createVersionedPage(sanitizedTitle, content);

        // Invalidate cache after creating a new version
        cache.clear();

        return res.json({ 
          success: true, 
          created: true, 
          versioned: true, 
          originalTitle: sanitizedTitle,
          newTitle: result.newTitle,
          version: result.version,
          versionHistory: result.versionHistory,
          pageId: result.pageId,
          message: `Created new version ${result.version} of the page`,
          contentFormat: isBlockFormatContent ? 'block' : 'markdown'
        });
      } catch (versionError) {
        // Handle version creation errors specifically
        logger.error("Version creation failed", versionError, req.requestId);
        return res.status(409).json({ 
          error: versionError.message || "Failed to create versioned page",
          suggestion: "Try again later or with a different title"
        });
      }
    }
  } catch (error) {
    logger.error("Error writing page by title", error, req.requestId);
    handleApiError(res, error, "write-page-by-title");
  }
});

/**
 * @route   GET /get-page-by-title
 * @desc    Gets page content by title with optional format conversion
 * @query   {string} title - The page title to find
 * @query   {string} format - Output format: 'blocks' (default) or 'markdown'
 * @returns {Object} JSON response with page content
 */
router.get("/get-page-by-title", async (req, res) => {
  try {
    const { title, format = 'blocks' } = req.query;
    
    if (!title) {
      logger.warn("Missing title parameter", null, req.requestId);
      return res.status(400).json({ error: "Missing title parameter." });
    }
    
    // Validate format
    if (format !== 'blocks' && format !== 'markdown') {
      logger.warn("Invalid format", { format }, req.requestId);
      return res.status(400).json({
        error: "Invalid format. Must be 'blocks' or 'markdown'."
      });
    }
    
    const sanitizedTitle = sanitizeInput(title);
    if (!sanitizedTitle) {
      logger.warn("Empty title after sanitization", { title }, req.requestId);
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }
    
    logger.info(`Looking for page titled "${sanitizedTitle}"`, { title: sanitizedTitle, format }, req.requestId);
    const match = await findPageByTitle(sanitizedTitle);
    
    if (!match) {
      logger.warn(`No page found with title "${sanitizedTitle}"`, { title: sanitizedTitle }, req.requestId);
      return res.status(404).json({ 
        error: `No page found with title "${sanitizedTitle}"`,
        message: "Page not found"
      });
    }
    
    const pageId = match.page.id;
    logger.info(`Found page with title "${sanitizedTitle}" (ID: ${pageId})`, { pageId }, req.requestId);
    
    // Get page blocks
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=100`)
    , { requestId: req.requestId });

    const blocks = response.data.results;
    logger.debug(`Retrieved ${blocks.length} blocks for page "${sanitizedTitle}"`, 
      { blockCount: blocks.length }, req.requestId);
    
    // Convert to requested format
    let formattedContent;
    if (format === 'markdown') {
      formattedContent = blocksToMarkdown(blocks);
      logger.debug(`Converted blocks to markdown (${formattedContent.length} chars)`, 
        { contentLength: formattedContent.length }, req.requestId);
    } else {
      formattedContent = blocks;
    }

    res.json({ 
      success: true, 
      pageId,
      title: match.title,
      format,
      content: formattedContent 
    });
  } catch (error) {
    logger.error("Error getting page by title", error, req.requestId);
    handleApiError(res, error, "get-page-by-title");
  }
});

/**
 * @route   POST /convert-content
 * @desc    Converts content between markdown and block formats
 * @body    {string|Array} content - The content to convert
 * @body    {string} outputFormat - Format to convert to: 'blocks' or 'markdown'
 * @returns {Object} JSON response with converted content
 */
router.post("/convert-content", async (req, res) => {
  try {
    const { content, outputFormat } = req.body;
    
    if (!content) {
      logger.warn("Missing content for conversion", null, req.requestId);
      return res.status(400).json({ error: "Missing content." });
    }
    
    if (!outputFormat || (outputFormat !== 'blocks' && outputFormat !== 'markdown')) {
      logger.warn("Invalid output format for conversion", { outputFormat }, req.requestId);
      return res.status(400).json({
        error: "Invalid outputFormat. Must be 'blocks' or 'markdown'."
      });
    }
    
    // Determine input format
    const isBlockContent = isBlockFormat(content);
    const inputFormat = isBlockContent ? 'blocks' : 'markdown';
    
    logger.info(`Converting content from ${inputFormat} to ${outputFormat}`, 
      { inputFormat, outputFormat }, req.requestId);
    
    // Convert if formats are different
    let convertedContent;
    if (inputFormat === outputFormat) {
      // No conversion needed
      logger.debug("No conversion needed, formats are the same", 
        { format: inputFormat }, req.requestId);
      convertedContent = content;
    } else if (inputFormat === 'markdown' && outputFormat === 'blocks') {
      logger.debug("Converting markdown to blocks", null, req.requestId);
      convertedContent = parseMarkdownToBlocks(content);
    } else if (inputFormat === 'blocks' && outputFormat === 'markdown') {
      logger.debug("Converting blocks to markdown", null, req.requestId);
      convertedContent = blocksToMarkdown(
        typeof content === 'string' ? JSON.parse(content) : content
      );
    }
    
    logger.info("Content conversion successful", null, req.requestId);
    res.json({
      success: true,
      inputFormat,
      outputFormat,
      content: convertedContent
    });
  } catch (error) {
    logger.error("Error converting content", error, req.requestId);
    handleApiError(res, error, "convert-content");
  }
});

module.exports = router;

/**
 * Notion Page Utilities
 * 
 * This module provides functions for working with Notion pages, including:
 * - Page title extraction from various Notion objects
 * - Finding pages by title with caching support
 * - Recursive child page extraction
 * - Helper functions for parsing Notion page data
 */

const { notionApi, apiCallWithRetry, sanitizeInput } = require('./api-utils');
const { cache } = require('./cache');
const { CONFIG } = require('./config');

/**
 * Extracts the title from a Notion page object with caching
 * 
 * @param {Object} page - The Notion page object
 * @returns {Promise<string>} - The extracted page title or a default title
 */
async function extractPageTitle(page) {
  if (!page) {
    console.warn("Cannot extract title: page object is undefined");
    return "Untitled Page";
  }
  
  // Check cache first
  const cacheKey = page.id;
  if (!cacheKey) {
    console.warn("Cannot cache page title: missing page ID");
    return extractTitleUncached(page);
  }
  
  const cachedTitle = cache.get(cacheKey, 'titles');
  if (cachedTitle) {
    return cachedTitle;
  }

  // Extract title using helper function
  const extractedTitle = await extractTitleUncached(page);
  
  // Cache the result
  if (extractedTitle && cacheKey) {
    cache.set(cacheKey, extractedTitle, 'titles');
  }

  return extractedTitle;
}

/**
 * Helper function for title extraction that attempts multiple strategies
 * 
 * @param {Object} page - The Notion page object
 * @returns {Promise<string>} - The extracted page title or a default title
 */
async function extractTitleUncached(page) {
  // Try to extract title from properties first (for pages and databases)
  if (page.properties) {
    // Check all title-like properties in descending order of likelihood
    const titleProps = ['title', 'Name', 'Feature', 'Title'];

    for (const prop of titleProps) {
      const titleArray = page.properties[prop]?.title;
      if (titleArray && titleArray.length > 0) {
        const textContent = titleArray[0]?.plain_text || titleArray[0]?.text?.content;
        if (textContent) {
          console.log(`✅ Found title in properties.${prop}: "${textContent}"`);
          return textContent;
        }
      }
    }
  }

  // For direct title property (older Notion API format)
  if (page.title) {
    if (Array.isArray(page.title) && page.title.length > 0) {
      const textContent = page.title[0]?.plain_text || page.title[0]?.text?.content;
      if (textContent) {
        console.log(`✅ Found title in direct title array: "${textContent}"`);
        return textContent;
      }
    } else if (typeof page.title === 'string') {
      console.log(`✅ Found string title: "${page.title}"`);
      return page.title;
    }
  }

  // Try to get from page object
  if (page.child_page?.title) {
    console.log(`✅ Found title in child_page: "${page.child_page.title}"`);
    return page.child_page.title;
  }

  // Last resort: Extract from page content
  if (page.id) {
    try {
      return await extractTitleFromBlocks(page.id);
    } catch (err) {
      console.error(`❌ Failed to extract title from blocks for ${page.id}:`, err.message);
      return `Untitled Page (${page.id.substring(0, 8)})`;
    }
  }

  return `Untitled Page (${page.id ? page.id.substring(0, 8) : 'unknown'})`;
}

/**
 * Extracts title from a page's blocks by examining their content
 * 
 * @param {string} pageId - The Notion page ID
 * @returns {Promise<string>} - The extracted title or a default title
 */
async function extractTitleFromBlocks(pageId) {
  try {
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=50`)
    );

    const blocks = response.data.results;

    // First check for a child_page with title
    const childPageBlock = blocks.find(block => block.type === "child_page");
    if (childPageBlock?.child_page?.title) {
      const title = childPageBlock.child_page.title;
      console.log(`📄 Found child page title: ${title}`);
      return title;
    }

    // Look for the first heading block
    const headingTypes = ["heading_1", "heading_2", "heading_3"];
    const headingBlock = blocks.find(block => headingTypes.includes(block.type));

    if (headingBlock) {
      const blockType = headingBlock.type;
      const richText = headingBlock[blockType]?.rich_text || [];
      const title = richText.map(rt => rt.text?.content || '').join("").trim();

      if (title) {
        console.log(`✅ Found title in ${blockType}: "${title}"`);
        return title;
      }
    }

    // Try to get first paragraph text as fallback
    const paragraphBlock = blocks.find(block => block.type === "paragraph");
    if (paragraphBlock) {
      const richText = paragraphBlock.paragraph?.rich_text || [];
      const title = richText.map(rt => rt.text?.content || '').join("").trim();

      if (title) {
        console.log(`✅ Found title in paragraph: "${title}"`);
        return title;
      }
    }

    // Get page info directly as last resort
    try {
      const pageInfo = await apiCallWithRetry(() => 
        notionApi.get(`/pages/${pageId}`)
      );

      // Try to find any property that might contain a title
      const properties = pageInfo.data.properties;
      if (properties) {
        for (const [key, value] of Object.entries(properties)) {
          if (value.title && value.title.length > 0) {
            const title = value.title[0]?.plain_text || value.title[0]?.text?.content;
            if (title) {
              console.log(`✅ Found title in page properties.${key}: "${title}"`);
              return title;
            }
          }
        }
      }
    } catch (err) {
      console.error(`❌ Failed to fetch page info for ${pageId}:`, err.message);
    }

    console.log(`⚠️ No usable title found for ${pageId}`);
    return `Untitled Page (${pageId.substring(0, 8)})`;
  } catch (err) {
    console.error(`❌ Title extraction failed for ${pageId}:`, err.message);
    return `Untitled Page (${pageId.substring(0, 8)})`;
  }
}

/**
 * Finds a Notion page by its title with caching support
 * 
 * @param {string} title - The page title to search for
 * @returns {Promise<Object|null>} - Object containing page data and title, or null if not found
 */
async function findPageByTitle(title) {
  title = sanitizeInput(title);
  
  if (!title) {
    console.warn("Empty title provided to findPageByTitle");
    return null;
  }
  
  const normalizedInput = title.toLowerCase();
  
  // Check cache first
  const cacheKey = `title:${normalizedInput}`;
  const cachedPage = cache.get(cacheKey);
  if (cachedPage) {
    return cachedPage;
  }
  
  try {
    const searchResponse = await apiCallWithRetry(() => 
      notionApi.post('/search', {
        query: title,
        filter: { property: "object", value: "page" },
        page_size: 10
      })
    );

    // No results
    if (!searchResponse.data.results.length) {
      return null;
    }

    // Use the enhanced title extraction for better matching
    const pages = await Promise.all(searchResponse.data.results.map(async (page) => {
      try {
        const extractedTitle = await extractPageTitle(page);
        return {
          page,
          title: extractedTitle
        };
      } catch (err) {
        console.error(`Error extracting title for page ${page.id}:`, err.message);
        return {
          page,
          title: `Untitled (${page.id.substring(0, 8)})`
        };
      }
    }));

    // Find exact match or closest match
    const exactMatch = pages.find(item => 
      item.title && item.title.toLowerCase() === normalizedInput
    );
    
    const match = exactMatch || null;
    
    // Cache the result
    if (match) {
      cache.set(cacheKey, match);
    }
    
    return match;
  } catch (error) {
    console.error(`❌ Find page error for "${title}":`, error.message);
    return null;
  }
}

/**
 * Recursively extracts child pages from a Notion page with duplicate detection
 * and controlled concurrency
 * 
 * @param {string} pageId - The parent page ID to extract children from
 * @param {Array} [pages=[]] - Accumulator for child pages
 * @param {Set} [visited=new Set()] - Set of already visited page IDs to prevent loops
 * @param {number} [depth=0] - Current recursion depth
 * @param {number} [maxDepth=3] - Maximum recursion depth
 * @returns {Promise<Array>} - Array of child page objects
 */
async function extractChildPages(pageId, pages = [], visited = new Set(), depth = 0, maxDepth = 3) {
  // Guard against invalid pageId or excessive recursion
  if (!pageId || visited.has(pageId) || depth > maxDepth) {
    return pages;
  }
  
  // Protect against infinite recursion
  visited.add(pageId);
  
  // Track recursion depth for debugging
  const indentation = "  ".repeat(depth);
  console.log(`${indentation}🔍 Exploring page ${pageId} (depth: ${depth}/${maxDepth})`);

  try {
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=100`)
    );

    const blocks = response.data.results;
    
    const blockCount = blocks.length;
    console.log(`${indentation}🧱 Found ${blockCount} blocks in page ${pageId}`);

    // Process child pages specifically
    const childPagePromises = blocks
      .filter(block => block.type === "child_page")
      .map(async (block) => {
        const childId = block.id;
        
        // Skip if we already added this page
        if (pages.some(p => p.id === childId)) {
          console.log(`${indentation}⚠️ Duplicate page detected: ${childId}`);
          return null;
        }
        
        let childTitle = block.child_page?.title;

        // If no title in the initial response, try to extract it
        if (!childTitle || childTitle === "(no title)") {
          try {
            const pageInfo = await apiCallWithRetry(() => 
              notionApi.get(`/pages/${childId}`)
            );
            childTitle = await extractPageTitle(pageInfo.data) || childTitle || "(no title)";
          } catch (err) {
            console.error(`${indentation}❌ Failed to fetch child page info for ${childId}:`, err.message);
            childTitle = `Untitled (${childId.substring(0, 8)})`;
          }
        }

        console.log(`${indentation}📄 Found child page: ${childTitle} (ID: ${childId})`);
        
        return {
          id: childId,
          title: childTitle,
          parent: pageId,
          type: "page"
        };
      });
    
    // Wait for all promises to resolve and filter out nulls
    const childPages = (await Promise.all(childPagePromises)).filter(Boolean);
    
    // Add the child pages to our results
    for (const childPage of childPages) {
      pages.push(childPage);
    }

    // Process nested pages with controlled concurrency (max 3 concurrent requests)
    if (depth < maxDepth) {
      const batchSize = 3;
      for (let i = 0; i < childPages.length; i += batchSize) {
        const batch = childPages.slice(i, i + batchSize);
        await Promise.all(
          batch.map(child => 
            extractChildPages(child.id, pages, visited, depth + 1, maxDepth)
          )
        );
      }
    }

    return pages;
  } catch (err) {
    console.error(`${indentation}❌ Failed to fetch children for ${pageId}:`, err.message);
    return pages;
  }
}

/**
 * Normalizes a page object to a consistent format with essential properties
 * 
 * @param {Object} page - The Notion page object to normalize
 * @param {string} [title] - Optional pre-extracted title
 * @returns {Promise<Object>} - Normalized page object with id, title, type, etc.
 */
async function normalizePage(page, title = null) {
  if (!page) return null;
  
  try {
    const pageTitle = title || await extractPageTitle(page);
    
    return {
      id: page.id,
      title: pageTitle,
      type: page.object || 'page',
      parent: page.parent?.page_id || page.parent?.database_id || null,
      url: page.url || null,
      createdTime: page.created_time,
      lastEditedTime: page.last_edited_time
    };
  } catch (err) {
    console.error(`Error normalizing page ${page.id}:`, err.message);
    return {
      id: page.id,
      title: `Error (${page.id.substring(0, 8)})`,
      type: page.object || 'page',
      parent: page.parent?.page_id || page.parent?.database_id || null,
      url: page.url || null,
      error: true
    };
  }
}

module.exports = {
  extractPageTitle,
  extractTitleFromBlocks,
  findPageByTitle,
  extractChildPages,
  normalizePage
};

/**
 * Notion Rate Limiter
 * 
 * This module provides rate limiting functionality for the Notion API to respect
 * the API's limits of 3 requests per second overall and varying limits for different
 * operation types.
 */

/**
 * Token bucket rate limiter for the Notion API
 * Handles:
 * - 3 requests per second per token overall
 * - Request queueing with promise resolution
 * - Dynamic adjustment based on rate limit headers
 */
class NotionRateLimiter {
  /**
   * Creates a new NotionRateLimiter instance
   * @param {Object} options - Rate limiter configuration
   * @param {number} [options.maxTokens=3] - Maximum number of tokens (requests per second)
   * @param {number} [options.refillRate=3] - Tokens to add per second
   */
  constructor(options = {}) {
    this.maxTokens = options.maxTokens || 3;
    this.refillRate = options.refillRate || 3;
    this.tokens = this.maxTokens;
    this.lastRefill = Date.now();
    this.queued = [];
    this.processing = false;
    
    // Track different operation types for more specific rate limiting
    this.operationLimits = {
      read: { tokens: 3, lastRefill: Date.now() },     // 3 req/sec for reads
      write: { tokens: 2, lastRefill: Date.now() }     // 2 req/sec for writes
    };
    
    // Track per-minute limits
    this.minuteLimits = {
      write: { 
        count: 0, 
        resetTime: Date.now() + 60000,
        max: 30   // 30 req/min for writes
      }
    };
    
    // Set up automatic queue processing
    setInterval(() => {
      if (this.queued.length > 0 && !this.processing) {
        this.processQueue();
      }
    }, 100);
  }
  
  /**
   * Refills tokens based on time elapsed since last refill
   * @private
   */
  refillTokens() {
    const now = Date.now();
    const timePassed = now - this.lastRefill;
    
    if (timePassed >= 1000) {
      const secondsPassed = timePassed / 1000;
      const tokensToAdd = Math.floor(secondsPassed * this.refillRate);
      
      if (tokensToAdd > 0) {
        this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
        this.lastRefill = now;
        
        // Also refill operation-specific tokens
        for (const op of Object.keys(this.operationLimits)) {
          const opLimit = this.operationLimits[op];
          const opTimePassed = now - opLimit.lastRefill;
          const opSecondsPassed = opTimePassed / 1000;
          const opTokensToAdd = Math.floor(opSecondsPassed * opLimit.tokens);
          
          if (opTokensToAdd > 0) {
            opLimit.tokens = Math.min(opLimit.tokens, opLimit.tokens + opTokensToAdd);
            opLimit.lastRefill = now;
          }
        }
      }
    }
    
    // Check minute-based limits
    for (const op of Object.keys(this.minuteLimits)) {
      const minuteLimit = this.minuteLimits[op];
      if (now >= minuteLimit.resetTime) {
        minuteLimit.count = 0;
        minuteLimit.resetTime = now + 60000;
      }
    }
  }
  
  /**
   * Queues a request with promise resolution
   * @param {Function} requestFn - Function that returns a promise for the API call
   * @param {Object} options - Queue options
   * @param {string} [options.operationType='read'] - Type of operation ('read' or 'write')
   * @param {string} [options.resourceType=null] - Type of resource (e.g., 'database', 'page')
   * @param {boolean} [options.priority=false] - Whether this request has priority in the queue
   * @returns {Promise<*>} - Promise that resolves with the API response
   */
  queueRequest(requestFn, options = {}) {
    const operationType = options.operationType || 'read';
    const resourceType = options.resourceType || null;
    const priority = options.priority || false;
    
    return new Promise((resolve, reject) => {
      const request = { 
        requestFn, 
        resolve, 
        reject, 
        operationType,
        resourceType,
        attempts: 0,
        maxAttempts: 5
      };
      
      if (priority) {
        this.queued.unshift(request);
      } else {
        this.queued.push(request);
      }
      
      if (!this.processing) {
        this.processQueue();
      }
    });
  }
  
  /**
   * Processes queued requests if tokens are available
   * @private
   */
  async processQueue() {
    if (this.processing || this.queued.length === 0) {
      return;
    }
    
    this.processing = true;
    this.refillTokens();
    
    // Find the next request that can be processed based on token availability
    let requestIndex = -1;
    
    for (let i = 0; i < this.queued.length; i++) {
      const request = this.queued[i];
      
      // Check if we have overall tokens available
      if (this.tokens <= 0) {
        break;
      }
      
      // Check operation-specific tokens
      const opLimit = this.operationLimits[request.operationType];
      if (opLimit && opLimit.tokens <= 0) {
        continue;
      }
      
      // Check minute-based limits
      const minuteLimit = this.minuteLimits[request.operationType];
      if (minuteLimit && minuteLimit.count >= minuteLimit.max) {
        continue;
      }
      
      requestIndex = i;
      break;
    }
    
    if (requestIndex === -1) {
      // No eligible requests, wait for token refill
      this.processing = false;
      return;
    }
    
    // Process the request
    const request = this.queued.splice(requestIndex, 1)[0];
    this.tokens--;
    
    // Update operation-specific tokens
    const opLimit = this.operationLimits[request.operationType];
    if (opLimit) {
      opLimit.tokens--;
    }
    
    // Update minute-based limits
    const minuteLimit = this.minuteLimits[request.operationType];
    if (minuteLimit) {
      minuteLimit.count++;
    }
    
    try {
      const result = await request.requestFn();
      
      // Update token info from headers if available
      if (result.headers) {
        if (result.headers['x-notion-rate-limit-limit']) {
          this.maxTokens = parseInt(result.headers['x-notion-rate-limit-limit']);
        }
        
        if (result.headers['x-notion-rate-limit-remaining']) {
          this.tokens = Math.min(
            this.maxTokens, 
            parseInt(result.headers['x-notion-rate-limit-remaining'])
          );
        }
      }
      
      request.resolve(result);
    } catch (err) {
      request.attempts++;
      
      // Handle rate limit errors
      if (err.response && err.response.status === 429) {
        console.warn(`🚦 Rate limit hit for ${request.operationType} operation. Retrying...`);
        
        // Get reset time from headers or use default
        const resetTime = err.response.headers && err.response.headers['x-notion-rate-limit-reset'] 
          ? parseInt(err.response.headers['x-notion-rate-limit-reset']) * 1000
          : 1000;
        
        if (request.attempts < request.maxAttempts) {
          // Re-queue the request with priority after waiting
          setTimeout(() => {
            this.queued.unshift(request);
          }, resetTime);
        } else {
          console.error(`❌ Max retries (${request.maxAttempts}) exceeded for rate-limited request`);
          request.reject(err);
        }
      } else {
        // Other errors, just reject
        request.reject(err);
      }
    } finally {
      this.processing = false;
      
      // Process more from queue after a small delay
      if (this.queued.length > 0) {
        setTimeout(() => this.processQueue(), 50);
      }
    }
  }
  
  /**
   * Gets statistics about the rate limiter state
   * @returns {Object} Object containing rate limit statistics
   */
  getStats() {
    return {
      queueLength: this.queued.length,
      availableTokens: this.tokens,
      maxTokens: this.maxTokens,
      operationLimits: { ...this.operationLimits },
      minuteLimits: { ...this.minuteLimits }
    };
  }
}

// Create and export a rate limiter instance
const notionRateLimiter = new NotionRateLimiter();

module.exports = {
  NotionRateLimiter,
  notionRateLimiter
};

