 * 
 * This module provides rate limiting functionality for the Notion API to respect
 * the API's limits of 3 requests per second overall and varying limits for different
 * operation types.
 */

const { FEATURES, CONFIG } = require('./config');
const logger = require('./logger');

/**
 * Token bucket rate limiter for the Notion API
 * Handles:
 * - 3 requests per second per token overall
 * - Request queueing with promise resolution
 * - Dynamic adjustment based on rate limit headers
 */
class NotionRateLimiter {
  /**
   * Creates a new NotionRateLimiter instance
   * @param {Object} options - Rate limiter configuration
   * @param {number} [options.maxTokens=5] - Maximum number of tokens (requests per second)
   * @param {number} [options.refillRate=5] - Tokens to add per second
   * @param {number} [options.queueCheckInterval=100] - Interval to check queue in ms
   */
  constructor(options = {}) {
    this.enabled = FEATURES.RATE_LIMITING_ENABLED;
    this.maxTokens = options.maxTokens || CONFIG.RATE_LIMIT_MAX_TOKENS;
    this.refillRate = options.refillRate || CONFIG.RATE_LIMIT_REFILL_RATE;
    this.queueCheckInterval = options.queueCheckInterval || CONFIG.RATE_LIMIT_QUEUE_CHECK_INTERVAL;
    this.tokens = this.maxTokens;
    this.lastRefill = Date.now();
    this.queued = [];
    this.processing = false;

    // Track different operation types for more specific rate limiting
    this.operationLimits = {
      read: { tokens: 3, maxTokens: 3, lastRefill: Date.now() },     // 3 req/sec for reads
      write: { tokens: 2, maxTokens: 2, lastRefill: Date.now() }     // 2 req/sec for writes
    };

    // Track per-minute limits
    this.minuteLimits = {
      write: { 
        count: 0, 
        resetTime: Date.now() + 60000,
        max: 30   // 30 req/min for writes
      }
    };

    // Set up automatic queue processing
    this.queueInterval = setInterval(() => {
      if (this.queued.length > 0 && !this.processing) {
        this.processQueue();
      }
    }, this.queueCheckInterval);

    if (this.enabled) {
      console.log(`🚦 Rate limiter initialized: maxTokens=${this.maxTokens}, refillRate=${this.refillRate}/sec`);
    } else {
      console.log('🚦 Rate limiter is DISABLED via feature flag');
    }
  }

  /**
   * Refills tokens based on time elapsed since last refill
   * @private
   */
  refillTokens() {
    const now = Date.now();
    const timePassed = now - this.lastRefill;

    if (timePassed >= 1000) {
      const secondsPassed = timePassed / 1000;
      const tokensToAdd = Math.floor(secondsPassed * this.refillRate);

      if (tokensToAdd > 0) {
        this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
        this.lastRefill = now;

        // Also refill operation-specific tokens
        for (const op of Object.keys(this.operationLimits)) {
          const opLimit = this.operationLimits[op];
          const opTimePassed = now - opLimit.lastRefill;
          const opSecondsPassed = opTimePassed / 1000;
          const opTokensToAdd = Math.floor(opSecondsPassed * opLimit.maxTokens);

          if (opTokensToAdd > 0) {
            opLimit.tokens = Math.min(opLimit.maxTokens, opLimit.tokens + opTokensToAdd);
            opLimit.lastRefill = now;
          }
        }
      }
    }

    // Check minute-based limits
    for (const op of Object.keys(this.minuteLimits)) {
      const minuteLimit = this.minuteLimits[op];
      if (now >= minuteLimit.resetTime) {
        minuteLimit.count = 0;
        minuteLimit.resetTime = now + 60000;
      }
    }
  }

  /**
   * Queues a request with promise resolution
   * @param {Function} requestFn - Function that returns a promise for the API call
   * @param {Object} options - Queue options
   * @param {string} [options.operationType='read'] - Type of operation ('read' or 'write')
   * @param {string} [options.resourceType=null] - Type of resource (e.g., 'database', 'page')
   * @param {boolean} [options.priority=false] - Whether this request has priority in the queue
   * @param {string} [options.requestId=null] - For logging correlation
   * @returns {Promise<*>} - Promise that resolves with the API response
   */
  queueRequest(requestFn, options = {}) {
    // Skip rate limiting if disabled
    if (!this.enabled) {
      return requestFn();
    }

    const operationType = options.operationType || 'read';
    const resourceType = options.resourceType || null;
    const priority = options.priority || false;
    const requestId = options.requestId || null;

    return new Promise((resolve, reject) => {
      const request = { 
        requestFn, 
        resolve, 
        reject, 
        operationType,
        resourceType,
        requestId,
        attempts: 0,
        maxAttempts: 5,
        queuedAt: Date.now()
      };

      if (priority) {
        this.queued.unshift(request);
        if (requestId) {
          logger.debug('Added priority request to queue', { 
            operationType, resourceType, queueLength: this.queued.length 
          }, requestId);
        }
      } else {
        this.queued.push(request);
        if (requestId) {
          logger.debug('Added request to queue', { 
            operationType, resourceType, queueLength: this.queued.length 
          }, requestId);
        }
      }

      if (!this.processing) {
        this.processQueue();
      }
    });
  }

  /**
