        // Check minute-based limits
        const minuteLimit = this.minuteLimits[request.operationType];
        if (minuteLimit && minuteLimit.count >= minuteLimit.max) {
          continue;
        }

        requestIndex = i;
        break;
      }

      if (requestIndex === -1) {
        // No eligible requests, wait for token refill
        this.processing = false;
        return;
      }

      // Process the request
      const request = this.queued.splice(requestIndex, 1)[0];
      this.tokens--;

      // Update operation-specific tokens
      const opLimit = this.operationLimits[request.operationType];
      if (opLimit) {
        opLimit.tokens--;
      }

      // Update minute-based limits
      const minuteLimit = this.minuteLimits[request.operationType];
      if (minuteLimit) {
        minuteLimit.count++;
      }

      const waitTime = Date.now() - request.queuedAt;
      if (request.requestId && waitTime > 500) {
        logger.debug(`Request waited ${waitTime}ms in queue`, { 
          operationType: request.operationType,
          waitTime 
        }, request.requestId);
      }

      try {
        const result = await request.requestFn();

        // Update token info from headers if available
        if (result.headers) {
          if (result.headers['x-notion-rate-limit-limit']) {
            this.maxTokens = parseInt(result.headers['x-notion-rate-limit-limit'], 10);
          }

          if (result.headers['x-notion-rate-limit-remaining']) {
            this.tokens = Math.min(
              this.maxTokens, 
              parseInt(result.headers['x-notion-rate-limit-remaining'], 10)
            );
          }

          // Log rate limit headers for debugging
          if (request.requestId) {
            const rateLimitHeaders = {
              limit: result.headers['x-notion-rate-limit-limit'],
              remaining: result.headers['x-notion-rate-limit-remaining'],
              reset: result.headers['x-notion-rate-limit-reset']
            };

            if (rateLimitHeaders.limit || rateLimitHeaders.remaining) {
              logger.debug('Rate limit headers received', rateLimitHeaders, request.requestId);
            }
          }
        }

        request.resolve(result);
      } catch (err) {
        request.attempts++;

        // Handle rate limit errors
        if (err.response && err.response.status === 429) {
          const resetAfter = err.response.headers && 
            err.response.headers['x-notion-rate-limit-reset'] 
              ? parseInt(err.response.headers['x-notion-rate-limit-reset'], 10) * 1000
              : 1000;

          const message = `Rate limit hit for ${request.operationType} operation. Retrying after ${resetAfter}ms...`;

          if (request.requestId) {
            logger.warn(message, { 
              statusCode: 429, 
              resetAfter, 
              attempt: request.attempts,
              maxAttempts: request.maxAttempts
            }, request.requestId);
          } else {
            console.warn(`🚦 ${message}`);
          }

          // Adjust our tokens to 0 to respect the rate limit
          this.tokens = 0;

          if (request.attempts < request.maxAttempts) {
            // Re-queue the request with priority after waiting
            setTimeout(() => {
              this.queued.unshift(request);
              // Try processing the queue again
              if (!this.processing) {
                this.processQueue();
              }
            }, resetAfter);
          } else {
            const errorMessage = `Max retries (${request.maxAttempts}) exceeded for rate-limited request`;
            if (request.requestId) {
              logger.error(errorMessage, {
                statusCode: 429,
                attempts: request.attempts,
                maxAttempts: request.maxAttempts
              }, request.requestId);
            } else {
              console.error(`❌ ${errorMessage}`);
            }
            request.reject(err);
          }
        } else {
          // Other errors, just reject
          request.reject(err);
        }
      }
    } catch (error) {
      console.error('❌ Error in rate limiter queue processing:', error);
    } finally {
      this.processing = false;

      // Process more from queue if there are pending requests
      if (this.queued.length > 0) {
        setTimeout(() => this.processQueue(), 50);
      }
    }
  }

  /**
   * Gets statistics about the rate limiter state
   * @returns {Object} Object containing rate limit statistics
   */
  getStats() {
    return {
      enabled: this.enabled,
      queueLength: this.queued.length,
      availableTokens: this.tokens,
      maxTokens: this.maxTokens,
      refillRate: this.refillRate,
      operationLimits: { ...this.operationLimits },
      minuteLimits: { ...this.minuteLimits },
      processing: this.processing
    };
  }

  /**
   * Clears all queued requests and resets tokens
   * @returns {number} Number of cleared requests
   */
  clearQueue() {
    const queueLength = this.queued.length;

    // Reject all queued requests
    for (const request of this.queued) {
      request.reject(new Error("Queue was cleared"));
    }

    this.queued = [];
    this.tokens = this.maxTokens;
    this.processing = false;

    // Reset operation limits
    for (const op in this.operationLimits) {
      this.operationLimits[op].tokens = this.operationLimits[op].maxTokens;
      this.operationLimits[op].lastRefill = Date.now();
    }

    return queueLength;
  }

  /**
   * Enables or disables the rate limiter
   * @param {boolean} isEnabled - Whether the rate limiter should be enabled
   * @returns {Object} Current state after toggle
   */
  setEnabled(isEnabled) {
    this.enabled = isEnabled;
    console.log(`🚦 Rate limiter ${isEnabled ? 'enabled' : 'disabled'}`);

    if (!isEnabled) {
      this.clearQueue();
    }

    return { enabled: this.enabled };
  }
}

