    return response.data;
  };

  // First request to get initial batch and pagination info
  try {
    const firstBatch = await makeRequest(undefined);
    results = [...firstBatch.results];
    hasMore = firstBatch.has_more;
    startCursor = firstBatch.next_cursor;
    pageCount++;

    logger.info(`Fetched page ${pageCount} with ${results.length} items from ${endpoint}`, {
      endpoint,
      pageCount,
      itemCount: results.length,
      hasMore
    }, requestId);

    // If we need more pages and haven't hit limits
    const cursors = [];
    while (hasMore && results.length < maxItems && pageCount < 50) {
      cursors.push(startCursor);

      // Process in batches of concurrent requests
      if (cursors.length >= concurrentRequests || !hasMore) {
        const batchResults = await Promise.all(
          cursors.map(cursor => makeRequest(cursor))
        );

        for (const data of batchResults) {
          results = results.concat(data.results || []);
          hasMore = data.has_more;
          startCursor = data.next_cursor;
          pageCount++;

          logger.info(`Fetched page ${pageCount} with ${data.results.length} items from ${endpoint}`, {
            endpoint,
            pageCount,
            itemCount: data.results.length,
            totalItems: results.length,
            hasMore
          }, requestId);

          if (results.length >= maxItems) {
            const warningMsg = `Pagination limit reached (${maxItems} items)`;
            logger.warn(warningMsg, { maxItems, endpoint }, requestId);
            hasMore = false;
            break;
          }

          if (pageCount >= 50) {
            const errorMsg = `Too many pages fetched (${pageCount}). Possible API issue.`;
            logger.error(errorMsg, { pageCount, endpoint }, requestId);
            hasMore = false;
            break;
          }

          if (!data.has_more) {
            hasMore = false;
            break;
          }
        }

        cursors.length = 0;
      }
    }

    logger.info(`Completed paginated request to ${endpoint}`, {
      endpoint,
      totalItems: results.length,
      pageCount
    }, requestId);

    return results;
  } catch (error) {
    logger.error(`Pagination error for ${endpoint}`, {
      error: error.message,
      stack: error.stack,
      endpoint,
      pageCount
    }, requestId);
    throw error;
  }
