app.post('/logging/toggle', (req, res) => {
  const { enabled } = req.body;
  logger.info(`Request to ${enabled ? 'enable' : 'disable'} logging received`, 
    { enabled }, req.requestId);

  if (typeof enabled !== 'boolean') {
    return res.status(400).json({ 
