  // Log with console directly in case logging was just disabled
  console.log(`Logging has been ${result.current.enabled ? 'enabled' : 'disabled'}`);

  res.json({
    success: true,
    enabled: result.current.enabled,
    message: `Logging is now ${result.current.enabled ? 'enabled' : 'disabled'}`
  });
});

app.post('/logging/config', (req, res) => {
  const newConfig = req.body;
  logger.info("Request to update logging configuration", { newConfig }, req.requestId);

  if (!newConfig || typeof newConfig !== 'object') {
    return res.status(400).json({ 
      success: false,
      error: "Invalid configuration object" 
    });
  }

  const result = logger.updateConfig(newConfig);

  // Log with console directly in case logging config changed dramatically
  console.log("Logging configuration updated:", result.current);

  res.json({
    success: true,
    previous: result.previous,
    current: result.current
  });
});

