      arch: process.arch,
      nodeVersion: process.version,
      uptime: process.uptime()
    };

    // Get feature flags
    const features = { ...FEATURES };

    // Get cache stats
    const cacheStats = getCacheStats();

    // Get rate limiter stats
    const rateLimitStats = getRateLimitStats();

    // Get logging config
    const loggingConfig = logger.getConfig();

    // Environment variables (excluding sensitive data)
    const environment = {
      NODE_ENV: process.env.NODE_ENV,
      PORT: process.env.PORT || 3000,
      // Don't include tokens or secrets
      NOTION_CONFIGURED: !!process.env.NOTION_TOKEN,
      GITHUB_CONFIGURED: !!process.env.GITHUB_TOKEN,
      GPT_MEMORY_CONFIGURED: !!process.env.GPT_MEMORY
    };

    const debugInfo = {
