async function normalizePage(page, title = null, options = {}) {
  if (!page) return null;

  try {
    const pageTitle = title || await extractPageTitle(page, options);

    return {
      id: page.id,
      title: pageTitle,
      type: page.object || 'page',
      parent: page.parent?.page_id || page.parent?.database_id || null,
      url: page.url || null,
      createdTime: page.created_time,
      lastEditedTime: page.last_edited_time
    };
  } catch (err) {
    logger.error(`Error normalizing page ${page.id}`, err, options.requestId);
    return {
      id: page.id,
      title: `Error (${page.id.substring(0, 8)})`,
      type: page.object || 'page',
      parent: page.parent?.page_id || page.parent?.database_id || null,
