// routes/notion/database-routes.js
const express = require('express');
const createNotionRouter = require('./notion-route-factory');
const notionApi = require('./notion-api');

// Create a router using the factory without a specific database
const router = createNotionRouter({
  // No default database name or ID - will be specified in the request
  prefix: 'databases',
  routeNames: {
    create: 'createentry',
    update: 'updateentry',
    delete: 'deleteentry',
    list: 'listentries',
    read: 'readentry'
  }
});

// Middleware to check if database is specified and show available databases if not
const checkDatabaseSpecified = async (req, res, next) => {
  // Check if database ID or name is in the request
  const databaseId = req.query.database_id || req.body.database_id;
  const databaseName = req.query.database || req.body.database;

  if (databaseId || databaseName) {
    return next(); // Database is specified, continue with the request
  }

  try {
    // Fetch list of available databases
    const { results } = await notionApi.search({
      filter: {
        property: 'object',
        value: 'database'
      }
    });

    // Format database list
    const availableDatabases = results
      .filter(db => db.object === 'database')
      .map(db => {
        const title = db.title && db.title.length > 0 
          ? db.title.map(t => t.plain_text).join('') 
          : 'Untitled';

        return {
          id: db.id,
          title: title,
          url: db.url
        };
      });

    return res.status(400).json({
      error: 'No database specified',
      message: 'Please specify a database using database_id or database parameter',
      available_databases: availableDatabases
    });
  } catch (err) {
    console.error('Error fetching available databases:', err);
    return res.status(500).json({
      error: 'Failed to fetch available databases',
      message: err.message
    });
  }
};

// Apply the middleware to all routes
router.use('/:route', checkDatabaseSpecified);

module.exports = router;

// Modified getDatabaseId function to be extracted from notion-route-factory.js

// Get database ID from environment variable or find by name
const getDatabaseId = async (req) => {
  // Run cache cleanup occasionally
  if (Math.random() < 0.1) {
    databaseNameCache.cleanup();
  }

  // First check if database ID is provided in the request
  const reqDatabaseId = req.query.database_id || req.body.database_id;
  if (reqDatabaseId) return reqDatabaseId;

  // Then check if database name is provided in the request
  const reqDatabaseName = req.query.database || req.body.database;
  if (reqDatabaseName) {
    // Convert to uppercase for case-insensitive comparison
    const upperReqName = reqDatabaseName.toUpperCase();

    // Check cache first
    const cachedId = databaseNameCache.get(upperReqName);
    if (cachedId) return cachedId;

    // Search Notion if not in cache
    const { results } = await notionApi.search(reqDatabaseName);
    const database = results.find(r => 
      r.object === 'database' && 
      r.title && 
      r.title.some(t => t.plain_text.toUpperCase() === upperReqName)
    );

    if (database) {
      // Add to cache and return
      databaseNameCache.set(upperReqName, database.id);
      return database.id;
    }
  }

  // If config has a databaseId environment variable, use that
  if (config.databaseId && process.env[config.databaseId]) {
    return process.env[config.databaseId];
  }

  // If config has a databaseName, search for it
  if (config.databaseName) {
    // Convert to uppercase for case-insensitive comparison
    const upperConfigName = config.databaseName.toUpperCase();

    // Check cache first
    const cachedId = databaseNameCache.get(upperConfigName);
    if (cachedId) return cachedId;

    // Search Notion if not in cache
    const { results } = await notionApi.search(config.databaseName);
    const database = results.find(r => 
      r.object === 'database' && 
      r.title && 
      r.title.some(t => t.plain_text.toUpperCase() === upperConfigName)
    );

    if (database) {
      // Add to cache and return
      databaseNameCache.set(upperConfigName, database.id);
      return database.id;
    }
  }

  // Return null if no database ID was found
  return null;
};

// Add this function to notion-api.js

