/**
 * Comprehensive Logging System
 * 
 * This module provides a centralized logging system for the Notion integration,
 * with features including:
 * - Multiple log levels (info, warn, error, debug)
 * - Request/response logging
 * - Error tracking
 * - Enable/disable functionality
 * - Request ID tracking across logs
 */

const { v4: uuidv4 } = require('uuid');
const fs = require('fs');
const path = require('path');
const util = require('util');

class Logger {
  constructor() {
    // Configuration with defaults
    this.config = {
      enabled: process.env.LOGGING_ENABLED !== 'false', // Enable by default unless explicitly disabled
      logLevel: process.env.LOG_LEVEL || 'info', // Default log level
      logToConsole: process.env.LOG_TO_CONSOLE !== 'false', // Log to console by default
      logToFile: process.env.LOG_TO_FILE === 'true', // Don't log to file by default
      logDir: process.env.LOG_DIR || 'logs', // Default log directory
      logFileName: process.env.LOG_FILENAME || 'notion-api.log', // Default log file name
      requestBodyLogging: process.env.LOG_REQUEST_BODY !== 'false', // Log request bodies by default
      responseBodyLogging: process.env.LOG_RESPONSE_BODY === 'true', // Don't log response bodies by default
      sensitiveFields: (process.env.SENSITIVE_FIELDS || 'token,password,secret,key').split(',') // Default sensitive fields to mask
    };

    // Create log levels with numeric values for comparison
    this.LOG_LEVELS = {
      debug: 0,
      info: 1,
      warn: 2,
      error: 3
    };

    // Set up file logging if enabled
    if (this.config.logToFile) {
      this.setupFileLogging();
    }
  }

  /**
   * Sets up file logging, ensuring directory exists
   */
  setupFileLogging() {
    try {
      // Create log directory if it doesn't exist
      if (!fs.existsSync(this.config.logDir)) {
        fs.mkdirSync(this.config.logDir, { recursive: true });
      }

      this.logFilePath = path.join(this.config.logDir, this.config.logFileName);

      // Test file access
      fs.accessSync(path.dirname(this.logFilePath), fs.constants.W_OK);

      console.log(`📝 Logging to file: ${this.logFilePath}`);
    } catch (err) {
      console.error(`❌ Failed to set up file logging: ${err.message}`);
      this.config.logToFile = false;
    }
  }

  /**
   * Updates logger configuration
   * @param {Object} newConfig - New configuration values
   */
  updateConfig(newConfig) {
    const oldConfig = { ...this.config };
    this.config = { ...this.config, ...newConfig };

    // Re-initialize file logging if relevant settings changed
    if (this.config.logToFile && 
        (!oldConfig.logToFile || 
         oldConfig.logDir !== this.config.logDir || 
         oldConfig.logFileName !== this.config.logFileName)) {
      this.setupFileLogging();
    }

    return { 
      previous: oldConfig, 
      current: this.config 
    };
  }

  /**
   * Masks sensitive information in objects
   * @param {Object} obj - Object to mask sensitive data in
   * @returns {Object} - Masked object
   */
  maskSensitiveData(obj) {
    if (!obj || typeof obj !== 'object') return obj;

    const masked = { ...obj };

    // Deep clone to avoid modifying original
    const clone = JSON.parse(JSON.stringify(masked));

    // Recursively mask sensitive fields
    const maskRecursive = (obj, sensitiveFields) => {
      for (const key in obj) {
        // Check if current key is sensitive
        if (sensitiveFields.some(field => key.toLowerCase().includes(field.toLowerCase()))) {
          obj[key] = '[REDACTED]';
        } 
        // Recurse if value is an object and not null
        else if (obj[key] && typeof obj[key] === 'object') {
          maskRecursive(obj[key], sensitiveFields);
        }
      }
      return obj;
    };

    return maskRecursive(clone, this.config.sensitiveFields);
  }

  /**
   * Formats a log entry consistently
   * @param {string} level - Log level
   * @param {string} message - Log message
   * @param {Object} [data] - Optional data to include
   * @param {string} [requestId] - Optional request ID
   * @returns {Object} - Formatted log entry
   */
  formatLogEntry(level, message, data, requestId) {
    const timestamp = new Date().toISOString();

    const logEntry = {
      timestamp,
      level,
      message
    };

    if (requestId) {
      logEntry.requestId = requestId;
    }

    if (data) {
      // If data is an error, format it appropriately
      if (data instanceof Error) {
        logEntry.error = {
          name: data.name,
          message: data.message,
          stack: data.stack
        };

        // Include any additional properties from the error
        for (const key in data) {
          if (key !== 'name' && key !== 'message' && key !== 'stack') {
            logEntry.error[key] = data[key];
          }
        }
      } else {
        // Mask sensitive data
        const maskedData = this.maskSensitiveData(data);
        logEntry.data = maskedData;
      }
    }

    return logEntry;
  }

  /**
   * Logs a message to the configured outputs
   * @param {string} level - Log level
   * @param {string} message - Log message
   * @param {Object} [data] - Optional data to include
   * @param {string} [requestId] - Optional request ID
   */
  log(level, message, data, requestId) {
    if (!this.config.enabled) return;

    // Check if this log level should be logged
    const configuredLevel = this.LOG_LEVELS[this.config.logLevel];
    const messageLevel = this.LOG_LEVELS[level];

    if (messageLevel < configuredLevel) return;

    const logEntry = this.formatLogEntry(level, message, data, requestId);

    // Convert to string for output
    const logString = JSON.stringify(logEntry, null, this.config.logToConsole ? 2 : 0);

    // Log to console
    if (this.config.logToConsole) {
      switch (level) {
        case 'error':
          console.error(logString);
          break;
        case 'warn':
          console.warn(logString);
          break;
        case 'debug':
          console.debug(logString);
          break;
        default:
          console.log(logString);
      }
    }

    // Log to file
    if (this.config.logToFile) {
      try {
        fs.appendFileSync(this.logFilePath, logString + '\n');
      } catch (err) {
        console.error(`❌ Failed to write to log file: ${err.message}`);
      }
    }
  }

  // Convenience methods for different log levels
  debug(message, data, requestId) {
    this.log('debug', message, data, requestId);
  }

  info(message, data, requestId) {
    this.log('info', message, data, requestId);
  }

  warn(message, data, requestId) {
    this.log('warn', message, data, requestId);
  }

  error(message, data, requestId) {
    this.log('error', message, data, requestId);
  }

  /**
   * Creates Express middleware for request/response logging
   * @returns {Function} - Express middleware
   */
  requestLogger() {
    return (req, res, next) => {
      if (!this.config.enabled) return next();

      // Generate unique ID for this request
      const requestId = uuidv4();
      req.requestId = requestId;

      // Capture original timestamp
      req.startTime = Date.now();

      // Log the request
      this.info(`${req.method} ${req.originalUrl}`, {
        method: req.method,
        url: req.originalUrl,
        path: req.path,
        params: req.params,
        query: req.query,
        headers: this.maskSensitiveData(req.headers),
        body: this.config.requestBodyLogging ? this.maskSensitiveData(req.body) : '[BODY LOGGING DISABLED]',
        ip: req.ip
      }, requestId);

      // Capture the original response methods
      const originalSend = res.send;
      const originalJson = res.json;
      const originalEnd = res.end;

      // Override response methods to log responses
      res.send = function(body) {
        res.body = body;
        return originalSend.apply(res, arguments);
      };

      res.json = function(body) {
        res.body = body;
        return originalJson.apply(res, arguments);
      };

      res.end = function(chunk) {
        // Calculate response time
        const responseTime = Date.now() - req.startTime;

        // Log response
        const logData = {
          method: req.method,
          url: req.originalUrl,
          statusCode: res.statusCode,
          responseTime: `${responseTime}ms`
        };

        // Include response body if enabled and available
        if (res.body && this.config.responseBodyLogging) {
          logData.body = this.maskSensitiveData(
            typeof res.body === 'string' ? JSON.parse(res.body) : res.body
          );
        }

        this.info(`${req.method} ${req.originalUrl} ${res.statusCode} ${responseTime}ms`, logData, requestId);

        return originalEnd.apply(res, arguments);
      };

      next();
    };
  }

  /**
   * Creates Express middleware for error logging
   * @returns {Function} - Express error middleware
   */
  errorLogger() {
    return (err, req, res, next) => {
      if (!this.config.enabled) return next(err);

      // Use the request ID if available
      const requestId = req.requestId || uuidv4();

      this.error(`Error processing ${req.method} ${req.originalUrl}`, {
        error: err,
        method: req.method,
        url: req.originalUrl,
        path: req.path,
        params: req.params,
        query: req.query
      }, requestId);

      next(err);
    };
  }

  /**
   * Gets the current logger configuration
   * @returns {Object} - Current configuration
   */
  getConfig() {
    return { ...this.config };
  }

  /**
   * Toggles logging on/off
   * @param {boolean} enabled - Whether logging should be enabled
   * @returns {Object} - Updated configuration
   */
  toggleLogging(enabled) {
    return this.updateConfig({ enabled });
  }
}

// Create and export a singleton instance
const logger = new Logger();

module.exports = logger;

/**
 * Notion Integration Router
 * 
 * This is the main router for the Notion integration, assembling all modular components
 * and route handlers. It serves as the entry point for all Notion-related functionality.
 * 
 * The router combines the following modules:
 * - Page routes (list, create, version)
 * - Page operations (append, update, archive)
 * - Memory routes (CRUD operations for Notion memory database)
 * - Database operations
 * - Health checks
 */

const express = require('express');
const router = express.Router();

// Import the logger
const logger = require('./logger');

// Import route modules
const pageRoutes = require('./page-routes');
const pageOperations = require('./page-operations');
const memoryRoutes = require('./memory-routes');

// Import utility modules
const { 
  notionApi, 
  handleApiError, 
  apiCallWithRetry, 
  getRateLimitStats 
} = require('./api-utils');
const { notionDatabaseId, requiredEnvVars } = require('./config');
const { cache } = require('./cache');

// Apply logging middleware to all routes
router.use(logger.requestLogger());

// Mount modular route handlers
router.use(pageRoutes);
router.use(pageOperations);
router.use(memoryRoutes);

/**
 * @route   GET /query-database
 * @desc    Queries the configured Notion database and returns entries
 * @query   {number} limit - Maximum number of entries to return
 * @returns {Object} JSON response with database entries
 */
router.get("/query-database", async (req, res) => {
  try {
    const { CONFIG } = require('./config');
    const { limit = CONFIG.DEFAULT_PAGE_SIZE } = req.query;

    if (!notionDatabaseId) {
      logger.warn("Missing database ID", { databaseId: notionDatabaseId }, req.requestId);
      return res.status(400).json({ error: "Missing NOTION_DATABASE_ID in environment variables." });
    }

    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit < 1) {
      logger.warn("Invalid limit parameter", { limit }, req.requestId);
      return res.status(400).json({ error: "Invalid limit parameter. Must be a positive number." });
    }

    logger.info(`Querying database with limit=${parsedLimit}`, { databaseId: notionDatabaseId, limit: parsedLimit }, req.requestId);
    const response = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionDatabaseId}/query`, {
        page_size: parsedLimit
      })
    );

    const { extractPageTitle } = require('./page-utils');
    const rows = await Promise.all(response.data.results.map(async (item) => {
      try {
        const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;

        return {
          title,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null
        };
      } catch (err) {
        logger.error(`Error processing database item ${item.id}`, err, req.requestId);
        return {
          title: `Error (${item.id.substring(0, 8)})`,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null,
          error: true
        };
      }
    }));

    logger.info(`Database query returned ${rows.length} results`, { count: rows.length }, req.requestId);
    res.json({ success: true, count: rows.length, entries: rows });
  } catch (error) {
    logger.error("Database query failed", error, req.requestId);
    handleApiError(res, error, "query-database");
  }
});

/**
 * @route   GET /health
 * @desc    Health check endpoint for Notion integration
 * @returns {Object} JSON response with health status
 */
router.get("/health", async (req, res) => {
  try {
    const { notionParentPageId } = require('./config');

    logger.debug("Processing health check request", null, req.requestId);

    // Check if Notion API is accessible
    const response = await apiCallWithRetry(() => notionApi.get('/users/me'));

    // Verify required environment variables
    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
      logger.warn("Missing required environment variables", { missingVars }, req.requestId);
      return res.status(503).json({
        status: 'degraded',
        message: 'Missing required environment variables',
        details: { missingVars }
      });
    }

    // Check if parent page exists
    try {
      await apiCallWithRetry(() => notionApi.get(`/pages/${notionParentPageId}`));
    } catch (error) {
      logger.error("Health check: Parent page is invalid or inaccessible", error, req.requestId);
      return res.status(503).json({
        status: 'degraded',
        message: 'Parent page ID is invalid or inaccessible',
        details: { error: error.message }
      });
    }

    // Include cache stats
    const cacheStats = cache.getStats();

    // Include rate limiter stats
    const rateLimitStats = getRateLimitStats();

    logger.info("Health check successful", { cacheStats, rateLimitStats }, req.requestId);

    res.json({ 
      status: 'healthy', 
      message: 'Notion integration is working properly',
      version: '1.0.0',
      timestamp: new Date().toISOString(),
      cache: cacheStats,
      rateLimits: rateLimitStats
    });
  } catch (error) {
    logger.error("Health check failed", error, req.requestId);
    res.status(503).json({ 
      status: 'unhealthy', 
      message: 'Unable to connect to Notion API',
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @route   GET /rate-limits
 * @desc    Get rate limit statistics
 * @returns {Object} JSON response with rate limit information
 */
router.get("/rate-limits", (req, res) => {
  try {
    const stats = getRateLimitStats();
    logger.debug("Rate limits requested", { stats }, req.requestId);
    res.json({
      success: true,
      rateLimit: stats
    });
  } catch (error) {
    logger.error("Failed to get rate limits", error, req.requestId);
    handleApiError(res, error, "rate-limits");
  }
});

/**
 * @route   GET /logs/config
 * @desc    Get current logging configuration
 * @returns {Object} Current logging configuration
 */
router.get("/logs/config", (req, res) => {
  const config = logger.getConfig();
  res.json({
    success: true,
    config
  });
