const { BLOCK_TYPES } = require('./block-types')

const mdToBlocks = (markdown) => {
  return markdown.split('\n').map(line => {
    if (/^#\s+/.test(line)) return BLOCK_TYPES.heading_1(line.replace(/^#\s+/, ''))
    if (/^##\s+/.test(line)) return BLOCK_TYPES.heading_2(line.replace(/^##\s+/, ''))
    if (/^###\s+/.test(line)) return BLOCK_TYPES.heading_3(line.replace(/^###\s+/, ''))
    if (/^-\s+/.test(line)) return BLOCK_TYPES.bulleted_list_item(line.replace(/^-\s+/, ''))
    if (/^\d+\.\s+/.test(line)) return BLOCK_TYPES.numbered_list_item(line.replace(/^\d+\.\s+/, ''))
    if (/^>\s+/.test(line)) return BLOCK_TYPES.quote(line.replace(/^>\s+/, ''))
    if (/^```/.test(line)) return BLOCK_TYPES.code('', 'javascript')
    return BLOCK_TYPES.paragraph(line)
  })
}

const blocksToMd = (blocks) => {
  return blocks.map(block => {
    const content = block[block.type]?.rich_text?.[0]?.plain_text || ''
    switch (block.type) {
      case 'heading_1': return `# ${content}`
      case 'heading_2': return `## ${content}`
      case 'heading_3': return `### ${content}`
      case 'bulleted_list_item': return `- ${content}`
      case 'numbered_list_item': return `1. ${content}`
      case 'to_do': return `- [${block.to_do.checked ? 'x' : ' '}] ${content}`
      case 'quote': return `> ${content}`
      case 'code': return `\n\n\`\`\`${block.code.language || 'text'}\n${content}\n\`\`\``
      case 'divider': return '---'
      default: return content
    }
  }).join('\n')
}

module.exports = {
  mdToBlocks,
  blocksToMd
}

