  return titleProp?.title?.[0]?.plain_text || null
}

const normalizeKey = (key) => decodeURIComponent(key.trim().toLowerCase())

const extractTitleFromBlocks = async (pageId) => {
  try {
    const res = await notionApi.retrievePage(pageId)
    const blocks = await notionApi.appendBlockToPage(pageId, []) // simulates children fetch
    const heading = blocks.results.find(b => b.type.startsWith('heading_'))
    if (heading) {
      return heading[heading.type].rich_text.map(rt => rt.text?.content).join('').trim()
    }
    const para = blocks.results.find(b => b.type === 'paragraph')
    if (para) {
      return para.paragraph.rich_text.map(rt => rt.text?.content).join('').trim()
    }
  } catch (err) {
    console.error(`Failed to extract title from blocks: ${err.message}`)
  }
  return `Untitled (${pageId.slice(0, 8)})`
}

const extractPageTitle = async (page) => {
  const properties = page.properties || {}
  const propKeys = ['title', 'Name', 'Title', 'Feature']
  for (const key of propKeys) {
    const val = properties[key]?.title
    if (val?.length) return val[0].plain_text || val[0].text?.content
  }
  if (page.title?.length) return page.title[0].plain_text || page.title[0].text?.content
  if (page.child_page?.title) return page.child_page.title
  return extractTitleFromBlocks(page.id)
}

