// schema-utils.js
const notionApi = require('./notion-api')

/**
 * Retrieves and caches a database's schema
 * @param {string} databaseId The Notion database ID
 * @returns {Promise<Object>} The database schema
 */
const databaseSchemaCache = {}

const getDatabaseSchema = async (databaseId) => {
  // Return cached schema if available
  if (databaseSchemaCache[databaseId]) {
    return databaseSchemaCache[databaseId]
  }

  try {
    // Retrieve database using Notion API
    const response = await notionApi.client.get(`/databases/${databaseId}`)
    const database = response.data

    // Extract and process schema information
    const schema = {
      id: database.id,
      title: database.title?.[0]?.plain_text || 'Untitled Database',
      properties: {}
    }

    // Process each property to determine its type and configuration
    for (const [name, property] of Object.entries(database.properties)) {
      schema.properties[name] = {
        id: property.id,
        type: property.type,
        name,
        // Store specific configuration based on property type
        config: property[property.type]
      }
    }

    // Cache the schema
    databaseSchemaCache[databaseId] = schema
    return schema
  } catch (error) {
    console.error(`Failed to retrieve database schema: ${error.message}`)
    throw error
  }
}

/**
 * Maps arbitrary incoming data to the correct Notion property format
 * @param {Object} data The raw data object with key-value pairs
 * @param {Object} schema The database schema
 * @returns {Object} Notion-formatted properties object
 */
const mapDataToProperties = (data, schema) => {
  const properties = {}

  for (const [key, value] of Object.entries(data)) {
    // Find the matching property in the schema
    const propertyName = findMatchingPropertyName(key, schema.properties)
    if (!propertyName) continue

    const property = schema.properties[propertyName]
    properties[propertyName] = formatPropertyValue(value, property.type)
  }

  return properties
}

/**
 * Find the matching property name in the schema, case-insensitive
 */
const findMatchingPropertyName = (key, schemaProps) => {
  const normalizedKey = key.toLowerCase().trim()

  // Try exact match first
  if (schemaProps[key]) return key

  // Try case-insensitive match
  for (const propName of Object.keys(schemaProps)) {
    if (propName.toLowerCase().trim() === normalizedKey) {
      return propName
    }
  }

  return null
}

/**
 * Format a value according to Notion's expected structure for the property type
 */
const formatPropertyValue = (value, type) => {
  switch (type) {
    case 'title':
      return { title: [{ text: { content: String(value) } }] }
    case 'rich_text':
      return { rich_text: [{ text: { content: String(value) } }] }
    case 'number':
      return { number: Number(value) }
    case 'select':
      return { select: { name: String(value) } }
    case 'multi_select':
      const options = Array.isArray(value) ? value : [value]
      return { multi_select: options.map(opt => ({ name: String(opt) })) }
    case 'date':
      return { date: typeof value === 'string' ? { start: value } : value }
    case 'checkbox':
      return { checkbox: Boolean(value) }
    case 'url':
      return { url: String(value) }
    case 'email':
      return { email: String(value) }
    case 'phone_number':
      return { phone_number: String(value) }
    default:
      // For unsupported types, try to make a reasonable guess
      return { [type]: value }
  }
}

module.exports = {
  getDatabaseSchema,
  mapDataToProperties
}

const express = require('express')
const notionApi = require('./notion-api')
const pageUtils = require('./page-utils')
const schemaUtils = require('./schema-utils')

const router = express.Router()
const DB_ID = process.env.NOTION_DATABASE_ID

router.put('/createentry', async (req, res, next) => {
  try {
    // Get database schema
    const schema = await schemaUtils.getDatabaseSchema(DB_ID)
    let properties = {}

    if (req.body.line) {
      // Process simple key-value line
      const [key, value] = req.body.line.split(/:(.+)/).map(s => s.trim())
      if (!key || !value) return res.status(400).json({ error: 'Invalid line format. Use "key: value"' })

      // Find the title property from schema
      const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'
      const title = pageUtils.normalizeKey(key)

      // Map to correct property structure
      properties[titleProp] = { title: [{ text: { content: title } }] }

      // Look for a "Value" property or similar for the value
      const valueProp = Object.entries(schema.properties).find(([name, _]) => 
        ['value', 'content', 'description'].includes(name.toLowerCase()))?.[0] || 'Value'

      if (schema.properties[valueProp]) {
        properties[valueProp] = { rich_text: [{ text: { content: value } }] }
      }
    } else {
      // Handle structured input
      const title = req.body.title
      const inputProperties = req.body.properties || {}

      if (!title) return res.status(400).json({ error: 'Title is required' })

      // Find title property from schema
      const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'
      properties[titleProp] = { title: [{ text: { content: title } }] }

      // Map other properties according to schema
      if (Object.keys(inputProperties).length) {
        const mappedProps = schemaUtils.mapDataToProperties(inputProperties, schema)
        properties = { ...properties, ...mappedProps }
      }
    }

    const page = await notionApi.createPage({
      parent: { database_id: DB_ID },
      properties
    })

    res.json({ created: true, id: page.id })
  } catch (err) {
    next(err)
  }
})

// Other routes would follow the same pattern of retrieving schema first
// Here's an example for updateentry

router.patch('/updateentry', async (req, res, next) => {
  try {
    // Get database schema
    const schema = await schemaUtils.getDatabaseSchema(DB_ID)
    let page, properties

    if (req.body.key && req.body.value) {
      // Simple key-value update
      const normKey = pageUtils.normalizeKey(req.body.key)

      // Find title property from schema
      const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'

      // Query by title property
      const { results } = await notionApi.queryDatabase(DB_ID, {
        filter: {
          property: titleProp,
          title: { equals: normKey }
        }
      })

      page = results[0]
      if (!page) return res.status(404).json({ error: 'Key not found' })

      // Find value property
      const valueProp = Object.entries(schema.properties).find(([name, _]) => 
        ['value', 'content', 'description'].includes(name.toLowerCase()))?.[0] || 'Value'

      properties = {}
      properties[valueProp] = { rich_text: [{ text: { content: req.body.value } }] }

      const updated = await notionApi.updatePage(page.id, properties)
      return res.json({ updated: true, id: updated.id })
    }

    // Handle structured input
    const { idOrTitle, properties: inputProperties } = req.body
    if (!idOrTitle || !inputProperties) return res.status(400).json({ error: 'Missing idOrTitle or properties' })

    page = await pageUtils.findPage(DB_ID, idOrTitle)
    if (!page) return res.status(404).json({ error: 'Database entry not found' })

    // Map properties according to schema
    properties = schemaUtils.mapDataToProperties(inputProperties, schema)

    const updated = await notionApi.updatePage(page.id, properties)
    res.json(updated)
  } catch (err) {
    next(err)
  }
})

// The other route implementations would follow similar patterns
// Implementing all routes with schema handling would make this artifact very long
// But the pattern would be the same for all of them

module.exports = router

