router.put('/createentry', async (req, res, next) => {
  try {
    // Get database schema
    const schema = await schemaUtils.getDatabaseSchema(DB_ID)
    let properties = {}

    if (req.body.line) {
      // Process simple key-value line
      const [key, value] = req.body.line.split(/:(.+)/).map(s => s.trim())
      if (!key || !value) return res.status(400).json({ error: 'Invalid line format. Use "key: value"' })

      // Find the title property from schema
      const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'
      const title = pageUtils.normalizeKey(key)

      // Map to correct property structure
      properties[titleProp] = { title: [{ text: { content: title } }] }

      // Look for a "Value" property or similar for the value
      const valueProp = Object.entries(schema.properties).find(([name, _]) => 
        ['value', 'content', 'description'].includes(name.toLowerCase()))?.[0] || 'Value'

      if (schema.properties[valueProp]) {
        properties[valueProp] = { rich_text: [{ text: { content: value } }] }
      }
    } else {
      // Handle structured input
      const title = req.body.title
      const inputProperties = req.body.properties || {}

      if (!title) return res.status(400).json({ error: 'Title is required' })

      // Find title property from schema
      const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'
      properties[titleProp] = { title: [{ text: { content: title } }] }

      // Map other properties according to schema
      if (Object.keys(inputProperties).length) {
        const mappedProps = schemaUtils.mapDataToProperties(inputProperties, schema)
        properties = { ...properties, ...mappedProps }
      }
    }

    const page = await notionApi.createPage({
      parent: { database_id: DB_ID },
      properties
    })

    res.json({ created: true, id: page.id })
  } catch (err) {
    next(err)
  }
})

router.patch('/updateentry', async (req, res, next) => {
  try {
    // Get database schema
    const schema = await schemaUtils.getDatabaseSchema(DB_ID)
    let page, properties = {}

    if (req.body.key && req.body.value) {
      // Simple key-value update
      const normKey = pageUtils.normalizeKey(req.body.key)

      // Find title property from schema
      const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'

      // Query by title property
      const { results } = await notionApi.queryDatabase(DB_ID, {
        filter: {
          property: titleProp,
          title: { equals: normKey }
        }
      })

      page = results[0]
      if (!page) return res.status(404).json({ error: 'Key not found' })

      // Find value property
      const valueProp = Object.entries(schema.properties).find(([name, _]) => 
        ['value', 'content', 'description'].includes(name.toLowerCase()))?.[0] || 'Value'

      properties[valueProp] = { rich_text: [{ text: { content: req.body.value } }] }

      const updated = await notionApi.updatePage(page.id, properties)
      return res.json({ updated: true, id: updated.id })
    }

    // Handle structured input
    const { idOrTitle, properties: inputProperties } = req.body
    if (!idOrTitle || !inputProperties) return res.status(400).json({ error: 'Missing idOrTitle or properties' })

    page = await pageUtils.findPage(DB_ID, idOrTitle)
    if (!page) return res.status(404).json({ error: 'Database entry not found' })

    // Map properties according to schema
    properties = schemaUtils.mapDataToProperties(inputProperties, schema)

    const updated = await notionApi.updatePage(page.id, properties)
    res.json(updated)
  } catch (err) {
    next(err)
  }
})

