    if (!key) return res.status(400).json({ error: 'Missing key' })

    const normKey = pageUtils.normalizeKey(key)

    // Find title property from schema
    const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'

    // Find value property
    const valueProp = Object.entries(schema.properties).find(([name, _]) => 
      ['value', 'content', 'description'].includes(name.toLowerCase()))?.[0] || 'Value'

    // Query by title property
    const { results } = await notionApi.queryDatabase(DB_ID, {
      filter: {
        property: titleProp,
        title: { equals: normKey }
      }
    })

    const page = results[0]

    // Extract value based on property type
    let value = null
    if (page) {
      const prop = page.properties[valueProp]
      if (prop) {
        switch (prop.type) {
          case 'rich_text':
            value = prop.rich_text?.[0]?.text?.content || null
            break
          case 'number':
            value = prop.number
            break
          case 'select':
            value = prop.select?.name || null
            break
          case 'multi_select':
            value = prop.multi_select?.map(item => item.name) || []
            break
          case 'date':
            value = prop.date
            break
          case 'checkbox':
            value = prop.checkbox
            break
          default:
            value = prop[prop.type] || null
        }
      }
    }

    res.json({ key, value })
  } catch (err) {
    next(err)
  }
})

