// schema-utils.js
const notionApi = require('./notion-api')

/**
 * Retrieves and caches a database's schema
 * @param {string} databaseId The Notion database ID
 * @returns {Promise<Object>} The database schema
 */
const databaseSchemaCache = {}

const getDatabaseSchema = async (databaseId) => {
  // Return cached schema if available
  if (databaseSchemaCache[databaseId]) {
    return databaseSchemaCache[databaseId]
  }

  try {
    // Use the retrieveDatabase method instead of direct client access
    const database = await notionApi.retrieveDatabase(databaseId)

    // Extract and process schema information
    const schema = {
      id: database.id,
      title: database.title?.[0]?.plain_text || 'Untitled Database',
      properties: {}
    }

    // Process each property to determine its type and configuration
    for (const [name, property] of Object.entries(database.properties)) {
      schema.properties[name] = {
        id: property.id,
        type: property.type,
        name,
        // Store specific configuration based on property type
        config: property[property.type]
      }
    }

    // Cache the schema
    databaseSchemaCache[databaseId] = schema
    return schema
  } catch (error) {
    console.error(`Failed to retrieve database schema: ${error.message}`)
    throw error
  }
}

/**
 * Maps arbitrary incoming data to the correct Notion property format
 * @param {Object} data The raw data object with key-value pairs
 * @param {Object} schema The database schema
 * @returns {Object} Notion-formatted properties object
 */
const mapDataToProperties = (data, schema) => {
  const properties = {}

  for (const [key, value] of Object.entries(data)) {
    // Find the matching property in the schema
    const propertyName = findMatchingPropertyName(key, schema.properties)
    if (!propertyName) continue

    const property = schema.properties[propertyName]
    properties[propertyName] = formatPropertyValue(value, property.type)
  }

  return properties
}

/**
 * Find the matching property name in the schema, case-insensitive
 */
const findMatchingPropertyName = (key, schemaProps) => {
  const normalizedKey = key.toLowerCase().trim()

  // Try exact match first
  if (schemaProps[key]) return key

  // Try case-insensitive match
  for (const propName of Object.keys(schemaProps)) {
    if (propName.toLowerCase().trim() === normalizedKey) {
      return propName
    }
  }

  return null
}

/**
 * Format a value according to Notion's expected structure for the property type
 */
const formatPropertyValue = (value, type) => {
  switch (type) {
    case 'title':
      return { title: [{ text: { content: String(value) } }] }
    case 'rich_text':
      return { rich_text: [{ text: { content: String(value) } }] }
    case 'number':
      return { number: Number(value) }
    case 'select':
      return { select: { name: String(value) } }
    case 'multi_select':
      const options = Array.isArray(value) ? value : [value]
      return { multi_select: options.map(opt => ({ name: String(opt) })) }
    case 'date':
      return { date: typeof value === 'string' ? { start: value } : value }
    case 'checkbox':
      return { checkbox: Boolean(value) }
    case 'url':
      return { url: String(value) }
    case 'email':
      return { email: String(value) }
    case 'phone_number':
      return { phone_number: String(value) }
    default:
      // For unsupported types, try to make a reasonable guess
      return { [type]: value }
  }
}

module.exports = {
  getDatabaseSchema,
  mapDataToProperties
}

const express = require('express')
