router.put('/createentry', async (req, res, next) => {
  try {
    let title, properties = {}

    // Try to get schema, but fall back to original behavior if schema retrieval fails
    let schema = null
    try {
      schema = await schemaUtils.getDatabaseSchema(DB_ID)
    } catch (schemaErr) {
      console.warn('Schema retrieval failed, using fallback behavior:', schemaErr.message)
    }

    if (req.body.line) {
      const [key, value] = req.body.line.split(/:(.+)/).map(s => s.trim())
      if (!key || !value) return res.status(400).json({ error: 'Invalid line format. Use "key: value"' })

      title = pageUtils.normalizeKey(key)

      // Use schema-based property mapping if available
      if (schema) {
        const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'
        const valueProp = Object.entries(schema.properties).find(([name, _]) => 
          ['value', 'content', 'description'].includes(name.toLowerCase()))?.[0] || 'Value'

        properties[titleProp] = { title: [{ text: { content: title } }] }
        if (schema.properties[valueProp]) {
          properties[valueProp] = { rich_text: [{ text: { content: value } }] }
        }
      } else {
        // Original fallback behavior
        properties = {
          Name: { title: [{ text: { content: title } }] },
          Value: { rich_text: [{ text: { content: value } }] }
        }
      }
    } else {
      title = req.body.title
      properties = req.body.properties || {}

      if (!title) return res.status(400).json({ error: 'Title is required' })

      if (schema) {
        // Schema-aware property mapping
        const titleProp = Object.entries(schema.properties).find(([_, prop]) => prop.type === 'title')?.[0] || 'Name'
        properties = {
          [titleProp]: { title: [{ text: { content: title } }] },
          ...schemaUtils.mapDataToProperties(properties, schema)
        }
      } else {
        // Original fallback behavior
        properties = {
          Name: { title: [{ text: { content: title } }] },
          ...properties
        }
      }
    }

    const page = await notionApi.createPage({
      parent: { database_id: DB_ID },
      properties
    })

    res.json({ created: true, id: page.id })
