const express = require('express')
const notionApi = require('./notion-api')
const pageUtils = require('./page-utils')

const router = express.Router()
const DB_ID = process.env.NOTION_DATABASE_ID

// A helper function to get the database schema with proper error handling
const getDatabaseSchema = async (databaseId) => {
  try {
    // First, fetch the actual database to get schema
    const database = await notionApi.retrieveDatabase(databaseId)

    // Extract title property name (usually "Name" or "Feature")
    const titlePropName = Object.entries(database.properties)
      .find(([_, prop]) => prop.type === 'title')?.[0]

    if (!titlePropName) {
      console.warn(`Database ${databaseId} has no title property`)
      return { titleProperty: 'Name', properties: database.properties } 
    }

    // Find potential value properties (rich_text type usually)
    const textProps = Object.entries(database.properties)
      .filter(([_, prop]) => prop.type === 'rich_text')
      .map(([name, _]) => name)

    return {
      titleProperty: titlePropName,
      valueProperties: textProps,
      properties: database.properties
    }
  } catch (error) {
    console.error(`Error retrieving database schema: ${error.message}`)
    // Return default property names as fallback
    return {
      titleProperty: 'Name',
      valueProperties: [],
      properties: {}
    }
  }
}

// Special handler for key-value entries
const processKeyValueEntry = async (key, value, schema) => {
  // Create properties object with title property
  const properties = {
    [schema.titleProperty]: { title: [{ text: { content: key } }] }
  }

  // Process value only if we have valid value properties
  if (schema.valueProperties && schema.valueProperties.length > 0) {
    // Use the first rich_text property available
    properties[schema.valueProperties[0]] = { 
      rich_text: [{ text: { content: value } }] 
    }
  } else {
    // Try to create a property with the key's name
    const propName = key.charAt(0).toUpperCase() + key.slice(1)

    // Check if property exists in schema
    if (schema.properties[propName] && schema.properties[propName].type === 'rich_text') {
      properties[propName] = { rich_text: [{ text: { content: value } }] }
    }
    // Otherwise, just set the title and don't try to set other properties
  }

  return properties
}

router.put('/createentry', async (req, res, next) => {
  try {
    // Get database schema with robust error handling
    const schema = await getDatabaseSchema(DB_ID)
    let properties = {}

    if (req.body.line) {
      // Process simple key-value line
      const [key, value] = req.body.line.split(/:(.+)/).map(s => s.trim())
      if (!key || !value) return res.status(400).json({ error: 'Invalid line format. Use "key: value"' })

      const normKey = pageUtils.normalizeKey(key)
      properties = await processKeyValueEntry(normKey, value, schema)
    } else {
      // Handle standard title+properties input
      const title = req.body.title
      const inputProps = req.body.properties || {}

      if (!title) return res.status(400).json({ error: 'Title is required' })

      // Start with title property
      properties = {
        [schema.titleProperty]: { title: [{ text: { content: title } }] }
      }

      // Add other properties only if they exist in the database schema
      for (const [propName, propValue] of Object.entries(inputProps)) {
        if (schema.properties[propName]) {
          // Add property with appropriate format based on its type
          const propType = schema.properties[propName].type

          if (propType === 'rich_text') {
            properties[propName] = { 
              rich_text: [{ text: { content: String(propValue) } }] 
            }
          } else if (propType === 'number') {
            properties[propName] = { number: Number(propValue) }
          } else if (propType === 'select') {
            properties[propName] = { select: { name: String(propValue) } }
          } else if (propType === 'multi_select') {
            const options = Array.isArray(propValue) ? propValue : [propValue]
            properties[propName] = { 
              multi_select: options.map(opt => ({ name: String(opt) })) 
            }
          } else if (propType === 'checkbox') {
            properties[propName] = { checkbox: Boolean(propValue) }
          }
          // Ignore properties that don't exist or have unsupported types
        }
      }
    }

    // Log the actual request being sent for debugging
    console.log('Creating page with properties:', JSON.stringify(properties, null, 2))

    const page = await notionApi.createPage({
      parent: { database_id: DB_ID },
      properties
    })

    res.json({ created: true, id: page.id })
  } catch (err) {
    console.error('Error creating entry:', err.message)
    // If we get an API error, try to extract the message
    if (err.response && err.response.data) {
      return res.status(err.response.status || 500).json({
        error: err.response.data.message || 'Error creating entry',
        details: err.response.data
      })
    }
    next(err)
  }
})

router.patch('/updateentry', async (req, res, next) => {
  try {
    const schema = await getDatabaseSchema(DB_ID)
    let page, properties = {}

    if (req.body.key && req.body.value) {
      // Simple key-value update
      const normKey = pageUtils.normalizeKey(req.body.key)

      // Query by title property
      const { results } = await notionApi.queryDatabase(DB_ID, {
        filter: {
          property: schema.titleProperty,
          title: { equals: normKey }
        }
      })

      page = results[0]
      if (!page) return res.status(404).json({ error: 'Key not found' })

      // Try to update a matching value property if available
      if (schema.valueProperties && schema.valueProperties.length > 0) {
        properties[schema.valueProperties[0]] = { 
          rich_text: [{ text: { content: req.body.value } }] 
        }
      } else {
        // Try to update a property with the key's name if it exists
        const propName = normKey.charAt(0).toUpperCase() + normKey.slice(1)
        if (schema.properties[propName] && schema.properties[propName].type === 'rich_text') {
          properties[propName] = { rich_text: [{ text: { content: req.body.value } }] }
        } else {
          return res.status(400).json({ 
            error: 'No suitable text property found to update value',
            availableProperties: Object.keys(schema.properties)
          })
        }
      }

      const updated = await notionApi.updatePage(page.id, properties)
      return res.json({ updated: true, id: updated.id })
    }

    // Handle structured update
    const { idOrTitle, properties: inputProps } = req.body
    if (!idOrTitle || !inputProps) return res.status(400).json({ error: 'Missing idOrTitle or properties' })

    page = await pageUtils.findPage(DB_ID, idOrTitle)
    if (!page) return res.status(404).json({ error: 'Database entry not found' })

    // Filter properties to only include those that exist in the schema
    for (const [propName, propValue] of Object.entries(inputProps)) {
      if (schema.properties[propName]) {
        const propType = schema.properties[propName].type

        if (propType === 'title') {
          properties[propName] = { title: [{ text: { content: String(propValue) } }] }
        } else if (propType === 'rich_text') {
          properties[propName] = { rich_text: [{ text: { content: String(propValue) } }] }
        } else if (propType === 'number') {
          properties[propName] = { number: Number(propValue) }
        } else if (propType === 'select') {
          properties[propName] = { select: { name: String(propValue) } }
        } else if (propType === 'multi_select') {
          const options = Array.isArray(propValue) ? propValue : [propValue]
          properties[propName] = { 
            multi_select: options.map(opt => ({ name: String(opt) })) 
          }
        } else if (propType === 'checkbox') {
          properties[propName] = { checkbox: Boolean(propValue) }
        }
      }
    }

    const updated = await notionApi.updatePage(page.id, properties)
    res.json(updated)
  } catch (err) {
    console.error('Error updating entry:', err.message)
    if (err.response && err.response.data) {
      return res.status(err.response.status || 500).json({
        error: err.response.data.message || 'Error updating entry',
        details: err.response.data
      })
    }
    next(err)
  }
})

router.delete('/deleteentry', async (req, res, next) => {
  try {
    const schema = await getDatabaseSchema(DB_ID)
