const findPage = async (databaseId, idOrTitle) => {
  if (!idOrTitle) return null;

  console.log(`Finding page with idOrTitle: "${idOrTitle}"`)

  // First try - treat as direct page ID
  if (idOrTitle.length >= 32 && idOrTitle.includes('-')) {
