const createVersionedPage = async (baseTitle, content, parentId) => {
  const query = await notionApi.search(baseTitle)
  const pages = query.results || []
  const versions = pages.map(p => ({
    title: p.properties?.title?.[0]?.plain_text,
    id: p.id
  })).filter(p => p.title?.startsWith(baseTitle))

  let version = 1
  versions.forEach(v => {
    const m = v.title.match(/(\d+)$/)
    if (m) version = Math.max(version, parseInt(m[1]) + 1)
  })

  const newTitle = `${baseTitle} ${version.toString().padStart(2, '0')}`

  return notionApi.createPage({
    parent: { type: 'page_id', page_id: parentId },
    properties: {
      title: [ { type: 'text', text: { content: newTitle } } ]
    },
    children: [
      {
        object: 'block',
        type: 'heading_1',
        heading_1: { rich_text: [ { type: 'text', text: { content: newTitle } } ] }
      },
      {
        object: 'block',
        type: 'paragraph',
        paragraph: { rich_text: [ { type: 'text', text: { content } } ] }
      }
    ]
  })
}

