router.get('/readentry', async (req, res, next) => {
  try {
    const schema = await getDatabaseSchema(DB_ID)
    const { key } = req.query

    if (!key) return res.status(400).json({ error: 'Missing key' })

    const normKey = pageUtils.normalizeKey(key)
    const { results } = await notionApi.queryDatabase(DB_ID, {
        filter: {
          property: schema.titleProperty,
          title: { equals: normKey }
        }
    })

    const page = results[0]
    if (!page) return res.status(404).json({ error: 'Key not found' })

    // Try to get value from first value property if available
    let value = null
    if (schema.valueProperties && schema.valueProperties.length > 0) {
      const valueProp = schema.valueProperties[0]
      value = page.properties[valueProp]?.rich_text?.[0]?.text?.content || null
    }

    // If no value property is found or value is null, look for a property with the key's name
    if (value === null) {
      const propName = normKey.charAt(0).toUpperCase() + normKey.slice(1)
      if (page.properties[propName]) {
        const prop = page.properties[propName]
        if (prop.type === 'rich_text') {
          value = prop.rich_text?.[0]?.text?.content || null
        } else if (prop.type === 'number') {
          value = prop.number
        } else if (prop.type === 'select') {
          value = prop.select?.name || null
        } else if (prop.type === 'multi_select') {
          value = prop.multi_select?.map(item => item.name) || []
        } else if (prop.type === 'checkbox') {
          value = prop.checkbox
        }
      }
    }

    res.json({ key, value })
  } catch (err) {
    console.error('Error reading entry:', err.message)
    next(err)
  }
})

