const notionApi = require('./notion-api')

const extractTitle = (properties) => {
  const titleProp = Object.values(properties).find(p => p.type === 'title')
  return titleProp?.title?.[0]?.plain_text || null
}

const normalizeKey = (key) => decodeURIComponent(key.trim().toLowerCase())

const extractTitleFromBlocks = async (pageId) => {
  try {
    const res = await notionApi.retrievePage(pageId)
    const blocks = await notionApi.appendBlockToPage(pageId, []) // simulates children fetch
    const heading = blocks.results.find(b => b.type.startsWith('heading_'))
    if (heading) {
      return heading[heading.type].rich_text.map(rt => rt.text?.content).join('').trim()
    }
    const para = blocks.results.find(b => b.type === 'paragraph')
    if (para) {
      return para.paragraph.rich_text.map(rt => rt.text?.content).join('').trim()
    }
  } catch (err) {
    console.error(`Failed to extract title from blocks: ${err.message}`)
  }
  return `Untitled (${pageId.slice(0, 8)})`
}

const extractPageTitle = async (page) => {
  const properties = page.properties || {}
  const propKeys = ['title', 'Name', 'Title', 'Feature']
  for (const key of propKeys) {
    const val = properties[key]?.title
    if (val?.length) return val[0].plain_text || val[0].text?.content
  }
  if (page.title?.length) return page.title[0].plain_text || page.title[0].text?.content
  if (page.child_page?.title) return page.child_page.title
  return extractTitleFromBlocks(page.id)
}

const findPageByTitle = async (databaseId, title) => {
  const { results } = await notionApi.queryDatabase(databaseId, {
    filter: {
      property: 'Name',
      title: { equals: title }
    }
  })
  return results[0] || null
}

const generateUniqueTitle = async (databaseId, baseTitle) => {
  let title = baseTitle
  let i = 0
  while (await findPageByTitle(databaseId, title)) {
    i++
    title = `${baseTitle} ${i}`
  }
  return title
}

const findPage = async (databaseId, idOrTitle) => {
  if (idOrTitle.length === 36) return await notionApi.retrievePage(idOrTitle)
  const page = await findPageByTitle(databaseId, idOrTitle)
  return page ? await notionApi.retrievePage(page.id) : null
}

const createVersionedPage = async (baseTitle, content, parentId) => {
  const query = await notionApi.search(baseTitle)
  const pages = query.results || []
  const versions = pages.map(p => ({
    title: p.properties?.title?.[0]?.plain_text,
    id: p.id
  })).filter(p => p.title?.startsWith(baseTitle))

  let version = 1
  versions.forEach(v => {
    const m = v.title.match(/(\d+)$/)
    if (m) version = Math.max(version, parseInt(m[1]) + 1)
  })

  const newTitle = `${baseTitle} ${version.toString().padStart(2, '0')}`

  return notionApi.createPage({
    parent: { type: 'page_id', page_id: parentId },
    properties: {
      title: [ { type: 'text', text: { content: newTitle } } ]
    },
    children: [
      {
        object: 'block',
        type: 'heading_1',
        heading_1: { rich_text: [ { type: 'text', text: { content: newTitle } } ] }
      },
      {
        object: 'block',
        type: 'paragraph',
        paragraph: { rich_text: [ { type: 'text', text: { content } } ] }
      }
    ]
  })
}

module.exports = {
  extractTitle,
  extractPageTitle,
  extractTitleFromBlocks,
  findPageByTitle,
  generateUniqueTitle,
  findPage,
  normalizeKey,
  createVersionedPage
}

