router.get('/readentry', async (req, res, next) => {
  try {
    const { key, field = 'value' } = req.query
    if (!key) return res.status(400).json({ error: 'Missing key' })

    const normKey = pageUtils.normalizeKey(key)
    const { results } = await notionApi.queryDatabase(DB_ID, {
      filter: {
        property: 'Name',
        title: { equals: normKey }
      }
    })

    const page = results[0]
    if (!page) return res.status(404).json({ error: 'Entry not found' })

    // Return all properties if field=all is specified
    if (field.toLowerCase() === 'all') {
      // Extract and format all properties for easier consumption
      const formattedProperties = {}

      // Process each property based on its type
      Object.entries(page.properties).forEach(([propName, propData]) => {
        switch (propData.type) {
          case 'title':
            formattedProperties[propName] = propData.title.map(t => t.plain_text).join('') || null
            break
          case 'rich_text':
            formattedProperties[propName] = propData.rich_text.map(t => t.plain_text).join('') || null
            break
          case 'number':
            formattedProperties[propName] = propData.number
            break
          case 'select':
            formattedProperties[propName] = propData.select?.name || null
            break
          case 'multi_select':
            formattedProperties[propName] = propData.multi_select.map(s => s.name) || []
