            formattedProperties[propName] = propData.checkbox
            break
          case 'url':
            formattedProperties[propName] = propData.url
            break
          case 'email':
            formattedProperties[propName] = propData.email
            break
          case 'phone_number':
            formattedProperties[propName] = propData.phone_number
            break
          default:
            // For other types, return the raw property data
            formattedProperties[propName] = propData
        }
      })

      return res.json({ 
        id: page.id, 
        key, 
        properties: formattedProperties 
      })
    } else {
      // Return a specific field (default to 'Value')
      const fieldName = field === 'value' ? 'Value' : field
      const propertyData = page.properties[fieldName]

      if (!propertyData) {
        return res.json({ key, value: null, message: `Field '${fieldName}' not found in entry` })
      }

      // Extract the property value based on its type
      let value = null
      switch (propertyData.type) {
        case 'title':
          value = propertyData.title.map(t => t.plain_text).join('')
          break
        case 'rich_text':
          value = propertyData.rich_text.map(t => t.plain_text).join('')
          break
        case 'number':
          value = propertyData.number
          break
        case 'select':
          value = propertyData.select?.name
          break
        case 'multi_select':
          value = propertyData.multi_select.map(s => s.name)
          break
        case 'date':
          value = propertyData.date?.start
          break
        case 'checkbox':
          value = propertyData.checkbox
          break
        case 'url':
          value = propertyData.url
          break
        case 'email':
          value = propertyData.email
          break
        case 'phone_number':
          value = propertyData.phone_number
          break
        default:
          value = propertyData
      }

      return res.json({ key, value })
    }
  } catch (err) {
