// routes/notion/memory-routes.js
const express = require('express')
const notionApi = require('./notion-api')
const pageUtils = require('./page-utils')

const router = express.Router()
const MEMORY_DB_ID = process.env.GPT_MEMORY

// Helper function to extract property value based on its type
const extractPropertyValue = (propertyData) => {
  if (!propertyData) return null

  switch (propertyData.type) {
    case 'title':
      return propertyData.title.map(t => t.plain_text).join('') || null
    case 'rich_text':
      return propertyData.rich_text.map(t => t.plain_text).join('') || null
    case 'number':
      return propertyData.number
    case 'select':
      return propertyData.select?.name || null
    case 'multi_select':
      return propertyData.multi_select.map(s => s.name) || []
    case 'date':
      return propertyData.date?.start || null
    case 'checkbox':
      return propertyData.checkbox
    case 'url':
      return propertyData.url
    case 'email':
      return propertyData.email
    case 'phone_number':
      return propertyData.phone_number
    default:
      return propertyData
  }
}

// Helper to format all properties in a page
const formatPageProperties = (page) => {
  if (!page?.properties) return {}

  const formattedProperties = {}
  Object.entries(page.properties).forEach(([propName, propData]) => {
    formattedProperties[propName] = extractPropertyValue(propData)
  })

  return formattedProperties
}

router.put('/creatememory', async (req, res, next) => {
  try {
    let title, properties = {}

    if (req.body.line) {
      const [key, value] = req.body.line.split(/:(.+)/).map(s => s.trim())
      if (!key || !value) return res.status(400).json({ error: 'Invalid line format. Use "key: value"' })
      title = pageUtils.normalizeKey(key)
      properties = {
        Name: { title: [{ text: { content: title } }] },
        Value: { rich_text: [{ text: { content: value } }] }
      }
    } else {
      title = req.body.title
      properties = req.body.properties || {}
      if (!title) return res.status(400).json({ error: 'Title is required' })
      properties = {
        Name: { title: [{ text: { content: title } }] },
        ...properties
      }
    }

    const page = await notionApi.createPage({
      parent: { database_id: MEMORY_DB_ID },
      properties
    })
    res.json({ 
      created: true, 
      id: page.id,
      title
    })
  } catch (err) {
    console.error('Error creating memory:', err.message, err.stack)
    next(err)
  }
})

router.patch('/updatememory', async (req, res, next) => {
  try {
    let page

    if (req.body.key && req.body.value) {
      const normKey = pageUtils.normalizeKey(req.body.key)
      const { results } = await notionApi.queryDatabase(MEMORY_DB_ID, {
        filter: {
          property: 'Name',
          title: { equals: normKey }
        }
      })
      page = results[0]
      if (!page) {
        // Create if doesn't exist
        if (req.body.createIfMissing) {
          const newPage = await notionApi.createPage({
            parent: { database_id: MEMORY_DB_ID },
            properties: {
              Name: { title: [{ text: { content: normKey } }] },
              Value: { rich_text: [{ text: { content: req.body.value } }] }
            }
          })
          return res.json({ created: true, id: newPage.id })
        }
        return res.status(404).json({ error: 'Key not found' })
      }

      const updated = await notionApi.updatePage(page.id, {
        Value: { rich_text: [{ text: { content: req.body.value } }] }
      })
      return res.json({ 
        updated: true, 
        id: updated.id,
        key: normKey,
        value: req.body.value
      })
    }

    const { idOrTitle, properties } = req.body
    if (!idOrTitle || !properties) return res.status(400).json({ error: 'Missing idOrTitle or properties' })

    page = await pageUtils.findPage(MEMORY_DB_ID, idOrTitle)
    if (!page) return res.status(404).json({ error: 'Memory entry not found' })

    const updated = await notionApi.updatePage(page.id, properties)
    res.json({
      updated: true,
      id: updated.id,
      properties: formatPageProperties(updated)
    })
  } catch (err) {
    console.error('Error updating memory:', err.message, err.stack)
    next(err)
  }
})

router.delete('/deletememory', async (req, res, next) => {
  try {
    let page

    if (req.query.key) {
      const normKey = pageUtils.normalizeKey(req.query.key)
      const { results } = await notionApi.queryDatabase(MEMORY_DB_ID, {
        filter: {
          property: 'Name',
          title: { equals: normKey }
        }
      })
      page = results[0]
    } else if (req.query.idOrTitle) {
      page = await pageUtils.findPage(MEMORY_DB_ID, req.query.idOrTitle)
    } else {
      return res.status(400).json({ error: 'Missing key or idOrTitle' })
    }

    if (!page) return res.status(404).json({ error: 'Memory entry not found' })

    // Use updatePage with archived:true instead of deleteBlock for proper deletion
    const archived = await notionApi.updatePage(page.id, {}, true)
    res.json({ 
      deleted: true, 
      id: archived.id, 
      title: pageUtils.extractTitle(page.properties) 
    })
  } catch (err) {
    console.error('Error deleting memory:', err.message, err.stack)
    next(err)
  }
})

router.get('/listmemories', async (req, res, next) => {
  try {
    const { results } = await notionApi.queryDatabase(MEMORY_DB_ID)
    const entries = results.map(p => ({
      id: p.id,
      title: pageUtils.extractTitle(p.properties),
      properties: formatPageProperties(p)
    }))
    res.json(entries)
  } catch (err) {
    console.error('Error listing memories:', err.message, err.stack)
    next(err)
  }
})

router.get('/readmemory', async (req, res, next) => {
  try {
    const { key, field = 'value' } = req.query
    if (!key) return res.status(400).json({ error: 'Missing key' })

    const normKey = pageUtils.normalizeKey(key)
    const { results } = await notionApi.queryDatabase(MEMORY_DB_ID, {
      filter: {
        property: 'Name',
        title: { equals: normKey }
      }
    })

    const page = results[0]
    if (!page) return res.status(404).json({ error: 'Memory not found' })

    // Return all properties if field=all is specified
    if (field.toLowerCase() === 'all') {
      return res.json({ 
        id: page.id, 
        key, 
        properties: formatPageProperties(page) 
      })
    } else {
      // Return a specific field (default to 'Value')
      const fieldName = field === 'value' ? 'Value' : field
      const propertyData = page.properties[fieldName]

      if (!propertyData) {
        return res.json({ key, value: null, message: `Field '${fieldName}' not found in memory entry` })
      }

      return res.json({ 
        key, 
        value: extractPropertyValue(propertyData) 
      })
    }
  } catch (err) {
    console.error('Error reading memory:', err.message, err.stack)
    next(err)
  }
})

module.exports = router

const axios = require('axios')

const NOTION_API_BASE = 'https://api.notion.com/v1'
const notionToken = process.env.NOTION_TOKEN
const notionVersion = '2022-06-28'

const client = axios.create({
  baseURL: NOTION_API_BASE,
  headers: {
    Authorization: `Bearer ${notionToken}`,
    'Notion-Version': notionVersion,
    'Content-Type': 'application/json'
  }
})

// Add request and response interceptors for better debugging
client.interceptors.request.use(request => {
  console.log(`[Notion API Request] ${request.method.toUpperCase()} ${request.url}`)
  return request
})

client.interceptors.response.use(
  response => {
    console.log(`[Notion API Response] Status: ${response.status}`)
    return response
  },
  error => {
    console.error('[Notion API Error]', error.response?.status, error.response?.data || error.message)
    return Promise.reject(error)
  }
)

/**
 * Query a Notion database with filters
 * @param {string} database_id - The ID of the database to query
 * @param {Object} filter - Query filters
 * @returns {Promise<Object>} - Query results
 */
const queryDatabase = async (database_id, filter = {}) => {
  return client.post(`/databases/${database_id}/query`, filter).then(res => res.data)
}

/**
 * Retrieve a specific page by ID
 * @param {string} page_id - The ID of the page to retrieve
 * @returns {Promise<Object>} - Page data
 */
const retrievePage = async (page_id) => {
  return client.get(`/pages/${page_id}`).then(res => res.data)
}

/**
 * Get information about a database by ID
 * @param {string} database_id - The ID of the database
 * @returns {Promise<Object>} - Database information
 */
const retrieveDatabase = async (database_id) => {
  return client.get(`/databases/${database_id}`).then(res => res.data)
}

/**
 * Create a new page
 * @param {Object} payload - The page creation payload
 * @returns {Promise<Object>} - Created page data
 */
const createPage = async (payload) => {
  return client.post('/pages', payload).then(res => res.data)
}

/**
 * Update a page's properties or archive state
 * @param {string} page_id - The ID of the page to update
 * @param {Object} properties - The properties to update
 * @param {boolean} archived - Whether to archive the page
 * @returns {Promise<Object>} - Updated page data
 */
const updatePage = async (page_id, properties = {}, archived = false) => {
  const payload = { properties }

  if (archived) {
    payload.archived = true
  }

  return client.patch(`/pages/${page_id}`, payload).then(res => res.data)
}

/**
 * Archive a block (Note: Prefer updatePage with archived=true for pages)
 * @param {string} block_id - The ID of the block to archive
 * @returns {Promise<Object>} - Archived block data
 */
const deleteBlock = async (block_id) => {
  return client.patch(`/blocks/${block_id}`, { archived: true }).then(res => res.data)
}

/**
 * Create a new database
 * @param {Object} payload - The database creation payload
 * @returns {Promise<Object>} - Created database data
 */
const createDatabase = async (payload) => {
  return client.post('/databases', payload).then(res => res.data)
}

/**
 * Update a database
 * @param {string} database_id - The ID of the database to update
 * @param {Object} props - The properties to update
 * @returns {Promise<Object>} - Updated database data
 */
const updateDatabase = async (database_id, props) => {
  return client.patch(`/databases/${database_id}`, props).then(res => res.data)
}

/**
 * Search Notion
 * @param {string} query - The search query
 * @returns {Promise<Object>} - Search results
 */
const search = async (query) => {
  return client.post('/search', { query }).then(res => res.data)
}

/**
 * Get the children blocks of a block
 * @param {string} blockId - The ID of the parent block
 * @param {string} startCursor - The cursor to start from for pagination
 * @returns {Promise<Object>} - Block children data
 */
const getBlockChildren = async (blockId, startCursor = undefined) => {
  const params = {}
  if (startCursor) params.start_cursor = startCursor

  return client.get(`/blocks/${blockId}/children`, { params }).then(res => res.data)
}

/**
 * Append blocks to a page or block
 * @param {string} blockId - The ID of the parent block
 * @param {Array} blocks - The blocks to append
 * @returns {Promise<Object>} - Block children data
 */
const appendBlockToPage = async (blockId, blocks) => {
  return client.patch(`/blocks/${blockId}/children`, { children: blocks }).then(res => res.data)
}

/**
 * Create a standalone page in the workspace
 * @param {string} title - The page title
 * @param {string} content - The page content
 * @returns {Promise<Object>} - Created page data
 */
const createStandalonePage = async (title, content) => {
  const blocks = [
    {
      object: 'block',
      type: 'heading_1',
      heading_1: { rich_text: [{ type: 'text', text: { content: title } }] }
    },
    ...(content ? [{
      object: 'block',
      type: 'paragraph',
      paragraph: { rich_text: [{ type: 'text', text: { content } }] }
    }] : [])
  ]

  const payload = {
    parent: { type: 'page_id', page_id: process.env.NOTION_PARENT_PAGE_ID },
    properties: {
      title: [
        {
          type: 'text',
          text: { content: title }
        }
      ]
    },
    children: blocks
  }

  return client.post('/pages', payload).then(res => res.data)
}

module.exports = {
  queryDatabase,
  retrievePage,
  retrieveDatabase,
  createPage,
  updatePage,
  deleteBlock,
  createDatabase,
  updateDatabase,
  search,
  getBlockChildren,
  appendBlockToPage,
  createStandalonePage
}

