// routes/notion/memory-routes.js
const express = require('express');
const notionApi = require('./notion-api');
const pageUtils = require('./page-utils');
const schemaDetection = require('./schema-detection');

const router = express.Router();
const MEMORY_DB_ID = process.env.GPT_MEMORY;

/**
 * Extract property value based on its Notion type
 * @param {Object} property - The Notion property object
 * @returns {any} - The extracted value
 */
const extractPropertyValue = (property) => {
  if (!property) return null;

  switch (property.type) {
    case 'title':
      return property.title?.length ? property.title.map(t => t.plain_text || '').join('') : null;
    case 'rich_text':
      return property.rich_text?.length ? property.rich_text.map(t => t.plain_text || '').join('') : null;
    case 'number':
      return property.number;
    case 'select':
      return property.select?.name || null;
    case 'multi_select':
      return property.multi_select?.length ? property.multi_select.map(s => s.name) : [];
    case 'date':
      return property.date?.start || null;
    case 'checkbox':
      return property.checkbox;
    case 'url':
      return property.url;
    case 'email':
      return property.email;
    case 'phone_number':
      return property.phone_number;
    default:
      return null;
  }
};

/**
 * Create a new memory entry
 */
router.put('/creatememory', async (req, res, next) => {
  try {
    // Ensure database exists
    try {
      const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);
      if (!schema) {
        return res.status(404).json({ 
          error: 'Memory database not found',
          message: 'Check the GPT_MEMORY environment variable'
        });
      }
    } catch (err) {
      return res.status(500).json({ 
        error: 'Error accessing memory database',
        message: err.message
      });
    }

    // Process the line input (key: value format)
    if (req.body.line) {
      const parts = req.body.line.split(/:(.+)/);
      if (parts.length < 2) {
        return res.status(400).json({ 
          error: 'Invalid line format', 
          message: 'Use "key: value" format'
        });
      }

      const key = parts[0].trim();
      const value = parts[1].trim();

      if (!key || !value) {
        return res.status(400).json({ 
          error: 'Invalid input', 
          message: 'Both key and value are required'
        });
      }

      try {
        // Get database schema
        const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);

        // Find title property
        const titleProperty = Object.entries(schema)
          .find(([_, prop]) => prop.type === 'title');

        if (!titleProperty) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Memory database must have a title property'
          });
        }

        const titlePropertyName = titleProperty[0];

        // Find a rich_text property for the value
        const textProperty = Object.entries(schema)
          .find(([name, prop]) => prop.type === 'rich_text' && name !== titlePropertyName);

        if (!textProperty) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Memory database must have a rich_text property for values'
          });
        }

        const textPropertyName = textProperty[0];

        // Create the page
        const page = await notionApi.createPage({
          parent: { database_id: MEMORY_DB_ID },
          properties: {
            [titlePropertyName]: { 
              title: [{ text: { content: key } }] 
            },
            [textPropertyName]: { 
              rich_text: [{ text: { content: value } }] 
            }
          }
        });

        return res.json({
          success: true,
          created: true,
          id: page.id,
          key,
          value
        });
      } catch (err) {
        console.error('Error creating memory from line:', err);
        return res.status(500).json({ 
          error: 'Failed to create memory',
          message: err.message
        });
      }
    }

    // Process title and properties input
    const title = req.body.title;
    const properties = req.body.properties || {};

    if (!title && Object.keys(properties).length === 0) {
      return res.status(400).json({ 
        error: 'Missing data', 
        message: 'Either title or properties is required'
      });
    }

    try {
      // Get database schema
      const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);

      // Find title property
      const titleProperty = Object.entries(schema)
        .find(([_, prop]) => prop.type === 'title');

      if (!titleProperty) {
        return res.status(500).json({ 
          error: 'Invalid database structure', 
          message: 'Memory database must have a title property'
        });
      }

      const titlePropertyName = titleProperty[0];
      const mappedProperties = {};

      // Add title if provided
      if (title) {
        mappedProperties[titlePropertyName] = {
          title: [{ text: { content: title } }]
        };
      }

      // Map other properties
      for (const [propName, propValue] of Object.entries(properties)) {
        // Skip if property doesn't exist in schema
        if (!schema[propName]) {
          console.warn(`Property ${propName} does not exist in memory database schema`);
          continue;
        }

        const propType = schema[propName].type;

        // Format property based on its type
        switch (propType) {
          case 'title':
            mappedProperties[propName] = {
              title: [{ text: { content: String(propValue) } }]
            };
            break;
          case 'rich_text':
            mappedProperties[propName] = {
              rich_text: [{ text: { content: String(propValue) } }]
            };
            break;
          case 'number':
            mappedProperties[propName] = {
              number: Number(propValue)
            };
            break;
          case 'select':
            mappedProperties[propName] = {
              select: { name: String(propValue) }
            };
            break;
          case 'multi_select':
            const values = Array.isArray(propValue) ? propValue : [propValue];
            mappedProperties[propName] = {
              multi_select: values.map(v => ({ name: String(v) }))
            };
            break;
          case 'checkbox':
            mappedProperties[propName] = {
              checkbox: Boolean(propValue)
            };
            break;
          // Add cases for other property types as needed
        }
      }

      // Create the page
      const page = await notionApi.createPage({
        parent: { database_id: MEMORY_DB_ID },
        properties: mappedProperties
      });

      // Extract the title for response
      const pageTitle = pageUtils.extractTitle(page.properties);

      return res.json({
        success: true,
        created: true,
        id: page.id,
        title: pageTitle
      });
    } catch (err) {
      console.error('Error creating memory from properties:', err);
      return res.status(500).json({ 
        error: 'Failed to create memory',
        message: err.message
      });
    }
  } catch (err) {
    console.error('Unexpected error in creatememory:', err);
    next(err);
  }
});

/**
 * Update an existing memory entry
 */
router.patch('/updatememory', async (req, res, next) => {
  try {
    // Handle key-value update
    if (req.body.key && req.body.value !== undefined) {
      const key = req.body.key.trim();
