      try {
        // Get database schema
        const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);

        // Find title property
        const titleProperty = Object.entries(schema)
          .find(([_, prop]) => prop.type === 'title');

        if (!titleProperty) {
