const express = require('express')
const path = require('path')
const app = express()

// Middleware
app.use(express.json())

app.use((req, res, next) => {
  const { method, url, headers, body } = req;
  console.log(`[${new Date().toISOString()}] ${method} ${url}`);
  console.log('Headers:', headers);
  if (Object.keys(body || {}).length) console.log('Body:', body);
  next();
});

// Routes
app.use('/notion/pages', require('./routes/notion/page-routes'))
app.use('/notion/databases', require('./routes/notion/database-routes'))
app.use('/notion/memory', require('./routes/notion/memory-routes'))

// Health Check
app.get("/", (req, res) => {
  res.send("✅ Notion + GitHub Full API is live.")
})

// Error Handler
app.use((err, req, res, next) => {
  console.error(err)
  res.status(500).json({ error: 'Internal Server Error' })
})

// Static + OpenAPI
app.use(express.static(path.join(__dirname, 'public')))
app.get("/openapi.json", (req, res) => {
  res.sendFile(path.join(__dirname, "openapi.json"))
})

// Boot server
const PORT = process.env.PORT || 3000
app.listen(PORT, '0.0.0.0', () => console.log(`Server running on port ${PORT}`))

