const BLOCK_TYPES = {
  paragraph: (text) => ({
    type: 'paragraph',
    paragraph: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  heading_1: (text) => ({
    type: 'heading_1',
    heading_1: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  heading_2: (text) => ({
    type: 'heading_2',
    heading_2: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  heading_3: (text) => ({
    type: 'heading_3',
    heading_3: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  bulleted_list_item: (text) => ({
    type: 'bulleted_list_item',
    bulleted_list_item: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  numbered_list_item: (text) => ({
    type: 'numbered_list_item',
    numbered_list_item: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  to_do: (text, checked = false) => ({
    type: 'to_do',
    to_do: { rich_text: [{ type: 'text', text: { content: text } }], checked }
  }),
  quote: (text) => ({
    type: 'quote',
    quote: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  code: (text, language = 'javascript') => ({
    type: 'code',
    code: { rich_text: [{ type: 'text', text: { content: text } }], language }
  }),
  toggle: (text) => ({
    type: 'toggle',
    toggle: { rich_text: [{ type: 'text', text: { content: text } }], children: [] }
  }),
  callout: (text, icon = { emoji: '💡' }) => ({
    type: 'callout',
    callout: { rich_text: [{ type: 'text', text: { content: text } }], icon }
  }),
  divider: () => ({ type: 'divider', divider: {} }),
  image: (url) => ({ type: 'image', image: { type: 'external', external: { url } } }),
  video: (url) => ({ type: 'video', video: { type: 'external', external: { url } } }),
  file: (url) => ({ type: 'file', file: { type: 'external', external: { url } } }),
  pdf: (url) => ({ type: 'pdf', pdf: { type: 'external', external: { url } } }),
  bookmark: (url) => ({ type: 'bookmark', bookmark: { url } }),
  embed: (url) => ({ type: 'embed', embed: { url } }),
  equation: (expression) => ({ type: 'equation', equation: { expression } }),
  table: (tableData) => ({ type: 'table', table: tableData }),
  table_row: (cells) => ({ type: 'table_row', table_row: { cells } }),
  synced_block: (synced_from = null) => ({ type: 'synced_block', synced_block: { synced_from } }),
  child_page: (title) => ({ type: 'child_page', child_page: { title } }),
  child_database: (title) => ({ type: 'child_database', child_database: { title } }),
  template: (text) => ({ type: 'template', template: { rich_text: [{ type: 'text', text: { content: text } }] } }),
  link_to_page: (type, id) => ({
    type: 'link_to_page',
    link_to_page: { type, [type === 'page_id' ? 'page_id' : 'database_id']: id }
  })
}

module.exports = { BLOCK_TYPES }

const { BLOCK_TYPES } = require('./block-types')

const mdToBlocks = (markdown) => {
  const lines = markdown.split('\n')
  const blocks = []
  let inCode = false
  let codeLang = 'text'
  let codeBuffer = []

  for (let line of lines) {
    if (/^```/.test(line)) {
      if (!inCode) {
        inCode = true
        codeLang = line.replace(/^```/, '').trim() || 'text'
        codeBuffer = []
      } else {
        inCode = false
        blocks.push(BLOCK_TYPES.code(codeBuffer.join('\n'), codeLang))
      }
      continue
    }
    if (inCode) {
      codeBuffer.push(line)
      continue
    }
    if (/^#\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_1(line.replace(/^#\s+/, '')))
    else if (/^##\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_2(line.replace(/^##\s+/, '')))
    else if (/^###\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_3(line.replace(/^###\s+/, '')))
    else if (/^-\s+\[ \]\s+/.test(line)) blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[ \]\s+/, ''), false))
    else if (/^-\s+\[x\]\s+/.test(line)) blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[x\]\s+/, ''), true))
    else if (/^-\s+/.test(line)) blocks.push(BLOCK_TYPES.bulleted_list_item(line.replace(/^-\s+/, '')))
    else if (/^\d+\.\s+/.test(line)) blocks.push(BLOCK_TYPES.numbered_list_item(line.replace(/^\d+\.\s+/, '')))
    else if (/^>\s+/.test(line)) blocks.push(BLOCK_TYPES.quote(line.replace(/^>\s+/, '')))
    else if (/^---+$/.test(line)) blocks.push(BLOCK_TYPES.divider())
    else blocks.push(BLOCK_TYPES.paragraph(line))
  }

  return blocks
}

const blocksToMd = (blocks) => {
  return blocks.map(block => {
    const rich = block[block.type]?.rich_text
    const content = Array.isArray(rich)
      ? rich.map(r => r.plain_text || r.text?.content).join('')
      : ''

    switch (block.type) {
      case 'heading_1': return `# ${content}`
      case 'heading_2': return `## ${content}`
      case 'heading_3': return `### ${content}`
      case 'bulleted_list_item': return `- ${content}`
      case 'numbered_list_item': return `1. ${content}`
      case 'to_do': return `- [${block.to_do.checked ? 'x' : ' '}] ${content}`
      case 'quote': return `> ${content}`
      case 'code': return `\n\n\`\`\`${block.code.language || 'text'}\n${block.code.rich_text?.map(rt => rt.text?.content).join('') || ''}\n\`\`\``
      case 'divider': return '---'
      case 'toggle': return `<details><summary>${content}</summary></details>`
      case 'callout': return `> 💡 ${content}`
      default: return content
    }
  }).join('\n')
}

const convertTextToBlocks = async (text) => {
  return text.split('\n').map(line => BLOCK_TYPES.paragraph(line))
}

const convertBlocksToText = (blocks) => {
  return blocks.map(block => {
    const rich = block[block.type]?.rich_text
    return Array.isArray(rich)
      ? rich.map(r => r.plain_text || r.text?.content || '').join('')
      : ''
  }).join('\n')
}

const smartTextToBlocks = async (text) => {
  const isMarkdown = /[#>`*-]|\n.*\n/.test(text.trim())
  return isMarkdown ? mdToBlocks(text) : await convertTextToBlocks(text)
}

module.exports = {
  mdToBlocks,
  blocksToMd,
  convertTextToBlocks,
  convertBlocksToText,
  smartTextToBlocks
}

