// notion-route-factory.js
const express = require('express');
const notionApi = require('./notion-api');
const pageUtils = require('./page-utils');
const schemaDetection = require('./schema-detection');

/**
 * Create a configurable router for Notion database operations
 * @param {Object} config - Configuration for the router
 * @param {string} config.databaseId - The environment variable containing the database ID
 * @param {string} config.prefix - Prefix for route names (e.g., '' or 'memory')
 * @param {Object} config.routeNames - Custom route names mapping
 * @returns {express.Router} - Configured Express router
 */
const createNotionRouter = (config) => {
  const router = express.Router();
  const DB_ID = process.env[config.databaseId];

  // Default route names
  const defaultRouteNames = {
    create: 'createentry',
    update: 'updateentry',
    delete: 'deleteentry',
    list: 'listentries',
    read: 'readentry'
  };

  // Custom route names based on prefix
  let routeNames = {};
  if (config.prefix) {
    for (const [key, value] of Object.entries(defaultRouteNames)) {
      routeNames[key] = `${key}${config.prefix}`;
    }
  } else {
    routeNames = { ...defaultRouteNames };
  }

  // Override with any custom route names provided
  if (config.routeNames) {
    routeNames = { ...routeNames, ...config.routeNames };
  }

  /**
   * Extract property value based on its Notion type
   * @param {Object} property - The Notion property object
   * @returns {any} - The extracted value
   */
  const extractPropertyValue = (property) => {
    if (!property) return null;

    switch (property.type) {
      case 'title':
        return property.title?.length ? property.title.map(t => t.plain_text || '').join('') : null;
      case 'rich_text':
        return property.rich_text?.length ? property.rich_text.map(t => t.plain_text || '').join('') : null;
      case 'number':
        return property.number;
      case 'select':
        return property.select?.name || null;
      case 'multi_select':
        return property.multi_select?.length ? property.multi_select.map(s => s.name) : [];
      case 'date':
        return property.date?.start || null;
      case 'checkbox':
        return property.checkbox;
      case 'url':
        return property.url;
      case 'email':
        return property.email;
      case 'phone_number':
        return property.phone_number;
      default:
        return null;
    }
  };

  // CREATE route
  router.put(`/${routeNames.create}`, async (req, res, next) => {
    try {
      // Ensure database exists
      try {
        const schema = await schemaDetection.getDatabaseSchema(DB_ID);
        if (!schema) {
          return res.status(404).json({ 
            error: `Database not found`,
            message: `Check the ${config.databaseId} environment variable`
          });
        }
      } catch (err) {
        return res.status(500).json({ 
          error: `Error accessing database`,
          message: err.message
        });
      }

      let properties = {};

      if (req.body.line) {
        // Handle key-value format
        const parts = req.body.line.split(/:(.+)/);
        if (parts.length < 2) {
          return res.status(400).json({ 
            error: 'Invalid line format', 
            message: 'Use "key: value" format'
          });
        }

        const key = parts[0].trim();
        const value = parts[1].trim();

        if (!key || !value) {
          return res.status(400).json({ 
            error: 'Invalid input', 
            message: 'Both key and value are required'
          });
        }

        // Get database schema
        const schema = await schemaDetection.getDatabaseSchema(DB_ID);

        // Find title property
        const titleProperty = schemaDetection.findTitleProperty(schema);

        if (!titleProperty) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Database must have a title property'
          });
        }

        // Find a rich_text property for the value
        const textProperty = schemaDetection.findPropertyByType(schema, 'rich_text') || 'Value';

        if (!schema[textProperty]) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Database must have a rich_text property for values'
          });
        }

        // Create the page
        properties = {
          [titleProperty]: { 
            title: [{ text: { content: key } }] 
          },
          [textProperty]: { 
            rich_text: [{ text: { content: value } }] 
          }
        };
      } else {
        // Process title and properties input
        const title = req.body.title;
        const inputProperties = req.body.properties || {};

        if (!title && Object.keys(inputProperties).length === 0) {
          return res.status(400).json({ 
            error: 'Missing data', 
            message: 'Either title or properties is required'
          });
        }

        // Map properties to schema
        try {
          if (title) {
            // Map the title to the proper schema property
            const titleMapped = await schemaDetection.mapPropertiesToSchema(DB_ID, { title });
            properties = { ...titleMapped };
          }

          // Map other properties if provided
          if (Object.keys(inputProperties).length > 0) {
            const mappedProps = await schemaDetection.mapPropertiesToSchema(DB_ID, inputProperties);
            properties = { ...properties, ...mappedProps };
          }
        } catch (err) {
          console.error('Error mapping properties:', err.message);
          return res.status(500).json({ 
            error: 'Error mapping properties to database schema',
            message: err.message
          });
        }
      }

      // Create the page
      const page = await notionApi.createPage({
        parent: { database_id: DB_ID },
        properties
      });

      // Extract the title for response
      const title = await pageUtils.extractPageTitle(page);

      return res.json({
        success: true,
        created: true,
        id: page.id,
        title
      });
    } catch (err) {
      console.error(`Error in ${routeNames.create}:`, err);
      next(err);
    }
  });

  // UPDATE route
  router.patch(`/${routeNames.update}`, async (req, res, next) => {
    try {
      // Handle key-value update
      if (req.body.key && req.body.value !== undefined) {
        const key = req.body.key.trim();
        const value = req.body.value;

        try {
          // Get database schema
          const schema = await schemaDetection.getDatabaseSchema(DB_ID);

          // Build a filter using the title property
          const filter = await schemaDetection.buildTitleFilter(DB_ID, key);

          // Query for the page
          const { results } = await notionApi.queryDatabase(DB_ID, { filter });

          // Create if not found and createIfMissing is true
          if (results.length === 0) {
            if (req.body.createIfMissing) {
              // Find title property
              const titleProperty = schemaDetection.findTitleProperty(schema);

              // Find a rich_text property for the value
              const textProperty = schemaDetection.findPropertyByType(schema, 'rich_text') || 'Value';

              if (!schema[textProperty]) {
                return res.status(500).json({ 
                  error: 'Invalid database structure', 
                  message: 'Database must have a rich_text property for values'
                });
              }

              // Create the page
              const newPage = await notionApi.createPage({
                parent: { database_id: DB_ID },
                properties: {
                  [titleProperty]: { 
                    title: [{ text: { content: key } }] 
                  },
                  [textProperty]: { 
                    rich_text: [{ text: { content: String(value) } }] 
                  }
                }
              });

              return res.json({
                success: true,
                created: true,
                id: newPage.id,
                key,
                value
              });
            } else {
              return res.status(404).json({ 
                error: 'Entry not found',
                message: `No entry found with key: ${key}`
              });
            }
          }

          const page = results[0];

          // Find a property for storing the value
          const textProperty = schemaDetection.findPropertyByType(schema, 'rich_text') || 'Value';

          if (!schema[textProperty]) {
            return res.status(500).json({ 
              error: 'Invalid database structure', 
              message: 'Database must have a rich_text property for values'
            });
          }

          // Update the page
          const updated = await notionApi.updatePage(page.id, {
            [textProperty]: { 
              rich_text: [{ text: { content: String(value) } }] 
            }
          });

          return res.json({
            success: true,
            updated: true,
            id: updated.id,
            key,
            value
          });
        } catch (err) {
          console.error(`Error updating entry with key-value:`, err);
          return res.status(500).json({ 
            error: 'Failed to update entry',
            message: err.message
          });
        }
      }

      // Handle update by ID or title with properties
      const { idOrTitle, properties } = req.body;

      if (!idOrTitle) {
        return res.status(400).json({ 
          error: 'Missing identifier', 
          message: 'Either key+value or idOrTitle+properties is required'
        });
      }

      if (!properties || Object.keys(properties).length === 0) {
        return res.status(400).json({ 
          error: 'Missing properties', 
          message: 'Properties object is required'
        });
      }

      try {
        // Find the page
        const page = await pageUtils.findPage(DB_ID, idOrTitle);

        if (!page) {
          return res.status(404).json({ 
            error: 'Entry not found',
            message: `No entry found with identifier: ${idOrTitle}`
          });
        }

        // Map properties to the schema
        const mappedProperties = await schemaDetection.mapPropertiesToSchema(DB_ID, properties);

        // Update the page
        const updated = await notionApi.updatePage(page.id, mappedProperties);

        // Format properties for response
        const formattedProperties = {};

        for (const [propName, propData] of Object.entries(updated.properties)) {
          formattedProperties[propName] = extractPropertyValue(propData);
        }

        return res.json({
          success: true,
          updated: true,
          id: updated.id,
          properties: formattedProperties
        });
      } catch (err) {
        console.error(`Error updating entry with properties:`, err);
        return res.status(500).json({ 
          error: 'Failed to update entry',
          message: err.message
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.update}:`, err);
      next(err);
    }
  });

  // DELETE route
  router.delete(`/${routeNames.delete}`, async (req, res, next) => {
    try {
      const { key, idOrTitle } = req.query;

      if (!key && !idOrTitle) {
        return res.status(400).json({ 
          error: 'Missing identifier', 
          message: 'Either key or idOrTitle is required'
        });
      }

      let page;

      try {
        // Find by key
        if (key) {
          // Build a filter using the title property
          const filter = await schemaDetection.buildTitleFilter(DB_ID, key);

          // Query for the page
          const { results } = await notionApi.queryDatabase(DB_ID, { filter });

          if (results.length === 0) {
            return res.status(404).json({ 
              error: 'Entry not found',
              message: `No entry found with key: ${key}`
            });
          }

          page = results[0];
        }
        // Find by ID or title
        else {
          page = await pageUtils.findPage(DB_ID, idOrTitle);

          if (!page) {
            return res.status(404).json({ 
              error: 'Entry not found',
              message: `No entry found with identifier: ${idOrTitle}`
            });
          }
        }

        // Archive the page (Notion's way of deletion)
        await notionApi.updatePage(page.id, {}, true);

        // Extract title for response
        const title = await pageUtils.extractPageTitle(page);

        return res.json({
          success: true,
          deleted: true,
          id: page.id,
          title
        });
      } catch (err) {
        console.error(`Error deleting entry:`, err);
        return res.status(500).json({ 
          error: 'Failed to delete entry',
          message: err.message
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.delete}:`, err);
      next(err);
    }
  });

  // LIST route
  router.get(`/${routeNames.list}`, async (req, res, next) => {
    try {
      try {
        const { results } = await notionApi.queryDatabase(DB_ID);

        // Format the results
        const entries = await Promise.all(results.map(async (page) => {
          const title = await pageUtils.extractPageTitle(page);

          return {
            id: page.id,
            title,
            url: page.url,
            created_time: page.created_time,
            last_edited_time: page.last_edited_time
          };
        }));

        return res.json(entries);
      } catch (err) {
        console.error(`Error listing entries:`, err);
        return res.status(500).json({ 
          error: 'Failed to list entries',
          message: err.message
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.list}:`, err);
      next(err);
    }
  });

  // READ route
  router.get(`/${routeNames.read}`, async (req, res, next) => {
    try {
      const { key, id, field = 'value' } = req.query;

      if (!key && !id) {
        return res.status(400).json({ 
          error: 'Missing identifier', 
          message: 'Either key or id parameter is required'
        });
      }

      try {
        let page;

        // Find by key
        if (key) {
          // Build a filter using the title property
          const filter = await schemaDetection.buildTitleFilter(DB_ID, key);

          // Query for the page
          const { results } = await notionApi.queryDatabase(DB_ID, { filter });

          if (results.length === 0) {
            return res.status(404).json({ 
              error: 'Entry not found',
              message: `No entry found with key: ${key}`
            });
          }

          page = results[0];
        }
        // Find by ID
        else {
          try {
            page = await notionApi.retrievePage(id);
          } catch (err) {
            return res.status(404).json({ 
              error: 'Entry not found',
              message: `No entry found with id: ${id}`
            });
          }
        }

        // Return all fields
        if (field.toLowerCase() === 'all') {
          // Format all properties
          const formattedProperties = {};

          for (const [propName, propData] of Object.entries(page.properties)) {
            formattedProperties[propName] = extractPropertyValue(propData);
          }

          return res.json({
            id: page.id,
            key: key || id,
            properties: formattedProperties,
            url: page.url,
            created_time: page.created_time,
            last_edited_time: page.last_edited_time
          });
        }

        // Return a specific field
        const schema = await schemaDetection.getDatabaseSchema(DB_ID);

        // If field is 'value', look for rich_text property
        if (field.toLowerCase() === 'value') {
          // First try 'Value' property
          if (page.properties.Value && page.properties.Value.type === 'rich_text') {
            const value = extractPropertyValue(page.properties.Value);

            return res.json({
              id: page.id,
              key: key || id,
              value
            });
          }

          // Then try any rich_text property
          const textProperty = schemaDetection.findPropertyByType(schema, 'rich_text');

          if (textProperty) {
            const value = extractPropertyValue(page.properties[textProperty]);

            return res.json({
              id: page.id,
              key: key || id,
              value,
              property: textProperty
            });
          }

          return res.json({
            id: page.id,
            key: key || id,
            value: null,
            message: 'No suitable value property found'
          });
        }

        // Return the specified field
        const property = page.properties[field];

        if (!property) {
          return res.json({
            id: page.id,
            key: key || id,
            value: null,
            message: `Field '${field}' not found in entry`
          });
        }

        const value = extractPropertyValue(property);

        return res.json({
          id: page.id,
          key: key || id,
          value,
          property: field
        });
      } catch (err) {
        console.error(`Error reading entry:`, err);
        return res.status(500).json({ 
          error: 'Failed to read entry',
          message: err.message
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.read}:`, err);
      next(err);
    }
  });

  return router;
};

