    }
    if (children) {
      const content = typeof children === 'string' ? await smartTextToBlocks(children) : children
      const appended = await notionApi.appendBlocks(page.id, content)
      results.push({ type: 'blocks', count: appended?.results?.length || 0 })
    }

    cache.invalidate(idOrTitle)
    res.json({ updated: true, id: page.id, results })
  } catch (err) {
    next(err)
  }
})

// Delete (archive) a standalone page
router.delete('/deletepage', async (req, res, next) => {
  try {
    const { idOrTitle } = req.query
    if (!idOrTitle) return res.status(400).json({ error: 'Missing idOrTitle' })

    const page = await pageUtils.findPageAcrossWorkspace(idOrTitle)
    if (!page) return res.status(404).json({ error: 'Page not found' })

    const archived = await notionApi.deleteBlock(page.id)
    cache.invalidate(idOrTitle)
    res.json({ deleted: true, id: archived.id })
  } catch (err) {
    next(err)
  }
})

// Read content of a standalone page
router.get('/readpage', async (req, res, next) => {
  try {
    const { idOrTitle, format = 'blocks' } = req.query // format can be: blocks, markdown, text, html, pdf
    if (!idOrTitle) return res.status(400).json({ error: 'Missing idOrTitle' })

    const page = await pageUtils.findPageAcrossWorkspace(idOrTitle)
    if (!page) return res.status(404).json({ error: 'Page not found' })

    const blocks = await notionApi.getBlockChildren(page.id)
    const title = await pageUtils.extractPageTitle(page)
    const safeName = title.replace(/[^a-z0-9]/gi, '_').toLowerCase()

    if (format === 'markdown') {
      res.setHeader('Content-Type', 'text/markdown')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.md\"`)
      return res.send(blocksToMd(blocks))
    }
    if (format === 'text') {
      res.setHeader('Content-Type', 'text/plain')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.txt\"`)
      return res.send(convertBlocksToText(blocks))
    }
    if (format === 'html') {
      res.setHeader('Content-Type', 'text/html')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.html\"`)
      return res.send(marked.parse(blocksToMd(blocks)))
    }

    if (format === 'pdf') {
      const pdfDoc = await PDFDocument.create()
      const page = pdfDoc.addPage()
      const text = convertBlocksToText(blocks)
      page.drawText(text, { x: 50, y: page.getHeight() - 50, size: 12 })
      const pdfBytes = await pdfDoc.save()
      res.setHeader('Content-Type', 'application/pdf')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.pdf\"`)
      res.send(Buffer.from(pdfBytes))
      return
    }

    res.json({ id: page.id, blocks })
  } catch (err) {
    next(err)
  }
})

// List standalone pages only (exclude DB entries)
router.get('/listpages', async (req, res, next) => {
  try {
    const query = await notionApi.search('')
    const basePages = await Promise.all(
      query.results
        .filter(p => p.object === 'page' && p.parent?.type !== 'database_id')
        .map(async p => ({
          id: p.id,
          title: await pageUtils.extractPageTitle(p) || `Untitled (${p.id.slice(0, 8)})`,
          parent: p.parent?.page_id || null,
          type: 'page',
          url: p.url || null
        }))
    )

    res.json({ success: true, count: basePages.length, pages: basePages })
  } catch (err) {
    next(err)
  }
})

module.exports = router

const notionApi = require('./notion-api')
const { BLOCK_TYPES } = require('./block-types')

/**
 * Extract title from page properties
 * @param {Object} properties - Page properties
 * @returns {string|null} - The extracted title or null
 */
const extractTitle = (properties) => {
  // Try to find a property with type 'title'
  const titleProp = Object.values(properties).find(p => p.type === 'title')
  if (titleProp?.title?.length) {
    return titleProp.title.map(t => t.plain_text || t.text?.content || '').join('')
  }

  // If no title type found, try looking for properties with common title names
  const commonTitleProps = ['Name', 'Title', 'Feature', 'Topic', 'Subject']
  for (const propName of commonTitleProps) {
    const prop = properties[propName]
    if (prop?.type === 'rich_text' && prop.rich_text.length) {
      return prop.rich_text.map(t => t.plain_text || t.text?.content || '').join('')
    }
  }

  return null
}

/**
 * Normalize a key string (trim, decode, lowercase)
 * @param {string} key - The key to normalize
 * @returns {string} - Normalized key
 */
const normalizeKey = (key) => {
  try {
    return decodeURIComponent(key.trim().toLowerCase())
  } catch (err) {
    // If decoding fails, just trim and lowercase
    return key.trim().toLowerCase()
  }
}

/**
 * Extract title from a page's blocks
 * @param {string} pageId - The page ID
 * @returns {Promise<string>} - The extracted title
 */
const extractTitleFromBlocks = async (pageId) => {
  try {
    const page = await notionApi.retrievePage(pageId)
    const blocks = await notionApi.getBlockChildren(pageId)

    // Try to find a heading block first
    const heading = blocks.results.find(b => b.type.startsWith('heading_'))
    if (heading) {
      const headingText = heading[heading.type].rich_text
        .map(rt => rt.plain_text || rt.text?.content || '')
        .join('')
        .trim()

      if (headingText) return headingText
    }

    // Try the first paragraph
    const para = blocks.results.find(b => b.type === 'paragraph')
    if (para) {
      const paraText = para.paragraph.rich_text
        .map(rt => rt.plain_text || rt.text?.content || '')
        .join('')
        .trim()

      if (paraText) return paraText
    }

    // Fall back to page property title or ID
    const title = extractTitle(page.properties)
    return title || `Untitled (${pageId.slice(0, 8)})`
  } catch (err) {
    console.error(`Failed to extract title from blocks: ${err.message}`)
    return `Untitled (${pageId.slice(0, 8)})`
  }
}

/**
 * Extract title from a page object using multiple strategies
 * @param {Object} page - The page object
 * @returns {Promise<string>} - The extracted title
 */
const extractPageTitle = async (page) => {
  // Try properties first
  const properties = page.properties || {}
  const propKeys = ['title', 'Name', 'Title', 'Feature', 'Subject', 'Topic']

  for (const key of propKeys) {
    const val = properties[key]

    if (val?.type === 'title' && val.title?.length) {
      return val.title.map(t => t.plain_text || t.text?.content || '').join('')
    }

    if (val?.type === 'rich_text' && val.rich_text?.length) {
      return val.rich_text.map(t => t.plain_text || t.text?.content || '').join('')
    }
  }

  // Try page title field (different format)
  if (page.title?.length) {
    return page.title.map(t => t.plain_text || t.text?.content || '').join('')
  }

  // Try child_page type
  if (page.child_page?.title) {
    return page.child_page.title
  }

  // Try to extract from blocks as last resort
  return extractTitleFromBlocks(page.id)
}

/**
 * Find a page by title in a database
 * @param {string} databaseId - The database ID
 * @param {string} title - The title to search for
 * @returns {Promise<Object|null>} - The found page or null
 */
const findPageByTitle = async (databaseId, title) => {
  const normalizedTitle = normalizeKey(title)

  // Try exact match first
  const exactMatchResults = await notionApi.queryDatabase(databaseId, {
    filter: {
      property: 'Name',
      title: { equals: normalizedTitle }
    }
  })

  if (exactMatchResults.results?.length > 0) {
    return exactMatchResults.results[0]
  }

  // Try contains match if exact match fails
  const containsMatchResults = await notionApi.queryDatabase(databaseId, {
    filter: {
      property: 'Name',
      title: { contains: normalizedTitle }
    }
  })

  if (containsMatchResults.results?.length > 0) {
    return containsMatchResults.results[0]
  }

  // Try searching across all properties as last resort
  const { results } = await notionApi.search(normalizedTitle)

  if (results?.length > 0) {
    // Filter to pages in the target database
    const matchingPage = results.find(p => 
      p.parent?.database_id === databaseId && 
      p.object === 'page'
    )

    return matchingPage || null
  }

  return null
}

/**
 * Generate a unique title in a database
 * @param {string} databaseId - The database ID
 * @param {string} baseTitle - The base title
 * @returns {Promise<string>} - A unique title
 */
const generateUniqueTitle = async (databaseId, baseTitle) => {
  let title = baseTitle
  let i = 0

  while (await findPageByTitle(databaseId, title)) {
    i++
    title = `${baseTitle} ${i}`
  }

  return title
}

/**
 * Find a page by ID or title
 * @param {string} databaseId - The database ID
 * @param {string} idOrTitle - The ID or title to find
 * @returns {Promise<Object|null>} - The found page or null
 */
const findPage = async (databaseId, idOrTitle) => {
  // Check if it's an ID (36 chars with hyphens) or UUID format
  const isId = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(idOrTitle)

  if (isId) {
    try {
      return await notionApi.retrievePage(idOrTitle)
    } catch (err) {
      console.error(`Error retrieving page by ID: ${err.message}`)
      // If page not found by ID, try finding by title as fallback
      return await findPageByTitle(databaseId, idOrTitle)
    }
  }

  // Find by title
  return await findPageByTitle(databaseId, idOrTitle)
}

/**
 * Convert text to Notion blocks based on content
 * @param {string} text - The text to convert
 * @returns {Array} - Array of Notion blocks
 */
const convertTextToBlocks = (text) => {
  const lines = text.split('\n')
  const blocks = []
  let codeBlock = null

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]

    // Handle code blocks
    if (line.startsWith('```')) {
      if (codeBlock) {
        // End code block
        blocks.push(codeBlock)
        codeBlock = null
      } else {
        // Start code block
        const language = line.slice(3).trim() || 'javascript'
        codeBlock = BLOCK_TYPES.code('', language)
      }
      continue
    }

    // Add content to existing code block
    if (codeBlock) {
      const currentContent = codeBlock.code.rich_text[0].text.content
      codeBlock.code.rich_text[0].text.content = currentContent
        ? currentContent + '\n' + line
        : line
      continue
    }

    // Handle regular blocks
    if (line.startsWith('# ')) {
      blocks.push(BLOCK_TYPES.heading_1(line.slice(2)))
    } else if (line.startsWith('## ')) {
      blocks.push(BLOCK_TYPES.heading_2(line.slice(3)))
    } else if (line.startsWith('### ')) {
      blocks.push(BLOCK_TYPES.heading_3(line.slice(4)))
    } else if (line.match(/^-\s+\[ \]\s+/)) {
      blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[ \]\s+/, ''), false))
    } else if (line.match(/^-\s+\[x\]\s+/i)) {
      blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[x\]\s+/i, ''), true))
    } else if (line.match(/^-\s+/)) {
      blocks.push(BLOCK_TYPES.bulleted_list_item(line.replace(/^-\s+/, '')))
    } else if (line.match(/^\d+\.\s+/)) {
      blocks.push(BLOCK_TYPES.numbered_list_item(line.replace(/^\d+\.\s+/, '')))
    } else if (line.match(/^>\s+/)) {
      blocks.push(BLOCK_TYPES.quote(line.replace(/^>\s+/, '')))
    } else if (line.match(/^---+$/)) {
      blocks.push(BLOCK_TYPES.divider())
    } else if (line.trim() === '') {
      // Only add empty paragraphs if they're between content (not at start/end)
      if (i > 0 && i < lines.length - 1) {
        blocks.push(BLOCK_TYPES.paragraph(''))
      }
    } else {
      blocks.push(BLOCK_TYPES.paragraph(line))
    }
  }

  // If we ended while still in a code block, add it
  if (codeBlock) {
    blocks.push(codeBlock)
  }

  return blocks
}

/**
 * Create a versioned page based on a base title
 * @param {string} baseTitle - The base title for versioning
 * @param {string} content - The page content
 * @param {string} parentId - The parent page ID
 * @returns {Promise<Object>} - The created page
 */
const createVersionedPage = async (baseTitle, content, parentId) => {
  const query = await notionApi.search(baseTitle)
  const pages = query.results || []

  // Extract version numbers from existing pages with the same base title
  const versionRegex = new RegExp(`^${baseTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s+(\\d+)$`)
  const versions = pages.map(p => {
    const pageTitle = extractTitle(p.properties) || ''
    const match = pageTitle.match(versionRegex)
    return match ? parseInt(match[1], 10) : 0
  }).filter(v => v > 0)

  // Determine next version number
  const nextVersion = versions.length > 0 ? Math.max(...versions) + 1 : 1
  const newTitle = `${baseTitle} ${nextVersion.toString().padStart(2, '0')}`

  // Convert content to blocks
  const blocks = convertTextToBlocks(content)

  // Create the page
  return notionApi.createPage({
    parent: { type: 'page_id', page_id: parentId },
    properties: {
      title: [{ type: 'text', text: { content: newTitle } }]
    },
    children: [
      BLOCK_TYPES.heading_1(newTitle),
      ...blocks
    ]
  })
}

module.exports = {
  extractTitle,
  extractPageTitle,
  extractTitleFromBlocks,
  findPageByTitle,
  generateUniqueTitle,
  findPage,
  normalizeKey,
  createVersionedPage,
  convertTextToBlocks
}

// schema-detection.js
const notionApi = require('./notion-api');

/**
 * Cache for database schemas to avoid repeated API calls
 * Format: { database_id: { schema, timestamp } }
 */
const schemaCache = {};

/**
 * Get the schema of a Notion database
 * @param {string} databaseId - The ID of the database
 * @param {boolean} forceRefresh - Whether to force a refresh of the schema cache
 * @returns {Promise<Object>} - The database schema
 */
const getDatabaseSchema = async (databaseId, forceRefresh = false) => {
  // Return cached schema if available and less than 5 minutes old
  const now = Date.now();
  const cachedSchema = schemaCache[databaseId];

  if (!forceRefresh && cachedSchema && (now - cachedSchema.timestamp < 5 * 60 * 1000)) {
    return cachedSchema.schema;
  }

  try {
    const database = await notionApi.retrieveDatabase(databaseId);
    const schema = database.properties || {};

    // Cache the schema
    schemaCache[databaseId] = {
      schema,
      timestamp: now
    };

    return schema;
  } catch (error) {
    console.error(`Error getting database schema: ${error.message}`);
    throw error;
  }
};

/**
 * Find the title property in a database schema
 * @param {Object} schema - The database schema
 * @returns {string|null} - The name of the title property
 */
const findTitleProperty = (schema) => {
  for (const [propName, propData] of Object.entries(schema)) {
    if (propData.type === 'title') {
      return propName;
    }
  }
  return null;
};

/**
 * Find a property of a specific type in a database schema
 * @param {Object} schema - The database schema
 * @param {string} type - The property type to find
 * @returns {string|null} - The name of the first property of the specified type
 */
const findPropertyByType = (schema, type) => {
  for (const [propName, propData] of Object.entries(schema)) {
    if (propData.type === type) {
      return propName;
    }
  }
  return null;
};

/**
 * Map standard property names to database-specific property names
 * @param {string} databaseId - The ID of the database
 * @param {Object} properties - The properties to map
 * @returns {Promise<Object>} - The mapped properties
 */
const mapPropertiesToSchema = async (databaseId, properties) => {
  try {
    const schema = await getDatabaseSchema(databaseId);
    const titleProp = findTitleProperty(schema);

    if (!titleProp) {
      throw new Error(`No title property found in database ${databaseId}`);
    }

    // Start with the mapped properties
    const mappedProps = {};

    // If there's a "title" or "name" property in the input, map it to the title property
    if (properties.title !== undefined) {
      const value = properties.title;
      mappedProps[titleProp] = { 
        title: [{ text: { content: String(value) } }] 
      };
      delete properties.title;
    } else if (properties.name !== undefined) {
      const value = properties.name;
      mappedProps[titleProp] = { 
        title: [{ text: { content: String(value) } }] 
      };
      delete properties.name;
    } else if (properties.Name !== undefined) {
      const value = properties.Name;
      mappedProps[titleProp] = { 
        title: [{ text: { content: String(value) } }] 
      };
      delete properties.Name;
    }

    // Map remaining properties based on the schema
    for (const [propName, propValue] of Object.entries(properties)) {
      // Skip if the property doesn't exist in the schema
      if (!schema[propName]) {
        console.warn(`Property "${propName}" does not exist in database schema`);
        continue;
      }

      // Format the property value based on its type
      const propType = schema[propName].type;

      switch (propType) {
        case 'rich_text':
          mappedProps[propName] = { 
            rich_text: [{ text: { content: String(propValue) } }] 
          };
          break;
        case 'number':
          mappedProps[propName] = { number: Number(propValue) };
          break;
        case 'select':
          mappedProps[propName] = { select: { name: String(propValue) } };
          break;
        case 'multi_select':
          // Handle both array and string values
          const values = Array.isArray(propValue) ? propValue : [propValue];
          mappedProps[propName] = { 
            multi_select: values.map(v => ({ name: String(v) }))
          };
          break;
        case 'date':
          // Handle both Date objects and strings
          let dateValue = propValue;
          if (propValue instanceof Date) {
            dateValue = propValue.toISOString();
          }
          mappedProps[propName] = { date: { start: dateValue } };
          break;
        case 'checkbox':
          mappedProps[propName] = { checkbox: Boolean(propValue) };
          break;
        case 'url':
          mappedProps[propName] = { url: String(propValue) };
          break;
        case 'email':
          mappedProps[propName] = { email: String(propValue) };
          break;
        case 'phone_number':
          mappedProps[propName] = { phone_number: String(propValue) };
          break;
        default:
          // For other types, use the raw value (this might fail for some types)
          mappedProps[propName] = propValue;
      }
    }

    return mappedProps;
  } catch (error) {
    console.error(`Error mapping properties to schema: ${error.message}`);
    throw error;
  }
};

/**
 * Build a Notion filter for searching by a title-like value
 * @param {string} databaseId - The ID of the database
 * @param {string} searchValue - The value to search for
 * @returns {Promise<Object>} - A Notion filter object
 */
const buildTitleFilter = async (databaseId, searchValue) => {
  try {
    const schema = await getDatabaseSchema(databaseId);
    const titleProp = findTitleProperty(schema);

    if (!titleProp) {
      throw new Error(`No title property found in database ${databaseId}`);
    }

    return {
      property: titleProp,
      title: { equals: searchValue }
    };
  } catch (error) {
    console.error(`Error building title filter: ${error.message}`);
    throw error;
  }
};

module.exports = {
  getDatabaseSchema,
  findTitleProperty,
  findPropertyByType,
  mapPropertiesToSchema,
  buildTitleFilter
};

