    "/notion/databases/createentry": {
      "put": {
        "summary": "Create database entry",
        "description": "Creates a new entry in the PROJECT_TRACKER database. Properties will be mapped to the database schema automatically.",
        "operationId": "createEntry",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "title": { 
                    "type": "string",
                    "description": "The title for the entry"
                  },
                  "properties": { 
                    "type": "object",
                    "description": "Additional properties for the entry"
                  },
                  "line": { 
                    "type": "string",
                    "description": "A key-value list in the format 'Feature: Name, Status: Value, Priority: Level'. Can be comma-separated or newline-separated."
                  }
                },
                "oneOf": [
                  {
                    "required": ["title"]
                  },
                  {
                    "required": ["line"]
                  }
                ]
              },
              "example": {
                "line": "Feature: Quick Export Button, Status: Not started, Priority: Medium, Last Updated: 2025-04-25"
              }
            }
          }
        },
        "responses": { 
          "200": { 
            "description": "Entry created successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": { "type": "boolean" },
                    "created": { "type": "boolean" },
                    "id": { "type": "string" },
                    "title": { "type": "string" }
                  }
                }
              }
            }
          },
          "400": { "description": "Invalid request parameters" },
          "500": { "description": "Server error" }
        }
      }
    },
    "/notion/databases/updateentry": {
      "patch": {
        "summary": "Update database entry",
        "description": "Updates an entry in the PROJECT_TRACKER database. There are three ways to use this endpoint: 1) Update a specific field of an identified entry, 2) Update multiple properties at once, or 3) Find an entry by title and update a text field.",
        "operationId": "updateEntry",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "idOrTitle": { 
                    "type": "string",
                    "description": "The ID or title of the entry to update"
                  },
                  "key": { 
                    "type": "string",
                    "description": "The name of the field to update (e.g., 'Status', 'Priority')"
                  },
                  "value": { 
                    "type": "string",
                    "description": "The new value for the specified field"
                  },
                  "properties": { 
                    "type": "object",
                    "description": "Multiple properties to update at once"
                  },
                  "createIfMissing": {
                    "type": "boolean",
                    "description": "Whether to create the entry if it doesn't exist"
                  }
                },
                "oneOf": [
                  {
                    "required": ["idOrTitle", "key", "value"]
                  },
                  {
                    "required": ["idOrTitle", "properties"]
                  },
                  {
                    "required": ["key", "value"]
                  }
                ]
              },
              "examples": {
                "update-field": {
                  "summary": "Update a specific field",
                  "value": {
                    "idOrTitle": "Implement Authentication Module",
                    "key": "Status",
                    "value": "In Progress"
                  }
                },
                "update-properties": {
                  "summary": "Update multiple properties",
                  "value": {
                    "idOrTitle": "Implement Authentication Module",
                    "properties": {
                      "Status": "In Progress",
                      "Priority": "High" 
                    }
                  }
                },
                "legacy-update": {
                  "summary": "Legacy update by title",
                  "value": {
                    "key": "Quick Export Button",
                    "value": "This is a note about the export button",
                    "createIfMissing": true
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": { 
            "description": "Entry updated successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": { "type": "boolean" },
                    "updated": { "type": "boolean" },
                    "id": { "type": "string" },
                    "field": { "type": "string" },
                    "value": { "type": "string" },
                    "properties": { "type": "object" }
                  }
                }
              }
            }
          },
          "400": { "description": "Invalid request parameters" },
          "404": { "description": "Entry not found" },
          "500": { "description": "Server error" }
        }
      }
    },
    "/notion/databases/deleteentry": {
