    },
    "/health/statusComplete": {
      "get": {
        "summary": "Complete System Health Check",
        "description": "Comprehensive health check of the server, Notion API, and GitHub API",
        "operationId": "getCompleteHealth",
        "responses": {
          "200": {
            "description": "All systems are healthy"
          },
          "207": {
            "description": "Some systems are degraded but functional"
          },
          "500": {
            "description": "Critical system failure"
          }
        }
      }
    }  
  }
}

