// notion-route-factory.js
const express = require('express');
const notionApi = require('./notion-api');
const pageUtils = require('./page-utils');
const schemaDetection = require('./schema-detection');

/**
 * Create a configurable router for Notion database operations
 * @param {Object} config - Configuration for the router
 * @param {string} config.databaseId - Environment variable name containing the database ID
 * @param {string} config.databaseName - Optional database name to find in Notion (used if databaseId not provided)
 * @param {string} config.prefix - Prefix for route names (e.g., '' or 'memory')
 * @param {Object} config.routeNames - Custom route names mapping
 * @returns {express.Router} - Configured Express router
 */
const createNotionRouter = (config) => {
  const router = express.Router();

  // Get database ID from environment variable or find by name
  const getDatabaseId = async (req) => {
    // First check if database ID is provided in the request
    const reqDatabaseId = req.query.database_id || req.body.database_id;
    if (reqDatabaseId) return reqDatabaseId;

    // Then check if database name is provided in the request
    const reqDatabaseName = req.query.database || req.body.database;
    if (reqDatabaseName) {
      // Search for database by name
      const { results } = await notionApi.search(reqDatabaseName);
      const database = results.find(r => 
        r.object === 'database' && 
        r.title && 
        r.title.some(t => t.plain_text.toLowerCase() === reqDatabaseName.toLowerCase())
      );
      if (database) return database.id;
    }

    // If config has a databaseId environment variable, use that
    if (config.databaseId && process.env[config.databaseId]) {
      return process.env[config.databaseId];
    }

    // If config has a databaseName, search for it
    if (config.databaseName) {
      const { results } = await notionApi.search(config.databaseName);
      const database = results.find(r => 
        r.object === 'database' && 
        r.title && 
        r.title.some(t => t.plain_text.toLowerCase() === config.databaseName.toLowerCase())
      );
      if (database) return database.id;
    }

    return null;
  };

  // Default route names
  const defaultRouteNames = {
    create: 'createentry',
    update: 'updateentry',
    delete: 'deleteentry',
    list: 'listentries',
    read: 'readentry'
  };

  // Custom route names based on prefix
  let routeNames = {};
  if (config.prefix) {
    for (const [key, value] of Object.entries(defaultRouteNames)) {
      routeNames[key] = `${key}${config.prefix}`;
    }
  } else {
    routeNames = { ...defaultRouteNames };
  }

  // Override with any custom route names provided
  if (config.routeNames) {
    routeNames = { ...routeNames, ...config.routeNames };
  }

  /**
   * Extract property value based on its Notion type
   * @param {Object} property - The Notion property object
   * @returns {any} - The extracted value
   */
  const extractPropertyValue = (property) => {
    if (!property) return null;

    switch (property.type) {
      case 'title':
        return property.title?.length ? property.title.map(t => t.plain_text || '').join('') : null;
      case 'rich_text':
        return property.rich_text?.length ? property.rich_text.map(t => t.plain_text || '').join('') : null;
      case 'number':
        return property.number;
      case 'select':
        return property.select?.name || null;
      case 'multi_select':
        return property.multi_select?.length ? property.multi_select.map(s => s.name) : [];
      case 'date':
        return property.date?.start || null;
      case 'checkbox':
        return property.checkbox;
      case 'url':
        return property.url;
      case 'email':
        return property.email;
      case 'phone_number':
        return property.phone_number;
      default:
        return null;
    }
  };

  // CREATE route
  router.put(`/${routeNames.create}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Ensure database exists
      try {
        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        if (!schema) {
          return res.status(404).json({ 
            error: `Database not found`,
            message: `Check the database ID: ${databaseId}`
          });
        }
      } catch (err) {
        return res.status(500).json({ 
          error: `Error accessing database`,
          message: err.message
        });
      }

      // Rest of your existing create entry code...
      // (Using the databaseId variable for any database operations)

      let properties = {};

      if (req.body.line) {
        // Your existing code for handling line input
        // ...
      } else {
        // Your existing code for handling title and properties input
        // ...
      }

      // Create the page
      const page = await notionApi.createPage({
        parent: { database_id: databaseId },
        properties
      });

      // Extract the title for response
      const title = await pageUtils.extractPageTitle(page);

      return res.json({
        success: true,
        created: true,
        database_id: databaseId,
        id: page.id,
        title,
        message: "Entry created successfully"
      });
    } catch (err) {
      console.error(`Error in ${routeNames.create}:`, err);
      next(err);
    }
  });

  // UPDATE route
  router.patch(`/${routeNames.update}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Your existing update entry code using databaseId
      // ...
    } catch (err) {
      console.error(`Error in ${routeNames.update}:`, err);
      next(err);
    }
  });

  // DELETE route
  router.delete(`/${routeNames.delete}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Your existing delete entry code using databaseId
      // ...
    } catch (err) {
      console.error(`Error in ${routeNames.delete}:`, err);
      next(err);
    }
  });

  // LIST route
  router.get(`/${routeNames.list}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      try {
        const { results } = await notionApi.queryDatabase(databaseId);

        // Format the results
        const entries = await Promise.all(results.map(async (page) => {
          const title = await pageUtils.extractPageTitle(page);

          return {
            id: page.id,
            title,
            url: page.url,
            created_time: page.created_time,
            last_edited_time: page.last_edited_time
          };
        }));

        return res.json({
          database_id: databaseId,
          entries
        });
      } catch (err) {
        console.error(`Error listing entries:`, err);
        return res.status(500).json({ 
          error: 'Failed to list entries',
          message: err.message
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.list}:`, err);
      next(err);
    }
  });

  // READ route
  router.get(`/${routeNames.read}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Your existing read entry code using databaseId
      // ...
    } catch (err) {
      console.error(`Error in ${routeNames.read}:`, err);
      next(err);
    }
  });

  return router;
};

module.exports = createNotionRouter;

