          "500": { "description": "Server error" }
        }
      }
    },
    "/notion/pages/readpage": {
      "get": {
        "summary": "Read standalone page",
        "description": "Reads a standalone page by ID or title, with various output formats.",
        "operationId": "readPage",
        "parameters": [
          { 
            "name": "idOrTitle", 
            "in": "query", 
            "required": true, 
            "schema": { "type": "string" } 
          },
          { 
            "name": "format", 
            "in": "query", 
            "schema": { 
              "type": "string", 
              "enum": ["blocks", "markdown", "text", "html", "pdf"], 
              "default": "blocks" 
            } 
          }
        ],
        "responses": {
          "200": { "description": "Page content retrieved successfully" },
          "400": { "description": "Invalid request parameters" },
          "404": { "description": "Page not found" },
          "500": { "description": "Server error" }
        }
      }
    },
    "/health/status": {
      "get": {
        "summary": "Server Health Check",
        "description": "Returns the health status of the server including memory usage, CPU load, and system metrics",
        "operationId": "getServerHealth",
        "responses": {
          "200": {
            "description": "Server health information"
          },
          "500": {
            "description": "Internal server error"
          }
        }
      }
    },
    "/health/statusNotion": {
      "get": {
        "summary": "Notion API Health Check",
        "description": "Checks connectivity to the Notion API and verifies access to configured resources",
        "operationId": "getNotionHealth",
        "responses": {
          "200": {
            "description": "Notion API is healthy and accessible"
          },
          "500": {
            "description": "Notion API is not accessible"
          },
          "503": {
            "description": "Notion API is not configured"
          }
        }
      }
    },
    "/health/statusGithub": {
      "get": {
        "summary": "GitHub API Health Check",
        "description": "Checks connectivity to the GitHub API and verifies token access",
        "operationId": "getGithubHealth",
        "responses": {
          "200": {
            "description": "GitHub API is healthy and accessible"
          },
          "500": {
            "description": "GitHub API is not accessible"
          },
          "503": {
            "description": "GitHub API is not configured"
          }
        }
      }
    },
    "/health/statusComplete": {
      "get": {
        "summary": "Complete System Health Check",
        "description": "Comprehensive health check of the server, Notion API, and GitHub API",
        "operationId": "getCompleteHealth",
        "responses": {
          "200": {
            "description": "All systems are healthy"
          },
          "207": {
            "description": "Some systems are degraded but functional"
          },
          "500": {
            "description": "Critical system failure"
          }
        }
      }
    }  
  }
}

