const express = require('express');
const router = express.Router();
const { Client } = require('@notionhq/client');
const { normalizeDbName, getDatabaseId, getAvailableDatabases } = require('./database-utils');

// Initialize Notion client
const notion = new Client({
  auth: process.env.NOTION_API_KEY,
});

// Middleware to check for database name
async function checkDatabaseName(req, res, next) {
  const dbName = req.body.database || req.query.database;

  if (!dbName) {
    try {
      const databases = await getAvailableDatabases(notion);
      return res.status(400).json({
        error: 'Database name is required',
        available_databases: databases
      });
    } catch (error) {
      return res.status(500).json({ error: 'Failed to fetch available databases' });
    }
  }

  const normalizedName = normalizeDbName(dbName);

  try {
    const databaseId = await getDatabaseId(notion, normalizedName);
    if (!databaseId) {
      const databases = await getAvailableDatabases(notion);
      return res.status(404).json({
        error: `Database '${dbName}' not found`,
        available_databases: databases
      });
    }

    // Attach database ID to request for use in route handlers
    req.databaseId = databaseId;
    next();
  } catch (error) {
    res.status(500).json({ error: 'Database lookup failed' });
  }
}

// Create entry
router.post('/createentry', checkDatabaseName, async (req, res) => {
  try {
    const { properties } = req.body;

    if (!properties) {
      return res.status(400).json({ error: 'Properties are required' });
    }

    const response = await notion.pages.create({
      parent: { database_id: req.databaseId },
      properties
    });

    res.status(201).json(response);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create entry' });
  }
});

// List entries
router.get('/listentries', checkDatabaseName, async (req, res) => {
  try {
    const response = await notion.databases.query({
      database_id: req.databaseId,
      filter: req.body.filter || undefined,
      sorts: req.body.sorts || undefined
    });

    res.json(response);
  } catch (error) {
    res.status(500).json({ error: 'Failed to list entries' });
  }
});

// Read entry
router.get('/readentry', checkDatabaseName, async (req, res) => {
  try {
    const { entryId } = req.query;

    if (!entryId) {
      return res.status(400).json({ error: 'Entry ID is required' });
    }

    const response = await notion.pages.retrieve({
      page_id: entryId
    });

    res.json(response);
  } catch (error) {
    res.status(500).json({ error: 'Failed to read entry' });
  }
});

// Update entry
router.put('/updateentry', checkDatabaseName, async (req, res) => {
  try {
    const { entryId, properties } = req.body;

    if (!entryId) {
      return res.status(400).json({ error: 'Entry ID is required' });
    }

    if (!properties) {
      return res.status(400).json({ error: 'Properties are required' });
    }

    const response = await notion.pages.update({
      page_id: entryId,
      properties
    });

    res.json(response);
  } catch (error) {
    res.status(500).json({ error: 'Failed to update entry' });
  }
});

// Delete entry
router.delete('/deleteentry', checkDatabaseName, async (req, res) => {
  try {
    const { entryId } = req.body;

    if (!entryId) {
      return res.status(400).json({ error: 'Entry ID is required' });
    }

    // Notion doesn't have a true delete, but we can archive
    const response = await notion.pages.update({
      page_id: entryId,
      archived: true
    });

    res.json(response);
  } catch (error) {
    res.status(500).json({ error: 'Failed to delete entry' });
  }
});

module.exports = router;

