const { normalizeDbName, getDatabaseId, getAvailableDatabases } = require('./database-utils');
const notionRouteFactory = require('./notion-route-factory');

// Initialize Notion client
const notion = new Client({
  auth: process.env.NOTION_API_KEY,
});

// Dynamic database ID resolver
async function resolveDatabaseId(req) {
  const dbName = req.body.database || req.query.database;

  if (!dbName) {
    const databases = await getAvailableDatabases(notion);
    throw {
      status: 400,
      message: 'Database name is required',
      available_databases: databases
    };
  }

  const normalizedName = normalizeDbName(dbName);
  const databaseId = await getDatabaseId(notion, normalizedName);

  if (!databaseId) {
    const databases = await getAvailableDatabases(notion);
    throw {
      status: 404,
      message: `Database '${dbName}' not found`,
      available_databases: databases
    };
  }

  return databaseId;
}

// Create database routes using notion-route-factory
const databaseRoutes = {
  createEntry: notionRouteFactory.createPageInDb({
    route: '/createentry',
    getDatabaseId: resolveDatabaseId
  }),

  listEntries: notionRouteFactory.queryDb({
    route: '/listentries',
    getDatabaseId: resolveDatabaseId
  }),

  readEntry: notionRouteFactory.retrievePage({
    route: '/readentry',
