  }),

  updateEntry: notionRouteFactory.updatePage({
    route: '/updateentry',
    getPageId: req => req.body.entryId
  }),

  deleteEntry: notionRouteFactory.archivePage({
    route: '/deleteentry',
    getPageId: req => req.body.entryId
  })
};

