const express = require('express');
const axios = require('axios');
const { normalizeDbName, getDatabaseId, getAvailableDatabases } = require('./database-utils');

const createNotionRouter = (config) => {
  const router = express.Router();

  // Handle database ID resolution
  const getDbId = (req) => {
    // Check if a database name is provided in the request
    const dbName = req.body.database || req.query.database;

    if (dbName) {
      // Normalize and get ID for the specified database
      const normalizedName = normalizeDbName(dbName);
      const dbId = getDatabaseId(normalizedName);

      if (!dbId) {
        // Database not found, provide available options
        const availableDatabases = getAvailableDatabases();
        throw {
          status: 404,
          error: `Database '${dbName}' not found. Available databases: ${availableDatabases.join(', ')}`
        };
      }

      return dbId;
    } else {
      // Use the configured database ID (for memory routes)
      return process.env[config.databaseId];
    }
  };

  // Create page in database
  router.post(config.routes.create, async (req, res) => {
    try {
      const dbId = getDbId(req);

      if (!dbId) {
        const availableDatabases = getAvailableDatabases();
        return res.status(400).json({
          error: 'Database not specified or configured. Available databases: ' + availableDatabases.join(', ')
        });
      }

      const response = await axios.post(
        'https://api.notion.com/v1/pages',
        {
          parent: { database_id: dbId },
          properties: req.body.properties || {}
        },
        {
          headers: {
            'Authorization': `Bearer ${process.env.NOTION_KEY}`,
            'Notion-Version': '2022-06-28',
            'Content-Type': 'application/json'
          }
        }
      );

      res.status(201).json(response.data);
    } catch (error) {
      if (error.status) {
        return res.status(error.status).json({ error: error.error });
      }

      console.error('Error creating page:', error);
      res.status(500).json({ error: 'Failed to create page' });
    }
  });

  // Query database
  router.post(config.routes.list, async (req, res) => {
    try {
      const dbId = getDbId(req);

      if (!dbId) {
        const availableDatabases = getAvailableDatabases();
        return res.status(400).json({
          error: 'Database not specified or configured. Available databases: ' + availableDatabases.join(', ')
        });
      }

      const response = await axios.post(
        `https://api.notion.com/v1/databases/${dbId}/query`,
        {
          filter: req.body.filter || undefined,
          sorts: req.body.sorts || undefined
        },
        {
          headers: {
            'Authorization': `Bearer ${process.env.NOTION_KEY}`,
            'Notion-Version': '2022-06-28',
            'Content-Type': 'application/json'
          }
        }
      );

      res.json(response.data);
    } catch (error) {
      if (error.status) {
        return res.status(error.status).json({ error: error.error });
      }

      console.error('Error querying database:', error);
      res.status(500).json({ error: 'Failed to query database' });
    }
  });

  // Retrieve page
  router.get(config.routes.read, async (req, res) => {
    try {
      const pageId = req.query.pageId || req.body.pageId;

      if (!pageId) {
        return res.status(400).json({ error: 'Page ID is required' });
      }

      const response = await axios.get(
        `https://api.notion.com/v1/pages/${pageId}`,
        {
          headers: {
            'Authorization': `Bearer ${process.env.NOTION_KEY}`,
            'Notion-Version': '2022-06-28'
          }
        }
      );

      res.json(response.data);
    } catch (error) {
      console.error('Error retrieving page:', error);
      res.status(500).json({ error: 'Failed to retrieve page' });
    }
  });

  // Update page
  router.put(config.routes.update, async (req, res) => {
    try {
      const { pageId, properties } = req.body;

      if (!pageId) {
        return res.status(400).json({ error: 'Page ID is required' });
      }

      const response = await axios.patch(
        `https://api.notion.com/v1/pages/${pageId}`,
        {
          properties: properties || {}
        },
        {
          headers: {
            'Authorization': `Bearer ${process.env.NOTION_KEY}`,
            'Notion-Version': '2022-06-28',
            'Content-Type': 'application/json'
          }
        }
      );

      res.json(response.data);
    } catch (error) {
      console.error('Error updating page:', error);
      res.status(500).json({ error: 'Failed to update page' });
    }
  });

  // Delete (archive) page
  router.delete(config.routes.delete, async (req, res) => {
    try {
      const { pageId } = req.body;

      if (!pageId) {
        return res.status(400).json({ error: 'Page ID is required' });
      }

      const response = await axios.patch(
