  category?: string;
  importance?: number;
  metadata?: Record<string, any>;
}

export interface ChromaDocument {
  id: string;
  document: string;
  metadata?: Record<string, any>;
}

export interface ChromaQueryResult {
  ids: string[][];
  documents: string[][];
  metadatas: Record<string, any>[][];
  distances: number[][];
}

