// src/test/mocks/chroma-service.mock.ts
import { MemoryItem } from '@/types/memory';
import { mockChromaClient } from './chroma-client.mock';

// Constants for collection names
export const MEMORY_COLLECTION = 'memory_collection';

// Create a function to add memory items to ChromaDB
export async function addMemoryToDB(
  memory: MemoryItem | MemoryItem[],
  collectionName: string = MEMORY_COLLECTION
) {
  try {
    const collection = await mockChromaClient.getOrCreateCollection(collectionName);

    // Convert to array if single item
    const memories = Array.isArray(memory) ? memory : [memory];

    // Prepare data for ChromaDB
    const ids = memories.map(item => item.id);
    const contents = memories.map(item => item.content);
    const embeddings = memories.map(() => Array(384).fill(0)); // Mock embeddings with 384 dimensions
    const metadatas = memories.map(item => ({
      timestamp: item.timestamp,
      category: item.category || null,
      importance: item.importance || 0,
      ...(item.metadata || {}),
    }));

    // Add to ChromaDB
    await collection.add(ids, embeddings, contents, metadatas);

    return { success: true };
  } catch (error) {
    console.error('Error adding memory to ChromaDB:', error);
    return { success: false, error };
  }
}

// Create a function to retrieve memory items from ChromaDB
export async function getMemoryFromDB(
  ids?: string[],
  collectionName: string = MEMORY_COLLECTION
) {
  try {
    const collection = await mockChromaClient.getOrCreateCollection(collectionName);
    const result = await collection.get(ids);

    // Convert ChromaDB results to MemoryItems
    const memoryItems: MemoryItem[] = [];

    for (let i = 0; i < result.ids[0].length; i++) {
      const metadata = result.metadatas[0][i];

      memoryItems.push({
        id: result.ids[0][i],
        content: result.documents[0][i],
        timestamp: metadata.timestamp,
        category: metadata.category || undefined,
        importance: metadata.importance || undefined,
        metadata: { ...metadata },
      });
    }

    return { success: true, data: memoryItems };
  } catch (error) {
    console.error('Error retrieving memory from ChromaDB:', error);
    return { success: false, error };
  }
}
