```typescript
// src/test/helpers/test-utils.ts
import { MemoryItem } from '@/types/memory';
import { mockChromaClient } from '../mocks/chroma-client.mock';
import { MEMORY_COLLECTION } from '../mocks/chroma-service.mock';

// Reset the mock ChromaDB client before each test
export async function resetChromaClient() {
  await mockChromaClient.reset();
}

// Generate a random memory item for testing
export function generateMemoryItem(override: Partial<MemoryItem> = {}): MemoryItem {
  const id = override.id || `mem_${Math.random().toString(36).substring(2, 9)}`;

  return {
    id,
    content: override.content || `Test memory content ${id}`,
    timestamp: override.timestamp || new Date().toISOString(),
    category: override.category,
    importance: override.importance,
    metadata: override.metadata,
  };
}

// Generate multiple memory items for testing
export function generateMemoryItems(count: number, baseOverride: Partial<MemoryItem> = {}): MemoryItem[] {
  return Array.from({ length: count }).map((_, index) => {
    const id = `mem_${index}_${Math.random().toString(36).substring(2, 7)}`;

    return generateMemoryItem({
      ...baseOverride,
      id,
      content: baseOverride.content || `Test memory content ${id}`,
    });
  });
}

// Verify if two memory items are equal
export function areMemoryItemsEqual(a: MemoryItem, b: MemoryItem): boolean {
  const basicFieldsEqual = (
    a.id === b.id &&
    a.content === b.content &&
    a.timestamp === b.timestamp &&
    a.category === b.category &&
    a.importance === b.importance
  );

  // Check if metadata objects are equal
  if (a.metadata && b.metadata) {
    const aKeys = Object.keys(a.metadata);
    const bKeys = Object.keys(b.metadata);

    if (aKeys.length !== bKeys.length) return false;

    return aKeys.every(key => 
      a.metadata?.[key] === b.metadata?.[key]
    );
  }

  // If only one has metadata, they're not equal
  if ((a.metadata && !b.metadata) || (!a.metadata && b.metadata)) return false;

  return basicFieldsEqual;
}
