{
  "openapi": "3.1.0",
  "info": {
    "title": "Notion Proxy API",
    "version": "1.0.0",
    "description": "API for interacting with Notion databases and pages through a standardized interface"
  },
  "servers": [
    {
      "url": "https://d0c53e96-6150-4d3d-b538-c5ac77230c6b-00-2kv1xkk27re2v.picard.replit.dev/"
    }
  ],
  "components": {
    "schemas": {
      "ProjectTrackerEntry": {
        "type": "object",
        "properties": {
          "Feature": {
            "type": "string",
            "description": "Name of the feature or task (title field)"
          },
          "Status": {
            "type": "string",
            "enum": ["Complete", "In Progress", "Not started", "Backlog"],
            "description": "Current status of the task"
          },
          "Last Updated": {
            "type": "string",
            "format": "date-time",
            "description": "Date when the task was last updated"
          },
          "Priority": {
            "type": "string",
            "enum": ["Critical", "High", "Medium", "Low"],
            "description": "Priority level of the task"
          }
        },
        "required": ["Feature"]
      },
      "MemoryEntry": {
        "type": "object",
        "properties": {
          "Key": {
            "type": "string",
            "description": "Unique key identifier for the memory item (title field)"
          },
          "Value": {
            "type": "string",
            "description": "Stored value or content"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Tags associated with this memory"
          },
          "LastUpdated": {
            "type": "string",
            "format": "date-time",
            "description": "Date and time when the memory was last updated"
          },
          "Pinned": {
            "type": "boolean",
            "description": "Whether this memory is pinned or not"
          }
        },
        "required": ["Key", "Value"]
      },
      "NotionPage": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "Title of the page"
          },
          "content": {
            "type": "string",
            "description": "Content of the page, can be in markdown format"
          },
          "created_time": {
            "type": "string",
            "format": "date-time",
            "description": "When the page was created"
          },
          "last_edited_time": {
            "type": "string",
            "format": "date-time",
            "description": "When the page was last edited"
          },
          "url": {
            "type": "string",
            "description": "URL to the page in Notion"
          }
        },
        "required": ["title"]
      }
    }
  },
  "paths": {
    "/notion/databases/createentry": {
      "put": {
        "summary": "Create database entry in Project Tracker",
        "description": "Creates a new entry in the Project Tracker database. You can provide either a title+properties combination or a key-value line in the format 'key: value'.",
        "operationId": "createEntry",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "title": { 
                    "type": "string",
                    "description": "The feature name for the Project Tracker"
                  },
                  "properties": { 
                    "type": "object",
                    "properties": {
                      "Status": {
                        "type": "string",
                        "enum": ["Complete", "In Progress", "Not started", "Backlog"]
                      },
