  template: (text) => ({ type: 'template', template: { rich_text: [{ type: 'text', text: { content: text } }] } }),
  link_to_page: (type, id) => ({
    type: 'link_to_page',
    link_to_page: { type, [type === 'page_id' ? 'page_id' : 'database_id']: id }
  })
