module.exports = { BLOCK_TYPES }

const { BLOCK_TYPES } = require('./block-types')

const mdToBlocks = (markdown) => {
  const lines = markdown.split('\n')
  const blocks = []
  let inCode = false
  let codeLang = 'text'
  let codeBuffer = []

  for (let line of lines) {
    if (/^```/.test(line)) {
      if (!inCode) {
        inCode = true
        codeLang = line.replace(/^```/, '').trim() || 'text'
        codeBuffer = []
      } else {
        inCode = false
        blocks.push(BLOCK_TYPES.code(codeBuffer.join('\n'), codeLang))
      }
      continue
    }
    if (inCode) {
      codeBuffer.push(line)
      continue
    }
    if (/^#\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_1(line.replace(/^#\s+/, '')))
    else if (/^##\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_2(line.replace(/^##\s+/, '')))
    else if (/^###\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_3(line.replace(/^###\s+/, '')))
    else if (/^-\s+\[ \]\s+/.test(line)) blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[ \]\s+/, ''), false))
    else if (/^-\s+\[x\]\s+/.test(line)) blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[x\]\s+/, ''), true))
    else if (/^-\s+/.test(line)) blocks.push(BLOCK_TYPES.bulleted_list_item(line.replace(/^-\s+/, '')))
    else if (/^\d+\.\s+/.test(line)) blocks.push(BLOCK_TYPES.numbered_list_item(line.replace(/^\d+\.\s+/, '')))
    else if (/^>\s+/.test(line)) blocks.push(BLOCK_TYPES.quote(line.replace(/^>\s+/, '')))
    else if (/^---+$/.test(line)) blocks.push(BLOCK_TYPES.divider())
    else blocks.push(BLOCK_TYPES.paragraph(line))
  }

  return blocks
}

const blocksToMd = (blocks) => {
  return blocks.map(block => {
    const rich = block[block.type]?.rich_text
    const content = Array.isArray(rich)
      ? rich.map(r => r.plain_text || r.text?.content).join('')
      : ''

    switch (block.type) {
      case 'heading_1': return `# ${content}`
      case 'heading_2': return `## ${content}`
      case 'heading_3': return `### ${content}`
      case 'bulleted_list_item': return `- ${content}`
      case 'numbered_list_item': return `1. ${content}`
      case 'to_do': return `- [${block.to_do.checked ? 'x' : ' '}] ${content}`
      case 'quote': return `> ${content}`
      case 'code': return `\n\n\`\`\`${block.code.language || 'text'}\n${block.code.rich_text?.map(rt => rt.text?.content).join('') || ''}\n\`\`\``
      case 'divider': return '---'
      case 'toggle': return `<details><summary>${content}</summary></details>`
      case 'callout': return `> 💡 ${content}`
      default: return content
    }
  }).join('\n')
}

const convertTextToBlocks = async (text) => {
  return text.split('\n').map(line => BLOCK_TYPES.paragraph(line))
}

const convertBlocksToText = (blocks) => {
  return blocks.map(block => {
    const rich = block[block.type]?.rich_text
    return Array.isArray(rich)
      ? rich.map(r => r.plain_text || r.text?.content || '').join('')
      : ''
  }).join('\n')
}

const smartTextToBlocks = async (text) => {
  const isMarkdown = /[#>`*-]|\n.*\n/.test(text.trim())
  return isMarkdown ? mdToBlocks(text) : await convertTextToBlocks(text)
}

module.exports = {
  mdToBlocks,
  blocksToMd,
  convertTextToBlocks,
  convertBlocksToText,
  smartTextToBlocks
}

