 */
router.patch('/updatememory', async (req, res, next) => {
  try {
    // Handle key-value update
    if (req.body.key && req.body.value !== undefined) {
      const key = req.body.key.trim();
      const value = req.body.value;

      try {
        // Get database schema
        const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);

        // Find title property
        const titleProperty = Object.entries(schema)
          .find(([_, prop]) => prop.type === 'title');

        if (!titleProperty) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Memory database must have a title property'
          });
        }

        const titlePropertyName = titleProperty[0];

        // Find existing page
        const { results } = await notionApi.queryDatabase(MEMORY_DB_ID, {
          filter: {
            property: titlePropertyName,
            title: { equals: key }
          }
        });

        // Create if not found and createIfMissing is true
        if (results.length === 0) {
          if (req.body.createIfMissing) {
            // Find a rich_text property for the value
            const textProperty = Object.entries(schema)
              .find(([name, prop]) => prop.type === 'rich_text' && name !== titlePropertyName);

            if (!textProperty) {
              return res.status(500).json({ 
                error: 'Invalid database structure', 
                message: 'Memory database must have a rich_text property for values'
              });
            }

            const textPropertyName = textProperty[0];

            // Create the page
            const page = await notionApi.createPage({
              parent: { database_id: MEMORY_DB_ID },
              properties: {
                [titlePropertyName]: { 
                  title: [{ text: { content: key } }] 
                },
                [textPropertyName]: { 
                  rich_text: [{ text: { content: String(value) } }] 
                }
              }
            });

            return res.json({
              success: true,
              created: true,
              id: page.id,
              key,
              value
            });
          } else {
            return res.status(404).json({ 
              error: 'Memory not found',
              message: `No memory found with key: ${key}`
            });
