        }

        const page = results[0];

        // Find a rich_text property for the value
        const textProperty = Object.entries(schema)
          .find(([name, prop]) => prop.type === 'rich_text' && name !== titlePropertyName);

        if (!textProperty) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Memory database must have a rich_text property for values'
          });
        }

        const textPropertyName = textProperty[0];

        // Update the page
        const updated = await notionApi.updatePage(page.id, {
          [textPropertyName]: { 
            rich_text: [{ text: { content: String(value) } }] 
          }
        });

        return res.json({
          success: true,
          updated: true,
          id: updated.id,
          key,
          value
        });
      } catch (err) {
        console.error('Error updating memory with key-value:', err);
        return res.status(500).json({ 
          error: 'Failed to update memory',
          message: err.message
        });
      }
    }

    // Handle update by ID or title with properties
    const { idOrTitle, properties } = req.body;

    if (!idOrTitle) {
      return res.status(400).json({ 
        error: 'Missing identifier', 
        message: 'Either key+value or idOrTitle+properties is required'
      });
    }

    if (!properties || Object.keys(properties).length === 0) {
      return res.status(400).json({ 
        error: 'Missing properties', 
        message: 'Properties object is required'
      });
    }

    try {
      // Find the page
      let page;

      // Try to find as ID first
      if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(idOrTitle)) {
        try {
          page = await notionApi.retrievePage(idOrTitle);
        } catch (err) {
          // Not found by ID, will try by title below
        }
      }

      // If not found by ID, try by title
      if (!page) {
        const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);

        // Find title property
        const titleProperty = Object.entries(schema)
          .find(([_, prop]) => prop.type === 'title');

        if (!titleProperty) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Memory database must have a title property'
          });
        }

        const titlePropertyName = titleProperty[0];

        // Query by title
        const { results } = await notionApi.queryDatabase(MEMORY_DB_ID, {
          filter: {
            property: titlePropertyName,
            title: { equals: idOrTitle }
          }
        });

        if (results.length === 0) {
          return res.status(404).json({ 
            error: 'Memory not found',
            message: `No memory found with title: ${idOrTitle}`
          });
        }

        page = results[0];
      }

      // Map properties to the schema
      const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);
      const mappedProperties = {};

      for (const [propName, propValue] of Object.entries(properties)) {
        // Skip if property doesn't exist in schema
        if (!schema[propName]) {
          console.warn(`Property ${propName} does not exist in memory database schema`);
          continue;
        }

        const propType = schema[propName].type;

        // Format property based on its type
        switch (propType) {
          case 'title':
            mappedProperties[propName] = {
              title: [{ text: { content: String(propValue) } }]
            };
            break;
          case 'rich_text':
            mappedProperties[propName] = {
              rich_text: [{ text: { content: String(propValue) } }]
            };
            break;
          case 'number':
            mappedProperties[propName] = {
              number: Number(propValue)
            };
            break;
          case 'select':
            mappedProperties[propName] = {
              select: { name: String(propValue) }
            };
            break;
          case 'multi_select':
            const values = Array.isArray(propValue) ? propValue : [propValue];
            mappedProperties[propName] = {
              multi_select: values.map(v => ({ name: String(v) }))
            };
            break;
          case 'checkbox':
            mappedProperties[propName] = {
              checkbox: Boolean(propValue)
            };
            break;
          // Add cases for other property types as needed
        }
      }

      // Update the page
      const updated = await notionApi.updatePage(page.id, mappedProperties);

      // Format properties for response
      const formattedProperties = {};

      for (const [propName, propData] of Object.entries(updated.properties)) {
        formattedProperties[propName] = extractPropertyValue(propData);
      }

      return res.json({
        success: true,
        updated: true,
        id: updated.id,
        properties: formattedProperties
      });
    } catch (err) {
      console.error('Error updating memory with properties:', err);
      return res.status(500).json({ 
        error: 'Failed to update memory',
        message: err.message
      });
    }
  } catch (err) {
    console.error('Unexpected error in updatememory:', err);
    next(err);
  }
});

