router.get('/readmemory', async (req, res, next) => {
  try {
    const { key, id, field = 'value' } = req.query;

    if (!key && !id) {
      return res.status(400).json({ 
        error: 'Missing identifier', 
        message: 'Either key or id parameter is required'
      });
    }

    try {
      let page;

      // Find by key
      if (key) {
        const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);

        // Find title property
        const titleProperty = Object.entries(schema)
          .find(([_, prop]) => prop.type === 'title');

        if (!titleProperty) {
          return res.status(500).json({ 
            error: 'Invalid database structure', 
            message: 'Memory database must have a title property'
          });
        }

        const titlePropertyName = titleProperty[0];

        // Query by key (which is the title)
        const { results } = await notionApi.queryDatabase(MEMORY_DB_ID, {
          filter: {
            property: titlePropertyName,
            title: { equals: key }
          }
        });

        if (results.length === 0) {
          return res.status(404).json({ 
            error: 'Memory not found',
            message: `No memory found with key: ${key}`
          });
        }

        page = results[0];
      }
      // Find by ID
      else {
        try {
          page = await notionApi.retrievePage(id);
        } catch (err) {
          return res.status(404).json({ 
            error: 'Memory not found',
            message: `No memory found with id: ${id}`
          });
        }
      }

      // Return all fields
      if (field.toLowerCase() === 'all') {
        // Format all properties
        const formattedProperties = {};

        for (const [propName, propData] of Object.entries(page.properties)) {
          formattedProperties[propName] = extractPropertyValue(propData);
        }

        return res.json({
          id: page.id,
          key: key || id,
          properties: formattedProperties,
          url: page.url,
          created_time: page.created_time,
          last_edited_time: page.last_edited_time
        });
      }

      // Return a specific field
      const schema = await schemaDetection.getDatabaseSchema(MEMORY_DB_ID);

      // If field is 'value', look for rich_text property
      if (field.toLowerCase() === 'value') {
        // First try 'Value' property
        if (page.properties.Value && page.properties.Value.type === 'rich_text') {
          const value = extractPropertyValue(page.properties.Value);

          return res.json({
            id: page.id,
            key: key || id,
            value
          });
        }

        // Then try any rich_text property
        const textProperty = Object.entries(schema)
          .find(([name, prop]) => prop.type === 'rich_text' && name !== 'Name');

        if (textProperty) {
          const propName = textProperty[0];
          const value = extractPropertyValue(page.properties[propName]);

          return res.json({
            id: page.id,
            key: key || id,
            value,
            property: propName
          });
        }

        return res.json({
          id: page.id,
          key: key || id,
          value: null,
          message: 'No suitable value property found'
        });
      }

      // Return the specified field
      const property = page.properties[field];

      if (!property) {
        return res.json({
          id: page.id,
          key: key || id,
          value: null,
          message: `Field '${field}' not found in memory entry`
        });
      }

      const value = extractPropertyValue(property);

      return res.json({
        id: page.id,
        key: key || id,
        value,
        property: field
      });
    } catch (err) {
      console.error('Error reading memory:', err);
      return res.status(500).json({ 
        error: 'Failed to read memory',
        message: err.message
      });
    }
  } catch (err) {
    console.error('Unexpected error in readmemory:', err);
    next(err);
  }
});

