const router = express.Router()
const PARENT_PAGE_ID = process.env.NOTION_PARENT_PAGE_ID

// In-memory cache with TTL
const cache = {
  pages: new Map(),
  ttl: 1000 * 60 * 5,
  set(key, value) {
    this.pages.set(key, { value, timestamp: Date.now() })
  },
  get(key) {
    const item = this.pages.get(key)
    if (!item) return null
    if (Date.now() - item.timestamp > this.ttl) {
      this.pages.delete(key)
      return null
    }
    return item.value
  },
  invalidate(key) {
    this.pages.delete(key)
  },
  clear() {
    this.pages.clear()
  }
}

// Create a standalone page under parent page
router.post('/createpage', async (req, res, next) => {
  try {
    const { title, content, properties = {} } = req.body
    if (!title || !content) return res.status(400).json({ error: 'Missing title or content' })

    const match = await pageUtils.findPageAcrossWorkspace(title)
    if (match) {
      const newTitle = await pageUtils.generateVersionedTitle(title)
      return createPage(newTitle)
    } else {
      return createPage(title)
    }

    async function createPage(title) {
      const blocks = await smartTextToBlocks(content)
      const payload = {
        parent: { type: 'page_id', page_id: PARENT_PAGE_ID },
        properties: {
          title: [{ type: 'text', text: { content: title } }],
          ...properties
        },
        children: blocks
      }
      const page = await notionApi.createPage(payload)
      cache.invalidate(title)
      res.json({ id: page.id, title })
    }
  } catch (err) {
    next(err)
  }
})

// Update a standalone page by ID or title
router.patch('/updatepage', async (req, res, next) => {
  try {
    const { idOrTitle, properties, children } = req.body
    if (!idOrTitle) return res.status(400).json({ error: 'Missing idOrTitle' })

    const page = await pageUtils.findPageAcrossWorkspace(idOrTitle)
    if (!page) return res.status(404).json({ error: 'Page not found' })

    const results = []
    if (properties) {
      const updated = await notionApi.updatePage(page.id, properties)
      results.push({ type: 'properties', id: updated.id })
    }
    if (children) {
      const content = typeof children === 'string' ? await smartTextToBlocks(children) : children
      const appended = await notionApi.appendBlocks(page.id, content)
      results.push({ type: 'blocks', count: appended?.results?.length || 0 })
    }

    cache.invalidate(idOrTitle)
    res.json({ updated: true, id: page.id, results })
  } catch (err) {
    next(err)
  }
})

