                      },
                      "properties": { 
                        "type": "object",
                        "properties": {
                          "Status": {
                            "type": "string",
                            "enum": ["Not started", "In progress", "Completed", "Blocked"]
                          },
                          "Priority": {
                            "type": "string",
                            "enum": ["Low", "Medium", "High"]
                          }
                        },
                        "description": "Properties for the Project Tracker entry"
                      }
                    },
                    "required": ["title"]
                  },
                  {
                    "type": "object",
                    "properties": {
                      "line": { 
                        "type": "string",
                        "description": "A key-value pair in the format 'Feature: Description'"
                      }
                    },
                    "required": ["line"]
                  }
                ]
              },
              "examples": {
