  return request
})

client.interceptors.response.use(
  response => {
    console.log(`[Notion API Response] Status: ${response.status}`)
    return response
  },
  error => {
    console.error('[Notion API Error]', error.response?.status, error.response?.data || error.message)
    return Promise.reject(error)
  }
)

/**
 * Query a Notion database with filters
 * @param {string} database_id - The ID of the database to query
 * @param {Object} filter - Query filters
 * @returns {Promise<Object>} - Query results
 */
const queryDatabase = async (database_id, filter = {}) => {
  return client.post(`/databases/${database_id}/query`, filter).then(res => res.data)
}

/**
 * Retrieve a specific page by ID
 * @param {string} page_id - The ID of the page to retrieve
 * @returns {Promise<Object>} - Page data
 */
const retrievePage = async (page_id) => {
  return client.get(`/pages/${page_id}`).then(res => res.data)
}

/**
 * Get information about a database by ID
 * @param {string} database_id - The ID of the database
 * @returns {Promise<Object>} - Database information
 */
const retrieveDatabase = async (database_id) => {
  return client.get(`/databases/${database_id}`).then(res => res.data)
}

/**
 * Create a new page
 * @param {Object} payload - The page creation payload
 * @returns {Promise<Object>} - Created page data
 */
const createPage = async (payload) => {
  return client.post('/pages', payload).then(res => res.data)
}

/**
 * Update a page's properties or archive state
 * @param {string} page_id - The ID of the page to update
 * @param {Object} properties - The properties to update
 * @param {boolean} archived - Whether to archive the page
 * @returns {Promise<Object>} - Updated page data
 */
const updatePage = async (page_id, properties = {}, archived = false) => {
  const payload = { properties }

  if (archived) {
    payload.archived = true
  }

  return client.patch(`/pages/${page_id}`, payload).then(res => res.data)
}

/**
 * Archive a block (Note: Prefer updatePage with archived=true for pages)
 * @param {string} block_id - The ID of the block to archive
 * @returns {Promise<Object>} - Archived block data
 */
const deleteBlock = async (block_id) => {
  return client.patch(`/blocks/${block_id}`, { archived: true }).then(res => res.data)
}

/**
 * Create a new database
 * @param {Object} payload - The database creation payload
 * @returns {Promise<Object>} - Created database data
 */
const createDatabase = async (payload) => {
  return client.post('/databases', payload).then(res => res.data)
}

/**
 * Update a database
 * @param {string} database_id - The ID of the database to update
 * @param {Object} props - The properties to update
 * @returns {Promise<Object>} - Updated database data
 */
const updateDatabase = async (database_id, props) => {
  return client.patch(`/databases/${database_id}`, props).then(res => res.data)
}

/**
 * Search Notion
 * @param {string} query - The search query
 * @returns {Promise<Object>} - Search results
 */
const search = async (query) => {
  return client.post('/search', { query }).then(res => res.data)
}

/**
 * Get the children blocks of a block
 * @param {string} blockId - The ID of the parent block
 * @param {string} startCursor - The cursor to start from for pagination
 * @returns {Promise<Object>} - Block children data
 */
const getBlockChildren = async (blockId, startCursor = undefined) => {
  const params = {}
  if (startCursor) params.start_cursor = startCursor

  return client.get(`/blocks/${blockId}/children`, { params }).then(res => res.data)
}

/**
 * Append blocks to a page or block
 * @param {string} blockId - The ID of the parent block
 * @param {Array} blocks - The blocks to append
 * @returns {Promise<Object>} - Block children data
 */
const appendBlockToPage = async (blockId, blocks) => {
  return client.patch(`/blocks/${blockId}/children`, { children: blocks }).then(res => res.data)
}

/**
 * Create a standalone page in the workspace
 * @param {string} title - The page title
 * @param {string} content - The page content
 * @returns {Promise<Object>} - Created page data
 */
const createStandalonePage = async (title, content) => {
  const blocks = [
    {
      object: 'block',
      type: 'heading_1',
      heading_1: { rich_text: [{ type: 'text', text: { content: title } }] }
    },
    ...(content ? [{
      object: 'block',
      type: 'paragraph',
      paragraph: { rich_text: [{ type: 'text', text: { content } }] }
    }] : [])
  ]

  const payload = {
    parent: { type: 'page_id', page_id: process.env.NOTION_PARENT_PAGE_ID },
    properties: {
      title: [
        {
          type: 'text',
          text: { content: title }
        }
      ]
    },
    children: blocks
  }

  return client.post('/pages', payload).then(res => res.data)
}

module.exports = {
  queryDatabase,
  retrievePage,
  retrieveDatabase,
  createPage,
  updatePage,
  deleteBlock,
  createDatabase,
  updateDatabase,
  search,
  getBlockChildren,
  appendBlockToPage,
  createStandalonePage
}

