// Simple cache for database name to ID mapping to improve performance
const databaseNameCache = {
  // Format: { 'DATABASE_NAME_UPPERCASE': 'database_id', ... }
  entries: new Map(),
  // TTL in milliseconds (10 minutes)
  ttl: 10 * 60 * 1000,
  // Set a cache entry with timestamp
  set(name, id) {
    this.entries.set(name, { id, timestamp: Date.now() });
  },
  // Get a cache entry, returns null if expired or not found
  get(name) {
    const entry = this.entries.get(name);
    if (!entry) return null;
    if (Date.now() - entry.timestamp > this.ttl) {
      this.entries.delete(name);
      return null;
    }
    return entry.id;
  },
  // Clear expired entries
  cleanup() {
    const now = Date.now();
    for (const [name, entry] of this.entries.entries()) {
      if (now - entry.timestamp > this.ttl) {
        this.entries.delete(name);
      }
    }
  }
};

/**
 * Create a configurable router for Notion database operations
 * @param {Object} config - Configuration for the router
 * @param {string} config.databaseId - Environment variable name containing the database ID
 * @param {string} config.databaseName - Optional database name to find in Notion (used if databaseId not provided)
 * @param {string} config.prefix - Prefix for route names (e.g., '' or 'memory')
 * @param {Object} config.routeNames - Custom route names mapping
 * @returns {express.Router} - Configured Express router
 */
const createNotionRouter = (config) => {
  const router = express.Router();
  
  // Get database ID from environment variable or find by name
  const getDatabaseId = async (req) => {
    // Run cache cleanup occasionally
    if (Math.random() < 0.1) {
      databaseNameCache.cleanup();
    }
    
    // First check if database ID is provided in the request
    const reqDatabaseId = req.query.database_id || req.body.database_id;
    if (reqDatabaseId) return reqDatabaseId;
    
    // Then check if database name is provided in the request
    const reqDatabaseName = req.query.database || req.body.database;
    if (reqDatabaseName) {
      // Convert to uppercase for case-insensitive comparison
      const upperReqName = reqDatabaseName.toUpperCase();
      
      // Check cache first
      const cachedId = databaseNameCache.get(upperReqName);
      if (cachedId) return cachedId;
      
      // Search Notion if not in cache
      const { results } = await notionApi.search(reqDatabaseName);
      const database = results.find(r => 
        r.object === 'database' && 
        r.title && 
        r.title.some(t => t.plain_text.toUpperCase() === upperReqName)
      );
      
      if (database) {
        // Add to cache and return
        databaseNameCache.set(upperReqName, database.id);
        return database.id;
      }
    }
    
    // If config has a databaseId environment variable, use that
    if (config.databaseId && process.env[config.databaseId]) {
      return process.env[config.databaseId];
    }
    
    // If config has a databaseName, search for it
    if (config.databaseName) {
      // Convert to uppercase for case-insensitive comparison
      const upperConfigName = config.databaseName.toUpperCase();
      
      // Check cache first
      const cachedId = databaseNameCache.get(upperConfigName);
      if (cachedId) return cachedId;
      
      // Search Notion if not in cache
      const { results } = await notionApi.search(config.databaseName);
      const database = results.find(r => 
        r.object === 'database' && 
        r.title && 
        r.title.some(t => t.plain_text.toUpperCase() === upperConfigName)
      );
      
      if (database) {
        // Add to cache and return
        databaseNameCache.set(upperConfigName, database.id);
        return database.id;
      }
    }
    
    return null;
  };

  // Default route names
  const defaultRouteNames = {
    create: 'createentry',
    update: 'updateentry',
    delete: 'deleteentry',
    list: 'listentries',
    read: 'readentry'
  };

  // Custom route names based on prefix
  let routeNames = {};
  if (config.prefix) {
    for (const [key, value] of Object.entries(defaultRouteNames)) {
      routeNames[key] = `${key}${config.prefix}`;
    }
  } else {
    routeNames = { ...defaultRouteNames };
  }

  // Override with any custom route names provided
  if (config.routeNames) {
    routeNames = { ...routeNames, ...config.routeNames };
  }

  /**
   * Extract property value based on its Notion type
   * @param {Object} property - The Notion property object
   * @returns {any} - The extracted value
   */
  const extractPropertyValue = (property) => {
    if (!property) return null;

    switch (property.type) {
      case 'title':
        return property.title?.length ? property.title.map(t => t.plain_text || '').join('') : null;
      case 'rich_text':
        return property.rich_text?.length ? property.rich_text.map(t => t.plain_text || '').join('') : null;
      case 'number':
        return property.number;
      case 'select':
        return property.select?.name || null;
      case 'multi_select':
        return property.multi_select?.length ? property.multi_select.map(s => s.name) : [];
      case 'date':
        return property.date?.start || null;
      case 'checkbox':
        return property.checkbox;
      case 'url':
        return property.url;
      case 'email':
