      case 'phone_number':
        return property.phone_number;
      default:
        return null;
    }
  };

  // CREATE route
  router.put(`/${routeNames.create}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);
      
      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Ensure database exists
      try {
        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        if (!schema) {
          return res.status(404).json({ 
            error: `Database not found`,
            message: `Check the database ID: ${databaseId}`
          });
        }
      } catch (err) {
        return res.status(500).json({ 
          error: `Error accessing database`,
          message: err.message
        });
      }

      // Rest of your existing create entry code...
      // (Using the databaseId variable for any database operations)
      
      let properties = {};

      if (req.body.line) {
        // Your existing code for handling line input
        // ...
      } else {
        // Your existing code for handling title and properties input
        // ...
      }

      // Create the page
      const page = await notionApi.createPage({
        parent: { database_id: databaseId },
        properties
      });

      // Extract the title for response
      const title = await pageUtils.extractPageTitle(page);

      return res.json({
        success: true,
        created: true,
        database_id: databaseId,
        id: page.id,
        title,
        message: "Entry created successfully"
      });
    } catch (err) {
      console.error(`Error in ${routeNames.create}:`, err);
      next(err);
    }
  });

  // UPDATE route
  router.patch(`/${routeNames.update}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);
      
      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Your existing update entry code using databaseId
