/**
 * Find a Notion database ID by name (case-insensitive and normalizes spaces)
 * @param {string} databaseName - The name of the database to find
 * @returns {Promise<string|null>} The database ID if found, null otherwise
 */
const findDatabaseByName = async (databaseName) => {
  const notionApi = require('./notion-api');

  if (!databaseName) {
    throw new Error('Database name is required');
  }

  try {
    // Normalize the input name: uppercase and replace spaces with underscores
    const normalizedInputName = databaseName.trim().toUpperCase().replace(/\s+/g, '_');

    // Use the existing search endpoint to find all databases
    const response = await notionApi.search({
      filter: {
        property: 'object',
        value: 'database'
      }
    });

    // Loop through all databases and look for a match
    for (const db of response.results) {
      // Extract the database title
      const title = db.title?.length 
        ? db.title.map(t => t.plain_text || '').join('') 
        : '';

      // Normalize the found title in the same way as the input
      const normalizedTitle = title.trim().toUpperCase().replace(/\s+/g, '_');

      // Check for a match
      if (normalizedTitle === normalizedInputName) {
        return db.id;
      }
    }

    // Also try a direct search with the normalized name (as a fallback)
    const directSearch = await notionApi.search({
      query: databaseName.trim()
    });

    // Check results from direct search
    const matchedDb = directSearch.results.find(item => {
      if (item.object !== 'database') return false;

      const title = item.title?.length 
        ? item.title.map(t => t.plain_text || '').join('') 
        : '';

      const normalizedTitle = title.trim().toUpperCase().replace(/\s+/g, '_');
      return normalizedTitle === normalizedInputName;
    });

    return matchedDb ? matchedDb.id : null;
  } catch (error) {
    console.error(`Error finding database by name "${databaseName}":`, error);
    throw error;
  }
};

module.exports = findDatabaseByName;

