        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        const titleProp = schemaDetection.findTitleProperty(schema);

        if (!titleProp) {
          return res.status(400).json({ 
            error: `No title property found in database`,
            message: `Database schema doesn't include a title property`
          });
        }

