      }

      // Handle delete by key or idOrTitle
      const idOrTitle = req.query.idOrTitle || req.query.key;

      if (!idOrTitle) {
        return res.status(400).json({ 
          error: `Missing identifier`,
          message: `Provide idOrTitle or key parameter`
        });
      }

      const page = await pageUtils.findPage(databaseId, idOrTitle);

      if (!page) {
