        // Find the first text field in properties
        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        const textFields = Object.entries(schema)
          .filter(([_, prop]) => prop.type === 'rich_text')
          .map(([name, _]) => name);

        const targetField = textFields.find(name => 
          ['notes', 'description', 'content', 'details', 'value'].includes(name.toLowerCase())
        ) || textFields[0];

        if (!targetField) {
          return res.json({
            id: page.id,
            title: await pageUtils.extractPageTitle(page),
            value: null,
            message: "No suitable text field found"
          });
        }

        const value = extractPropertyValue(page.properties[targetField]);

        return res.json({
          id: page.id,
          title: await pageUtils.extractPageTitle(page),
          field: targetField,
          value
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.read}:`, err);
      next(err);
    }
  });

  return router;
};

module.exports = createNotionRouter;

