// notion-route-factory.js
const express = require('express');
const notionApi = require('./notion-api');
const pageUtils = require('./page-utils');
const schemaDetection = require('./schema-detection');
const { findDatabaseByName } = require('./database-utils');

// Simple cache for database name to ID mapping to improve performance
const databaseNameCache = {
  // Format: { 'DATABASE_NAME_UPPERCASE': 'database_id', ... }
  entries: new Map(),
  // TTL in milliseconds (10 minutes)
  ttl: 10 * 60 * 1000,
  // Set a cache entry with timestamp
  set(name, id) {
    this.entries.set(name, { id, timestamp: Date.now() });
  },
  // Get a cache entry, returns null if expired or not found
  get(name) {
    const entry = this.entries.get(name);
    if (!entry) return null;
    if (Date.now() - entry.timestamp > this.ttl) {
      this.entries.delete(name);
      return null;
    }
    return entry.id;
  },
  // Clear expired entries
  cleanup() {
    const now = Date.now();
    for (const [name, entry] of this.entries.entries()) {
      if (now - entry.timestamp > this.ttl) {
        this.entries.delete(name);
      }
    }
  }
};

/**
 * Create a configurable router for Notion database operations
 * @param {Object} config - Configuration for the router
 * @param {string} config.databaseName - The database name to find in Notion
 * @param {string} config.prefix - Prefix for route names (e.g., '' or 'memory')
 * @param {Object} config.routeNames - Custom route names mapping
 * @returns {express.Router} - Configured Express router
 */
const createNotionRouter = (config) => {
  const router = express.Router();

  // Get database ID from environment variable or find by name
  const getDatabaseId = async (req) => {
    // Run cache cleanup occasionally
    if (Math.random() < 0.1) {
      databaseNameCache.cleanup();
    }

    // First check if database ID is provided in the request
    const reqDatabaseId = req.query.database_id || req.body.database_id;
    if (reqDatabaseId) return reqDatabaseId;

    // Then check if database name is provided in the request
    const reqDatabaseName = req.query.database || req.body.database;
    if (reqDatabaseName) {
      // Check cache first
      const normalizedName = reqDatabaseName.trim().toUpperCase().replace(/\s+/g, '_');
      const cachedId = databaseNameCache.get(normalizedName);
      if (cachedId) return cachedId;

      // Use findDatabaseByName to search for the database
      try {
        const foundId = await findDatabaseByName(reqDatabaseName);
        if (foundId) {
          databaseNameCache.set(normalizedName, foundId);
          return foundId;
        }
      } catch (error) {
        console.error(`Error finding database by name "${reqDatabaseName}":`, error);
      }
    }

    // If config has a databaseName, try to find it using findDatabaseByName
    if (config.databaseName) {
      const normalizedName = config.databaseName.trim().toUpperCase().replace(/\s+/g, '_');

      // Check cache first
      const cachedId = databaseNameCache.get(normalizedName);
      if (cachedId) return cachedId;

      // Use findDatabaseByName to search
      try {
        const foundId = await findDatabaseByName(config.databaseName);
        if (foundId) {
          databaseNameCache.set(normalizedName, foundId);
          return foundId;
        }
      } catch (error) {
        console.error(`Error finding database by name "${config.databaseName}":`, error);
      }
    }

    return null;
  };

  // Default route names
  const defaultRouteNames = {
    create: 'createentry',
    update: 'updateentry',
    delete: 'deleteentry',
    list: 'listentries',
    read: 'readentry'
  };

  // Custom route names based on prefix
  let routeNames = {};
  if (config.prefix) {
    for (const [key, value] of Object.entries(defaultRouteNames)) {
      routeNames[key] = `${key}${config.prefix}`;
    }
  } else {
    routeNames = { ...defaultRouteNames };
  }

  // Override with any custom route names provided
  if (config.routeNames) {
    routeNames = { ...routeNames, ...config.routeNames };
  }

  /**
   * Extract property value based on its Notion type
   * @param {Object} property - The Notion property object
   * @returns {any} - The extracted value
   */
  const extractPropertyValue = (property) => {
    if (!property) return null;

    switch (property.type) {
      case 'title':
        return property.title?.length ? property.title.map(t => t.plain_text || '').join('') : null;
      case 'rich_text':
        return property.rich_text?.length ? property.rich_text.map(t => t.plain_text || '').join('') : null;
      case 'number':
        return property.number;
      case 'select':
        return property.select?.name || null;
      case 'multi_select':
        return property.multi_select?.length ? property.multi_select.map(s => s.name) : [];
      case 'date':
        return property.date?.start || null;
      case 'checkbox':
        return property.checkbox;
      case 'url':
        return property.url;
      case 'email':
        return property.email;
      case 'phone_number':
        return property.phone_number;
      default:
        return null;
    }
  };

  // CREATE route
  router.put(`/${routeNames.create}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Ensure database exists
      try {
        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        if (!schema) {
          return res.status(404).json({ 
            error: `Database not found`,
            message: `Check the database ID: ${databaseId}`
          });
        }
      } catch (err) {
        return res.status(500).json({ 
          error: `Error accessing database`,
          message: err.message
        });
      }

      let properties = {};

      if (req.body.line) {
        // Parse line-based input (e.g., "Feature: Name, Status: Value")
        const pairs = req.body.line.split(/,\s*|\n/).filter(Boolean);
        const parsedProperties = {};

        pairs.forEach(pair => {
          const [key, ...valueParts] = pair.split(':');
          if (key && valueParts.length) {
            parsedProperties[key.trim()] = valueParts.join(':').trim();
          }
        });

        // Map parsed properties to Notion schema
        properties = await schemaDetection.mapPropertiesToSchema(databaseId, parsedProperties);
      } else if (req.body.title) {
        // Get the title property name for this database
        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        const titleProp = schemaDetection.findTitleProperty(schema);

        if (!titleProp) {
          return res.status(400).json({ 
            error: `No title property found in database`,
            message: `Database schema doesn't include a title property`
          });
        }

        // Set up the title property
        properties[titleProp] = { 
          title: [{ text: { content: req.body.title } }] 
        };

        // Handle additional properties if provided
        if (req.body.properties) {
          const mappedProps = await schemaDetection.mapPropertiesToSchema(
            databaseId, 
            req.body.properties
          );
          properties = { ...properties, ...mappedProps };
        }
      } else {
        return res.status(400).json({ 
          error: `Missing required properties`,
          message: `Provide either 'line' or 'title'`
        });
      }

      // Create the page
      const page = await notionApi.createPage({
        parent: { database_id: databaseId },
        properties
      });

      // Extract the title for response
      const title = await pageUtils.extractPageTitle(page);

      return res.json({
        success: true,
        created: true,
        database_id: databaseId,
        id: page.id,
        title,
        message: "Entry created successfully"
      });
    } catch (err) {
      console.error(`Error in ${routeNames.create}:`, err);
      next(err);
    }
  });

  // UPDATE route
  router.patch(`/${routeNames.update}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Handle different update patterns
      if (req.body.idOrTitle) {
        // Pattern 1 & 2: Update by ID or title
        const page = await pageUtils.findPage(databaseId, req.body.idOrTitle);

        if (!page) {
          return res.status(404).json({ 
            error: `Entry not found`,
            message: `No entry found with ID or title: ${req.body.idOrTitle}`
          });
        }

        if (req.body.key && req.body.value !== undefined) {
          // Pattern 1: Update a specific field
          const schema = await schemaDetection.getDatabaseSchema(databaseId);
          const props = { [req.body.key]: req.body.value };
          const mappedProps = await schemaDetection.mapPropertiesToSchema(databaseId, props);

          const updatedPage = await notionApi.updatePage(page.id, mappedProps);
          const title = await pageUtils.extractPageTitle(updatedPage);

          return res.json({
            success: true,
            updated: true,
            id: updatedPage.id,
            title,
            field: req.body.key,
            value: req.body.value
          });
        } else if (req.body.properties) {
          // Pattern 2: Update multiple properties
          const mappedProps = await schemaDetection.mapPropertiesToSchema(
            databaseId, 
            req.body.properties
          );

          const updatedPage = await notionApi.updatePage(page.id, mappedProps);
          const title = await pageUtils.extractPageTitle(updatedPage);

          return res.json({
            success: true,
            updated: true,
            id: updatedPage.id,
            title,
            properties: req.body.properties
          });
        }
      } else if (req.body.key && req.body.value !== undefined) {
        // Pattern 3: Legacy update by just key/value (searches by key)
        // This treats the key as a title to search for
        let page = await pageUtils.findPageByTitle(databaseId, req.body.key);

        if (!page && req.body.createIfMissing) {
          // Create the entry if requested
          const schema = await schemaDetection.getDatabaseSchema(databaseId);
          const titleProp = schemaDetection.findTitleProperty(schema);

          if (!titleProp) {
            return res.status(400).json({ 
              error: `No title property found in database`,
              message: `Database schema doesn't include a title property`
            });
          }

          const properties = {
            [titleProp]: { title: [{ text: { content: req.body.key } }] }
          };

          page = await notionApi.createPage({
            parent: { database_id: databaseId },
            properties
          });

          // Now update the page with the value
          // First, find the "notes" or "description" field
          const schema = await schemaDetection.getDatabaseSchema(databaseId);
          const textFields = Object.entries(schema)
            .filter(([_, prop]) => prop.type === 'rich_text')
            .map(([name, _]) => name);

          const targetField = textFields.find(name => 
            ['notes', 'description', 'content', 'details', 'value'].includes(name.toLowerCase())
          ) || textFields[0];

          if (targetField) {
            const updateProps = {
              [targetField]: { 
                rich_text: [{ text: { content: req.body.value } }] 
              }
            };

            await notionApi.updatePage(page.id, updateProps);
          }

          return res.json({
            success: true,
            created: true,
            updated: true,
            id: page.id,
            field: targetField || 'unknown',
            value: req.body.value
          });
        } else if (!page) {
          return res.status(404).json({ 
            error: `Entry not found`,
            message: `No entry found with title: ${req.body.key}`
          });
        }

        // Find a rich_text field to update
        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        const textFields = Object.entries(schema)
          .filter(([_, prop]) => prop.type === 'rich_text')
          .map(([name, _]) => name);

        const targetField = textFields.find(name => 
          ['notes', 'description', 'content', 'details', 'value'].includes(name.toLowerCase())
        ) || textFields[0];

        if (!targetField) {
          return res.status(400).json({ 
            error: `No suitable text field found`,
            message: `Database schema doesn't include a rich_text field to update`
          });
        }

        const updateProps = {
          [targetField]: { 
            rich_text: [{ text: { content: req.body.value } }] 
          }
        };

        const updatedPage = await notionApi.updatePage(page.id, updateProps);
        const title = await pageUtils.extractPageTitle(updatedPage);

        return res.json({
          success: true,
          updated: true,
          id: updatedPage.id,
          title,
          field: targetField,
          value: req.body.value
        });
      }

      return res.status(400).json({ 
        error: `Invalid update request`,
        message: `Provide idOrTitle + key/value, idOrTitle + properties, or key + value`
      });
    } catch (err) {
      console.error(`Error in ${routeNames.update}:`, err);
      next(err);
    }
  });

  // DELETE route
  router.delete(`/${routeNames.delete}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Handle delete by key or idOrTitle
      const idOrTitle = req.query.idOrTitle || req.query.key;

      if (!idOrTitle) {
        return res.status(400).json({ 
          error: `Missing identifier`,
          message: `Provide idOrTitle or key parameter`
        });
      }

      const page = await pageUtils.findPage(databaseId, idOrTitle);

      if (!page) {
        return res.status(404).json({ 
          error: `Entry not found`,
          message: `No entry found with ID or title: ${idOrTitle}`
        });
      }

      // Archive the page (soft delete)
      const archivedPage = await notionApi.updatePage(page.id, {}, true);
      const title = await pageUtils.extractPageTitle(page);

      return res.json({
        success: true,
        deleted: true,
        id: archivedPage.id,
        title,
        message: "Entry archived successfully"
      });
    } catch (err) {
      console.error(`Error in ${routeNames.delete}:`, err);
      next(err);
    }
  });

  // LIST route
  router.get(`/${routeNames.list}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      try {
        // Build filter if provided
        let filter = {};
        if (req.query.filter) {
          try {
            filter = JSON.parse(req.query.filter);
          } catch (e) {
            console.warn('Invalid filter JSON:', req.query.filter);
          }
        }

        // Perform database query
        const { results } = await notionApi.queryDatabase(databaseId, filter);

        // Format the results
        const entries = await Promise.all(results.map(async (page) => {
          const title = await pageUtils.extractPageTitle(page);

          return {
            id: page.id,
            title,
            url: page.url,
            created_time: page.created_time,
            last_edited_time: page.last_edited_time
          };
        }));

        return res.json({
          database_id: databaseId,
          entries
        });
      } catch (err) {
        console.error(`Error listing entries:`, err);
        return res.status(500).json({ 
          error: 'Failed to list entries',
          message: err.message
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.list}:`, err);
      next(err);
    }
  });

  // READ route
  router.get(`/${routeNames.read}`, async (req, res, next) => {
    try {
      const databaseId = await getDatabaseId(req);

      if (!databaseId) {
        return res.status(400).json({ 
          error: `Missing database ID`,
          message: `Provide a database name or ID in the request`
        });
      }

      // Read by id or key
      const id = req.query.id;
      const key = req.query.key;

      if (!id && !key) {
        return res.status(400).json({ 
          error: `Missing identifier`,
          message: `Provide id or key parameter`
        });
      }

      const idOrTitle = id || key;
      const page = await pageUtils.findPage(databaseId, idOrTitle);

      if (!page) {
        return res.status(404).json({ 
          error: `Entry not found`,
          message: `No entry found with ID or title: ${idOrTitle}`
        });
      }

      // Determine what to return based on field parameter
      const field = req.query.field || 'value';

      if (field === 'all') {
        // Return all properties
        const formattedProps = {};

        for (const [propName, propValue] of Object.entries(page.properties)) {
          formattedProps[propName] = extractPropertyValue(propValue);
        }

        return res.json({
          id: page.id,
          title: await pageUtils.extractPageTitle(page),
          url: page.url,
          properties: formattedProps
        });
      } else {
        // Find the first text field in properties
        const schema = await schemaDetection.getDatabaseSchema(databaseId);
        const textFields = Object.entries(schema)
          .filter(([_, prop]) => prop.type === 'rich_text')
          .map(([name, _]) => name);

        const targetField = textFields.find(name => 
          ['notes', 'description', 'content', 'details', 'value'].includes(name.toLowerCase())
        ) || textFields[0];

        if (!targetField) {
          return res.json({
            id: page.id,
            title: await pageUtils.extractPageTitle(page),
            value: null,
            message: "No suitable text field found"
          });
        }

        const value = extractPropertyValue(page.properties[targetField]);

        return res.json({
          id: page.id,
          title: await pageUtils.extractPageTitle(page),
          field: targetField,
          value
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.read}:`, err);
      next(err);
    }
  });

  return router;
};

module.exports = createNotionRouter;

