    "/notion/databases/updateentry": {
      "patch": {
        "summary": "Update database entry",
        "description": "Updates an entry in the PROJECT_TRACKER database. There are three ways to use this endpoint: 1) Update a specific field of an identified entry, 2) Update multiple properties at once, or 3) Find an entry by title and update a text field.",
        "operationId": "updateEntry",
        "parameters": [
          {
            "name": "database",
            "in": "query",
            "required": true,
            "schema": {
              "type": "string"
            },
            "description": "The database environment variable name (e.g., 'PROJECT_TRACKER' or 'GPT_MEMORY_DB')"
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "idOrTitle": {
                    "type": "string",
                    "description": "The ID or title of the entry to update"
                  },
                  "key": {
                    "type": "string",
                    "description": "The name of the field to update (e.g., 'Status', 'Priority')"
                  },
                  "value": {
                    "type": "string",
                    "description": "The new value for the specified field"
                  },
                  "properties": {
                    "type": "object",
                    "description": "Multiple properties to update at once"
                  },
                  "createIfMissing": {
                    "type": "boolean",
                    "description": "Whether to create the entry if it doesn't exist"
                  }
                },
                "oneOf": [
                  {
                    "required": [
                      "idOrTitle",
                      "key",
                      "value"
                    ]
                  },
                  {
                    "required": [
                      "idOrTitle",
                      "properties"
                    ]
                  },
                  {
                    "required": [
                      "key",
                      "value"
                    ]
                  }
                ]
              },
              "examples": {
                "update-field": {
                  "summary": "Update a specific field",
                  "value": {
                    "idOrTitle": "Implement Authentication Module",
                    "key": "Status",
                    "value": "In Progress"
                  }
                },
                "update-properties": {
                  "summary": "Update multiple properties",
                  "value": {
                    "idOrTitle": "Implement Authentication Module",
                    "properties": {
                      "Status": "In Progress",
                      "Priority": "High"
                    }
                  }
                },
                "legacy-update": {
                  "summary": "Legacy update by title",
                  "value": {
                    "key": "Quick Export Button",
