                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Entry updated successfully",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "type": "boolean"
                    },
                    "updated": {
                      "type": "boolean"
                    },
                    "id": {
                      "type": "string"
                    },
                    "field": {
                      "type": "string"
                    },
                    "value": {
                      "type": "string"
                    },
                    "properties": {
                      "type": "object"
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Invalid request parameters"
          },
          "404": {
            "description": "Entry not found"
          },
          "500": {
            "description": "Server error"
          }
        }
      }
    },
