    // Extract the fields object if it exists
    let fields;
    if (bodyData.fields) {
      fields = bodyData.fields;
      delete bodyData.fields;
    } else {
      // If no fields object, use the rest of the body as fields
      // (after removing any other special properties)
      if (bodyData.database) {
