const BLOCK_TYPES = {
  paragraph: (text) => ({
    type: 'paragraph',
    paragraph: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  heading_1: (text) => ({
    type: 'heading_1',
    heading_1: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  heading_2: (text) => ({
    type: 'heading_2',
    heading_2: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  heading_3: (text) => ({
    type: 'heading_3',
    heading_3: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  bulleted_list_item: (text) => ({
    type: 'bulleted_list_item',
    bulleted_list_item: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  numbered_list_item: (text) => ({
    type: 'numbered_list_item',
    numbered_list_item: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  to_do: (text, checked = false) => ({
    type: 'to_do',
    to_do: { rich_text: [{ type: 'text', text: { content: text } }], checked }
  }),
  quote: (text) => ({
    type: 'quote',
    quote: { rich_text: [{ type: 'text', text: { content: text } }] }
  }),
  code: (text, language = 'javascript') => ({
    type: 'code',
    code: { rich_text: [{ type: 'text', text: { content: text } }], language }
  }),
  toggle: (text) => ({
    type: 'toggle',
    toggle: { rich_text: [{ type: 'text', text: { content: text } }], children: [] }
  }),
  callout: (text, icon = { emoji: '💡' }) => ({
    type: 'callout',
    callout: { rich_text: [{ type: 'text', text: { content: text } }], icon }
  }),
  divider: () => ({ type: 'divider', divider: {} }),
  image: (url) => ({ type: 'image', image: { type: 'external', external: { url } } }),
  video: (url) => ({ type: 'video', video: { type: 'external', external: { url } } }),
  file: (url) => ({ type: 'file', file: { type: 'external', external: { url } } }),
  pdf: (url) => ({ type: 'pdf', pdf: { type: 'external', external: { url } } }),
  bookmark: (url) => ({ type: 'bookmark', bookmark: { url } }),
  embed: (url) => ({ type: 'embed', embed: { url } }),
  equation: (expression) => ({ type: 'equation', equation: { expression } }),
  table: (tableData) => ({ type: 'table', table: tableData }),
  table_row: (cells) => ({ type: 'table_row', table_row: { cells } }),
  synced_block: (synced_from = null) => ({ type: 'synced_block', synced_block: { synced_from } }),
