const { BLOCK_TYPES } = require('./block-types')

/**
 * Parse markdown text and convert to Notion rich text objects with formatting
 * @param {string} text - The markdown text to parse
 * @returns {Array} - Array of Notion rich text objects
 */
const parseFormattedText = (text) => {
  // Initialize array to hold rich text objects
  const richTextObjects = [];
  
  // Helper to add text with annotations
  const addText = (content, annotations = {}) => {
    richTextObjects.push({
      type: 'text',
      text: { content },
      annotations: {
        bold: annotations.bold || false,
        italic: annotations.italic || false,
        strikethrough: annotations.strikethrough || false,
        underline: annotations.underline || false,
        code: annotations.code || false,
        color: 'default'
      }
    });
  };
  
  // Process bold text: **text**
  text = text.replace(/\*\*(.*?)\*\*/g, (match, content) => {
    addText(content, { bold: true });
    return '\0'; // Use null character as placeholder
  });
  
  // Process italic text: *text*
  text = text.replace(/\*(.*?)\*/g, (match, content) => {
    addText(content, { italic: true });
    return '\0';
  });
  
  // Process strikethrough: ~~text~~
  text = text.replace(/~~(.*?)~~/g, (match, content) => {
    addText(content, { strikethrough: true });
    return '\0';
  });
  
  // Process inline code: `text`
  text = text.replace(/`([^`]+)`/g, (match, content) => {
    addText(content, { code: true });
    return '\0';
  });
  
  // Process links: [text](url)
  text = text.replace(/\[(.*?)\]\((.*?)\)/g, (match, linkText, url) => {
    richTextObjects.push({
      type: 'text',
      text: { 
        content: linkText,
        link: { url }
      }
    });
    return '\0';
  });
  
  // Process any remaining plain text segments
  const plainTextSegments = text.split('\0');
  plainTextSegments.forEach(segment => {
    if (segment) {
      addText(segment);
    }
  });
  
  return richTextObjects;
};

/**
 * Create a block with formatted text
 * @param {string} blockType - The Notion block type
 * @param {string} text - The text content with markdown formatting
 * @returns {Object} - A properly formatted Notion block
 */
const createBlockWithFormatting = (blockType, text) => {
  const richText = parseFormattedText(text);
  
  // Create the block structure based on type
  switch (blockType) {
    case 'paragraph':
      return { type: 'paragraph', paragraph: { rich_text: richText } };
    case 'heading_1':
      return { type: 'heading_1', heading_1: { rich_text: richText } };
    case 'heading_2':
      return { type: 'heading_2', heading_2: { rich_text: richText } };
    case 'heading_3':
      return { type: 'heading_3', heading_3: { rich_text: richText } };
    case 'bulleted_list_item':
      return { type: 'bulleted_list_item', bulleted_list_item: { rich_text: richText } };
    case 'numbered_list_item':
      return { type: 'numbered_list_item', numbered_list_item: { rich_text: richText } };
    case 'quote':
      return { type: 'quote', quote: { rich_text: richText } };
    case 'to_do':
      return { type: 'to_do', to_do: { rich_text: richText, checked: false } };
    default:
      return { type: 'paragraph', paragraph: { rich_text: richText } };
  }
};

/**
 * Parse table cell content with formatting
 * @param {string} cellText - The cell text to parse
 * @returns {Array} - Array of rich text objects for the cell
 */
const parseTableCell = (cellText) => {
  return parseFormattedText(cellText);
};

const mdToBlocks = (markdown) => {
  const lines = markdown.split('\n')
  const blocks = []
  let inCode = false
  let codeLang = 'text'
  let codeBuffer = []
  
  // Table parsing variables
  let inTable = false
  let tableRows = []
  let tableHeaderSeparatorFound = false
  let tableWidth = 0

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    
    // Handle code blocks
    if (/^```/.test(line)) {
      if (!inCode) {
        inCode = true
        codeLang = line.replace(/^```/, '').trim() || 'text'
        codeBuffer = []
      } else {
        inCode = false
        blocks.push(BLOCK_TYPES.code(codeBuffer.join('\n'), codeLang))
      }
      continue
    }
    
    if (inCode) {
      codeBuffer.push(line)
      continue
    }
    
    // Table detection and parsing
    const isTableRow = line.trim().startsWith('|') && line.trim().endsWith('|')
    const isTableSeparator = /^\s*\|[\s\-\|:]+\|\s*$/.test(line)
    
    if (isTableRow) {
      // If this is the first row of a table
      if (!inTable) {
        inTable = true
        tableRows = []
        tableHeaderSeparatorFound = false
      }
      
      // Parse cells from the row
      const cells = line
        .trim()
        .split('|')
        .slice(1, -1) // Remove empty cells at start/end from the | chars
        .map(cell => cell.trim())
      
      tableWidth = Math.max(tableWidth, cells.length)
      
      if (!tableHeaderSeparatorFound) {
        // If the next line is a separator, this is a header row
        if (i + 1 < lines.length && /^\s*\|[\s\-\|:]+\|\s*$/.test(lines[i + 1])) {
          tableRows.push({
            isHeader: true,
            cells: cells
          })
        } else {
          // No separator = regular row
          tableRows.push({
            isHeader: false,
            cells: cells
          })
        }
      } else {
        // After separator = regular row
        tableRows.push({
          isHeader: false,
          cells: cells
        })
      }
      continue
    }
    
    // Handle table separator row - just mark that we found it
    if (isTableSeparator && inTable) {
      tableHeaderSeparatorFound = true
      continue
    }
    
    // If we were in a table but this line is not a table row, end the table
    if (inTable && !isTableRow && !isTableSeparator) {
      // Create table block using the existing BLOCK_TYPES.table
      const hasHeader = tableRows.length > 0 && tableRows[0].isHeader
      
      // Create table rows with formatted cells
      const tableData = {
        table_width: tableWidth,
        has_column_header: hasHeader,
        has_row_header: false,
        children: tableRows.map(row => ({
          type: 'table_row',
          table_row: {
            cells: row.cells.map(cell => parseTableCell(cell))
          }
        }))
      };
      
      blocks.push(BLOCK_TYPES.table(tableData));
      
      inTable = false
      tableRows = []
      tableWidth = 0
      
      // Process the current line (non-table line)
      i--  // Step back to process this line again
      continue
    }
    
    // Regular markdown processing (non-table lines) with formatting support
    if (/^#\s+/.test(line)) {
      blocks.push(createBlockWithFormatting('heading_1', line.replace(/^#\s+/, '')))
    } else if (/^##\s+/.test(line)) {
      blocks.push(createBlockWithFormatting('heading_2', line.replace(/^##\s+/, '')))
    } else if (/^###\s+/.test(line)) {
      blocks.push(createBlockWithFormatting('heading_3', line.replace(/^###\s+/, '')))
    } else if (/^-\s+\[ \]\s+/.test(line)) {
      const todoBlock = createBlockWithFormatting('to_do', line.replace(/^-\s+\[ \]\s+/, ''))
      todoBlock.to_do.checked = false
      blocks.push(todoBlock)
    } else if (/^-\s+\[x\]\s+/.test(line)) {
      const todoBlock = createBlockWithFormatting('to_do', line.replace(/^-\s+\[x\]\s+/, ''))
      todoBlock.to_do.checked = true
      blocks.push(todoBlock)
    } else if (/^-\s+/.test(line)) {
      blocks.push(createBlockWithFormatting('bulleted_list_item', line.replace(/^-\s+/, '')))
    } else if (/^\d+\.\s+/.test(line)) {
      blocks.push(createBlockWithFormatting('numbered_list_item', line.replace(/^\d+\.\s+/, '')))
    } else if (/^>\s+/.test(line)) {
      blocks.push(createBlockWithFormatting('quote', line.replace(/^>\s+/, '')))
    } else if (/^---+$/.test(line)) {
      blocks.push(BLOCK_TYPES.divider())
    } else {
      blocks.push(createBlockWithFormatting('paragraph', line))
    }
  }
  
  // Handle case where a table is at the end of the document
  if (inTable) {
    const hasHeader = tableRows.length > 0 && tableRows[0].isHeader;
    
    const tableData = {
      table_width: tableWidth,
      has_column_header: hasHeader,
      has_row_header: false,
      children: tableRows.map(row => ({
        type: 'table_row',
        table_row: {
          cells: row.cells.map(cell => parseTableCell(cell))
        }
      }))
    };
    
    blocks.push(BLOCK_TYPES.table(tableData));
  }

  return blocks
}

const blocksToMd = (blocks) => {
  return blocks.map(block => {
    const rich = block[block.type]?.rich_text
    const content = Array.isArray(rich)
      ? rich.map(r => r.plain_text || r.text?.content).join('')
      : ''

    switch (block.type) {
      case 'heading_1': return `# ${content}`
      case 'heading_2': return `## ${content}`
      case 'heading_3': return `### ${content}`
      case 'bulleted_list_item': return `- ${content}`
      case 'numbered_list_item': return `1. ${content}`
      case 'to_do': return `- [${block.to_do.checked ? 'x' : ' '}] ${content}`
      case 'quote': return `> ${content}`
      case 'code': return `\n\n\`\`\`${block.code.language || 'text'}\n${block.code.rich_text?.map(rt => rt.text?.content).join('') || ''}\n\`\`\``
      case 'divider': return '---'
      case 'toggle': return `<details><summary>${content}</summary></details>`
      case 'callout': return `> 💡 ${content}`
      case 'table': {
        // Handle table blocks
        if (!block.table || !block.table.children || !Array.isArray(block.table.children)) {
          return ''; // Return empty string for invalid table blocks
        }
        
        const tableRows = block.table.children;
        if (tableRows.length === 0) return '';
        
        // Get the maximum number of columns from all rows
        const maxColumns = tableRows.reduce((max, row) => {
          const cellCount = row.table_row?.cells?.length || 0;
          return Math.max(max, cellCount);
        }, 0);
        
        // If no valid columns, return empty string
        if (maxColumns === 0) return '';
        
        let markdown = [];
        
        // Process each row
        tableRows.forEach((row, rowIndex) => {
          if (!row.table_row || !Array.isArray(row.table_row.cells)) return;
          
          const cells = row.table_row.cells;
          let rowMd = '|';
          
          // Process each cell
          for (let i = 0; i < maxColumns; i++) {
            const cell = cells[i] || [];
            // Extract text content from cell
            const cellContent = cell.map(item => 
              item.plain_text || item.text?.content || ''
            ).join('');
            
            rowMd += ` ${cellContent} |`;
          }
          
          markdown.push(rowMd);
          
          // Add separator row after header if this is the first row and the table has headers
          if (rowIndex === 0 && block.table.has_column_header) {
            let separator = '|';
            for (let i = 0; i < maxColumns; i++) {
              separator += ' --- |';
            }
            markdown.push(separator);
          }
        });
        
        return markdown.join('\n');
      }
      default: return content
    }
  }).join('\n')
}

const convertTextToBlocks = async (text) => {
  return text.split('\n').map(line => createBlockWithFormatting('paragraph', line))
}

const convertBlocksToText = (blocks) => {
  return blocks.map(block => {
    const rich = block[block.type]?.rich_text
    return Array.isArray(rich)
      ? rich.map(r => r.plain_text || r.text?.content || '').join('')
      : ''
  }).join('\n')
}

const smartTextToBlocks = async (text) => {
  const isMarkdown = /[#>`*\-~]|\n.*\n/.test(text.trim())
  return isMarkdown ? mdToBlocks(text) : await convertTextToBlocks(text)
}

module.exports = {
  mdToBlocks,
  blocksToMd,
  convertTextToBlocks,
  convertBlocksToText,
  smartTextToBlocks,
  parseFormattedText
}

