        const property = page.properties[field];

        if (!property) {
          return res.json({
            id: page.id,
            key: key || id,
            value: null,
            message: `Field '${field}' not found in entry`
          });
        }

        const value = extractPropertyValue(property);

        return res.json({
          id: page.id,
          key: key || id,
          value,
          property: field
        });
      } catch (err) {
        console.error(`Error reading entry:`, err);
        return res.status(500).json({ 
          error: 'Failed to read entry',
          message: err.message
        });
