// Enhanced mdToBlocks function with table support
const mdToBlocks = (markdown) => {
  const lines = markdown.split('\n')
  const blocks = []
  let inCode = false
  let codeLang = 'text'
  let codeBuffer = []

  // Table parsing variables
  let inTable = false
  let tableRows = []
  let tableHeaderSeparatorFound = false
  let tableWidth = 0

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]

    // Handle code blocks
    if (/^```/.test(line)) {
      if (!inCode) {
        inCode = true
        codeLang = line.replace(/^```/, '').trim() || 'text'
        codeBuffer = []
      } else {
        inCode = false
        blocks.push(BLOCK_TYPES.code(codeBuffer.join('\n'), codeLang))
      }
      continue
    }

    if (inCode) {
      codeBuffer.push(line)
      continue
    }

    // Table detection and parsing
    const isTableRow = line.trim().startsWith('|') && line.trim().endsWith('|')
    const isTableSeparator = /^\s*\|[\s\-\|:]+\|\s*$/.test(line)

    if (isTableRow) {
      // If this is the first row of a table
      if (!inTable) {
        inTable = true
        tableRows = []
        tableHeaderSeparatorFound = false
      }

      // Parse cells from the row
      const cells = line
        .trim()
        .split('|')
        .slice(1, -1) // Remove empty cells at start/end from the | chars
        .map(cell => cell.trim())

      tableWidth = Math.max(tableWidth, cells.length)

      if (!tableHeaderSeparatorFound) {
        // If the next line is a separator, this is a header row
        if (i + 1 < lines.length && /^\s*\|[\s\-\|:]+\|\s*$/.test(lines[i + 1])) {
          tableRows.push({
            isHeader: true,
            cells: cells
          })
        } else {
          // No separator = regular row
          tableRows.push({
            isHeader: false,
            cells: cells
          })
        }
      } else {
        // After separator = regular row
        tableRows.push({
          isHeader: false,
          cells: cells
        })
      }
      continue
    }

    // Handle table separator row - just mark that we found it
    if (isTableSeparator && inTable) {
      tableHeaderSeparatorFound = true
      continue
    }

    // If we were in a table but this line is not a table row, end the table
    if (inTable && !isTableRow && !isTableSeparator) {
      // Create table block
      const hasHeader = tableRows.length > 0 && tableRows[0].isHeader

      // Create table_row children blocks
      const tableBlock = {
        type: 'table',
        table: {
          table_width: tableWidth,
          has_column_header: hasHeader,
          has_row_header: false,
          children: tableRows.map(row => ({
            type: 'table_row',
            table_row: {
              cells: row.cells.map(cell => [{ 
                type: 'text', 
                text: { content: cell } 
              }])
            }
          }))
        }
      }

      blocks.push(tableBlock)

      inTable = false
      tableRows = []
      tableWidth = 0

      // Process the current line (non-table line)
      i--  // Step back to process this line again
      continue
    }

    // Regular markdown processing (non-table lines)
    if (/^#\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_1(line.replace(/^#\s+/, '')))
    else if (/^##\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_2(line.replace(/^##\s+/, '')))
    else if (/^###\s+/.test(line)) blocks.push(BLOCK_TYPES.heading_3(line.replace(/^###\s+/, '')))
    else if (/^-\s+\[ \]\s+/.test(line)) blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[ \]\s+/, ''), false))
    else if (/^-\s+\[x\]\s+/.test(line)) blocks.push(BLOCK_TYPES.to_do(line.replace(/^-\s+\[x\]\s+/, ''), true))
    else if (/^-\s+/.test(line)) blocks.push(BLOCK_TYPES.bulleted_list_item(line.replace(/^-\s+/, '')))
    else if (/^\d+\.\s+/.test(line)) blocks.push(BLOCK_TYPES.numbered_list_item(line.replace(/^\d+\.\s+/, '')))
    else if (/^>\s+/.test(line)) blocks.push(BLOCK_TYPES.quote(line.replace(/^>\s+/, '')))
    else if (/^---+$/.test(line)) blocks.push(BLOCK_TYPES.divider())
    else blocks.push(BLOCK_TYPES.paragraph(line))
  }

  // Handle case where a table is at the end of the document
  if (inTable) {
    const hasHeader = tableRows.length > 0 && tableRows[0].isHeader

    const tableBlock = {
      type: 'table',
      table: {
        table_width: tableWidth,
        has_column_header: hasHeader,
        has_row_header: false,
        children: tableRows.map(row => ({
          type: 'table_row',
          table_row: {
            cells: row.cells.map(cell => [{ 
              type: 'text', 
              text: { content: cell } 
            }])
          }
        }))
      }
    }

    blocks.push(tableBlock)
  }

  return blocks
}

