    else if (/^>\s+/.test(line)) blocks.push(BLOCK_TYPES.quote(line.replace(/^>\s+/, '')))
    else if (/^---+$/.test(line)) blocks.push(BLOCK_TYPES.divider())
    else blocks.push(BLOCK_TYPES.paragraph(line))
  }

  // Handle case where a table is at the end of the document
  if (inTable) {
    const hasHeader = tableRows.length > 0 && tableRows[0].isHeader;

    const tableData = {
      table_width: tableWidth,
      has_column_header: hasHeader,
      has_row_header: false,
      children: tableRows.map(row => ({
        type: 'table_row',
        table_row: {
          cells: row.cells.map(cell => [{ 
            type: 'text', 
            text: { content: cell } 
          }])
        }
      }))
    };

    blocks.push(BLOCK_TYPES.table(tableData));
  }

  return blocks
}

