// First, install the required packages:
// npm install markdown-it turndown

const MarkdownIt = require('markdown-it');
const TurndownService = require('turndown');
const { BLOCK_TYPES } = require('./block-types');

// Initialize the parsers
const md = new MarkdownIt({
  html: false,        // Disable HTML parsing for security
  linkify: true,      // Auto-convert URL-like text to links
  typographer: true,  // Enable smartquotes and other typographic replacements
});

// Initialize Turndown for HTML to Markdown conversion
const turndown = new TurndownService({
  headingStyle: 'atx',       // Use # style headings
  codeBlockStyle: 'fenced',  // Use ``` style code blocks
  emDelimiter: '*',          // Use * for italics
  strongDelimiter: '**'      // Use ** for bold
});

/**
 * Convert markdown to Notion blocks using markdown-it
 * @param {string} markdown - The markdown text to convert
 * @returns {Array} - Array of Notion blocks
 */
const mdToBlocks = (markdown) => {
  const blocks = [];

  // Parse the markdown into tokens
  const tokens = md.parse(markdown, {});

  // Variables to track the current state
  let currentBlock = null;
  let tableRows = [];
  let tableHeader = false;
  let inTable = false;
  let inCode = false;
  let codeContent = '';
  let codeLang = '';

  // Process each token
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    // Handle different token types
    switch (token.type) {
      case 'heading_open': {
        // Extract the heading level from the tag (h1, h2, h3, etc.)
        const level = parseInt(token.tag.slice(1));
        const contentToken = tokens[i + 1];

        if (contentToken && contentToken.type === 'inline') {
          const richText = convertInlineTokensToRichText(contentToken.children);

          // Create the appropriate heading block
          if (level === 1) {
            blocks.push({ type: 'heading_1', heading_1: { rich_text: richText } });
          } else if (level === 2) {
            blocks.push({ type: 'heading_2', heading_2: { rich_text: richText } });
          } else if (level === 3) {
            blocks.push({ type: 'heading_3', heading_3: { rich_text: richText } });
          } else {
            // For h4-h6, just use paragraph with bold text
            blocks.push({ 
              type: 'paragraph', 
              paragraph: { 
                rich_text: richText.map(rt => ({
                  ...rt,
                  annotations: {
                    ...rt.annotations,
                    bold: true
                  }
                }))
              } 
            });
          }
        }

        // Skip the content token since we've already processed it
        i++;
        break;
      }

      case 'paragraph_open': {
        const contentToken = tokens[i + 1];
        if (contentToken && contentToken.type === 'inline') {
          blocks.push({
            type: 'paragraph',
            paragraph: { rich_text: convertInlineTokensToRichText(contentToken.children) }
          });
        }

        // Skip the content token since we've already processed it
        i++;
        break;
      }

      case 'bullet_list_open': {
        // We'll handle list items individually
        break;
      }

      case 'list_item_open': {
        // Check if the next tokens indicate a todo item
        const isTodo = tokens[i + 1]?.type === 'paragraph_open' && 
                       tokens[i + 2]?.type === 'inline' && 
                       tokens[i + 2]?.content.startsWith('[ ] ') || 
                       tokens[i + 2]?.content.startsWith('[x] ');

        if (isTodo) {
          const contentToken = tokens[i + 2];
          const checked = contentToken.content.startsWith('[x] ');
          const text = contentToken.content.replace(/^\[[x ]\]\s+/, '');

          blocks.push({
            type: 'to_do',
            to_do: {
              rich_text: [{ type: 'text', text: { content: text } }],
              checked
            }
          });

          // Skip the processed tokens
          i += 3;
        } else {
          // Regular list item
          const contentToken = tokens[i + 2];
          if (contentToken && contentToken.type === 'inline') {
            blocks.push({
              type: 'bulleted_list_item',
              bulleted_list_item: { rich_text: convertInlineTokensToRichText(contentToken.children) }
            });
          }

          // Skip the processed tokens
          i += 3;
        }
        break;
      }

      case 'ordered_list_open': {
        // We'll handle list items individually
        break;
      }

      case 'fence': {
        // Code block with language specified
        blocks.push(BLOCK_TYPES.code(token.content, token.info || 'text'));
        break;
      }

      case 'code_block': {
        // Code block without language specified
        blocks.push(BLOCK_TYPES.code(token.content, 'text'));
        break;
      }

      case 'hr': {
        // Horizontal rule
        blocks.push(BLOCK_TYPES.divider());
        break;
      }

      case 'blockquote_open': {
        // Find the content within the blockquote
        const contentToken = tokens[i + 1]?.type === 'paragraph_open' ? tokens[i + 2] : null;

        if (contentToken && contentToken.type === 'inline') {
          blocks.push({
            type: 'quote',
            quote: { rich_text: convertInlineTokensToRichText(contentToken.children) }
          });
        }

        // Skip processed tokens
        i += 3;
        break;
      }

      case 'table_open': {
        // Start of a table
        inTable = true;
        tableRows = [];
        tableHeader = false;
        break;
      }

      case 'thead_open': {
        // Table header section
        tableHeader = true;
        break;
      }

      case 'tr_open': {
        // Start of a table row
        const rowCells = [];

        // Process the cells in this row
        let j = i + 1;
        while (j < tokens.length && tokens[j].type !== 'tr_close') {
          if (tokens[j].type === 'th_open' || tokens[j].type === 'td_open') {
            // Found a cell, get the content
            const cellContentToken = tokens[j + 1];

            if (cellContentToken && cellContentToken.type === 'inline') {
              rowCells.push(convertInlineTokensToRichText(cellContentToken.children));
            } else {
              // Empty cell
              rowCells.push([{ type: 'text', text: { content: '' } }]);
            }

            // Skip to end of cell
            while (j < tokens.length && 
                  tokens[j].type !== 'th_close' && 
                  tokens[j].type !== 'td_close') {
              j++;
            }
          }
          j++;
        }

        // Add the row to our collection
        tableRows.push({
          isHeader: tableHeader,
          cells: rowCells
        });

        // Skip to end of row
        i = j;
        break;
      }

      case 'tbody_open':
      case 'thead_close': {
        // End of header section
        tableHeader = false;
        break;
      }

      case 'table_close': {
        // End of the table, create the table block
        if (tableRows.length > 0) {
          const hasHeader = tableRows.length > 0 && tableRows[0].isHeader;
          const tableWidth = Math.max(...tableRows.map(row => row.cells.length));

          const tableData = {
            table_width: tableWidth,
            has_column_header: hasHeader,
            has_row_header: false,
            children: tableRows.map(row => ({
              type: 'table_row',
              table_row: {
                cells: row.cells
              }
            }))
          };

          blocks.push(BLOCK_TYPES.table(tableData));
        }

        inTable = false;
        break;
      }
    }
  }

  return blocks;
};

/**
 * Convert markdown-it inline tokens to Notion rich text objects
 * @param {Array} tokens - Array of markdown-it inline tokens
 * @returns {Array} - Array of Notion rich text objects
 */
function convertInlineTokensToRichText(tokens) {
  const richTextArray = [];

  if (!tokens || !Array.isArray(tokens)) {
    return richTextArray;
  }

  for (const token of tokens) {
    if (token.type === 'text') {
      // Plain text
      richTextArray.push({
        type: 'text',
        text: { content: token.content },
        annotations: {
          bold: false,
          italic: false,
          strikethrough: false,
          underline: false,
          code: false,
          color: 'default'
        }
      });
    } else if (token.type === 'strong_open') {
      // Bold text - mark the next text token as bold
      const textToken = tokens[tokens.indexOf(token) + 1];
      if (textToken && textToken.type === 'text') {
        richTextArray.push({
          type: 'text',
          text: { content: textToken.content },
          annotations: {
            bold: true,
            italic: false,
            strikethrough: false,
            underline: false,
            code: false,
            color: 'default'
          }
        });
      }
    } else if (token.type === 'em_open') {
      // Italic text - mark the next text token as italic
      const textToken = tokens[tokens.indexOf(token) + 1];
      if (textToken && textToken.type === 'text') {
        richTextArray.push({
          type: 'text',
          text: { content: textToken.content },
          annotations: {
            bold: false,
            italic: true,
            strikethrough: false,
            underline: false,
            code: false,
            color: 'default'
          }
        });
      }
    } else if (token.type === 's_open') {
      // Strikethrough text - mark the next text token as strikethrough
      const textToken = tokens[tokens.indexOf(token) + 1];
      if (textToken && textToken.type === 'text') {
        richTextArray.push({
          type: 'text',
          text: { content: textToken.content },
          annotations: {
            bold: false,
            italic: false,
            strikethrough: true,
            underline: false,
            code: false,
            color: 'default'
          }
        });
      }
    } else if (token.type === 'code_inline') {
      // Inline code
      richTextArray.push({
        type: 'text',
        text: { content: token.content },
        annotations: {
          bold: false,
          italic: false,
          strikethrough: false,
          underline: false,
          code: true,
          color: 'default'
        }
      });
    } else if (token.type === 'link_open') {
      // Link - find the text content and URL
      const textToken = tokens[tokens.indexOf(token) + 1];
      const urlAttr = token.attrs.find(attr => attr[0] === 'href');

      if (textToken && textToken.type === 'text' && urlAttr) {
        richTextArray.push({
          type: 'text',
          text: { 
            content: textToken.content,
            link: { url: urlAttr[1] }
          },
          annotations: {
            bold: false,
            italic: false,
            strikethrough: false,
            underline: false,
            code: false,
            color: 'default'
          }
        });
      }
    }
  }

  return richTextArray;
}

/**
 * Convert Notion blocks to Markdown
 * @param {Array} blocks - Array of Notion blocks
 * @returns {string} - Markdown representation
 */
const blocksToMd = (blocks) => {
  // Array to collect HTML fragments
  const htmlFragments = [];

  for (const block of blocks) {
    switch (block.type) {
      case 'heading_1': {
        const content = richTextToHtml(block.heading_1.rich_text);
        htmlFragments.push(`<h1>${content}</h1>`);
        break;
      }
      case 'heading_2': {
        const content = richTextToHtml(block.heading_2.rich_text);
        htmlFragments.push(`<h2>${content}</h2>`);
        break;
      }
      case 'heading_3': {
        const content = richTextToHtml(block.heading_3.rich_text);
        htmlFragments.push(`<h3>${content}</h3>`);
        break;
      }
      case 'paragraph': {
        const content = richTextToHtml(block.paragraph.rich_text);
        if (content) {
          htmlFragments.push(`<p>${content}</p>`);
        } else {
          htmlFragments.push('<p></p>');
        }
        break;
      }
      case 'bulleted_list_item': {
        const content = richTextToHtml(block.bulleted_list_item.rich_text);
        htmlFragments.push(`<ul><li>${content}</li></ul>`);
        break;
      }
      case 'numbered_list_item': {
        const content = richTextToHtml(block.numbered_list_item.rich_text);
        htmlFragments.push(`<ol><li>${content}</li></ol>`);
        break;
      }
      case 'to_do': {
        const content = richTextToHtml(block.to_do.rich_text);
        const checked = block.to_do.checked;
        htmlFragments.push(`<ul><li>${checked ? '[x]' : '[ ]'} ${content}</li></ul>`);
        break;
      }
      case 'quote': {
        const content = richTextToHtml(block.quote.rich_text);
        htmlFragments.push(`<blockquote>${content}</blockquote>`);
        break;
      }
      case 'code': {
        const content = richTextToHtml(block.code.rich_text);
        const language = block.code.language || '';
        htmlFragments.push(`<pre><code class="language-${language}">${content}</code></pre>`);
        break;
      }
      case 'divider': {
        htmlFragments.push('<hr>');
        break;
      }
      case 'table': {
        // Start table
        let tableHtml = '<table>';

        // Process each row
        if (block.table.children && Array.isArray(block.table.children)) {
          const hasHeader = block.table.has_column_header;

          block.table.children.forEach((row, rowIndex) => {
            if (!row.table_row || !Array.isArray(row.table_row.cells)) return;

            const isHeader = hasHeader && rowIndex === 0;
            tableHtml += '<tr>';

            // Process cells
            row.table_row.cells.forEach(cell => {
              const cellTag = isHeader ? 'th' : 'td';
              const cellContent = Array.isArray(cell) 
                ? cell.map(item => richTextToHtml([item])).join('') 
                : '';

              tableHtml += `<${cellTag}>${cellContent}</${cellTag}>`;
            });

            tableHtml += '</tr>';
          });
        }

        // Close table
        tableHtml += '</table>';
        htmlFragments.push(tableHtml);
        break;
      }
      case 'toggle': {
        const summary = richTextToHtml(block.toggle.rich_text);
        htmlFragments.push(`<details><summary>${summary}</summary></details>`);
        break;
      }
      case 'callout': {
        const content = richTextToHtml(block.callout.rich_text);
        const emoji = block.callout.icon?.emoji || '💡';
        htmlFragments.push(`<div class="callout">${emoji} ${content}</div>`);
        break;
      }
      default:
        // For unsupported blocks, try to extract any text content
        const richText = block[block.type]?.rich_text;
        if (Array.isArray(richText)) {
          const content = richTextToHtml(richText);
          if (content) {
            htmlFragments.push(`<p>${content}</p>`);
          }
        }
    }
  }

  // Convert HTML to Markdown
  const html = htmlFragments.join('\n');
  return turndown.turndown(html);
};

/**
 * Convert Notion rich text to HTML
 * @param {Array} richText - Array of Notion rich text objects
 * @returns {string} - HTML representation
 */
function richTextToHtml(richText) {
  if (!richText || !Array.isArray(richText)) {
    return '';
  }

  return richText.map(rt => {
    if (!rt || rt.type !== 'text') return '';

    let content = rt.text.content || '';

    // Escape HTML special characters
    content = content
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');

    // Apply annotations
    if (rt.annotations) {
      if (rt.annotations.bold) {
        content = `<strong>${content}</strong>`;
      }
      if (rt.annotations.italic) {
        content = `<em>${content}</em>`;
      }
      if (rt.annotations.strikethrough) {
        content = `<s>${content}</s>`;
      }
      if (rt.annotations.underline) {
        content = `<u>${content}</u>`;
      }
      if (rt.annotations.code) {
        content = `<code>${content}</code>`;
      }
    }

    // Handle links
    if (rt.text.link) {
      content = `<a href="${rt.text.link.url}">${content}</a>`;
    }

    return content;
  }).join('');
}

module.exports = {
  mdToBlocks,
  blocksToMd
};

