// health-routes.js
const express = require('express');
const router = express.Router();
const notionApi = require('./notion-api');
const os = require('os');
const axios = require('axios');

// Utility function to get basic server health metrics
const getServerHealth = () => {
  return {
    status: 'ok',
    timestamp: new Date().toISOString(),
    hostname: os.hostname(),
    uptime: process.uptime(),
    memory: {
      free: os.freemem(),
      total: os.totalmem(),
      usage: process.memoryUsage()
    },
    cpu: {
      load: os.loadavg(),
      cores: os.cpus().length
    },
    platform: process.platform,
    nodejs: {
      version: process.version,
      env: process.env.NODE_ENV || 'development'
    }
  };
};

// Utility function to check Notion API health
const getNotionHealth = async () => {
  const notionHealth = {
    status: 'unknown',
    tokenConfigured: !!process.env.NOTION_TOKEN,
    timestamp: new Date().toISOString()
  };

  if (!notionHealth.tokenConfigured) {
    notionHealth.status = 'not_configured';
    return notionHealth;
  }

  try {
    // Use a lightweight API call to verify Notion connection
    const response = await notionApi.search('', { page_size: 1 });

    notionHealth.status = 'ok';
    notionHealth.apiVersion = '2022-06-28';

    // Check if databases are configured
    notionHealth.databases = {
      PROJECT_TRACKER: !!process.env.PROJECT_TRACKER,
      GPT_MEMORY_DB: !!process.env.GPT_MEMORY_DB
    };

    // Check parent page
    notionHealth.parentPage = {
      configured: !!process.env.NOTION_PARENT_PAGE_ID
    };

    if (notionHealth.parentPage.configured) {
      try {
        await notionApi.retrievePage(process.env.NOTION_PARENT_PAGE_ID);
        notionHealth.parentPage.status = 'ok';
      } catch (err) {
        notionHealth.parentPage.status = 'error';
        notionHealth.parentPage.error = err.message;
      }
    }
  } catch (err) {
    notionHealth.status = 'error';
    notionHealth.error = err.message;
  }

  return notionHealth;
};

// Utility function to check GitHub API health
const getGithubHealth = async () => {
  const githubHealth = {
    status: 'unknown',
    tokenConfigured: !!process.env.GITHUB_TOKEN,
    timestamp: new Date().toISOString()
  };

  if (!githubHealth.tokenConfigured) {
    githubHealth.status = 'not_configured';
    return githubHealth;
  }

  try {
    // Check GitHub API status
    const response = await axios.get('https://api.github.com/rate_limit', {
      headers: {
        'Authorization': `token ${process.env.GITHUB_TOKEN}`,
        'Accept': 'application/vnd.github.v3+json'
      }
    });

    githubHealth.status = 'ok';
    githubHealth.rateLimit = {
      limit: response.data.rate.limit,
      remaining: response.data.rate.remaining,
      reset: new Date(response.data.rate.reset * 1000).toISOString()
    };

    // Check repository access if configured
    if (process.env.GITHUB_REPO) {
      try {
        const [owner, repo] = process.env.GITHUB_REPO.split('/');
        const repoResponse = await axios.get(`https://api.github.com/repos/${owner}/${repo}`, {
          headers: {
            'Authorization': `token ${process.env.GITHUB_TOKEN}`,
            'Accept': 'application/vnd.github.v3+json'
          }
        });

        githubHealth.repository = {
          status: 'ok',
          name: repoResponse.data.full_name,
          private: repoResponse.data.private
        };
      } catch (err) {
        githubHealth.repository = {
          status: 'error',
          error: err.message
        };
      }
    }
  } catch (err) {
    githubHealth.status = 'error';
    githubHealth.error = err.message;
  }

  return githubHealth;
};

/**
 * GET /status
 * Basic server health check
 */
router.get('/status', (req, res) => {
  try {
    const health = getServerHealth();
    return res.json(health);
  } catch (err) {
    console.error('Server health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * GET /statusNotion
 * Notion API health check
 */
router.get('/statusNotion', async (req, res) => {
  try {
    const notionHealth = await getNotionHealth();

    // Determine status code based on health status
    if (notionHealth.status === 'ok') {
      return res.json(notionHealth);
    } else if (notionHealth.status === 'not_configured') {
      return res.status(503).json(notionHealth); // Service Unavailable
    } else {
      return res.status(500).json(notionHealth); // Internal Server Error
    }
  } catch (err) {
    console.error('Notion health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * GET /statusGithub
 * GitHub API health check
 */
router.get('/statusGithub', async (req, res) => {
  try {
    const githubHealth = await getGithubHealth();

    // Determine status code based on health status
    if (githubHealth.status === 'ok') {
      return res.json(githubHealth);
    } else if (githubHealth.status === 'not_configured') {
      return res.status(503).json(githubHealth); // Service Unavailable
    } else {
      return res.status(500).json(githubHealth); // Internal Server Error
    }
  } catch (err) {
    console.error('GitHub health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * GET /statusComplete
 * Complete health check for all systems
 */
router.get('/statusComplete', async (req, res) => {
  try {
    // Collect health data from all systems
    const serverHealth = getServerHealth();
    const notionHealth = await getNotionHealth();
    const githubHealth = await getGithubHealth();

    // Combine into a comprehensive health report
    const completeHealth = {
      status: 'ok', // Will be updated based on component health
      timestamp: new Date().toISOString(),
      server: serverHealth,
      notion: notionHealth,
      github: githubHealth
    };

    // Determine overall status based on component status
    if (notionHealth.status === 'error' || githubHealth.status === 'error') {
      completeHealth.status = 'degraded';
    }

    if (notionHealth.status === 'error' && githubHealth.status === 'error') {
      completeHealth.status = 'critical';
    }

    // Return appropriate status code
    if (completeHealth.status === 'ok') {
      return res.json(completeHealth);
    } else if (completeHealth.status === 'degraded') {
      return res.status(207).json(completeHealth); // Multi-Status
    } else {
      return res.status(500).json(completeHealth); // Internal Server Error
    }
  } catch (err) {
    console.error('Complete health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

