const express = require('express');
const app = express();

// Import your existing routes
const databaseRoutes = require('./notion/database-routes');
const memoryRoutes = require('./notion/memory-routes');
const pageRoutes = require('./notion/page-routes');
const schemaRoutes = require('./notion/schema-routes');

// Import the new health check routes
const healthRoutes = require('./health-routes');

