app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Register Notion routes with appropriate prefixes
app.use('/notion/databases', databaseRoutes);
app.use('/notion/memory', memoryRoutes);
app.use('/notion/pages', pageRoutes);
app.use('/notion/schema', schemaRoutes);

// Register health check routes at the root level for easier access
app.use('/', healthRoutes);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'An unexpected error occurred' : err.message
