      } catch (err) {
        console.error(`Error reading entry:`, err);
        return res.status(500).json({ 
          error: 'Failed to read entry',
          message: err.message
        });
      }
    } catch (err) {
      console.error(`Error in ${routeNames.read}:`, err);
      next(err);
    }
  });

  return router;
};

