    const { results } = await notionApi.search(title)

    let pageTitle = title
    // If we found pages with similar titles, create a versioned title
    if (results && results.length > 0) {
      // Simple versioning logic - find the highest number and increment
      const regex = new RegExp(`^${title}\\s+(\\d+)$`, 'i')
      let highestVersion = 0

      results.forEach(page => {
        // Get the title for this page
        let pageTitle = ''
        try {
          // Find the title property in the page
          const titleProp = Object.values(page.properties || {}).find(p => p.type === 'title')
          if (titleProp?.title?.length) {
            pageTitle = titleProp.title.map(t => t.plain_text || '').join('')
          }
        } catch (err) {
          // Skip this page if we can't extract the title
        }

        // Check if this title follows our versioning pattern
        const match = pageTitle.match(regex)
        if (match && match[1]) {
          const version = parseInt(match[1], 10)
          if (version > highestVersion) {
            highestVersion = version
          }
        }
      })

      // Create a new versioned title
      if (highestVersion > 0) {
        pageTitle = `${title} ${highestVersion + 1}`
      }
    }

    // Create the page with the final title
    const blocks = await smartTextToBlocks(content)
    const payload = {
      parent: { type: 'page_id', page_id: PARENT_PAGE_ID },
      properties: {
        title: [{ type: 'text', text: { content: pageTitle } }],
        ...properties
      },
      children: blocks
    }

    const page = await notionApi.createPage(payload)
    cache.invalidate(title)
    res.json({ id: page.id, title: pageTitle })
  } catch (err) {
    next(err)
  }
})

// Update a standalone page by ID or title
router.patch('/updatepage', async (req, res, next) => {
  try {
    const { idOrTitle, properties, children } = req.body
    if (!idOrTitle) return res.status(400).json({ error: 'Missing idOrTitle' })

    let page = null

    // First check if it's an ID
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(idOrTitle)) {
      try {
        page = await notionApi.retrievePage(idOrTitle)
      } catch (err) {
        // If retrieving by ID fails, we'll try to search by title below
      }
    }

    // If we didn't find by ID, search by title
    if (!page) {
      const { results } = await notionApi.search(idOrTitle)
      page = results.find(p => 
        p.object === 'page' && 
        p.parent?.type !== 'database_id'
      )
    }

    if (!page) return res.status(404).json({ error: 'Page not found' })

    const results = []
    if (properties) {
      const updated = await notionApi.updatePage(page.id, properties)
      results.push({ type: 'properties', id: updated.id })
    }
    if (children) {
      const content = typeof children === 'string' ? await smartTextToBlocks(children) : children
      const appended = await notionApi.appendBlockToPage(page.id, content)
      results.push({ type: 'blocks', count: appended?.results?.length || 0 })
    }

    cache.invalidate(idOrTitle)
    res.json({ updated: true, id: page.id, results })
  } catch (err) {
    next(err)
  }
})

