      }
    }

    // If we didn't find by ID, search by title
    if (!page) {
      const { results } = await notionApi.search(idOrTitle)
      page = results.find(p => 
        p.object === 'page' && 
        p.parent?.type !== 'database_id'
      )
    }

    if (!page) return res.status(404).json({ error: 'Page not found' })

    const archived = await notionApi.deleteBlock(page.id)
    cache.invalidate(idOrTitle)
    res.json({ deleted: true, id: archived.id })
  } catch (err) {
    next(err)
  }
})

// Read content of a standalone page
router.get('/readpage', async (req, res, next) => {
  try {
    const { idOrTitle, format = 'blocks' } = req.query // format can be: blocks, markdown, text, html, pdf
    if (!idOrTitle) return res.status(400).json({ error: 'Missing idOrTitle' })

    let page = null

    // First check if it's an ID
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(idOrTitle)) {
      try {
        page = await notionApi.retrievePage(idOrTitle)
      } catch (err) {
        // If retrieving by ID fails, we'll try to search by title below
      }
    }

    // If we didn't find by ID, search by title
    if (!page) {
      const { results } = await notionApi.search(idOrTitle)
      page = results.find(p => 
        p.object === 'page' && 
        p.parent?.type !== 'database_id'
      )
    }

    if (!page) return res.status(404).json({ error: 'Page not found' })

    const blocks = await notionApi.getBlockChildren(page.id)
    const title = await pageUtils.extractPageTitle(page)
    const safeName = title.replace(/[^a-z0-9]/gi, '_').toLowerCase()

    if (format === 'markdown') {
      res.setHeader('Content-Type', 'text/markdown')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.md\"`)
      return res.send(blocksToMd(blocks))
    }
    if (format === 'text') {
      res.setHeader('Content-Type', 'text/plain')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.txt\"`)
      return res.send(convertBlocksToText(blocks))
    }
    if (format === 'html') {
      res.setHeader('Content-Type', 'text/html')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.html\"`)
      return res.send(marked.parse(blocksToMd(blocks)))
    }

    if (format === 'pdf') {
      const pdfDoc = await PDFDocument.create()
      const page = pdfDoc.addPage()
      const text = convertBlocksToText(blocks)
      page.drawText(text, { x: 50, y: page.getHeight() - 50, size: 12 })
      const pdfBytes = await pdfDoc.save()
      res.setHeader('Content-Type', 'application/pdf')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.pdf\"`)
      res.send(Buffer.from(pdfBytes))
      return
    }

    res.json({ id: page.id, blocks })
  } catch (err) {
    next(err)
  }
})

// List standalone pages only (exclude DB entries)
router.get('/listpages', async (req, res, next) => {
  try {
    const query = await notionApi.search('')
    const basePages = await Promise.all(
      query.results
        .filter(p => p.object === 'page' && p.parent?.type !== 'database_id')
        .map(async p => ({
          id: p.id,
          title: await pageUtils.extractPageTitle(p) || `Untitled (${p.id.slice(0, 8)})`,
          parent: p.parent?.page_id || null,
          type: 'page',
          url: p.url || null
        }))
    )

    res.json({ success: true, count: basePages.length, pages: basePages })
  } catch (err) {
    next(err)
  }
})

module.exports = router

