router.get('/readpage', async (req, res, next) => {
  try {
    const { idOrTitle, format = 'blocks' } = req.query // format can be: blocks, markdown, text, html, pdf
    if (!idOrTitle) return res.status(400).json({ error: 'Missing idOrTitle' })

    const page = await pageUtils.findPageAcrossWorkspace(idOrTitle)
    if (!page) return res.status(404).json({ error: 'Page not found' })

    // Get the blocks for the page
    const blocksResponse = await notionApi.getBlockChildren(page.id)

    // Extract the results array from the response
    const blocks = blocksResponse.results || []

    // Get the page title
    const title = await pageUtils.extractPageTitle(page)
    const safeName = title.replace(/[^a-z0-9]/gi, '_').toLowerCase()

    if (format === 'markdown') {
      res.setHeader('Content-Type', 'text/markdown')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.md\"`)
      return res.send(blocksToMd(blocks))
    }

    if (format === 'text') {
      res.setHeader('Content-Type', 'text/plain')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.txt\"`)
      return res.send(convertBlocksToText(blocks))
    }

    if (format === 'html') {
      res.setHeader('Content-Type', 'text/html')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.html\"`)
      return res.send(marked.parse(blocksToMd(blocks)))
    }

    if (format === 'pdf') {
      const pdfDoc = await PDFDocument.create()
      const pdfPage = pdfDoc.addPage()
      const text = convertBlocksToText(blocks)
      pdfPage.drawText(text, { x: 50, y: pdfPage.getHeight() - 50, size: 12 })
      const pdfBytes = await pdfDoc.save()
      res.setHeader('Content-Type', 'application/pdf')
      res.setHeader('Content-Disposition', `attachment; filename=\"${safeName}.pdf\"`)
      res.send(Buffer.from(pdfBytes))
      return
    }

    // Default format: blocks
    res.json({ id: page.id, blocks: blocksResponse })
  } catch (err) {
    next(err)
  }
})

