          }

          // Get database schema to map the field name to the correct property
          const schema = await schemaDetection.getDatabaseSchema(DB_ID);

          // Try to find the property that matches the key (case insensitive)
          const matchedKey = Object.keys(schema).find(
            k => k.toLowerCase() === key.toLowerCase()
          );

          if (!matchedKey) {
            return res.status(400).json({ 
              error: 'Invalid field name', 
              message: `Field "${key}" not found in database schema`
            });
          }

          // Format the value based on the property type
          const propType = schema[matchedKey].type;
          let formattedValue;

          switch (propType) {
            case 'rich_text':
              formattedValue = { 
                rich_text: [{ text: { content: String(value) } }] 
              };
              break;
            case 'select':
              formattedValue = { 
                select: { name: String(value) } 
