    const DB_ID = process.env[database];

    if (!DB_ID) {
      return res.status(400).json({
        error: `Unknown database: ${database}`,
        message: `Ensure ${database} is defined as an environment variable`
      });
    }

    const { idOrTitle, fields } = req.body;

    if (!idOrTitle) {
      return res.status(400).json({ 
        error: 'Missing identifier', 
        message: 'The idOrTitle field is required to identify the entry to update'
      });
    }

    if (!fields || Object.keys(fields).length === 0) {
      return res.status(400).json({ 
        error: 'Missing data', 
        message: 'No fields provided to update'
      });
    }

    // Find the page
    const page = await pageUtils.findPage(DB_ID, idOrTitle);

    if (!page) {
      return res.status(404).json({ 
        error: 'Entry not found',
        message: `No entry found with identifier: ${idOrTitle}`
      });
    }

    // Map fields to Notion properties
    const schema = await schemaDetection.getDatabaseSchema(DB_ID);
    const properties = {};

    for (const [fieldName, fieldValue] of Object.entries(fields)) {
      // Skip null or undefined values
      if (fieldValue === null || fieldValue === undefined) continue;

      // Try to match the field name with a property in the schema (case-insensitive)
      const matchedKey = Object.keys(schema).find(
        k => k.toLowerCase() === fieldName.toLowerCase()
      );

      if (matchedKey) {
        const propType = schema[matchedKey].type;

        switch (propType) {
          case 'title':
            properties[matchedKey] = { 
              title: [{ text: { content: String(fieldValue) } }] 
            };
            break;
          case 'rich_text':
            properties[matchedKey] = { 
              rich_text: [{ text: { content: String(fieldValue) } }] 
            };
            break;
          case 'select':
            properties[matchedKey] = { 
              select: { name: String(fieldValue) } 
            };
            break;
          case 'multi_select':
            // Handle both array and single values
            const values = Array.isArray(fieldValue) ? fieldValue : [fieldValue];
            properties[matchedKey] = { 
              multi_select: values.map(v => ({ name: String(v) }))
            };
            break;
          case 'date':
            let dateValue = fieldValue;
            if (fieldValue instanceof Date) {
              dateValue = fieldValue.toISOString();
            }
            properties[matchedKey] = { 
              date: { start: dateValue } 
            };
            break;
          case 'number':
            const numValue = Number(fieldValue);
            if (!isNaN(numValue)) {
              properties[matchedKey] = { number: numValue };
            }
            break;
          case 'checkbox':
            const boolValue = typeof fieldValue === 'string' 
              ? fieldValue.toLowerCase() === 'true' || fieldValue.toLowerCase() === 'yes'
              : Boolean(fieldValue);
            properties[matchedKey] = { checkbox: boolValue };
            break;
          // Add other property types as needed...
          default:
            console.warn(`Unsupported property type ${propType} for ${matchedKey}`);
        }
      } else {
        console.warn(`No matching property found for field: ${fieldName}`);
      }
    }

    // Update the page
    const updated = await notionApi.updatePage(page.id, properties);

    // Format properties for response
    const formattedProperties = {};

    for (const [propName, propData] of Object.entries(updated.properties)) {
      if (properties[propName]) {  // Only include updated properties
        formattedProperties[propName] = extractPropertyValue(propData);
      }
    }

    return res.json({
      success: true,
      updated: true,
      id: updated.id,
      properties: formattedProperties
    });
  } catch (err) {
    console.error(`Error in ${routeNames.update}structured:`, err);
    next(err);
  }
});

