const express = require('express');
const axios = require('axios');
const { ChromaClient } = require('chromadb');
const { OpenAI } = require('openai');
const uuid = require('uuid');
const { spawn } = require('child_process');
const cors = require('cors');
require('dotenv').config();

// Initialize Express app
const app = express();
app.use(express.json());
app.use(cors());

// Environment variables
const PORT = process.env.PORT || 3000;
const RESTART_SECRET = process.env.RESTART_SECRET || 'default-secret-key';

// Initialize OpenAI client
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

// Initialize ChromaDB client
const chromaClient = new ChromaClient();
let therapyCollection;

// Initialize the collection when app starts
async function initializeChroma() {
  try {
    // Create or get existing collection
    therapyCollection = await chromaClient.getOrCreateCollection({
      name: "therapy_sessions",
      metadata: { "description": "Therapy session memory for GPT" }
    });
    console.log("ChromaDB collection initialized");
  } catch (error) {
    console.error("Failed to initialize ChromaDB:", error);
  }
}

// Store interaction in ChromaDB
async function addInteractionToMemory(userId, userMessage, assistantResponse) {
  try {
    // Generate embedding for the message
    const embeddingResponse = await openai.embeddings.create({
      input: userMessage,
      model: "text-embedding-3-small"
    });

    const embedding = embeddingResponse.data[0].embedding;

    // Store in ChromaDB
    await therapyCollection.add({
      ids: [uuid.v4()],
      embeddings: [embedding],
      metadatas: [{
        userId: userId,
        timestamp: new Date().toISOString(),
        userMessage: userMessage,
        assistantResponse: assistantResponse
      }],
      documents: [userMessage]
    });

    console.log("Added interaction to memory");
  } catch (error) {
    console.error("Failed to add to memory:", error);
  }
}
```

