// Retrieve relevant history from ChromaDB
async function getRelevantHistory(userId, currentMessage, limit = 5) {
  try {
    // Generate embedding for current message
    const embeddingResponse = await openai.embeddings.create({
      input: currentMessage,
      model: "text-embedding-3-small"
    });

    const currentEmbedding = embeddingResponse.data[0].embedding;

    // Query ChromaDB for similar past interactions
    const results = await therapyCollection.query({
      queryEmbeddings: [currentEmbedding],
      nResults: limit,
      where: { userId: userId }
    });

    return results;
  } catch (error) {
    console.error("Failed to get history:", error);
    return null;
  }
}

// Custom GPT API endpoint
app.post('/api/chat', async (req, res) => {
  try {
    const { userId, message } = req.body;

    if (!userId || !message) {
      return res.status(400).json({ error: 'userId and message are required' });
    }

    console.log(`Received message from user ${userId}: ${message}`);

    // Get relevant history
    const history = await getRelevantHistory(userId, message);

    // Construct context from history
    let context = "";
    if (history && history.metadatas && history.metadatas.length > 0) {
      context = "Previous relevant conversations:\n";
      for (let i = 0; i < history.metadatas[0].length; i++) {
        const metadata = history.metadatas[0][i];
        context += `Date: ${metadata.timestamp}\n`;
        context += `User: ${metadata.userMessage}\n`;
        context += `Assistant: ${metadata.assistantResponse}\n\n`;
      }
    }

    // Generate response with context
    const completion = await openai.chat.completions.create({
      model: "gpt-4-turbo",
      messages: [
        { 
          role: "system", 
          content: "You are a therapeutic assistant with memory of past conversations. " +
                   "Reference past discussions when appropriate and track progress over time. " +
                   "Be empathetic and supportive." + 
                   (context ? "\n\n" + context : "")
        },
        { role: "user", content: message }
      ]
    });

    const assistantResponse = completion.choices[0].message.content;

    // Add the new interaction to memory
    await addInteractionToMemory(userId, message, assistantResponse);

    // Send response
    res.json({ response: assistantResponse });
    console.log("Sent response to user");

  } catch (error) {
    console.error('Error processing request:', error);
    res.status(500).json({ error: 'Failed to process request' });
  }
});
