4. **Add JavaScript for Log Viewer**:
   - Continue with this code:

```html
    <script>
        // DOM Elements
        const connectionForm = document.getElementById('connectionForm');
        const mainApp = document.getElementById('mainApp');
        const serverUrlInput = document.getElementById('serverUrl');
        const secretKeyInput = document.getElementById('secretKey');
        const connectButton = document.getElementById('connectButton');
        const disconnectButton = document.getElementById('disconnectButton');
        const connectionStatus = document.getElementById('connectionStatus');
        const logsContainer = document.getElementById('logsContainer');
        const clearButton = document.getElementById('clearButton');
        const searchInput = document.getElementById('searchInput');
        const showErrorCheckbox = document.getElementById('showError');
        const showWarnCheckbox = document.getElementById('showWarn');
        const showInfoCheckbox = document.getElementById('showInfo');
        const showOtherCheckbox = document.getElementById('showOther');
        const autoscrollCheckbox = document.getElementById('autoscroll');
        const logCount = document.getElementById('logCount');
        const serverInfo = document.getElementById('serverInfo');

        // Variables
        let eventSource = null;
        let logEntries = [];
        let filteredEntries = [];
        let searchTerm = '';
        let reconnectAttempts = 0;
        let reconnectInterval = null;

        // Load saved connection details from localStorage
        if (localStorage.getItem('serverUrl')) {
            serverUrlInput.value = localStorage.getItem('serverUrl');
        }
        if (localStorage.getItem('secretKey')) {
            secretKeyInput.value = localStorage.getItem('secretKey');
        }

        // Connect to log stream
        connectButton.addEventListener('click', connect);

        // Disconnect from log stream
        disconnectButton.addEventListener('click', disconnect);

        // Clear logs
        clearButton.addEventListener('click', () => {
            logEntries = [];
            updateFilteredLogs();
            renderLogs();
        });

        // Search functionality
        searchInput.addEventListener('input', (e) => {
            searchTerm = e.target.value.toLowerCase();
            updateFilteredLogs();
            renderLogs();
        });

        // Filtering functionality
        showErrorCheckbox.addEventListener('change', updateLogsVisibility);
        showWarnCheckbox.addEventListener('change', updateLogsVisibility);
        showInfoCheckbox.addEventListener('change', updateLogsVisibility);
        showOtherCheckbox.addEventListener('change', updateLogsVisibility);

        function connect() {
            const serverUrl = serverUrlInput.value.trim();
            const secretKey = secretKeyInput.value.trim();

            if (!serverUrl || !secretKey) {
                alert('Please enter both server URL and secret key');
                return;
            }

            // Save connection details to localStorage
            localStorage.setItem('serverUrl', serverUrl);
            localStorage.setItem('secretKey', secretKey);

            // Show main app and hide connection form
            connectionForm.classList.add('hidden');
            mainApp.classList.remove('hidden');

            // Update status
            updateConnectionStatus('connecting');

            // Create URL for log endpoint
            const logUrl = `${serverUrl}/api/admin/logs?key=${encodeURIComponent(secretKey)}`;

            // Close any existing connection
            if (eventSource) {
                eventSource.close();
            }

            // Connect to server logs
            try {
                eventSource = new EventSource(logUrl);

                eventSource.onopen = () => {
                    updateConnectionStatus('connected');
                    reconnectAttempts = 0;
                    if (reconnectInterval) {
                        clearInterval(reconnectInterval);
                        reconnectInterval = null;
                    }
                    serverInfo.textContent = `Connected to ${new URL(serverUrl).hostname}`;
                };

                eventSource.onmessage = (event) => {
                    const timestamp = new Date().toISOString();
                    const logText = event.data;

                    // Determine log type
                    let logType = 'other';
                    if (logText.match(/\b(error|exception|fail|failed)\b/i)) {
                        logType = 'error';
                    } else if (logText.match(/\b(warn|warning)\b/i)) {
                        logType = 'warn';
                    } else if (logText.match(/\b(info|information)\b/i)) {
                        logType = 'info';
                    } else if (logText.match(/\b(success|successful|succeeded)\b/i)) {
                        logType = 'success';
                    }

                    // Add log entry
                    const entry = { timestamp, text: logText, type: logType, visible: true };
                    logEntries.push(entry);

                    // Limit log entries to prevent browser slowdown
                    if (logEntries.length > 1000) {
                        logEntries.shift();
                    }

                    updateFilteredLogs();
                    renderLogs();
                };

                eventSource.onerror = () => {
                    updateConnectionStatus('disconnected');

                    // Auto-reconnect
                    if (!reconnectInterval) {
                        reconnectAttempts++;
                        const delay = Math.min(30000, 1000 * Math.pow(1.5, reconnectAttempts));

                        serverInfo.textContent = `Connection lost. Reconnecting in ${Math.round(delay/1000)}s...`;

                        reconnectInterval = setInterval(() => {
                            eventSource.close();
                            connect();
                        }, delay);
                    }
                };
            } catch (error) {
                console.error('Failed to connect to log stream:', error);
                updateConnectionStatus('disconnected');
                serverInfo.textContent = `Connection error: ${error.message}`;
            }
        }

        function disconnect() {
            if (eventSource) {
                eventSource.close();
                eventSource = null;
            }

            if (reconnectInterval) {
                clearInterval(reconnectInterval);
                reconnectInterval = null;
            }

            // Hide main app and show connection form
            mainApp.classList.add('hidden');
            connectionForm.classList.remove('hidden');

            // Update status
            updateConnectionStatus('disconnected');
            serverInfo.textContent = 'Disconnected';
        }

        function updateConnectionStatus(status) {
            connectionStatus.className = 'connection-status ' + status;
        }

        function updateLogsVisibility() {
            updateFilteredLogs();
            renderLogs();
        }

        function updateFilteredLogs() {
            filteredEntries = logEntries.filter(entry => {
                // Apply type filter
                let typeVisible = 
                    (entry.type === 'error' && showErrorCheckbox.checked) ||
                    (entry.type === 'warn' && showWarnCheckbox.checked) ||
                    (entry.type === 'info' && showInfoCheckbox.checked) ||
                    (entry.type !== 'error' && entry.type !== 'warn' && entry.type !== 'info' && showOtherCheckbox.checked);

                // Apply search filter
                let searchVisible = searchTerm === '' || 
                    entry.text.toLowerCase().includes(searchTerm);

                return typeVisible && searchVisible;
            });

            // Update log count
            logCount.textContent = `${filteredEntries.length} of ${logEntries.length} log entries`;
        }

        function renderLogs() {
            // Only re-render everything if there are too many logs
            // or if we're filtering/searching
            if (searchTerm || logsContainer.children.length > 200) {
                logsContainer.innerHTML = '';

                filteredEntries.forEach(entry => {
                    const logElement = createLogElement(entry);
                    logsContainer.appendChild(logElement);
                });
            } else {
                // Just append the new entries
                const currentLogCount = logsContainer.children.length;
                const newEntries = filteredEntries.slice(currentLogCount);

                newEntries.forEach(entry => {
                    const logElement = createLogElement(entry);
                    logsContainer.appendChild(logElement);
                });
            }

            // Auto-scroll if enabled
            if (autoscrollCheckbox.checked) {
                logsContainer.scrollTop = logsContainer.scrollHeight;
            }
        }

        function createLogElement(entry) {
            const logElement = document.createElement('div');
            logElement.className = `log-entry ${entry.type}`;

            // Add timestamp
            const timestampSpan = document.createElement('span');
            timestampSpan.className = 'timestamp';
            timestampSpan.textContent = formatTimestamp(entry.timestamp);
            logElement.appendChild(timestampSpan);

            // Add log text
            const textNode = document.createTextNode(entry.text);
            logElement.appendChild(textNode);

            // Highlight search term if any
            if (searchTerm) {
                highlightSearchTerm(logElement, searchTerm);
            }

            return logElement;
        }

        function formatTimestamp(timestamp) {
            const date = new Date(timestamp);
            return date.toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit', fractionalSecondDigits: 3 });
        }

        function highlightSearchTerm(element, term) {
            if (!term) return;

            // Check if the element contains the search term
            if (element.textContent.toLowerCase().includes(term)) {
                element.classList.add('highlight');
            }
        }

        // Keyboard shortcuts
        document.addEventListener('keydown', (e) => {
            // Ctrl+F to focus search
            if (e.ctrlKey && e.key === 'f') {
                e.preventDefault();
                searchInput.focus();
            }

            // Esc to clear search
            if (e.key === 'Escape' && document.activeElement === searchInput) {
                searchInput.value = '';
                searchTerm = '';
                updateFilteredLogs();
                renderLogs();
            }
        });

        // Check if we can auto-connect (if credentials are saved)
        if (serverUrlInput.value && secretKeyInput.value) {
            // Delay auto-connect to allow page to load fully
            setTimeout(() => {
                connect();
            }, 500);
        }
    </script>
</body>
</html>
```

