// Middleware to handle GPT API calls from custom GPT
app.post('/api/gpt-plugin', async (req, res) => {
  try {
    const { userId, message } = req.body;
    
    // Forward to internal API
    const response = await axios.post(`http://localhost:${PORT}/api/chat`, {
      userId,
      message
    });
    
    res.json(response.data);
  } catch (error) {
    console.error('Error in GPT plugin:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Add restart endpoint
app.post('/api/admin/restart', (req, res) => {
  const { secretKey } = req.body;
  
  if (!secretKey || secretKey !== RESTART_SECRET) {
    console.log('Invalid restart attempt');
    return res.status(401).json({ error: 'Unauthorized' });
  }
  
  console.log('Authorized restart requested');
  res.status(200).json({ message: 'Restart initiated' });
  
  // Give time for response to be sent
  setTimeout(() => {
    console.log('Restarting server...');
    process.exit(0); // PM2 will restart the process
  }, 500);
});

// Log streaming endpoint
app.get('/api/admin/logs', (req, res) => {
  const secretKey = req.query.key;
  
  if (!secretKey || secretKey !== RESTART_SECRET) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  
  // Set headers for Server-Sent Events
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('Access-Control-Allow-Origin', '*');
  
  // Send initial connection message
  res.write(`data: Connected to log stream at ${new Date().toISOString()}\n\n`);
  
  // Function to send log data
  const sendLogData = (data) => {
    const cleanData = data.toString().trim();
    if (cleanData) {
      res.write(`data: ${cleanData.replace(/\n/g, '\ndata: ')}\n\n`);
    }
  };
  
  // Use spawn to get PM2 logs
  const logProcess = spawn('pm2', ['logs', 'therapy-assistant', '--raw', '--lines', '50']);
  
  logProcess.stdout.on('data', sendLogData);
  logProcess.stderr.on('data', sendLogData);
  
  // Handle client disconnect
  req.on('close', () => {
    logProcess.kill();
    console.log('Log stream client disconnected');
  });
});

// Simple status endpoint
app.get('/api/status', (req, res) => {
  res.json({ status: 'online', timestamp: new Date().toISOString() });
});

// Start the server
initializeChroma().then(() => {
  app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
});
```

