                  break;
                default:
                  console.warn(`Unsupported property type ${propType} for ${matchedKey}`);
              }
            }
          }

          // If no title was set but we have a Feature property, use that as title
          if (!propertiesData[titleProperty]) {
            // First look for a Feature property in the pairs
            const featurePair = pairs.find(p => p.toLowerCase().startsWith('feature:'));
            if (featurePair) {
              const featureValue = featurePair.split(/:(.+)/)[1].trim();
              if (featureValue) {
                propertiesData[titleProperty] = { 
                  title: [{ text: { content: featureValue } }] 
                };
              }
            } 
            // If no Feature property, try to use the title from request body
            else if (req.body.title) {
              propertiesData[titleProperty] = { 
                title: [{ text: { content: req.body.title } }] 
              };
            }
          }

          // Ensure we have a title
          if (!propertiesData[titleProperty]) {
            return res.status(400).json({ 
              error: 'Missing title', 
              message: `The ${titleProperty} property is required`
            });
          }

          console.log('Creating entry with properties:', JSON.stringify(propertiesData, null, 2));

          // Use the gathered properties
          properties = propertiesData;
        } 
        // Simple key-value format (original code)
        else {
          const parts = normalizedLine.split(/:(.+)/);
          if (parts.length < 2) {
            return res.status(400).json({ 
              error: 'Invalid line format', 
              message: 'Use "key: value" format'
            });
          }

