    const DB_ID = process.env[database];
    
    if (!DB_ID) {
      return res.status(400).json({
        error: `Unknown database: ${database}`,
        message: `Ensure ${database} is defined as an environment variable`
      });
    }

    // Ensure database exists
    try {
      const schema = await schemaDetection.getDatabaseSchema(DB_ID);
      if (!schema) {
        return res.status(404).json({ 
          error: `Database not found`,
          message: `Check the ${database} environment variable`
        });
      }
      
      // Find title property
      const titleProperty = schemaDetection.findTitleProperty(schema);
      if (!titleProperty) {
        return res.status(500).json({ 
          error: 'Invalid database structure', 
          message: 'Database must have a title property'
        });
      }

      // Get a copy of the request body to work with
      const bodyData = { ...req.body };
      
      // Check for requestArgs and merge them with the top-level fields
      // This is the new code to handle the requestArgs pattern
      if (bodyData.requestArgs && typeof bodyData.requestArgs === 'object') {
        console.log('Found requestArgs object, merging with top-level fields');
        Object.assign(bodyData, bodyData.requestArgs);
        delete bodyData.requestArgs;
      }

      // Extract the database parameter if it exists in the body (it shouldn't normally)
      if (bodyData.database) {
        delete bodyData.database;
      }

      // Extract a title parameter if it was explicitly provided
      const explicitTitle = bodyData.title;
      if (explicitTitle !== undefined) {
        delete bodyData.title;
      }

      // Now bodyData contains only the field values
      const fields = bodyData;
      
      if (Object.keys(fields).length === 0 && explicitTitle === undefined) {
        return res.status(400).json({ 
          error: 'Missing data', 
          message: 'Request body must contain fields or a title'
        });
      }

      // Map fields to Notion properties
      const properties = {};
      let titleSet = false;

      // First handle the explicit title if provided
      if (explicitTitle !== undefined) {
        properties[titleProperty] = { 
          title: [{ text: { content: String(explicitTitle) } }] 
        };
        titleSet = true;
      }

      // Process each field
      for (const [fieldName, fieldValue] of Object.entries(fields)) {
        // Skip null or undefined values
        if (fieldValue === null || fieldValue === undefined) continue;
        
        // Try to match the field name with a property in the schema (case-insensitive)
        const matchedKey = Object.keys(schema).find(
          k => k.toLowerCase() === fieldName.toLowerCase()
        );
        
        if (matchedKey) {
          const propType = schema[matchedKey].type;
          
          // If this is the title property and no title was explicitly set,
          // use this field value as the title
          if (propType === 'title' && !titleSet) {
            properties[matchedKey] = { 
              title: [{ text: { content: String(fieldValue) } }] 
            };
            titleSet = true;
            continue;
          }
          
          // Format the property value based on type
          switch (propType) {
            case 'rich_text':
              properties[matchedKey] = { 
                rich_text: [{ text: { content: String(fieldValue) } }] 
              };
              break;
            case 'select':
              properties[matchedKey] = { 
                select: { name: String(fieldValue) } 
              };
              break;
            case 'multi_select':
              // Handle both array and single values
              const values = Array.isArray(fieldValue) ? fieldValue : [fieldValue];
              properties[matchedKey] = { 
                multi_select: values.map(v => ({ name: String(v) }))
              };
              break;
            case 'date':
              // Accept ISO date strings, timestamps, or Date objects
              let dateValue = fieldValue;
              if (fieldValue instanceof Date) {
                dateValue = fieldValue.toISOString();
              }
              properties[matchedKey] = { 
                date: { start: dateValue } 
              };
              break;
            case 'number':
              // Ensure value is a number
              const numValue = Number(fieldValue);
              if (!isNaN(numValue)) {
                properties[matchedKey] = { number: numValue };
              } else {
                console.warn(`Could not convert "${fieldValue}" to number for ${matchedKey}`);
              }
              break;
            case 'checkbox':
              // Convert to boolean
              const boolValue = typeof fieldValue === 'string' 
                ? fieldValue.toLowerCase() === 'true' || fieldValue.toLowerCase() === 'yes'
                : Boolean(fieldValue);
              properties[matchedKey] = { checkbox: boolValue };
              break;
            case 'url':
              properties[matchedKey] = { url: String(fieldValue) };
              break;
            case 'email':
              properties[matchedKey] = { email: String(fieldValue) };
              break;
            case 'phone_number':
              properties[matchedKey] = { phone_number: String(fieldValue) };
              break;
            case 'files':
              // For file fields, we can only handle external URLs
              if (typeof fieldValue === 'string') {
                properties[matchedKey] = { 
                  files: [{ name: 'file', external: { url: fieldValue } }]
                };
              } else if (Array.isArray(fieldValue)) {
                properties[matchedKey] = {
                  files: fieldValue.map(url => ({ 
                    name: 'file', 
                    external: { url: String(url) } 
                  }))
                };
              }
              break;
            default:
              console.warn(`Unsupported property type ${propType} for ${matchedKey}`);
          }
        } else {
          console.warn(`No matching property found for field: ${fieldName}`);
        }
      }
      
      // Ensure we have a title
      if (!titleSet) {
        return res.status(400).json({ 
          error: 'Missing title', 
          message: `No title field provided and no field matching the title property "${titleProperty}" was found`
        });
      }
      
      console.log('Creating entry with properties:', JSON.stringify(properties, null, 2));
      
      // Create the page
      const page = await notionApi.createPage({
        parent: { database_id: DB_ID },
        properties
      });
      
      // Extract the title for response
      const title = await pageUtils.extractPageTitle(page);
      
      return res.json({
        success: true,
        created: true,
        id: page.id,
        title,
        message: "Entry created successfully"
      });
      
    } catch (err) {
      console.error(`Error accessing database:`, err);
      return res.status(500).json({ 
        error: `Error accessing database`,
        message: err.message
      });
    }
  } catch (err) {
    console.error(`Error in ${routeNames.create}structured:`, err);
    next(err);
  }
});

