    } catch (err) {
      console.error(`Error in ${routeNames.list}:`, err);
      next(err);
    }
  });

  // READ route
  router.get(`/${routeNames.read}`, async (req, res, next) => {
    try {
      // Get database from query parameter or use default from config
      const rawDatabaseName = req.query.database || config.databaseId;

      // Normalize the database name: uppercase and replace spaces with underscores
      const database = databaseUtils.normalizeDatabaseName(rawDatabaseName)

      // Get the database ID from environment variables
      const DB_ID = process.env[database];
      
      if (!DB_ID) {
        return res.status(400).json({
          error: `Unknown database: ${database}`,
          message: `Ensure ${database} is defined as an environment variable`
        });
      }

      const { key, id, field = 'value' } = req.query;

      if (!key && !id) {
        return res.status(400).json({ 
          error: 'Missing identifier', 
          message: 'Either key or id parameter is required'
        });
      }

      try {
        let page;

        // Find by key
