const express = require('express');
const router = express.Router();
const notionApi = require('../notion/notion-api');
const os = require('os');
const axios = require('axios');

// Utility function to get basic server health metrics
const getServerHealth = () => {
  return {
    status: 'ok',
    timestamp: new Date().toISOString(),
    hostname: os.hostname(),
    uptime: process.uptime(),
    memory: {
      free: os.freemem(),
      total: os.totalmem(),
      usage: process.memoryUsage()
    },
    cpu: {
      load: os.loadavg(),
      cores: os.cpus().length
    },
    platform: process.platform,
    nodejs: {
      version: process.version,
      env: process.env.NODE_ENV || 'development'
    }
  };
};

// Utility function to check Notion API health
const getNotionHealth = async () => {
  const notionHealth = {
    status: 'unknown',
    tokenConfigured: !!process.env.NOTION_TOKEN,
    timestamp: new Date().toISOString()
  };

  if (!notionHealth.tokenConfigured) {
    notionHealth.status = 'not_configured';
    return notionHealth;
  }

  try {
    // Use a lightweight API call to verify Notion connection
    const response = await notionApi.search('', { page_size: 1 });
    
    notionHealth.status = 'ok';
    notionHealth.apiVersion = '2022-06-28';
    
    // Check if databases are configured
    notionHealth.databases = {
      PROJECT_TRACKER: !!process.env.PROJECT_TRACKER,
      GPT_MEMORY_DB: !!process.env.GPT_MEMORY_DB
    };
    
    // Check parent page
    notionHealth.parentPage = {
      configured: !!process.env.NOTION_PARENT_PAGE_ID
    };
    
    if (notionHealth.parentPage.configured) {
      try {
        await notionApi.retrievePage(process.env.NOTION_PARENT_PAGE_ID);
        notionHealth.parentPage.status = 'ok';
      } catch (err) {
        notionHealth.parentPage.status = 'error';
        notionHealth.parentPage.error = err.message;
      }
    }
  } catch (err) {
    notionHealth.status = 'error';
    notionHealth.error = err.message;
  }

  return notionHealth;
};

// Utility function to check GitHub API health
const getGithubHealth = async () => {
  const githubHealth = {
    status: 'unknown',
    tokenConfigured: !!process.env.GITHUB_TOKEN,
    timestamp: new Date().toISOString()
  };

  if (!githubHealth.tokenConfigured) {
    githubHealth.status = 'not_configured';
    return githubHealth;
  }

  try {
    // Check GitHub API status
    const response = await axios.get('https://api.github.com/rate_limit', {
      headers: {
        'Authorization': `token ${process.env.GITHUB_TOKEN}`,
        'Accept': 'application/vnd.github.v3+json'
      }
    });

    githubHealth.status = 'ok';
    githubHealth.rateLimit = {
      limit: response.data.rate.limit,
      remaining: response.data.rate.remaining,
      reset: new Date(response.data.rate.reset * 1000).toISOString()
    };

    // Check repository access if configured
    if (process.env.GITHUB_REPO) {
      try {
        const [owner, repo] = process.env.GITHUB_REPO.split('/');
        const repoResponse = await axios.get(`https://api.github.com/repos/${owner}/${repo}`, {
          headers: {
            'Authorization': `token ${process.env.GITHUB_TOKEN}`,
            'Accept': 'application/vnd.github.v3+json'
          }
        });
        
        githubHealth.repository = {
          status: 'ok',
          name: repoResponse.data.full_name,
          private: repoResponse.data.private
        };
      } catch (err) {
        githubHealth.repository = {
          status: 'error',
          error: err.message
        };
      }
    }
  } catch (err) {
    githubHealth.status = 'error';
    githubHealth.error = err.message;
  }

  return githubHealth;
};

/**
 * GET /status
 * Basic server health check
 */
router.get('/status', (req, res) => {
  try {
    const health = getServerHealth();
    return res.json(health);
  } catch (err) {
    console.error('Server health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * GET /statusNotion
 * Notion API health check
 */
router.get('/statusNotion', async (req, res) => {
  try {
    const notionHealth = await getNotionHealth();
    
    // Determine status code based on health status
    if (notionHealth.status === 'ok') {
      return res.json(notionHealth);
    } else if (notionHealth.status === 'not_configured') {
      return res.status(503).json(notionHealth); // Service Unavailable
    } else {
      return res.status(500).json(notionHealth); // Internal Server Error
    }
  } catch (err) {
    console.error('Notion health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * GET /statusGithub
 * GitHub API health check
 */
router.get('/statusGithub', async (req, res) => {
  try {
    const githubHealth = await getGithubHealth();
    
    // Determine status code based on health status
    if (githubHealth.status === 'ok') {
      return res.json(githubHealth);
    } else if (githubHealth.status === 'not_configured') {
      return res.status(503).json(githubHealth); // Service Unavailable
    } else {
      return res.status(500).json(githubHealth); // Internal Server Error
    }
  } catch (err) {
    console.error('GitHub health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * GET /statusComplete
 * Complete health check for all systems
 */
router.get('/statusComplete', async (req, res) => {
  try {
    // Collect health data from all systems
    const serverHealth = getServerHealth();
    const notionHealth = await getNotionHealth();
    const githubHealth = await getGithubHealth();
    
    // Combine into a comprehensive health report
    const completeHealth = {
      status: 'ok', // Will be updated based on component health
      timestamp: new Date().toISOString(),
      server: serverHealth,
      notion: notionHealth,
      github: githubHealth
    };
    
    // Determine overall status based on component status
    if (notionHealth.status === 'error' || githubHealth.status === 'error') {
      completeHealth.status = 'degraded';
    }
    
    if (notionHealth.status === 'error' && githubHealth.status === 'error') {
      completeHealth.status = 'critical';
    }
    
    // Return appropriate status code
    if (completeHealth.status === 'ok') {
      return res.json(completeHealth);
    } else if (completeHealth.status === 'degraded') {
      return res.status(207).json(completeHealth); // Multi-Status
    } else {
      return res.status(500).json(completeHealth); // Internal Server Error
    }
  } catch (err) {
    console.error('Complete health check failed:', err);
    return res.status(500).json({ 
      status: 'error', 
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

module.exports = router;

const express = require("express");
const router = express.Router();
const axios = require("axios");

const githubToken = process.env.GITHUB_TOKEN;
const repoOwner = process.env.GITHUB_REPO_OWNER;
const repoName = process.env.GITHUB_REPO_NAME;

const headers = {
  Authorization: `Bearer ${githubToken}`,
  'X-GitHub-Api-Version': '2022-11-28',
  "User-Agent": "replit-gpt-api",
};

// Verify GitHub token is available
if (!githubToken) {
  console.error("WARNING: GITHUB_TOKEN environment variable not set");
}

// Helper function to handle rate limits
function handleRateLimit(error, res) {
  if (error.response?.status === 403 && error.response?.data?.message?.includes('API rate limit exceeded')) {
    return res.status(429).json({ 
      error: "GitHub API rate limit exceeded, please try again later",
      reset_at: error.response.headers['x-ratelimit-reset']
    });
  }
  // Handle other errors
  const status = error.response?.status || 500;
  res.status(status).json({
    error: error.response?.data?.message || error.message,
    status: status,
    documentation_url: error.response?.data?.documentation_url
  });
}

// Default axios options
const axiosOptions = {
  headers,
  timeout: 10000 // 10 seconds
};

// === Create GitHub issue ===
router.put("/issue", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { title, body } = req.body;

  console.log("Received body:", body);

  if (!title) {
    return res.status(400).json({ error: "Title is required" });
  }

  try {
    const response = await axios.post(
      `https://api.github.com/repos/${repoOwner}/${repoName}/issues`,
      { title, body },
      axiosOptions
    );
    res.json({ success: true, issueUrl: response.data.html_url });
  } catch (error) {
    console.error("GitHub create issue error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === Update GitHub issue ===
router.patch("/issue", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { issue_number, title, body, state } = req.body;

  if (!issue_number) {
    return res.status(400).json({ error: "Issue number is required" });
  }

  try {
    const response = await axios.patch(
      `https://api.github.com/repos/${repoOwner}/${repoName}/issues/${issue_number}`,
      { title, body, state },
      axiosOptions
    );
    res.json({ success: true, updated: response.data });
  } catch (error) {
    console.error("GitHub update issue error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === Add or update file ===
router.put("/file", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { path, content, message, branch } = req.body;

  if (!path || content === undefined) {
    return res.status(400).json({ error: "Path and content are required" });
  }

  if (!message) {
    return res.status(400).json({ error: "Commit message is required" });
  }

  try {
    let sha = null;
    try {
      const params = branch ? { ref: branch } : {};
      const getRes = await axios.get(
        `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
        { ...axiosOptions, params }
      );
      sha = getRes.data.sha;
    } catch (_) {
      // File doesn't exist yet, which is fine
    }

    const payload = {
      message,
      content: Buffer.from(content).toString("base64"),
      ...(sha && { sha }),
      ...(branch && { branch })
    };

    const response = await axios.put(
      `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
      payload,
      axiosOptions
    );
    res.json({ 
      success: true, 
      fileUrl: response.data.content.html_url,
      sha: response.data.content.sha
    });
  } catch (error) {
    console.error("GitHub file upload error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === Delete file ===
router.put("/delete-file", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { path, message, branch } = req.body;

  if (!path) {
    return res.status(400).json({ error: "Path is required" });
  }

  if (!message) {
    return res.status(400).json({ error: "Commit message is required" });
  }

  try {
    const params = branch ? { ref: branch } : {};
    const getRes = await axios.get(
      `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
      { ...axiosOptions, params }
    );
    const sha = getRes.data.sha;

    const payload = { 
      message, 
      sha,
      ...(branch && { branch })
    };

    const response = await axios.delete(
      `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${path}`,
      {
        ...axiosOptions,
        data: payload
      }
    );
    res.json({ 
      success: true, 
      deleted: path,
      commit: response.data.commit
    });
  } catch (error) {
    console.error("GitHub file delete error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

// === List issues ===
router.get("/issues", async (req, res) => {
  if (!githubToken) {
    return res.status(401).json({ error: "GitHub token not configured" });
  }

  const { page = 1, per_page = 30, state = 'all' } = req.query;

  try {
    const response = await axios.get(
      `https://api.github.com/repos/${repoOwner}/${repoName}/issues`,
      { 
        ...axiosOptions,
        params: { page, per_page, state, sort: 'created', direction: 'desc' }
      }
    );

    res.json({
      issues: response.data,
      pagination: {
        current_page: parseInt(page),
        per_page: parseInt(per_page),
        has_next: response.data.length === parseInt(per_page)
      }
    });
  } catch (error) {
    console.error("GitHub list issues error:", error.response?.data || error.message);
    handleRateLimit(error, res);
  }
});

