// routes/chroma/chroma-db.js
const { ChromaClient } = require('chromadb');
const { OpenAI } = require('openai');
const uuid = require('uuid');
require('dotenv').config();

// Initialize OpenAI client
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

// Create ChromaDB client with persistent storage
const chromaClient = new ChromaClient({
  path: "./chroma_db"
});

let therapyCollection;

/**
 * Initialize the ChromaDB collection
 * @returns {Promise<void>}
 */
const initializeChroma = async () => {
  try {
    // Create or get existing collection
    therapyCollection = await chromaClient.getOrCreateCollection({
      name: "therapy_sessions",
      metadata: { "description": "Therapy session memory for GPT" }
    });
    console.log("ChromaDB collection initialized");
  } catch (error) {
    console.error("Failed to initialize ChromaDB:", error);
    throw error;
  }
};

/**
 * Store interaction in ChromaDB
 * @param {string} userId - The user ID
 * @param {string} userMessage - The user's message
 * @param {string} assistantResponse - The assistant's response
 * @returns {Promise<void>}
 */
const addInteractionToMemory = async (userId, userMessage, assistantResponse) => {
  try {
    // Generate embedding for the message
    const embeddingResponse = await openai.embeddings.create({
      input: userMessage,
      model: "text-embedding-3-small"
    });

    const embedding = embeddingResponse.data[0].embedding;

    // Store in ChromaDB
    await therapyCollection.add({
      ids: [uuid.v4()],
      embeddings: [embedding],
      metadatas: [{
        userId: userId,
        timestamp: new Date().toISOString(),
        userMessage: userMessage,
        assistantResponse: assistantResponse
      }],
      documents: [userMessage]
    });

    console.log("Added interaction to memory");
  } catch (error) {
    console.error("Failed to add to memory:", error);
    throw error;
  }
};

/**
 * Retrieve relevant history from ChromaDB
 * @param {string} userId - The user ID
 * @param {string} currentMessage - The current message to find relevant history for
 * @param {number} limit - The maximum number of results to return
 * @returns {Promise<Object>} - The relevant history
 */
const getRelevantHistory = async (userId, currentMessage, limit = 5) => {
  try {
    // Generate embedding for current message
    const embeddingResponse = await openai.embeddings.create({
      input: currentMessage,
      model: "text-embedding-3-small"
    });

    const currentEmbedding = embeddingResponse.data[0].embedding;

    // Query ChromaDB for similar past interactions
    const results = await therapyCollection.query({
      queryEmbeddings: [currentEmbedding],
      nResults: limit,
      where: { userId: userId }
    });

    return results;
  } catch (error) {
    console.error("Failed to get history:", error);
    return null;
  }
};

module.exports = {
  initializeChroma,
  addInteractionToMemory,
  getRelevantHistory,
  chromaClient
};

// routes/chroma/chroma-utils.js
const { OpenAI } = require('openai');
const { getRelevantHistory, addInteractionToMemory } = require('./chroma-db');
require('dotenv').config();

// Initialize OpenAI client
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

/**
 * Generate a response with context from memory
 * @param {string} userId - The user ID
 * @param {string} message - The user's message
 * @returns {Promise<string>} - The generated response
 */
const generateResponseWithMemory = async (userId, message) => {
  try {
    // Get relevant history
    const history = await getRelevantHistory(userId, message);

    // Construct context from history
    let context = "";
    if (history && history.metadatas && history.metadatas.length > 0) {
      context = "Previous relevant conversations:\n";
      for (let i = 0; i < history.metadatas[0].length; i++) {
        const metadata = history.metadatas[0][i];
        context += `Date: ${metadata.timestamp}\n`;
        context += `User: ${metadata.userMessage}\n`;
        context += `Assistant: ${metadata.assistantResponse}\n\n`;
      }
    }

    // Generate response with context
    const completion = await openai.chat.completions.create({
      model: "gpt-4-turbo",
      messages: [
        { 
          role: "system", 
          content: "You are a therapeutic assistant with memory of past conversations. " +
                  "Reference past discussions when appropriate and track progress over time. " +
                  "Be empathetic and supportive." + 
                  (context ? "\n\n" + context : "")
        },
        { role: "user", content: message }
      ]
    });

    const assistantResponse = completion.choices[0].message.content;

    // Add the new interaction to memory
    await addInteractionToMemory(userId, message, assistantResponse);

    return assistantResponse;
  } catch (error) {
    console.error('Error generating response:', error);
    throw error;
  }
};

module.exports = {
  generateResponseWithMemory
};

// routes/chroma/chroma-routes.js
const express = require('express');
const router = express.Router();
const { generateResponseWithMemory } = require('./chroma-utils');

/**
 * POST /chroma/chat
 * Process a chat message with memory
 */
router.post('/chat', async (req, res) => {
  try {
    const { userId, message } = req.body;

    if (!userId || !message) {
      return res.status(400).json({ error: 'userId and message are required' });
    }

    console.log(`Received message from user ${userId}: ${message}`);

    const assistantResponse = await generateResponseWithMemory(userId, message);

    res.json({ response: assistantResponse });
    console.log("Sent response to user");
  } catch (error) {
    console.error('Error processing chat request:', error);
    res.status(500).json({ error: 'Failed to process request', message: error.message });
  }
});

/**
 * POST /chroma/gpt-plugin
 * Middleware to handle GPT API calls from custom GPT
 */
router.post('/gpt-plugin', async (req, res) => {
  try {
    const { userId, message } = req.body;

    if (!userId || !message) {
      return res.status(400).json({ error: 'userId and message are required' });
    }

    // Forward to internal API
    const assistantResponse = await generateResponseWithMemory(userId, message);

    res.json({ response: assistantResponse });
  } catch (error) {
    console.error('Error in GPT plugin:', error);
    res.status(500).json({ error: 'Internal server error', message: error.message });
  }
});

module.exports = router;

// routes/admin/admin-routes.js
const express = require('express');
const router = express.Router();
const { spawn } = require('child_process');
require('dotenv').config();

const RESTART_SECRET = process.env.RESTART_SECRET || 'default-secret-key';

/**
 * POST /admin/restart
 * Restart the server with authentication
 */
router.post('/restart', (req, res) => {
  const { secretKey } = req.body;

  if (!secretKey || secretKey !== RESTART_SECRET) {
    console.log('Invalid restart attempt');
    return res.status(401).json({ error: 'Unauthorized' });
  }

  console.log('Authorized restart requested');
  res.status(200).json({ message: 'Restart initiated' });

  // Give time for response to be sent
  setTimeout(() => {
    console.log('Restarting server...');
    process.exit(0); // PM2 will restart the process
  }, 500);
});

/**
 * GET /admin/logs
 * Stream server logs with authentication
 */
router.get('/logs', (req, res) => {
  const secretKey = req.query.key;

  if (!secretKey || secretKey !== RESTART_SECRET) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Set headers for Server-Sent Events
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('Access-Control-Allow-Origin', '*');

  // Send initial connection message
  res.write(`data: Connected to log stream at ${new Date().toISOString()}\n\n`);

  // Function to send log data
  const sendLogData = (data) => {
    const cleanData = data.toString().trim();
    if (cleanData) {
      res.write(`data: ${cleanData.replace(/\n/g, '\ndata: ')}\n\n`);
    }
  };

  // Use spawn to get PM2 logs
  const logProcess = spawn('pm2', ['logs', 'therapy-assistant', '--raw', '--lines', '50']);

  logProcess.stdout.on('data', sendLogData);
  logProcess.stderr.on('data', sendLogData);

  // Handle client disconnect
  req.on('close', () => {
    logProcess.kill();
    console.log('Log stream client disconnected');
  });
});

module.exports = router;

const express = require('express');
const cors = require('cors');
const path = require('path');
const dotenv = require('dotenv');
dotenv.config();

// Import ChromaDB initialization
const { initializeChroma } = require('./routes/chroma/chroma-db');

// Initialize Express app
const app = express();
app.use(express.json());
app.use(cors());

// Environment variables
const PORT = process.env.PORT || 3000;

// Middleware
app.use((req, res, next) => {
  const { method, url, headers, body } = req;
  console.log(`[${new Date().toISOString()}] ${method} ${url}`);
  if (Object.keys(body || {}).length > 0 && !url.includes('/logs')) {
    console.log('Body:', JSON.stringify(body));
  }
  next();
});

// Routes
app.use('/github', require('./routes/github/github'));
app.use('/health', require('./routes/health/health-routes'));
app.use('/notion/databases', require('./routes/notion/schema-routes'));
app.use('/notion/databases', require('./routes/notion/database-routes'));
app.use('/notion/memory', require('./routes/notion/memory-routes'));
app.use('/notion/pages', require('./routes/notion/page-routes'));
app.use('/admin', require('./routes/admin/admin-routes'));
app.use('/chroma', require('./routes/chroma/chroma-routes'));

// Basic Health Check
app.get("/", (req, res) => {
  res.send("✅ Notion + GitHub + ChromaDB Therapy API is live.");
});

// Simple status endpoint
app.get('/api/status', (req, res) => {
  res.json({ 
    status: 'online', 
    timestamp: new Date().toISOString(),
    services: {
      notion: !!process.env.NOTION_TOKEN,
      github: !!process.env.GITHUB_TOKEN,
      openai: !!process.env.OPENAI_API_KEY,
      chroma: true
    }
  });
});

// Static + OpenAPI
app.use(express.static(path.join(__dirname, 'public')));
app.get("/openapi.json", (req, res) => {
  res.sendFile(path.join(__dirname, "openapi.json"));
});

// Error Handler
app.use((err, req, res, next) => {
  console.error('Server error:', err);
  res.status(500).json({ error: 'Internal Server Error', message: err.message });
});

// Start the server
initializeChroma().then(() => {
  const server = app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });

  // Add graceful shutdown
  process.on('SIGTERM', () => {
    server.close(() => {
      console.log('🔴 Server closed gracefully on SIGTERM');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    server.close(() => {
      console.log('🔴 Server closed gracefully on SIGINT');
      process.exit(0);
    });
  });
}).catch(err => {
  console.error('Failed to initialize ChromaDB:', err);
  process.exit(1);
});

// routes/index.js
