require('dotenv').config();

// Initialize OpenAI client
const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
});

// GPT type configurations
const GPT_CONFIGS = {
  therapy: {
    systemPrompt: "You are a therapeutic assistant with memory of past conversations. " +
                 "Reference past discussions when appropriate and track progress over time. " +
                 "Be empathetic and supportive.",
    model: "gpt-4-turbo"
  },
  coaching: {
    systemPrompt: "You are a professional development coach with memory of past sessions. " +
                 "Help the user achieve their career goals, track their progress, and provide " +
                 "actionable advice based on their history and current situation.",
    model: "gpt-4-turbo"
  }
  // Add more GPT types as needed
};

/**
 * Generate a response with context from memory
 * @param {string} type - The type of GPT ('therapy', 'coaching', etc.)
 * @param {string} userId - The user ID
 * @param {string} message - The user's message
 * @returns {Promise<string>} - The generated response
 */
const generateResponseWithMemory = async (type, userId, message) => {
  try {
    // Validate GPT type
    if (!GPT_CONFIGS[type]) {
      throw new Error(`Unknown GPT type: '${type}'. Available types: ${Object.keys(GPT_CONFIGS).join(', ')}`);
    }

    const config = GPT_CONFIGS[type];

    // Get relevant history
    const history = await getRelevantHistory(type, userId, message);

    // Construct context from history
    let context = "";
    if (history && history.metadatas && history.metadatas.length > 0) {
      context = "Previous relevant conversations:\n";
      for (let i = 0; i < history.metadatas[0].length; i++) {
        const metadata = history.metadatas[0][i];
        context += `Date: ${metadata.timestamp}\n`;
        context += `User: ${metadata.userMessage}\n`;
        context += `Assistant: ${metadata.assistantResponse}\n\n`;
      }
    }

    // Generate response with context
    const completion = await openai.chat.completions.create({
      model: config.model,
      messages: [
        { 
          role: "system", 
          content: config.systemPrompt + (context ? "\n\n" + context : "")
        },
        { role: "user", content: message }
      ]
    });

    const assistantResponse = completion.choices[0].message.content;

    // Add the new interaction to memory
    await addInteractionToMemory(type, userId, message, assistantResponse);

    return assistantResponse;
  } catch (error) {
    console.error(`Error generating ${type} response:`, error);
    throw error;
  }
};

/**
 * Add a new GPT type configuration
 * @param {string} type - The type name
 * @param {string} systemPrompt - The system prompt
 * @param {string} model - The OpenAI model to use
 */
const addGptType = (type, systemPrompt, model = "gpt-4-turbo") => {
  GPT_CONFIGS[type] = { systemPrompt, model };
  console.log(`Added new GPT type: ${type}`);
};

/**
 * Get available GPT types
 * @returns {string[]} - Array of available GPT type names
 */
const getAvailableGptTypes = () => {
  return Object.keys(GPT_CONFIGS);
};

module.exports = {
  generateResponseWithMemory,
  addGptType,
  getAvailableGptTypes
};

